import type { BankQuestion } from "@/lib/bank";

/** Environment and Ecology (Environment): 1000 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "env-ecology-1", "question": "The Ramsar Convention is concerned with the conservation of:", "options": ["Wetlands", "Coral reefs only", "Mountain glaciers", "Deserts"], "answer": 0, "explanation": "The Ramsar Convention (1971) is an intergovernmental treaty for the conservation and wise use of wetlands.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "env-ecology-2", "question": "India's first national park, set up in 1936 as Hailey National Park, is now known as:", "options": ["Jim Corbett National Park", "Kaziranga National Park", "Kanha National Park", "Gir National Park"], "answer": 0, "explanation": "Hailey National Park in Uttarakhand was renamed Ramganga and then Jim Corbett National Park, after the hunter-turned-conservationist Jim Corbett.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "env-ecology-3", "question": "Project Tiger was launched in India in:", "options": ["1973", "1972", "1986", "1980"], "answer": 0, "explanation": "Project Tiger began on 1 April 1973; the Wildlife (Protection) Act came a year earlier, in 1972.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "env-ecology-4", "question": "Kaziranga National Park is best known for the:", "options": ["Hangul deer", "Snow leopard", "Asiatic lion", "One-horned rhinoceros"], "answer": 3, "explanation": "Kaziranga in Assam holds the largest population of the greater one-horned rhinoceros; it is a World Heritage Site and a tiger reserve.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "env-ecology-5", "question": "The Kyoto Protocol, adopted in 1997, deals with:", "options": ["Conservation of wetlands", "Protecting the ozone layer", "Trade in endangered species", "Reducing greenhouse gas emissions"], "answer": 3, "explanation": "Kyoto set binding emission-reduction targets for developed countries under the UNFCCC; the ozone layer is covered by the Montreal Protocol.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "env-ecology-6", "question": "The central goal of the Paris Agreement (2015) is to hold the rise in global average temperature to:", "options": ["Below 4 °C by 2100", "Exactly 1 °C above present levels", "Well below 2 °C above pre-industrial levels, while pursuing 1.5 °C", "Below 3 °C by 2050"], "answer": 2, "explanation": "The Paris Agreement aims to keep warming well below 2 °C above pre-industrial levels and to pursue efforts to limit it to 1.5 °C.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "env-ecology-7", "question": "Gir National Park, the only wild home of the Asiatic lion, is in:", "options": ["Maharashtra", "Madhya Pradesh", "Rajasthan", "Gujarat"], "answer": 3, "explanation": "The Asiatic lion survives in the wild only in the Gir forest and surrounding areas of Saurashtra, Gujarat.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "env-ecology-8", "question": "Among the following IUCN Red List categories, which indicates the highest risk of extinction in the wild?", "options": ["Near Threatened", "Vulnerable", "Critically Endangered", "Endangered"], "answer": 2, "explanation": "The threatened categories in rising order of risk are Vulnerable, Endangered and Critically Endangered; Near Threatened is below Vulnerable.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "env-ecology-9", "question": "CITES regulates:", "options": ["International trade in endangered species of wild animals and plants", "Emissions of greenhouse gases", "Dumping of waste at sea", "Use of mercury"], "answer": 0, "explanation": "CITES (Convention on International Trade in Endangered Species of Wild Fauna and Flora) controls cross-border trade in listed species through its appendices.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "env-ecology-10", "question": "Silent Valley National Park, saved from a hydroelectric project after a public campaign, is in:", "options": ["Goa", "Tamil Nadu", "Karnataka", "Kerala"], "answer": 3, "explanation": "Silent Valley in Palakkad district, Kerala, is a tropical evergreen forest and part of the Nilgiri Biosphere Reserve.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "env-ecology-11", "question": "Acid rain is caused mainly by:", "options": ["Argon and helium", "Sulphur dioxide and nitrogen oxides", "Carbon monoxide and methane", "Ozone and chlorofluorocarbons"], "answer": 1, "explanation": "SO₂ and NOₓ from burning fossil fuels form sulphuric and nitric acids in the atmosphere, which fall as acid rain.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "env-ecology-12", "question": "Keoladeo National Park at Bharatpur, Rajasthan, is famous for:", "options": ["Its tigers", "Its one-horned rhinos", "Its birds, including wintering migratory waterbirds", "Its wild asses"], "answer": 2, "explanation": "Keoladeo, a World Heritage Site and Ramsar site, is a wetland famous for resident and migratory birds; it was once a wintering site of the Siberian crane.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "env-ecology-13", "question": "The Nicobar Islands fall within which biodiversity hotspot?", "options": ["Sundaland", "Indo-Burma", "Western Ghats and Sri Lanka", "Himalaya"], "answer": 0, "explanation": "India has parts of four hotspots: the Himalaya, Indo-Burma, the Western Ghats and Sri Lanka, and Sundaland, which covers the Nicobar Islands.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "env-ecology-14", "question": "The Environment (Protection) Act, an umbrella law passed after the Bhopal gas tragedy, was enacted in:", "options": ["1986", "1980", "1972", "1974"], "answer": 0, "explanation": "The Environment (Protection) Act came in 1986; the Wildlife (Protection) Act dates from 1972, the Water Act from 1974 and the Forest (Conservation) Act from 1980.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-15", "question": "The concept of biosphere reserves comes from UNESCO's:", "options": ["World Heritage Convention", "Ramsar Convention", "Bonn Convention", "Man and the Biosphere (MAB) Programme"], "answer": 3, "explanation": "Biosphere reserves were launched under UNESCO's Man and the Biosphere Programme, begun in 1971.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-16", "question": "In a biosphere reserve, the zone where research, education and limited human activity are allowed but settlements are not is the:", "options": ["Corridor zone", "Buffer zone", "Core zone", "Transition zone"], "answer": 1, "explanation": "The core zone is strictly protected; the surrounding buffer zone allows research, education and limited activity; the outer transition zone has settlements and farming.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-17", "question": "Dachigam National Park in Jammu and Kashmir is known for the:", "options": ["Hangul (Kashmir stag)", "Sangai deer", "Wild ass", "Nilgiri tahr"], "answer": 0, "explanation": "Dachigam, near Srinagar, is the last stronghold of the hangul, the Kashmir red deer; the sangai lives in Manipur's Keibul Lamjao.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "env-ecology-18", "question": "Which of these tiger reserves is in Kerala?", "options": ["Nagarhole", "Bandipur", "Mudumalai", "Periyar"], "answer": 3, "explanation": "Periyar is in Kerala; Mudumalai is in Tamil Nadu, and Bandipur and Nagarhole are in Karnataka. All four lie in the Nilgiri–Western Ghats landscape.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "env-ecology-19", "question": "The Kigali Amendment (2016) to the Montreal Protocol aims to phase down:", "options": ["Mercury", "Chlorofluorocarbons (CFCs)", "Carbon dioxide", "Hydrofluorocarbons (HFCs)"], "answer": 3, "explanation": "HFCs do not harm the ozone layer but are powerful greenhouse gases; the Kigali Amendment set a schedule to cut them. CFCs were already being phased out under the original protocol.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "env-ecology-20", "question": "The Nagoya Protocol under the Convention on Biological Diversity deals with:", "options": ["Protection of migratory birds", "Safe handling of living modified organisms", "Trade in hazardous chemicals", "Access to genetic resources and fair sharing of their benefits"], "answer": 3, "explanation": "The Nagoya Protocol (2010) covers access and benefit-sharing; biosafety of living modified organisms is the subject of the Cartagena Protocol.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "env-ecology-21", "question": "Persistent organic pollutants (POPs) are the subject of the:", "options": ["Stockholm Convention", "Ramsar Convention", "Basel Convention", "Minamata Convention"], "answer": 0, "explanation": "The Stockholm Convention (2001) aims to eliminate or restrict POPs such as DDT and PCBs; Basel covers hazardous wastes and Minamata covers mercury.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-22", "question": "The Bonn Convention (CMS) aims to conserve:", "options": ["World cultural heritage", "Migratory species of wild animals", "The ozone layer", "Wetlands of international importance"], "answer": 1, "explanation": "The Convention on the Conservation of Migratory Species of Wild Animals was signed at Bonn in 1979.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "env-ecology-23", "question": "When a lake receives large amounts of nitrates and phosphates from fertiliser run-off, the usual chain of events is:", "options": ["Fall in algae, then rise in dissolved oxygen", "Algal bloom, then fall in dissolved oxygen and death of fish", "Rise in water clarity and in fish numbers", "Immediate fall in biochemical oxygen demand"], "answer": 1, "explanation": "This is eutrophication: nutrients feed an algal bloom, and decomposition of the dead algae uses up dissolved oxygen, killing fish.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "env-ecology-24", "question": "The IUCN Red List status of the Great Indian Bustard, the state bird of Rajasthan, is:", "options": ["Critically Endangered", "Vulnerable", "Endangered", "Near Threatened"], "answer": 0, "explanation": "The Great Indian Bustard has been listed as Critically Endangered since 2011; collisions with power lines in the Thar are a major threat.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-25", "question": "Match the international agreement with its subject. A. Basel Convention  B. Rotterdam Convention  C. Minamata Convention  D. Cartagena Protocol; 1. Prior informed consent for trade in hazardous chemicals  2. Transboundary movement of hazardous wastes  3. Biosafety of living modified organisms  4. Mercury", "options": ["A-4, B-1, C-2, D-3", "A-3, B-1, C-4, D-2", "A-2, B-1, C-4, D-3", "A-2, B-3, C-4, D-1"], "answer": 2, "explanation": "Basel controls movement of hazardous wastes, Rotterdam sets prior informed consent for hazardous chemicals and pesticides, Minamata limits mercury, and the Cartagena Protocol under the CBD covers biosafety of LMOs.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "env-ecology-26", "question": "How many of the following statements about the Ramsar Convention are correct? I. It was signed in 1971 at Ramsar in Iran. II. Chilika Lake and Keoladeo were India's first Ramsar sites, in 1981. III. The Montreux Record lists Ramsar sites where ecological change is occurring or likely. IV. Loktak Lake in Manipur is on the Montreux Record.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Keoladeo and Loktak are India's sites on the Montreux Record; Chilika was placed on it in 1993 and removed in 2002 after restoration.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "env-ecology-27", "question": "Which of these is NOT a tiger reserve in Madhya Pradesh?", "options": ["Satpura", "Bandhavgarh", "Kanha", "Tadoba-Andhari"], "answer": 3, "explanation": "Kanha, Bandhavgarh and Satpura are in Madhya Pradesh; Tadoba-Andhari is in Chandrapur district of Maharashtra.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-28", "question": "Match the national park with its state. A. Namdapha  B. Valley of Flowers  C. Bandipur  D. Simlipal; 1. Odisha  2. Karnataka  3. Arunachal Pradesh  4. Uttarakhand", "options": ["A-2, B-4, C-3, D-1", "A-3, B-1, C-2, D-4", "A-3, B-2, C-4, D-1", "A-3, B-4, C-2, D-1"], "answer": 3, "explanation": "Namdapha is in Arunachal Pradesh, the Valley of Flowers in Uttarakhand, Bandipur in Karnataka and Simlipal in Odisha.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "env-ecology-29", "question": "How many of the following statements are correct? I. National parks and wildlife sanctuaries are declared under the Wildlife (Protection) Act, 1972. II. Biosphere reserves are notified under the Wildlife (Protection) Act, 1972. III. Grazing of livestock may be regulated and permitted in a sanctuary but is not allowed in a national park. IV. Conservation reserves and community reserves were added by an amendment to the Wildlife (Protection) Act in 2002.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, III and IV are correct. Biosphere reserves are designated by the Centre under UNESCO's MAB framework and have no separate status under the Wildlife (Protection) Act, so II is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "env-ecology-30", "question": "How many of the following statements are correct? I. The UNFCCC was opened for signature at the Rio Earth Summit in 1992. II. The Kyoto Protocol set binding emission targets for developing countries such as India. III. Under the Paris Agreement every party must prepare and communicate Nationally Determined Contributions. IV. The Paris Agreement was adopted at COP-21 in Copenhagen.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and III are correct. Kyoto's binding targets applied only to developed (Annex I) countries (II wrong), and COP-21 was held in Paris; Copenhagen hosted COP-15 in 2009 (IV wrong).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "env-ecology-31", "question": "Arrange in chronological order: 1. Montreal Protocol  2. Kyoto Protocol  3. Stockholm Conference on the Human Environment  4. Rio Earth Summit", "options": ["4-1-3-2", "2-4-3-1", "3-1-4-2", "4-3-2-1"], "answer": 2, "explanation": "Stockholm Conference 1972, Montreal Protocol 1987, Rio Earth Summit 1992, Kyoto Protocol 1997.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-32", "question": "Assertion (A): The ozone hole is most pronounced over Antarctica in the southern spring (September–October). Reason (R): Polar stratospheric clouds formed in the extreme winter cold provide surfaces on which reactions release active chlorine.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "In the dark polar winter, polar stratospheric clouds convert stable chlorine compounds into reactive forms; when sunlight returns in spring, that chlorine rapidly destroys ozone.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "env-ecology-33", "question": "Match the disease with the pollutant that causes it. A. Minamata disease  B. Itai-itai disease  C. Blue baby syndrome  D. Blackfoot disease; 1. Arsenic  2. Nitrate  3. Mercury  4. Cadmium", "options": ["A-4, B-3, C-2, D-1", "A-1, B-4, C-2, D-3", "A-3, B-1, C-2, D-4", "A-3, B-4, C-2, D-1"], "answer": 3, "explanation": "Minamata disease comes from mercury, itai-itai from cadmium, blue baby syndrome (methaemoglobinaemia) from nitrate in drinking water, and blackfoot disease from arsenic.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "env-ecology-34", "question": "Arrange these IUCN categories in increasing order of extinction risk: 1. Vulnerable  2. Near Threatened  3. Critically Endangered  4. Endangered", "options": ["3-2-1-4", "2-1-4-3", "3-1-2-4", "4-1-2-3"], "answer": 1, "explanation": "Near Threatened is below the threatened categories; then come Vulnerable, Endangered and Critically Endangered, followed only by Extinct in the Wild and Extinct.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "env-ecology-35", "question": "How many of the following statements about biodiversity hotspots are correct? I. The concept was proposed by E. O. Wilson. II. A hotspot must have at least 1,500 endemic species of vascular plants. III. A hotspot must have lost at least 70% of its original habitat. IV. The Eastern Ghats are recognised as a separate hotspot.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "II and III are the two criteria and are correct. The concept was proposed by Norman Myers in 1988 (I wrong), and the Eastern Ghats are not a hotspot (IV wrong).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "env-ecology-36", "question": "Which pair of animal and protected area is NOT correctly matched?", "options": ["Indian wild ass — Little Rann of Kutch", "Lion-tailed macaque — Desert National Park", "Sangai — Keibul Lamjao", "Nilgiri tahr — Eravikulam"], "answer": 1, "explanation": "The lion-tailed macaque lives in the rainforests of the Western Ghats (e.g., Silent Valley); Desert National Park in Rajasthan is known for the Great Indian Bustard.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-37", "question": "Which of these Ramsar sites is NOT in Odisha?", "options": ["Hirakud reservoir", "Bhitarkanika mangroves", "Sambhar Lake", "Chilika Lake"], "answer": 2, "explanation": "Chilika, Bhitarkanika and Hirakud are Ramsar sites in Odisha; Sambhar, India's largest inland salt lake, is in Rajasthan.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-38", "question": "How many of the following statements about air pollution are correct? I. PM2.5 particles can penetrate deep into the lungs. II. Carbon dioxide is the main cause of stratospheric ozone depletion. III. Ground-level ozone is a primary pollutant emitted directly by vehicles. IV. Fly ash comes mainly from hydroelectric power stations.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 0, "explanation": "Only I is correct. Ozone depletion is caused chiefly by CFCs and other halogen compounds (II wrong); ground-level ozone is a secondary pollutant formed from NOₓ and hydrocarbons in sunlight (III wrong); fly ash comes from coal-fired thermal plants (IV wrong).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "env-ecology-39", "question": "Match the tiger reserve with its state. A. Dudhwa  B. Valmiki  C. Manas  D. Achanakmar; 1. Bihar  2. Uttar Pradesh  3. Chhattisgarh  4. Assam", "options": ["A-3, B-1, C-4, D-2", "A-2, B-3, C-4, D-1", "A-2, B-1, C-4, D-3", "A-2, B-4, C-1, D-3"], "answer": 2, "explanation": "Dudhwa is in Uttar Pradesh, Valmiki in Bihar, Manas in Assam and Achanakmar in Chhattisgarh.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "env-ecology-40", "question": "Which of the following is at the same time a UNESCO World Heritage Site, a tiger reserve and a biosphere reserve?", "options": ["Sundarbans", "Keoladeo", "Jim Corbett", "Nanda Devi"], "answer": 0, "explanation": "The Sundarbans is all three. Nanda Devi is a World Heritage Site and biosphere reserve but not a tiger reserve; Keoladeo is a World Heritage Site only; Corbett is a tiger reserve but not a World Heritage Site.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-41", "question": "Project Elephant was launched by the Government of India in:", "options": ["1973", "1992", "2006", "1985"], "answer": 1, "explanation": "Project Elephant began in 1992 to protect elephants, their habitats and corridors. Project Tiger dates from 1973.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "env-ecology-42", "question": "World Environment Day is observed every year on:", "options": ["22 April", "22 March", "5 June", "16 September"], "answer": 2, "explanation": "World Environment Day, led by UNEP, falls on 5 June. 22 April is Earth Day, 22 March World Water Day and 16 September World Ozone Day.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "env-ecology-43", "question": "Which greenhouse gas released by human activities contributes the most to global warming?", "options": ["Carbon dioxide", "Methane", "Nitrous oxide", "Water vapour from aircraft"], "answer": 0, "explanation": "Carbon dioxide from burning fossil fuels and clearing forests is the largest human contribution to warming. Methane is more potent per molecule but is emitted in much smaller amounts.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "env-ecology-44", "question": "Which of these biodiversity hotspots covers part of India?", "options": ["Madagascar", "Caribbean Islands", "Atlantic Forest", "Western Ghats and Sri Lanka"], "answer": 3, "explanation": "India has parts of four hotspots: the Himalaya, Indo-Burma, the Western Ghats and Sri Lanka, and Sundaland (Nicobar Islands). The others are outside Asia.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "env-ecology-45", "question": "The ozone layer that shields the Earth from ultraviolet radiation lies in the:", "options": ["Troposphere", "Stratosphere", "Mesosphere", "Thermosphere"], "answer": 1, "explanation": "Most atmospheric ozone sits in the stratosphere at about 15–35 km, where it absorbs harmful UV-B radiation. Ozone near the ground is a pollutant.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "env-ecology-46", "question": "The Red Data Book, which lists threatened species, is maintained by:", "options": ["UNEP", "WWF", "IUCN", "UNESCO"], "answer": 2, "explanation": "The International Union for Conservation of Nature (IUCN) compiles the Red List / Red Data Book of species at risk of extinction.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "env-ecology-47", "question": "A species found naturally only in one particular region and nowhere else is called:", "options": ["Endemic", "Exotic", "Keystone", "Invasive"], "answer": 0, "explanation": "Endemic species are restricted to one area, like the lion-tailed macaque of the Western Ghats. Exotic species are introduced from elsewhere.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "env-ecology-48", "question": "The transition zone between two ecosystems, such as a forest and a grassland, which often has more species than either, is called an:", "options": ["Ecological niche", "Ecotone", "Ecological pyramid", "Ecological footprint"], "answer": 1, "explanation": "An ecotone is the boundary zone where two communities meet; the higher variety of species there is called the edge effect. A niche is the role of a species.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "env-ecology-49", "question": "A species whose effect on its ecosystem is much larger than its numbers would suggest, so that its loss changes the whole community, is a:", "options": ["Pioneer species", "Flagship species", "Endemic species", "Keystone species"], "answer": 3, "explanation": "A keystone species, such as a top predator or the fig tree in tropical forests, holds the community together. A flagship species is chosen mainly to draw public support.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "env-ecology-50", "question": "The National Green Tribunal was set up in 2010 under:", "options": ["The Environment (Protection) Act, 1986", "The Wildlife (Protection) Act, 1972", "The National Green Tribunal Act, 2010", "An executive order of the Ministry of Environment"], "answer": 2, "explanation": "The NGT is a statutory body created by the National Green Tribunal Act, 2010, to dispose of environmental cases quickly.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "env-ecology-51", "question": "Mass nesting ('arribada') of Olive Ridley turtles takes place mainly on the coast of:", "options": ["Odisha, at Gahirmatha and Rushikulya", "Gujarat, at Kutch", "Kerala, at Kovalam", "Maharashtra, at Ratnagiri"], "answer": 0, "explanation": "Hundreds of thousands of Olive Ridleys nest together on the Odisha beaches of Gahirmatha, Rushikulya and the Devi river mouth.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "env-ecology-52", "question": "In 1730, Amrita Devi and more than 350 members of the Bishnoi community gave their lives to save khejri trees at:", "options": ["Reni, Uttarakhand", "Silent Valley, Kerala", "Khejarli, Rajasthan", "Sirsi, Karnataka"], "answer": 2, "explanation": "The Khejarli sacrifice near Jodhpur is an early example of tree-protection; the Chipko movement at Reni came more than two centuries later.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "env-ecology-53", "question": "Flooded paddy fields and the digestion of cattle are major sources of which greenhouse gas?", "options": ["Carbon monoxide", "Methane", "Sulphur dioxide", "Ozone"], "answer": 1, "explanation": "Anaerobic bacteria in waterlogged paddy soil and in the stomachs of ruminants produce methane.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "env-ecology-54", "question": "Using micro-organisms to break down pollutants, such as oil spills, into harmless substances is called:", "options": ["Bioremediation", "Biomagnification", "Eutrophication", "Biofortification"], "answer": 0, "explanation": "Bioremediation uses microbes (and sometimes plants) to clean up pollution. Biomagnification is the build-up of toxins up the food chain.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "env-ecology-55", "question": "In carbon trading, one carbon credit generally represents:", "options": ["One kilogram of carbon", "One tonne of oxygen released", "One tonne of carbon dioxide equivalent reduced or removed", "One hectare of forest planted"], "answer": 2, "explanation": "A carbon credit stands for a reduction or removal of one tonne of CO₂-equivalent; other gases are converted using their global warming potential.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-56", "question": "'Blue carbon' refers to carbon:", "options": ["Released by burning natural gas", "Captured and stored by coastal and marine ecosystems such as mangroves, seagrasses and salt marshes", "Stored in glaciers and ice sheets", "Emitted by shipping"], "answer": 1, "explanation": "Blue carbon is carbon stored by ocean and coastal ecosystems, which can lock it in their sediments for very long periods.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-57", "question": "The St Petersburg Declaration (2010) of the tiger range countries set the goal of:", "options": ["Banning all trade in tiger parts by 2015", "Creating a single tiger reserve across Asia", "Doubling the number of wild tigers by 2022", "Moving all tigers to protected zoos"], "answer": 2, "explanation": "The 13 tiger range countries pledged to double wild tiger numbers by 2022 (the TX2 goal), the next Chinese Year of the Tiger.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-58", "question": "Project Snow Leopard, covering the high Himalayan states, was launched in:", "options": ["1973", "1992", "2016", "2009"], "answer": 3, "explanation": "Project Snow Leopard began in 2009 to conserve the snow leopard and its high-altitude habitat through a participatory approach.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-59", "question": "India's first Dugong Conservation Reserve was notified in 2022 in:", "options": ["Palk Bay, Tamil Nadu", "Gulf of Kutch, Gujarat", "Chilika Lake, Odisha", "Lakshadweep"], "answer": 0, "explanation": "The dugong reserve in the northern Palk Bay off Tamil Nadu protects seagrass beds that dugongs, or sea cows, graze on.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-60", "question": "Black carbon, which darkens Himalayan snow and speeds its melting, is mainly:", "options": ["A long-lived gas like CO₂", "Fine soot from incomplete burning of fossil fuels, biomass and wood", "Dissolved carbon in seawater", "A type of coal found in Assam"], "answer": 1, "explanation": "Black carbon is soot. It stays in the air only days to weeks, which makes it a short-lived climate pollutant, but it absorbs sunlight strongly and lowers the reflectivity of snow.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-61", "question": "In which year were the Western Ghats inscribed as a UNESCO World Heritage Site?", "options": ["2002", "2012", "1985", "2016"], "answer": 1, "explanation": "The Western Ghats, a cluster of 39 sites across four states, were inscribed in 2012 for their outstanding biodiversity and endemism.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-62", "question": "After the Sundarbans, the second largest mangrove ecosystem in India is:", "options": ["Pichavaram", "Coringa", "Bhitarkanika", "Vembanad"], "answer": 2, "explanation": "Bhitarkanika in Odisha, in the Brahmani–Baitarani delta, is India's second largest mangrove ecosystem and is famous for saltwater crocodiles.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-63", "question": "The gas that leaked from the Union Carbide plant in the Bhopal disaster of 1984 was:", "options": ["Methyl isocyanate", "Phosgene", "Hydrogen sulphide", "Chlorine"], "answer": 0, "explanation": "Methyl isocyanate (MIC) leaked on the night of 2–3 December 1984, killing thousands. The disaster led to the Environment (Protection) Act, 1986.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-64", "question": "The National Tiger Conservation Authority (NTCA) was constituted in 2006 under:", "options": ["The Environment (Protection) Act, 1986", "The Forest (Conservation) Act, 1980", "The Biological Diversity Act, 2002", "An amendment to the Wildlife (Protection) Act, 1972"], "answer": 3, "explanation": "The 2006 amendment to the Wildlife (Protection) Act created the NTCA as a statutory body, replacing the earlier Project Tiger directorate.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-65", "question": "The ozone-depleting potential (ODP) of a substance is measured relative to:", "options": ["Carbon dioxide", "CFC-11", "Methane", "Halon-1301"], "answer": 1, "explanation": "ODP compares a chemical's ozone-destroying power with that of CFC-11 (ODP = 1). Global warming potential, by contrast, uses CO₂ as the reference.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-66", "question": "Which of these is NOT a major coral reef area of India?", "options": ["Gulf of Mannar", "Gulf of Kutch", "Lakshadweep", "Gulf of Khambhat"], "answer": 3, "explanation": "India's main reefs are in the Gulf of Mannar, the Gulf of Kutch, the Andaman and Nicobar Islands and Lakshadweep. The Gulf of Khambhat's muddy, turbid water does not suit corals.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-67", "question": "India hosted the 14th Conference of Parties (COP-14) in 2019 of the:", "options": ["UN Convention to Combat Desertification", "Ramsar Convention", "Convention on Biological Diversity", "CITES"], "answer": 0, "explanation": "COP-14 of the UNCCD was held at Greater Noida (Delhi NCR) in 2019; India set a target to restore 26 million hectares of degraded land by 2030. India had hosted CBD COP-11 at Hyderabad in 2012.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-68", "question": "Arrange these laws in chronological order: 1. Air (Prevention and Control of Pollution) Act  2. Water (Prevention and Control of Pollution) Act  3. Forest (Conservation) Act  4. Wildlife (Protection) Act", "options": ["4-3-2-1", "2-4-3-1", "4-2-1-3", "4-2-3-1"], "answer": 3, "explanation": "Wildlife (Protection) Act 1972, Water Act 1974, Forest (Conservation) Act 1980 and Air Act 1981. So 4-2-3-1.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-69", "question": "Match the environmental movement with its region. A. Chipko  B. Appiko  C. Jungle Bachao Andolan  D. Narmada Bachao Andolan; 1. Singhbhum, then in Bihar and now in Jharkhand  2. Garhwal Himalaya, now in Uttarakhand  3. Narmada valley  4. Uttara Kannada, Karnataka", "options": ["A-2, B-4, C-1, D-3", "A-4, B-2, C-1, D-3", "A-2, B-1, C-4, D-3", "A-2, B-4, C-3, D-1"], "answer": 0, "explanation": "Chipko began in Garhwal, Appiko in the Western Ghats of Karnataka, Jungle Bachao in Singhbhum against replacing sal forests with teak, and Narmada Bachao against the large dams on the Narmada.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-70", "question": "How many of the following statements about India's climate commitments are correct? I. India announced a net-zero emissions target for 2070 at COP-26 in Glasgow. II. The International Solar Alliance was launched by India and France at COP-21 in Paris. III. India's updated NDC aims for about half of its installed electric power capacity to come from non-fossil sources by 2030. IV. India accepted binding emission reduction targets under the Kyoto Protocol.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. Under Kyoto, binding targets applied only to developed (Annex I) countries, not India, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-71", "question": "Match the natural World Heritage Site with its state. A. Manas  B. Nanda Devi and Valley of Flowers  C. Great Himalayan National Park  D. Khangchendzonga National Park; 1. Himachal Pradesh  2. Sikkim  3. Assam  4. Uttarakhand", "options": ["A-3, B-4, C-2, D-1", "A-3, B-4, C-1, D-2", "A-4, B-3, C-1, D-2", "A-3, B-1, C-4, D-2"], "answer": 1, "explanation": "Manas is in Assam, Nanda Devi and Valley of Flowers in Uttarakhand, the Great Himalayan National Park in Himachal Pradesh and Khangchendzonga in Sikkim.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-72", "question": "Match the animal with the protected area known for it. A. Hoolock gibbon  B. Blackbuck  C. Hard-ground barasingha  D. Red panda; 1. Kanha, Madhya Pradesh  2. Singalila, West Bengal  3. Hollongapar Gibbon Sanctuary, Assam  4. Velavadar, Gujarat", "options": ["A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-3, B-1, C-4, D-2", "A-3, B-4, C-1, D-2"], "answer": 3, "explanation": "India's only ape, the hoolock gibbon, lives in Hollongapar; Velavadar is a blackbuck national park; Kanha saved the hard-ground barasingha from near-extinction; Singalila is known for red pandas.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-73", "question": "Assertion (A): Coral reefs turn white (bleach) when sea temperatures stay unusually high. Reason (R): Under heat stress, corals expel the symbiotic zooxanthellae algae that give them colour and food.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Corals depend on zooxanthellae for colour and most of their food. Warm water makes them expel the algae, leaving the white skeleton visible. R explains A.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-74", "question": "Assertion (A): Mangrove forests reduce the damage caused by storm surges and tsunamis on coasts. Reason (R): Mangroves grow best in fresh water, far from the sea.", "options": ["Both A and R are true and R is the correct explanation of A", "A is true but R is false", "Both A and R are true but R is not the correct explanation of A", "A is false but R is true"], "answer": 1, "explanation": "A is true: dense roots break waves and trap sediment. R is false: mangroves are salt-tolerant plants of the tidal zone in estuaries and deltas.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-75", "question": "Arrange these gases in increasing order of their 100-year global warming potential: 1. Nitrous oxide  2. Carbon dioxide  3. Sulphur hexafluoride  4. Methane", "options": ["2-1-4-3", "2-4-1-3", "4-2-1-3", "2-4-3-1"], "answer": 1, "explanation": "Taking CO₂ as 1, methane is about 28, nitrous oxide about 265 and SF₆ about 23,500. So 2-4-1-3.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-76", "question": "How many of the following are notified under the Environment (Protection) Act, 1986? I. Eco-sensitive zones around protected areas  II. The Coastal Regulation Zone notification  III. The Environmental Impact Assessment notification", "options": ["Only one", "Only two", "All three", "None"], "answer": 2, "explanation": "All three are issued under the EP Act. National parks and sanctuaries, by contrast, are declared under the Wildlife (Protection) Act, 1972.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-77", "question": "Which of the following is NOT a statutory body (created by an Act of Parliament)?", "options": ["Central Pollution Control Board", "National Biodiversity Authority", "Animal Welfare Board of India", "Wildlife Institute of India"], "answer": 3, "explanation": "The Wildlife Institute of India (Dehradun) is an autonomous institute of the Environment Ministry. The CPCB comes from the Water Act 1974, the NBA from the Biological Diversity Act 2002 and the AWBI from the Prevention of Cruelty to Animals Act 1960.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-78", "question": "Match the invasive plant with its description. A. Lantana camara  B. Prosopis juliflora  C. Eichhornia crassipes  D. Parthenium hysterophorus; 1. Floating water weed that chokes ponds, called the 'terror of Bengal'  2. 'Congress grass', a weed that causes allergies  3. Thorny Mexican shrub ('vilayati babul') spreading in dry areas  4. Flowering shrub that has invaded forests and tiger habitats", "options": ["A-4, B-3, C-1, D-2", "A-3, B-4, C-1, D-2", "A-4, B-3, C-2, D-1", "A-4, B-1, C-3, D-2"], "answer": 0, "explanation": "Lantana smothers forest undergrowth, Prosopis juliflora (vilayati babul) spreads in drylands, water hyacinth (Eichhornia) chokes water bodies and Parthenium is congress grass.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-79", "question": "How many of the following statements about biosphere reserves in India are correct? I. The Nilgiri Biosphere Reserve, set up in 1986, was India's first. II. The Gulf of Mannar Biosphere Reserve includes a marine national park. III. The Great Rann of Kutch is the largest biosphere reserve in India by area. IV. All of India's biosphere reserves are included in UNESCO's World Network of Biosphere Reserves.", "options": ["Only one", "Only three", "Only two", "All four"], "answer": 1, "explanation": "I, II and III are correct. Only some of India's biosphere reserves are on UNESCO's World Network, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-80", "question": "Match the UNFCCC Conference of Parties with its host city. A. COP-21  B. COP-26  C. COP-27  D. COP-28; 1. Dubai  2. Sharm el-Sheikh  3. Paris  4. Glasgow", "options": ["A-3, B-4, C-1, D-2", "A-4, B-3, C-2, D-1", "A-3, B-4, C-2, D-1", "A-3, B-2, C-4, D-1"], "answer": 2, "explanation": "COP-21 (2015) in Paris adopted the Paris Agreement, COP-26 (2021) was in Glasgow, COP-27 (2022) in Sharm el-Sheikh agreed to set up a loss and damage fund, and COP-28 (2023) was in Dubai.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-81", "question": "How many of the following statements about the Ganges river dolphin are correct? I. It is India's National Aquatic Animal. II. It is nearly blind and finds its way and food by echolocation. III. The Vikramshila Gangetic Dolphin Sanctuary is in Bihar. IV. It is listed as Endangered on the IUCN Red List.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. The dolphin was declared the National Aquatic Animal in 2009, and the Vikramshila sanctuary near Bhagalpur protects a stretch of the Ganga.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-82", "question": "Match the report with the organisation that publishes it. A. India State of Forest Report  B. Living Planet Report  C. Emissions Gap Report  D. Global Risks Report; 1. World Economic Forum  2. UNEP  3. Forest Survey of India  4. WWF", "options": ["A-3, B-4, C-2, D-1", "A-4, B-3, C-2, D-1", "A-3, B-2, C-4, D-1", "A-3, B-4, C-1, D-2"], "answer": 0, "explanation": "The Forest Survey of India (Dehradun) publishes the ISFR every two years, WWF the Living Planet Report, UNEP the Emissions Gap Report and the World Economic Forum the Global Risks Report.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-83", "question": "How many of the following statements are correct? I. The Forest Rights Act, 2006 recognises the forest rights of Scheduled Tribes and other traditional forest dwellers. II. Under that Act, the Gram Sabha starts the process of deciding individual and community rights. III. The Compensatory Afforestation Fund Act, 2016 governs funds collected for afforestation when forest land is diverted. IV. The National Biodiversity Authority, set up under the Biological Diversity Act, 2002, is headquartered in Chennai.", "options": ["Only two", "Only three", "Only one", "All four"], "answer": 3, "explanation": "All four statements are correct.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-84", "question": "How many of the following statements about the reintroduction of cheetahs in India are correct? I. The cheetah was declared extinct in India in 1952. II. Cheetahs were brought from Namibia and South Africa. III. They were first released in Kuno National Park in Madhya Pradesh. IV. The African cheetahs belong to the same subspecies as the extinct Asiatic cheetah.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. The animals brought in are African subspecies; the Asiatic cheetah now survives only in Iran, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-85", "question": "Which of the following is NOT one of the eight national missions under India's National Action Plan on Climate Change (2008)?", "options": ["National Solar Mission", "National Mission for a Green India", "National Mission on Clean Coal", "National Mission for Sustaining the Himalayan Ecosystem"], "answer": 2, "explanation": "The eight NAPCC missions are Solar, Enhanced Energy Efficiency, Sustainable Habitat, Water, Sustaining the Himalayan Ecosystem, Green India, Sustainable Agriculture and Strategic Knowledge for Climate Change. There is no clean-coal mission.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-86", "question": "In an ecosystem, the organisms that make their own food from sunlight are called:", "options": ["Producers", "Herbivores", "Decomposers", "Carnivores"], "answer": 0, "explanation": "Green plants, algae and some bacteria are producers (autotrophs); every food chain starts with them. Consumers and decomposers depend on the energy they fix.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "env-ecology-87", "question": "Which of these wastes is non-biodegradable?", "options": ["Vegetable peels", "Polythene bags", "Paper", "Cotton cloth"], "answer": 1, "explanation": "Microbes cannot readily break down most plastics such as polythene, so they persist for centuries. Peels, paper and cotton are decomposed naturally.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "env-ecology-88", "question": "Bacteria and fungi that break down dead plants and animals and return nutrients to the soil are called:", "options": ["Producers", "Primary consumers", "Decomposers", "Predators"], "answer": 2, "explanation": "Decomposers recycle nutrients locked in dead matter; without them, elements such as nitrogen and phosphorus would not return to the soil.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "env-ecology-89", "question": "The “3 Rs” of waste management stand for:", "options": ["Remove, Replace, Repair", "Recover, Refine, Resell", "Read, Recall, Revise", "Reduce, Reuse, Recycle"], "answer": 3, "explanation": "Reducing waste comes first, then reusing items, and finally recycling materials into new products.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "env-ecology-90", "question": "Which of these is the most effective way to check soil erosion on a slope?", "options": ["Maintaining a cover of trees and grass", "Removing all vegetation", "Overgrazing by cattle", "Ploughing straight down the slope"], "answer": 0, "explanation": "Plant roots bind soil and leaves break the force of rain. Clearing vegetation, overgrazing and ploughing up and down the slope all speed up erosion.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "env-ecology-91", "question": "Which biome has the highest biodiversity on land?", "options": ["Tundra", "Tropical rainforest", "Temperate grassland", "Hot desert"], "answer": 1, "explanation": "Warm temperatures, abundant rain all year and a long, stable history make tropical rainforests the richest terrestrial biome, though they cover a small share of the land.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "env-ecology-92", "question": "Which of these is an abiotic component of an ecosystem?", "options": ["Grass", "Earthworms", "Sunlight", "Fungi"], "answer": 2, "explanation": "Abiotic components are non-living factors such as sunlight, temperature, water and soil minerals. Grass, earthworms and fungi are biotic.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "env-ecology-93", "question": "In a food chain, herbivores such as deer and grasshoppers are:", "options": ["Producers", "Secondary consumers", "Decomposers", "Primary consumers"], "answer": 3, "explanation": "Herbivores eat producers directly and occupy the second trophic level as primary consumers; carnivores that eat them are secondary consumers.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "env-ecology-94", "question": "Ecological succession on abandoned farmland or after a forest fire, where soil is already present, is called:", "options": ["Secondary succession", "Primary succession", "Retrogressive succession", "Xerarch succession on bare rock"], "answer": 0, "explanation": "Secondary succession starts where a community was removed but soil remains, so it is faster. Primary succession begins on lifeless surfaces such as bare rock or new lava.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "env-ecology-95", "question": "Which of these is an example of in situ conservation?", "options": ["A zoo", "A national park", "A seed bank", "A botanical garden"], "answer": 1, "explanation": "In situ conservation protects species in their natural habitat, as in national parks and sanctuaries. Zoos, seed banks and botanical gardens conserve species outside it (ex situ).", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "env-ecology-96", "question": "A very high Biochemical Oxygen Demand (BOD) in a river indicates that the water:", "options": ["Is very clean", "Has a lot of dissolved oxygen", "Is heavily polluted with organic matter", "Is very cold"], "answer": 2, "explanation": "Microbes decomposing organic waste such as sewage use up dissolved oxygen, so a high BOD signals heavy organic pollution and low oxygen left for fish.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "env-ecology-97", "question": "Photochemical smog, typical of cities with heavy traffic and strong sunshine, contains mainly:", "options": ["Water droplets and smoke from coal", "Methane and carbon dioxide", "Chlorofluorocarbons", "Ozone, nitrogen oxides and peroxyacetyl nitrate (PAN)"], "answer": 3, "explanation": "Sunlight drives reactions between nitrogen oxides and hydrocarbons from vehicle exhaust, producing ozone and PAN. Classical (London) smog was smoke and sulphur dioxide with fog.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "env-ecology-98", "question": "The “ten per cent law” of energy transfer between trophic levels was proposed by:", "options": ["Raymond Lindeman", "Charles Darwin", "Eugene Odum", "A. G. Tansley"], "answer": 0, "explanation": "Lindeman (1942) observed that only about 10% of energy passes to the next trophic level. Tansley coined the term “ecosystem”.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "env-ecology-99", "question": "Fly ash, which is used to make bricks and cement, is a by-product of:", "options": ["Steel rolling mills", "Coal-based thermal power plants", "Nuclear power plants", "Hydroelectric dams"], "answer": 1, "explanation": "Burning pulverised coal leaves fine ash that is carried in flue gas; its safe use in bricks and cement reduces the need to dump it in ash ponds.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "env-ecology-100", "question": "An orchid growing on the branch of a mango tree gets support and light without harming the tree. This relationship is:", "options": ["Parasitism", "Mutualism", "Commensalism", "Predation"], "answer": 2, "explanation": "In commensalism one partner benefits while the other is unaffected. The orchid is an epiphyte, making its own food, not a parasite.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "env-ecology-101", "question": "In a tree-based ecosystem, where one large tree supports thousands of insects that are eaten by a few birds, the pyramid of numbers is:", "options": ["Upright", "Always rectangular", "Absent", "Inverted or spindle-shaped"], "answer": 3, "explanation": "Because a single tree supports many herbivores, the base is narrow and the next level wide, giving an inverted (spindle-shaped) pyramid of numbers. The pyramid of energy is never inverted.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-102", "question": "Chemical Oxygen Demand (COD) of a water sample is generally equal to or higher than its BOD because COD:", "options": ["Measures oxygen needed to oxidise both biodegradable and non-biodegradable matter", "Is measured over a longer period of 20 days", "Measures only the oxygen used by bacteria", "Ignores organic matter altogether"], "answer": 0, "explanation": "COD uses a strong chemical oxidant that oxidises almost all organic matter, while BOD counts only what microbes can break down, typically over 5 days; so COD ≥ BOD.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-103", "question": "A lichen is a classic example of which kind of interaction?", "options": ["Parasitism between two plants", "Mutualism between an alga (or cyanobacterium) and a fungus", "Predation by a fungus", "Competition between mosses"], "answer": 1, "explanation": "The photosynthetic partner supplies food while the fungus gives shelter and absorbs water and minerals; both benefit, which is mutualism.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-104", "question": "The mould Penicillium releases a substance that kills nearby bacteria while the mould itself is not affected. This interaction is called:", "options": ["Mutualism", "Commensalism", "Amensalism", "Parasitism"], "answer": 2, "explanation": "In amensalism one species is harmed and the other is unaffected. In parasitism the harming partner also benefits by feeding on the host.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-105", "question": "Net primary productivity (NPP) of an ecosystem is:", "options": ["The total energy fixed by plants, including what they use in respiration", "The energy stored in carnivores", "Energy lost as heat at each level", "Gross primary productivity minus the energy plants use in respiration"], "answer": 3, "explanation": "NPP = GPP − R. It is the organic matter actually available to herbivores and decomposers.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-106", "question": "A charismatic species such as the tiger or the giant panda, used to draw public support for conserving a whole habitat, is called a:", "options": ["Flagship species", "Keystone species", "Indicator species", "Invasive species"], "answer": 0, "explanation": "Flagship species are chosen for their public appeal; protecting them protects many other species sharing the habitat. A keystone species is defined by its outsized ecological role instead.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-107", "question": "Which of these biogeochemical cycles has no significant gaseous phase in the atmosphere?", "options": ["Carbon cycle", "Phosphorus cycle", "Nitrogen cycle", "Oxygen cycle"], "answer": 1, "explanation": "Phosphorus moves mainly through rocks, soil, water and living things (a sedimentary cycle), so it is slow and often limits plant growth. Carbon, nitrogen and oxygen cycle through the air.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-108", "question": "The carrying capacity of an environment refers to:", "options": ["The number of species in it", "The rate at which a population grows at the start", "The maximum population of a species it can support indefinitely with its resources", "The amount of rain it receives"], "answer": 2, "explanation": "Population growth slows as it nears the carrying capacity (K) because food, space and other resources run short, giving the S-shaped logistic curve.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-109", "question": "Species that produce very many offspring, give little parental care and thrive in unstable environments, such as many insects, are called:", "options": ["K-selected species", "Keystone species", "Endemic species", "r-selected species"], "answer": 3, "explanation": "r-selected species maximise reproductive rate (r). K-selected species, such as elephants and whales, have few young, long lives and heavy parental care.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-110", "question": "The “ecological footprint” of a population measures:", "options": ["The area of land and water needed to supply the resources it uses and absorb its wastes", "The number of trees it plants", "The length of roads in its territory", "The area of its protected forests"], "answer": 0, "explanation": "The footprint is usually expressed in global hectares and compared with the biocapacity available; a footprint larger than biocapacity indicates overuse.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-111", "question": "In cryopreservation, seeds, gametes or tissues are stored for long periods at about:", "options": ["0 °C in a refrigerator", "−196 °C in liquid nitrogen", "−18 °C in a deep freezer", "4 °C in cold rooms"], "answer": 1, "explanation": "At −196 °C, the temperature of liquid nitrogen, biological activity virtually stops, so genetic material can be preserved ex situ for decades.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-112", "question": "“Devrai” in Maharashtra, “Kavu” in Kerala, “Orans” in Rajasthan and “Law Kyntang” in Meghalaya are all names for:", "options": ["Traditional water tanks", "Shifting cultivation plots", "Sacred groves protected by local communities", "Seed banks"], "answer": 2, "explanation": "Sacred groves are patches of forest left untouched for religious reasons; they are a form of community-based in situ conservation and often shelter rare species.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-113", "question": "The most abundant greenhouse gas in the Earth's atmosphere is:", "options": ["Carbon dioxide", "Methane", "Nitrous oxide", "Water vapour"], "answer": 3, "explanation": "Water vapour contributes the most to the natural greenhouse effect, but its amount depends on temperature; carbon dioxide is the main gas whose rise from human activity drives warming.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-114", "question": "In ecology, alpha diversity refers to:", "options": ["Diversity of species within a particular habitat or community", "Change in species composition between habitats", "Total diversity of a whole region", "Genetic diversity within one species"], "answer": 0, "explanation": "Alpha diversity is within-habitat richness; beta diversity measures turnover between habitats; gamma diversity covers a whole landscape or region.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-115", "question": "Using plants such as sunflower or Indian mustard to absorb heavy metals from contaminated soil is called:", "options": ["Biomagnification", "Phytoremediation", "Eutrophication", "Vermicomposting"], "answer": 1, "explanation": "In phytoremediation plants take up, stabilise or break down pollutants. Biomagnification is the build-up of toxins along a food chain.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-116", "question": "Bioaccumulation, as distinct from biomagnification, refers to:", "options": ["The build-up of a toxic substance inside a single organism over its lifetime, faster than it can be excreted", "The rise in a toxin's concentration from one trophic level to the next", "The decomposition of toxins by bacteria", "The spread of an invasive species"], "answer": 0, "explanation": "Bioaccumulation happens within one organism, for example mercury building up in a fish as it ages; biomagnification is the increase in concentration along the food chain, as with DDT in fish-eating birds.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-117", "question": "Under the principle of Extended Producer Responsibility (EPR) applied to plastic packaging and e-waste in India, producers are responsible for:", "options": ["Only the quality of their products at the time of sale", "Collecting and ensuring the recycling or safe disposal of their products after consumers discard them", "Paying all municipal sanitation workers", "Manufacturing only biodegradable products"], "answer": 1, "explanation": "EPR shifts part of the burden of end-of-life waste from municipalities to producers, importers and brand owners, who must meet collection and recycling targets.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-118", "question": "How many of these statements about ecological pyramids are correct? I. The pyramid of energy is always upright. II. The pyramid of biomass can be inverted in some aquatic ecosystems. III. The pyramid of numbers can be inverted in a tree-based ecosystem. IV. In a pond, the pyramid of energy is usually inverted.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct; in the sea a small standing crop of fast-growing phytoplankton supports a larger biomass of zooplankton. Energy is lost at every transfer, so the energy pyramid can never be inverted; IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "env-ecology-119", "question": "Match the interaction with its effect on the two species (+ benefit, − harm, 0 no effect). A. Mutualism  B. Commensalism  C. Parasitism  D. Competition; 1. + / 0  2. + / −  3. + / +  4. − / −", "options": ["A-3, B-2, C-1, D-4", "A-1, B-3, C-2, D-4", "A-3, B-1, C-4, D-2", "A-3, B-1, C-2, D-4"], "answer": 3, "explanation": "Mutualism helps both partners, commensalism helps one and leaves the other unaffected, parasitism helps the parasite at the host's cost, and competition harms both.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-120", "question": "Assertion (A): Fish-eating birds can carry much higher concentrations of DDT than the fish they eat. Reason (R): DDT is fat-soluble and is not easily broken down or excreted, so it accumulates and is passed up the food chain.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Each predator eats many contaminated prey and retains the DDT in its fat, so concentrations multiply at each level; this thinned eggshells and crashed populations of birds of prey.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "env-ecology-121", "question": "How many of these statements about the nitrogen cycle are correct? I. Rhizobium in the root nodules of legumes fixes atmospheric nitrogen. II. Nitrosomonas converts ammonia into nitrite. III. Nitrobacter converts nitrite into nitrate. IV. Denitrifying bacteria convert nitrate into ammonia.", "options": ["Only one", "Only two", "All four", "Only three"], "answer": 3, "explanation": "I, II and III are correct. Denitrifying bacteria such as Pseudomonas reduce nitrate to nitrogen gas, returning it to the atmosphere, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-122", "question": "Arrange these stages of primary succession on bare rock in the order they appear: 1. Shrubs  2. Lichens  3. Grasses and herbs  4. Mosses", "options": ["2-4-3-1", "4-2-3-1", "2-3-4-1", "2-4-1-3"], "answer": 0, "explanation": "Crustose lichens are the pioneers that start weathering rock; mosses follow on the thin soil, then grasses and herbs, then shrubs, and finally a climax forest.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-123", "question": "How many of the following are ex situ methods of conservation? I. Seed bank  II. Sacred grove  III. Botanical garden  IV. Cryopreservation of gametes", "options": ["Only one", "Only three", "Only two", "All four"], "answer": 1, "explanation": "Seed banks, botanical gardens and cryopreservation keep species outside their natural habitat. A sacred grove protects species where they naturally occur, so it is in situ.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-124", "question": "Assertion (A): Lichens are useful indicators of air pollution. Reason (R): Many lichens are very sensitive to sulphur dioxide and disappear from heavily polluted areas.", "options": ["A is true but R is false", "Both A and R are true but R is not the correct explanation of A", "Both A and R are true and R is the correct explanation of A", "A is false but R is true"], "answer": 2, "explanation": "Lichens absorb water and minerals directly from the air and cannot shed toxins, so their absence or decline around industrial towns signals SO₂ pollution.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "env-ecology-125", "question": "How many of these statements about ozone are correct? I. Stratospheric ozone absorbs much of the Sun's harmful ultraviolet radiation. II. Ozone near the ground is a pollutant that harms lungs and crops. III. Ground-level ozone is a secondary pollutant formed from nitrogen oxides and volatile organic compounds in sunlight. IV. The largest seasonal ozone hole forms over the Arctic every year.", "options": ["Only three", "Only one", "Only two", "All four"], "answer": 0, "explanation": "I, II and III are correct. The large recurring ozone hole forms over Antarctica in the southern spring, helped by its very cold polar stratospheric clouds, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "env-ecology-126", "question": "Match the pollutant with its source or effect. A. Carbon monoxide  B. Sulphur dioxide  C. Lead  D. Nitrogen oxides; 1. Binds to haemoglobin, reducing oxygen supply to tissues  2. Released mainly by burning coal, a major cause of acid rain  3. A neurotoxin once emitted widely from leaded petrol  4. Formed in high-temperature combustion in engines; a precursor of photochemical smog", "options": ["A-1, B-3, C-2, D-4", "A-2, B-1, C-3, D-4", "A-1, B-2, C-3, D-4", "A-1, B-2, C-4, D-3"], "answer": 2, "explanation": "CO forms carboxyhaemoglobin; SO₂ from coal forms sulphuric acid in rain; lead harms the nervous system, especially in children, which is why leaded petrol was phased out; NOₓ from vehicles drives smog and ozone formation.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-127", "question": "Arrange these biomes in decreasing order of average net primary productivity per unit area: 1. Desert  2. Tropical rainforest  3. Temperate grassland  4. Temperate deciduous forest", "options": ["2-3-4-1", "4-2-3-1", "2-4-1-3", "2-4-3-1"], "answer": 3, "explanation": "Warmth and moisture all year make tropical rainforests most productive, followed by temperate forests, then temperate grasslands; deserts, short of water, are the least productive.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "env-ecology-128", "question": "How many of these statements about mangroves are correct? I. Many mangroves have breathing roots (pneumatophores) that grow up out of the mud. II. Some mangrove species show vivipary, with seeds germinating while still on the parent tree. III. Mangroves tolerate saline, tidal water. IV. Mangroves are found mainly along temperate coasts.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. Mangroves grow along tropical and subtropical coasts and estuaries, such as the Sundarbans and Bhitarkanika, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-129", "question": "Assertion (A): Air quality in Delhi often worsens sharply on calm winter nights. Reason (R): A temperature inversion places warmer air above cooler surface air, preventing vertical mixing and trapping pollutants near the ground.", "options": ["Both A and R are true but R is not the correct explanation of A", "Both A and R are true and R is the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 1, "explanation": "With low wind and an inversion lid, emissions from vehicles, industry and crop-residue burning accumulate close to the ground; daytime heating breaks the inversion and lets them disperse.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "env-ecology-130", "question": "Match the term with its meaning. A. Ecotone  B. Niche  C. Habitat  D. Edge effect; 1. The physical place where an organism lives  2. The functional role of a species, including the resources it uses  3. A transition zone between two communities  4. The tendency for a transition zone to have greater variety and density of species", "options": ["A-3, B-2, C-1, D-4", "A-2, B-3, C-1, D-4", "A-3, B-1, C-2, D-4", "A-3, B-2, C-4, D-1"], "answer": 0, "explanation": "A habitat is an address, a niche a profession. Ecotones such as forest edges or estuaries often hold species from both sides plus their own, which is the edge effect.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "env-ecology-131", "question": "How many of these statements about greenhouse gases are correct? I. Per kilogram, methane traps far more heat than carbon dioxide over a 100-year period. II. Nitrous oxide is released from fertilised agricultural soils. III. HFCs do not deplete the ozone layer but are powerful greenhouse gases. IV. CFCs deplete ozone but have no greenhouse effect.", "options": ["Only one", "Only three", "Only two", "All four"], "answer": 1, "explanation": "I, II and III are correct; HFCs are being phased down under the Kigali Amendment for this reason. CFCs are also very potent greenhouse gases, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "env-ecology-132", "question": "Arrange these international environmental conferences in chronological order: 1. Rio Earth Summit (UN Conference on Environment and Development)  2. Stockholm Conference on the Human Environment  3. World Summit on Sustainable Development, Johannesburg  4. Rio+20 Conference on Sustainable Development", "options": ["1-2-3-4", "2-3-1-4", "2-1-3-4", "2-1-4-3"], "answer": 2, "explanation": "Stockholm was held in 1972 (and led to UNEP), the Rio Earth Summit in 1992, Johannesburg in 2002 and Rio+20 in 2012.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "env-ecology-133", "question": "Assertion (A): Invasive plants such as water hyacinth can choke lakes and rivers in India. Reason (R): In a new region they often lack natural enemies and spread rapidly, crowding out native species.", "options": ["A is true but R is false", "A is false but R is true", "Both A and R are true but R is not the correct explanation of A", "Both A and R are true and R is the correct explanation of A"], "answer": 3, "explanation": "Water hyacinth, a South American plant, forms dense mats that block light and deplete oxygen; freed from its native herbivores, it multiplies unchecked.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "env-ecology-134", "question": "How many of these statements about plastic pollution are correct? I. India banned a list of identified single-use plastic items from 1 July 2022. II. Extended Producer Responsibility makes brand owners responsible for collecting their plastic packaging. III. Microplastics are plastic particles smaller than 5 mm. IV. Plastics labelled biodegradable break down fully within a few days in any environment.", "options": ["Only three", "Only one", "Only two", "All four"], "answer": 0, "explanation": "I, II and III are correct. Most 'biodegradable' plastics need specific conditions such as industrial composting and can persist for long periods in soil or sea, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "env-ecology-135", "question": "Match the body with the law under which it was set up. A. Central Pollution Control Board  B. National Tiger Conservation Authority  C. National Green Tribunal  D. National Biodiversity Authority; 1. Biological Diversity Act, 2002  2. National Green Tribunal Act, 2010  3. Wildlife (Protection) Act, 1972, as amended in 2006  4. Water (Prevention and Control of Pollution) Act, 1974", "options": ["A-4, B-2, C-3, D-1", "A-4, B-3, C-2, D-1", "A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2"], "answer": 1, "explanation": "The CPCB was constituted under the Water Act of 1974 and later given Air Act functions; the NTCA came through the 2006 amendment of the Wildlife Act; the NGT has its own Act of 2010; the NBA, in Chennai, was set up under the Biological Diversity Act.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id":"env-ecology-136","question":"Consider the following statements about productivity in an ecosystem: 1. Net primary productivity equals gross primary productivity minus the energy used by producers in respiration. 2. Secondary productivity is the rate at which consumers form new organic matter. 3. In a mature climax forest, the net productivity of the whole community tends towards zero. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three hold: NPP = GPP − R of producers; secondary productivity is consumer production; at climax total community respiration nearly balances GPP, so net ecosystem productivity approaches zero even though NPP itself is still positive.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-137","question":"The open ocean covers most of the Earth's surface yet has a low net primary productivity per unit area. The main reason is that its sunlit surface waters are:","options":["Too poorly lit for photosynthesis by phytoplankton","Short of nutrients such as nitrogen, phosphorus and iron","Short of dissolved carbon dioxide for photosynthesis","Too cold throughout the year for algal growth"],"answer":1,"explanation":"Light is ample in the surface layer and dissolved inorganic carbon is plentiful; productivity is limited because nutrients sink below the sunlit zone, which is why upwelling zones and coasts are far more productive.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-138","question":"In a lake, the standing biomass of phytoplankton measured at one moment is smaller than that of the zooplankton that graze on it. This is possible because:","options":["Zooplankton are partly autotrophic and make some of their own food","In aquatic systems more energy reaches each higher trophic level","Phytoplankton reproduce very fast, so a small standing crop yields a large flow of food over time","The pyramid of energy in such lakes is also inverted"],"answer":2,"explanation":"Biomass is a snapshot; fast turnover lets a small phytoplankton stock support a larger zooplankton stock. Energy flow over time still decreases upward, so the energy pyramid stays upright.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-139","question":"A grassland receives 2,000,000 J of sunlight and its producers convert 1 per cent of it into net primary production. If 10 per cent of the energy passes from one trophic level to the next, how much energy reaches the secondary consumers?","options":["2,000 J","20 J","20,000 J","200 J"],"answer":3,"explanation":"NPP = 20,000 J; primary consumers get 2,000 J; secondary consumers get 200 J. 2,000 J is the herbivore level and 20 J the tertiary level.","difficulty":"moderate","source":"UPSC Prelims · CDS"},
  {"id":"env-ecology-140","question":"Consider the following statements about food chains: 1. In many forests, more energy flows through the detritus food chain than through the grazing food chain. 2. The detritus food chain begins with dead organic matter and its decomposers are mainly fungi and bacteria. 3. The detritus and grazing food chains are entirely separate, with no organism common to both. Which of the statements given above are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Most forest NPP is never eaten alive and enters the detritus chain; the two chains are linked because animals of the grazing chain die into detritus and some detritivores are eaten by grazing-chain predators.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-141","question":"Consider the following statements about decomposition of leaf litter: 1. Litter rich in lignin and chitin decomposes more slowly than litter rich in nitrogen and water-soluble sugars. 2. Waterlogged, oxygen-poor conditions speed up decomposition. 3. Leaching carries water-soluble inorganic nutrients from the detritus down into the soil. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":2,"explanation":"Lignin and chitin are resistant while nitrogen-rich, sugary litter breaks down fast; anaerobic waterlogging slows decomposition, which is why peat builds up in bogs.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-142","question":"With reference to ecosystem terms, consider the following statements: 1. 'Standing crop' is the mass of living material present at a trophic level at a particular time. 2. 'Standing state' is the amount of inorganic nutrients present in the soil at a particular time. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Both definitions are correct: standing crop is living biomass at a level, and standing state is the stock of nutrients such as N, P and Ca held in the soil at a given time.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-143","question":"Consider the following statements: 1. Photosynthetically active radiation makes up less than half of the solar radiation reaching the Earth's surface. 2. Green plants capture only a small fraction, of the order of 2–10 per cent, of the photosynthetically active radiation. 3. Energy flow in an ecosystem is cyclic, because decomposers return energy to the producers. Which of the statements given above are correct?","options":["1, 2 and 3","1 and 3 only","2 and 3 only","1 and 2 only"],"answer":3,"explanation":"Nutrients cycle but energy flows one way and leaves as heat; decomposers release energy in respiration rather than handing it back to plants.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-144","question":"Assertion (A): A complex food web is generally more stable than a single, simple food chain. Reason (R): In a food web, when one food source declines, consumers can switch to alternative prey. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Multiple feeding links give alternative pathways for energy, so the loss of one species does not collapse the whole system; that redundancy is exactly why webs are more stable.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-145","question":"Consider the following statements: 1. A single species can occupy more than one trophic level in the same ecosystem at the same time. 2. A trophic level refers to a particular species rather than to a functional feeding position. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"A trophic level is a functional position, not a species; an omnivore such as a bear eating berries and fish is a primary and a higher consumer at once, so statement 2 is wrong.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-146","question":"Food chains in nature rarely have more than four or five links. The main reason is that:","options":["Top predators would become too large to find enough space","Nutrients are not recycled to the higher trophic levels","Biomagnified poisons kill every predator above the fourth level","So much energy is lost at each transfer that little is left to support another level"],"answer":3,"explanation":"Roughly 90 per cent of energy is lost as heat and in respiration at each step, so beyond four or five levels too little energy remains to sustain a viable population.","difficulty":"moderate","source":"UPSC Prelims · CDS"},
  {"id":"env-ecology-147","question":"Which of the following are recognised limitations of ecological pyramids? 1. They do not account for the same species belonging to two or more trophic levels. 2. They give no place to saprophytes, even though these play a vital role in the ecosystem. 3. They assume a simple food chain, which seldom exists in nature. Select the correct answer.","options":["1 only","2 only","1, 2 and 3","1 and 3 only"],"answer":2,"explanation":"All three are standard limitations: pyramids ignore species spanning levels, leave out decomposers and saprophytes, and assume a linear chain rather than a web.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-148","question":"A pyramid of biomass can be inverted, but a pyramid of energy cannot. Which of the following best explains the difference?","options":["Biomass is a snapshot of standing crop, while the energy pyramid records flow over time, and no level can receive more energy than the level below supplies","Energy is measured as dry weight, while biomass is measured in joules","Decomposers are included only in the pyramid of energy","The pyramid of biomass leaves out the producers"],"answer":0,"explanation":"Fast-turnover producers can have small standing biomass, but energy passed per unit time must fall at each level because of respiratory losses, so the energy pyramid is always upright.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-149","question":"Consider the following statements: 1. According to Gause's principle, two species competing for the same limiting resource cannot coexist indefinitely. 2. Resource partitioning, such as related warblers feeding in different parts of the same tree, can allow similar species to coexist. Which of the statements given above is/are correct?","options":["1 only","2 only","Neither 1 nor 2","Both 1 and 2"],"answer":3,"explanation":"Competitive exclusion predicts that the inferior competitor is eliminated, unless the species divide the resource, as MacArthur showed for warblers foraging in different parts of a tree.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-150","question":"In the classification of ecosystem services used by the Millennium Ecosystem Assessment, soil formation and nutrient cycling fall under:","options":["Regulating services","Supporting services","Provisioning services","Cultural services"],"answer":1,"explanation":"Supporting services underpin all others; regulating services include climate regulation and pollination, provisioning covers goods such as food and timber, and cultural covers recreation and spiritual value.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-151","question":"Consider the following statements about biomes: 1. The taiga is dominated by coniferous evergreen trees. 2. In tropical savannas, a long dry season and periodic fires help keep tree cover sparse. 3. Temperate grasslands have poor soils because most nutrients are locked up in the living vegetation. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Temperate grasslands have some of the most fertile soils (deep, humus-rich); it is the tropical rainforest whose nutrients are held mainly in the biomass.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-152","question":"When a patch of tropical rainforest is cleared for farming, the land often loses its fertility within a few years. This is mainly because:","options":["Rainforest soils are naturally saline","The forest canopy had been fixing all the soil's nitrogen","Most nutrients were held in the living biomass, and heavy rain leaches the thin soil once the cover is gone","Rainforest soils contain too much undecomposed humus"],"answer":2,"explanation":"Rapid decomposition and uptake keep nutrients in the vegetation, not the soil; after clearing, intense rainfall leaches the remaining nutrients and lateritic soils harden.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-153","question":"Consider the following statements about deep lakes in temperate regions: 1. Fresh water is densest at about 4 °C. 2. In spring and autumn, the whole lake may mix (overturn), carrying oxygen downwards and nutrients upwards. 3. In summer, the bottom layer (hypolimnion) is warmer than the surface layer (epilimnion). Which of the statements given above are correct?","options":["1, 2 and 3","1 and 2 only","2 and 3 only","1 only"],"answer":1,"explanation":"In summer warm, light water sits on top and cold dense water below, separated by the thermocline; when the surface reaches about 4 °C in autumn and spring the lake can mix.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-154","question":"The profundal zone of a deep lake is best described as the zone where:","options":["Rooted plants grow along the shallow margins","Phytoplankton photosynthesis is at its maximum","Water temperature changes fastest with depth","Too little light reaches for photosynthesis, so life depends on organic matter sinking from above"],"answer":3,"explanation":"The littoral zone has rooted plants and the limnetic zone holds most phytoplankton; the dark profundal zone relies on detritus raining down, while the rapid temperature change describes the thermocline.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-155","question":"Consider the following statements: 1. In clear ocean water, the euphotic zone in which photosynthesis is possible extends to a depth of about 2,000 m. 2. Communities around deep-sea hydrothermal vents depend on chemosynthetic bacteria rather than sunlight as their primary energy source. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":1,"explanation":"The euphotic zone reaches only about 200 m at most; vent communities are built on bacteria that oxidise chemicals such as hydrogen sulphide.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-156","question":"Arctic foxes have noticeably shorter ears and limbs than foxes living in hot deserts. This pattern is described by:","options":["Allen's rule","Bergmann's rule","Gloger's rule","Liebig's law of the minimum"],"answer":0,"explanation":"Allen's rule: endotherms in cold climates have shorter extremities to reduce heat loss. Bergmann's rule concerns overall body size, and Gloger's rule concerns pigmentation.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-157","question":"Consider the following statements: 1. Liebig's law of the minimum says that growth is limited by the essential resource in shortest supply rather than by the total of all resources. 2. Shelford's law of tolerance says that an organism's distribution is limited by both the minimum and the maximum levels of an environmental factor. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Liebig focused on the scarcest factor; Shelford extended this by showing that too much of a factor can be as limiting as too little.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-158","question":"Which of the following pairs are correctly matched? 1. Euryhaline — tolerates a wide range of salinity 2. Stenothermal — tolerates a wide range of temperature 3. Ectotherm — body temperature largely follows that of the surroundings. Select the correct answer.","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":2,"explanation":"'Steno-' means narrow: stenothermal organisms tolerate only a narrow temperature range; the wide-range term is eurythermal.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-159","question":"Very small mammals and birds, such as shrews and hummingbirds, are rarely found in polar regions. The best explanation is that:","options":["Their eggs cannot develop below freezing point","Their high surface-area-to-volume ratio makes them lose body heat fast, so keeping warm costs too much energy","They are ectotherms and cannot regulate body temperature","Polar regions have no insects or nectar at any time of year"],"answer":1,"explanation":"Small endotherms lose heat rapidly through their relatively large surface and must burn energy fast to stay warm; shrews and hummingbirds are endotherms, not ectotherms.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-160","question":"In hydrarch succession, which begins in a pond or lake, the pioneer community usually consists of:","options":["Lichens","Rooted submerged plants","Phytoplankton","Mosses"],"answer":2,"explanation":"Phytoplankton colonise open water first, followed by rooted submerged and floating plants, reed swamp, sedge meadow and finally woodland; lichens are pioneers on bare rock.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-161","question":"Consider the following statements about ecological succession: 1. Both hydrarch and xerarch successions tend to move towards a mesic (moderate moisture) climax. 2. Secondary succession is usually faster than primary succession because soil is already present. 3. Net community productivity is higher in a climax community than in early successional stages. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Early stages accumulate biomass fast; at climax respiration nearly balances production, so net community productivity falls towards zero.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-162","question":"A species such as a reef-building coral or a giant kelp, whose physical structure creates the habitat on which a whole community depends, is best termed a:","options":["Keystone species","Flagship species","Indicator species","Foundation species"],"answer":3,"explanation":"Foundation species build habitat, usually by sheer abundance; keystone species have influence out of proportion to their abundance, often as predators.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-163","question":"After sea otters were hunted out of parts of the North Pacific coast, sea urchins multiplied and kelp forests collapsed. This sequence is an example of:","options":["A trophic cascade set off by the loss of a keystone predator","Biomagnification along a marine food chain","Competitive exclusion between urchins and kelp","Bottom-up control by nutrient supply"],"answer":0,"explanation":"Removing the top predator released the herbivore, which overgrazed the producer: a classic top-down trophic cascade.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-164","question":"Which of the following pairs of organism and what its presence indicates are correctly matched? 1. Lichens on tree bark — low sulphur dioxide pollution 2. Mayfly and stonefly nymphs — clean, well-oxygenated stream water 3. Dense populations of Tubifex worms — organically polluted, oxygen-poor water. Select the correct answer.","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Lichens are SO2-sensitive, mayfly and stonefly nymphs need high dissolved oxygen, and Tubifex tolerates low oxygen, so it thrives where sewage pollution is heavy.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-165","question":"Which of the following properties make a chemical likely to biomagnify along a food chain? 1. It persists for a long time without breaking down. 2. It is highly soluble in water and easily excreted. 3. It is soluble in fat and stored in body tissues. Select the correct answer.","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Persistent, fat-soluble compounds such as DDT and methylmercury accumulate; water-soluble substances are excreted and do not concentrate up the chain.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-166","question":"Consider the following statements about population growth: 1. Exponential (J-shaped) growth occurs when resources are effectively unlimited. 2. In the logistic model, the absolute growth rate (dN/dt) is highest when the population is at its carrying capacity. 3. In exponential growth, the per capita growth rate r stays constant. Which of the statements given above are correct?","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"In the logistic model dN/dt = rN(1 − N/K) peaks at N = K/2 and falls to zero at K; the trap is to think growth is fastest at the carrying capacity.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-167","question":"Which of the following are typical of K-selected species? 1. Late maturity and a long life span 2. Few offspring with a high level of parental care 3. A Type III survivorship curve with very heavy juvenile mortality. Select the correct answer.","options":["1, 2 and 3","2 and 3 only","1 and 2 only","3 only"],"answer":2,"explanation":"K-selected species such as elephants and great apes invest heavily in few young and show a Type I curve; heavy early mortality (Type III) is typical of r-selected species such as oysters.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-168","question":"In oysters and many fishes, the great majority of individuals die very young, and the few that survive live for a long time. Such populations show a survivorship curve of:","options":["Type I","Type III","Type II","A line that rises with age"],"answer":1,"explanation":"Type III curves fall steeply at the start; Type I (humans, large mammals) stays high until old age, and Type II shows a constant death rate.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-169","question":"An urn-shaped age pyramid, narrower at the base (young) than in the middle age groups, indicates a population that is:","options":["Expanding rapidly","Stable in size","Declining","At carrying capacity with a high birth rate"],"answer":2,"explanation":"Fewer young than adults means fewer future parents, so the population will shrink; a broad-based triangle shows growth and a bell shape a stable population.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-170","question":"The Asian koel lays its eggs in the nest of the house crow, which then raises the koel's chicks. This interaction is an example of:","options":["Commensalism","Amensalism","Mutualism","Brood parasitism"],"answer":3,"explanation":"The crow spends effort raising another species' young and gains nothing, so it is harmed; the koel's eggs often resemble the host's to avoid detection.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-171","question":"Consider the following pairs of interaction and its type: 1. Mycorrhiza between fungi and plant roots — mutualism 2. Cuscuta growing on hedge plants — parasitism 3. Cattle egrets foraging near grazing cattle — commensalism 4. Barnacles growing on the back of a whale — amensalism. How many of the pairs given above are correctly matched?","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Barnacles gain a moving home while the whale is barely affected, which is commensalism, not amensalism; the other three pairs are correct.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-172","question":"The flower of the Mediterranean orchid Ophrys resembles the female of a bee species, so that males attempt to mate with it and carry away pollen. This is best described as:","options":["Pollination by sexual deceit (pseudocopulation)","Brood parasitism","Commensalism in which the bee benefits","Obligate mutualism in which both partners gain food"],"answer":0,"explanation":"The bee gets no reward; the orchid exploits the male's mating behaviour, so this is deceptive pollination rather than mutualism.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-173","question":"Which of the following are ecological roles of predators? 1. Transferring energy fixed by plants to higher trophic levels 2. Keeping prey populations in check 3. Helping maintain species diversity by reducing competition among prey species. Select the correct answer.","options":["1, 2 and 3","1 and 2 only","2 only","1 and 3 only"],"answer":0,"explanation":"All three apply; Paine's experiment of removing the starfish Pisaster from a rocky shore led to the loss of more than ten invertebrate species as one dominant competitor took over.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-174","question":"The prickly pear cactus, introduced into Australia, spread over millions of hectares until a cactus-eating moth from its native range was released there. This episode best illustrates:","options":["Competitive exclusion between native and alien cacti","An invasive species spreading in the absence of natural enemies, and its biological control","Co-extinction of a plant and its pollinator","Ecological succession reaching a climax"],"answer":1,"explanation":"Freed from its natural predators, the cactus became invasive; reintroducing a specialist herbivore (Cactoblastis) brought it under control.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-175","question":"Consider the following statements about the carbon cycle: 1. The oceans hold far more carbon than the atmosphere. 2. Photosynthesis and respiration are the main fluxes of carbon between living things and the atmosphere. 3. Weathering of carbonate rocks is the main way carbon returns quickly to the atmosphere. Which of the statements given above are correct?","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"Rock weathering and sedimentation move carbon over geological time, not quickly; the fast exchanges are photosynthesis, respiration, decomposition, ocean exchange and combustion.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-176","question":"The ocean's 'biological pump' refers to:","options":["Upwelling currents that bring nutrients to the surface","The exchange of CO2 between air and sea driven only by temperature","The pumping of oxygen into deep water by marine animals","Phytoplankton fixing CO2 at the surface, part of which sinks as dead organic matter to the deep ocean"],"answer":3,"explanation":"The biological pump moves carbon downward through sinking organic matter; the temperature-driven exchange is called the solubility pump.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-177","question":"Consider the following statements about the nitrogen cycle: 1. Denitrification converts nitrate into nitrogen gas and takes place mainly in oxygen-poor soils. 2. Lightning fixes some atmospheric nitrogen into compounds that reach the soil with rain. 3. Ammonification converts nitrates into ammonia. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Ammonification is the release of ammonia from the organic nitrogen in dead matter and wastes by decomposers, not the conversion of nitrate.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-178","question":"Which one of the following pairs is NOT correctly matched?","options":["Azotobacter — free-living aerobic nitrogen fixer","Frankia — nitrogen fixer in the root nodules of non-legumes such as alder","Anabaena — cyanobacterium that fixes nitrogen in heterocysts","Nitrobacter — converts atmospheric nitrogen into ammonia"],"answer":3,"explanation":"Nitrobacter is a nitrifying bacterium that oxidises nitrite to nitrate; it does not fix atmospheric nitrogen.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-179","question":"The pink pigment leghaemoglobin found in the root nodules of legumes helps nitrogen fixation by:","options":["Binding oxygen and so protecting the oxygen-sensitive enzyme nitrogenase","Supplying iron that the bacteria use to make ammonia","Storing the fixed nitrogen until the plant needs it","Carrying carbon dioxide out of the nodule"],"answer":0,"explanation":"Nitrogenase is inactivated by oxygen; leghaemoglobin acts as an oxygen scavenger while still supplying enough for bacterial respiration.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-180","question":"Consider the following statements about the phosphorus cycle: 1. Sedimentary rocks are the main natural reservoir of phosphorus. 2. Guano deposited by seabirds returns some phosphorus from the sea to land. 3. Rainfall supplies more phosphorus to ecosystems than weathering of rocks does. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Phosphorus has no significant gaseous phase, so atmospheric input is tiny; weathering of phosphate rock is the main natural source.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-181","question":"Consider the following statements about the sulphur cycle: 1. Dimethyl sulphide released by marine phytoplankton is a natural source of atmospheric sulphur that can help form cloud-condensation nuclei. 2. Volcanic eruptions release sulphur dioxide into the atmosphere. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Both are natural sulphur sources; sulphate aerosols formed from DMS and volcanic SO2 seed clouds and reflect sunlight.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-182","question":"The largest store of fresh water on Earth is held in:","options":["Groundwater aquifers","Ice caps and glaciers","Lakes and rivers","Water vapour in the atmosphere"],"answer":1,"explanation":"About two-thirds of fresh water is frozen in ice sheets and glaciers; groundwater is the next largest store, while lakes and rivers hold a very small fraction.","difficulty":"moderate","source":"UPSC Prelims · CDS"},
  {"id":"env-ecology-183","question":"Assertion (A): Large-scale deforestation in the Amazon basin can reduce rainfall in regions downwind. Reason (R): A large share of the rainfall over the basin is moisture recycled into the air by the forest's evapotranspiration. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Forests pump soil water back into the air; removing them cuts this recycled moisture, so less rain falls further along the airflow.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-184","question":"Which of the following biogeochemical cycles are conventionally classified as gaseous cycles? 1. Nitrogen 2. Phosphorus 3. Carbon. Select the correct answer.","options":["2 only","1, 2 and 3","1 and 2 only","1 and 3 only"],"answer":3,"explanation":"Nitrogen and carbon have large atmospheric pools; phosphorus is a sedimentary cycle with no significant gaseous phase.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-185","question":"David Tilman's long-term field experiments on grassland plots showed that plots with more plant species tended to have:","options":["Lower total biomass but greater year-to-year variation","Higher rates of invasion by alien species","Less year-to-year variation in total biomass and higher productivity","No measurable difference from plots with fewer species"],"answer":2,"explanation":"The experiments supported the idea that greater diversity makes an ecosystem's productivity more stable over time.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-186","question":"The 'rivet popper' hypothesis, proposed by Paul Ehrlich, compares species in an ecosystem to the rivets in an aircraft wing. It suggests that:","options":["Every species is equally important, so the loss of any one causes immediate collapse","Losing species has no effect, because others always take their place","Only alien species weaken an ecosystem","The loss of a few species may not show at once, but continued losses weaken the system until it fails, and some species matter more than others"],"answer":3,"explanation":"A plane can lose a few rivets safely, but each loss erodes the margin, and losing a key rivet on the wing is more dangerous than losing one on a seat.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-187","question":"The medicinal plant Rauwolfia vomitoria growing in different Himalayan ranges varies in the potency and concentration of the chemical reserpine it produces. This is an example of:","options":["Genetic diversity","Species diversity","Ecological diversity","Gamma diversity"],"answer":0,"explanation":"The variation lies within one species, so it is genetic diversity; species and ecological diversity concern differences between species and between ecosystems.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-188","question":"Consider the following statements: 1. Gamma diversity is the diversity of a whole region or landscape. 2. Beta diversity between two communities is zero if they have exactly the same species. 3. Alpha diversity is the diversity within a single community or habitat. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Beta diversity measures turnover in species composition between habitats, so identical communities have zero beta diversity; alpha is local and gamma regional.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-189","question":"Consider the following statements about the species–area relationship: 1. Within a region, the number of species rises as the area explored increases, but only up to a limit. 2. On a log–log plot, the slope of the line is much steeper when very large areas such as whole continents are compared. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Humboldt's relationship gives a slope Z of about 0.1–0.2 within regions, but about 0.6–1.2 for very large areas such as continents.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-190","question":"Which of the following are proposed explanations for the greater species diversity of the tropics? 1. Tropical regions have remained relatively undisturbed for millions of years, with no glaciation. 2. Tropical environments are less seasonal and more predictable. 3. More solar energy is available, which supports higher productivity. Select the correct answer.","options":["1 and 2 only","2 and 3 only","1, 2 and 3","1 only"],"answer":2,"explanation":"All three are standard hypotheses: long evolutionary time without glacial disturbance, environmental stability that favours niche specialisation, and greater energy input.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-191","question":"Which of the following is NOT one of the four causes of biodiversity loss grouped as the 'Evil Quartet'?","options":["Co-extinctions","Climate change","Alien species invasions","Over-exploitation"],"answer":1,"explanation":"The Evil Quartet is habitat loss and fragmentation, over-exploitation, alien species invasions and co-extinctions; climate change is a serious threat but is not one of the four.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-192","question":"The extinction of many native cichlid fish species in Lake Victoria after the Nile perch was introduced is an example of which cause of biodiversity loss?","options":["Co-extinction","Over-exploitation","Habitat fragmentation","Invasion by an alien species"],"answer":3,"explanation":"The introduced predator ate its way through the native cichlids; co-extinction is when a dependent species is lost along with its host or partner.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-193","question":"Consider the following statements about habitat fragmentation: 1. It increases the proportion of edge habitat relative to interior habitat. 2. Large mammals and birds that need big territories are badly affected. 3. It always increases the number of species that live in the forest interior. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 only","1, 2 and 3"],"answer":0,"explanation":"Fragmentation shrinks interior habitat and favours edge species; interior specialists and wide-ranging animals decline.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-194","question":"According to the theory of island biogeography, which of the following islands would be expected to hold the largest number of species at equilibrium?","options":["A small island far from the mainland","A large island close to the mainland","A small island close to the mainland","A large island far from the mainland"],"answer":1,"explanation":"Large islands have lower extinction rates and near islands receive more immigrants; the theory is also used to argue for large, connected protected areas.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-195","question":"Wildlife corridors that link separate protected areas mainly help conservation by:","options":["Raising the number of tourists in each area","Keeping all predators out of the protected areas","Allowing animals to move and breed between populations, which maintains gene flow and reduces inbreeding","Ending the need for any buffer zone around the protected areas"],"answer":2,"explanation":"Isolated small populations lose genetic diversity and face local extinction; corridors reconnect them and allow seasonal movement and recolonisation.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-196","question":"Which of the following biodiversity hotspots include part of India's territory? 1. Himalaya 2. Indo-Burma 3. Sundaland 4. Mountains of Southwest China. Select the correct answer.","options":["1 and 2 only","1, 2 and 3 only","2 and 3 only","1, 2, 3 and 4"],"answer":1,"explanation":"India shares the Himalaya, Indo-Burma, Western Ghats–Sri Lanka and Sundaland (through the Nicobar Islands) hotspots; the Mountains of Southwest China hotspot lies wholly outside India.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-197","question":"A species whose only surviving individuals are in zoos and captive-breeding centres, with none left in its natural range, is classified by the IUCN as:","options":["Critically Endangered","Extinct","Extinct in the Wild","Data Deficient"],"answer":2,"explanation":"'Extinct in the Wild' means it survives only in cultivation, in captivity or as a naturalised population well outside its past range; 'Extinct' means no individual survives anywhere.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-198","question":"Which of the following IUCN Red List categories are grouped together as 'threatened'? 1. Near Threatened 2. Vulnerable 3. Endangered 4. Critically Endangered. Select the correct answer.","options":["2, 3 and 4 only","1, 2, 3 and 4","3 and 4 only","1 and 4 only"],"answer":0,"explanation":"Only Vulnerable, Endangered and Critically Endangered are 'threatened'; despite its name, Near Threatened is a separate category for species close to qualifying.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-199","question":"With reference to the IUCN Red List, consider the following statements: 1. 'Data Deficient' means a species has been assessed, but there is too little information to judge its risk of extinction. 2. 'Not Evaluated' means a species has not yet been assessed against the Red List criteria. Which of the statements given above is/are correct?","options":["Both 1 and 2","1 only","2 only","Neither 1 nor 2"],"answer":0,"explanation":"Both definitions are right; neither category is a threat category, and a Data Deficient species may in fact be at high risk.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-200","question":"Which of the following animals are endemic to the Western Ghats? 1. Lion-tailed macaque 2. Nilgiri tahr 3. Hoolock gibbon 4. Purple frog. Select the correct answer.","options":["1 and 2 only","1, 2 and 4 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":1,"explanation":"The lion-tailed macaque, Nilgiri tahr and the burrowing purple frog are found only in the Western Ghats; the hoolock gibbon lives in north-east India and neighbouring countries.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-201","question":"Consider the following statements about protected areas under the Wildlife (Protection) Act, 1972: 1. Grazing of livestock is not permitted in a national park. 2. Conservation reserves are usually declared on government land, typically adjoining national parks and sanctuaries. 3. Community reserves can be declared on community or private land where the community or individuals have volunteered to conserve wildlife. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"The Act bars livestock grazing inside national parks; conservation reserves (government land) and community reserves (community or private land) were added later to link and buffer protected areas.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-202","question":"Consider the following statements about biosphere reserves in India: 1. They are notified under the Wildlife (Protection) Act, 1972. 2. The core zone of a biosphere reserve often consists of a national park or wildlife sanctuary. 3. A biosphere reserve must first be included in UNESCO's Man and the Biosphere network before India can designate it. Which of the statements given above is/are correct?","options":["1 and 2 only","2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Biosphere reserves are not a category under the Wildlife Act; they are designated by the Central Government, and only some of India's reserves are in UNESCO's world network.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-203","question":"In the IUCN system of protected area management categories, Category II corresponds to:","options":["Strict nature reserve","National park","Protected landscape or seascape","Habitat or species management area"],"answer":1,"explanation":"Category Ia is strict nature reserve, Ib wilderness area, II national park, III natural monument, IV habitat/species management area, V protected landscape/seascape and VI protected area with sustainable use.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-204","question":"Which IUCN protected area management category has the sustainable, low-level use of natural resources as one of its main aims?","options":["Category Ia","Category III","Category VI","Category Ib"],"answer":2,"explanation":"Category VI, protected area with sustainable use of natural resources, allows non-industrial use compatible with conservation; Ia and Ib are the strictest categories.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-205","question":"The Svalbard Global Seed Vault, which stores duplicate seed samples from gene banks around the world, is located in:","options":["Norway","Iceland","Greenland","Sweden"],"answer":0,"explanation":"The vault is dug into a mountain on the Arctic archipelago of Svalbard, which belongs to Norway; the permafrost keeps the samples cold even if power fails.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-206","question":"Seeds of mango, jackfruit and cocoa are poorly suited to storage in a conventional seed bank. This is because such seeds:","options":["Are too small to be handled individually","Contain toxins that build up during storage","Germinate only after passing through an animal's gut","Are recalcitrant, losing viability when dried and frozen"],"answer":3,"explanation":"Seed banks dry and freeze 'orthodox' seeds; recalcitrant seeds die when dried, so they are conserved in field gene banks, by tissue culture or by cryopreserving embryos.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-207","question":"The 'Montreux Record' maintained under the Ramsar Convention is:","options":["A list of the largest wetlands in each country","A register of wetlands nominated but not yet accepted as Ramsar sites","A register of Ramsar sites where changes in ecological character have occurred, are occurring or are likely because of human activity","A list of wetlands removed from the Ramsar list"],"answer":2,"explanation":"Sites are placed on the Montreux Record to flag them for priority conservation attention and can be removed once restored.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-208","question":"Consider the following statements about the definition of wetlands under the Ramsar Convention: 1. Areas of marine water whose depth at low tide does not exceed six metres can be wetlands. 2. Human-made sites such as rice paddies and fish ponds can be classified as wetlands. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"The Ramsar definition is very broad: it includes shallow marine waters up to six metres at low tide, and its classification lists human-made wetlands such as paddies, reservoirs and fish ponds.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-209","question":"Consider the following statements: 1. The Ramsar Convention is not part of the United Nations system of environmental treaties, although UNESCO acts as its depositary. 2. World Wetlands Day is observed on 2 February, the date on which the Convention was adopted. Which of the statements given above is/are correct?","options":["1 only","2 only","Neither 1 nor 2","Both 1 and 2"],"answer":3,"explanation":"The Ramsar Convention is an independent treaty with its own secretariat, and it was adopted at Ramsar, Iran, on 2 February 1971.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-210","question":"Consider the following statements about coral reefs in India: 1. Most of the Lakshadweep islands are coral atolls. 2. The reefs of the Gulf of Mannar are mainly fringing reefs around a chain of small islands. 3. Reef-building corals grow best in cold, nutrient-rich water. Which of the statements given above are correct?","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Reef corals need warm, clear, nutrient-poor water; nutrient-rich water favours algae that smother corals.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-211","question":"Reef-building corals are mostly restricted to shallow, clear water. The main reason is that:","options":["Water pressure at depth crushes coral skeletons","Their symbiotic algae (zooxanthellae) need sunlight for photosynthesis","Deep water is too salty for corals","Corals feed only on plankton found at the surface"],"answer":1,"explanation":"Much of a reef coral's food comes from the photosynthesis of zooxanthellae in its tissues, so reefs grow only where enough light penetrates.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-212","question":"Estuaries are among the most productive ecosystems on Earth. Which of the following contribute to this? 1. Rivers and tides bring in nutrients. 2. The mixing of fresh and salt water tends to trap nutrients within the estuary. 3. Salinity stays constant throughout the year. Select the correct answer.","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Estuaries are nutrient traps fed from both river and sea; their salinity fluctuates widely with tides and seasons, so organisms there must be euryhaline.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-213","question":"Consider the following statements about seagrasses: 1. Seagrasses are flowering plants, not algae. 2. The dugong feeds mainly on seagrass. 3. Seagrass meadows store significant amounts of 'blue carbon' in their sediments. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 only","1, 2 and 3"],"answer":3,"explanation":"Seagrasses have roots, leaves and flowers, unlike seaweeds (algae); they are grazed by dugongs and turtles, and their sediments lock away carbon for long periods.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-214","question":"Assertion (A): Peatlands are important long-term stores of carbon. Reason (R): Peat forms because decomposition is unusually fast in waterlogged soils. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Peat builds up because waterlogged, oxygen-poor and often acidic conditions slow decomposition, so plant matter accumulates faster than it rots.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-215","question":"Consider the following statements: 1. Sholas are patches of stunted evergreen forest found together with grasslands in the high-altitude valleys of the southern Western Ghats. 2. The Banni grasslands lie in the Kachchh district of Gujarat. Which of the statements given above is/are correct?","options":["Both 1 and 2","1 only","2 only","Neither 1 nor 2"],"answer":0,"explanation":"The shola–grassland mosaic is typical of the Nilgiris, Anamalais and Palanis; Banni is a large tropical grassland on the edge of the Rann of Kachchh.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-216","question":"Consider the following statements about India's biodiversity: 1. India has about 2.4 per cent of the world's land area. 2. India accounts for roughly 7–8 per cent of the world's recorded species. 3. India is counted among the megadiverse countries of the world. Which of the statements given above are correct?","options":["1 and 3 only","1, 2 and 3","2 only","3 only"],"answer":1,"explanation":"All three are standard: a small share of the land area holds a disproportionately large share of species, which places India among the megadiverse countries.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-217","question":"Of the biogeographic zones into which India is divided, which one covers the largest area?","options":["Western Ghats","Himalaya","Deccan Peninsula","Gangetic Plain"],"answer":2,"explanation":"The Deccan Peninsula zone covers over two-fifths of the country; the Western Ghats, though rich in endemics, is a narrow zone.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-218","question":"Which of the following animals are characteristic of the Trans-Himalayan cold desert of Ladakh? 1. Kiang (Tibetan wild ass) 2. Black-necked crane 3. Nilgai 4. Tibetan antelope (chiru). Select the correct answer.","options":["1, 2 and 4 only","1 and 3 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":0,"explanation":"The kiang, chiru and breeding black-necked cranes belong to the high Tibetan plateau; the nilgai is an antelope of the plains and dry forests.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-219","question":"In the wild, the Indian wild ass (khur) is now found only in:","options":["The Changthang plateau of Ladakh","The Desert National Park in Rajasthan","The Chambal ravines","The Rann of Kachchh region of Gujarat"],"answer":3,"explanation":"The khur survives in the Little Rann and surrounding areas of Gujarat; the wild ass of Ladakh is the kiang, a different species.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-220","question":"Consider the following statements: 1. The gharial is a fish-eating crocodilian with a long, narrow snout. 2. The National Chambal Sanctuary extends over Rajasthan, Madhya Pradesh and Uttar Pradesh. 3. The mugger crocodile is found only in brackish mangrove waters. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"The mugger is a freshwater crocodile of rivers, lakes and reservoirs; the estuarine (saltwater) crocodile is the one found in mangroves such as Bhitarkanika and the Sundarbans.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-221","question":"A species with very large area requirements, whose protection automatically conserves many other species that share its habitat, is called a(n):","options":["Keystone species","Indicator species","Flagship species","Umbrella species"],"answer":3,"explanation":"Umbrella species are chosen for their range; flagship species for public appeal, keystone species for their outsized ecological role, and indicator species for revealing environmental conditions.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-222","question":"Consider the following statements: 1. Biopiracy is the use of biological resources or traditional knowledge without proper authorisation or compensation to the communities concerned. 2. India's Traditional Knowledge Digital Library was created to help patent offices avoid granting patents on existing traditional knowledge. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Episodes such as patents on turmeric and neem led India to document traditional knowledge so that patent examiners could find it as prior art.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-223","question":"Consider the following statements about the Biological Diversity Act, 2002: 1. The National Biodiversity Authority set up under it is headquartered at Chennai. 2. Biodiversity Management Committees are formed by local bodies and maintain People's Biodiversity Registers. 3. The Act was passed to give effect to India's commitments under the Convention on Biological Diversity. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"The Act sets up a three-tier structure (NBA at Chennai, State Biodiversity Boards, local BMCs) to regulate access to biological resources and share benefits, as the CBD requires.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-224","question":"Which one of the following pairs of extinct animal and its former home is NOT correctly matched?","options":["Dodo — Mauritius","Quagga — southern Africa","Thylacine — Tasmania and mainland Australia","Steller's sea cow — the Indian Ocean"],"answer":3,"explanation":"Steller's sea cow lived in the Bering Sea of the North Pacific and was hunted out within decades of its discovery in the eighteenth century.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-225","question":"Amphibians are often regarded as especially sensitive indicators of environmental change. Which of the following help explain this? 1. Their permeable skin readily absorbs chemicals from water and soil. 2. Their life cycle spans both water and land, exposing them to conditions in both. 3. Their hard-shelled eggs let toxins accumulate inside before hatching. Select the correct answer.","options":["1 and 2 only","1, 2 and 3","2 only","1 and 3 only"],"answer":0,"explanation":"Thin, permeable skin and a two-habitat life cycle expose amphibians to pollution in water and on land; their eggs are soft and jelly-coated, not hard-shelled, which is a reptile and bird feature.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-226","question":"Electrostatic precipitators fitted to the chimneys of coal-based thermal power plants are designed mainly to remove:","options":["Sulphur dioxide","Nitrogen oxides","Particulate matter such as fly ash","Carbon dioxide"],"answer":2,"explanation":"An ESP charges dust particles in the flue gas and collects them on oppositely charged plates; gases such as SO2 need scrubbers or flue-gas desulphurisation.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-227","question":"Consider the following statements about controlling emissions from power plants: 1. In flue-gas desulphurisation, limestone slurry reacts with sulphur dioxide to form gypsum. 2. A wet scrubber can remove gases such as sulphur dioxide as well as some particles. 3. The electrostatic precipitator is the main device for removing sulphur dioxide. Which of the statements given above are correct?","options":["1, 2 and 3","1 and 2 only","2 only","1 and 3 only"],"answer":1,"explanation":"ESPs remove particles, not gases; SO2 is absorbed in scrubbers, and limestone-based FGD gives gypsum as a by-product.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-228","question":"Consider the following statements about the three-way catalytic converter of a petrol vehicle: 1. It converts unburnt hydrocarbons into carbon dioxide and water. 2. It converts nitric oxide into nitrogen gas. 3. Vehicles fitted with it must use unleaded petrol, because lead inactivates the catalyst. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Platinum, palladium and rhodium oxidise CO and hydrocarbons and reduce NO to N2; lead coats and poisons the catalyst, which is one reason leaded petrol was phased out.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-229","question":"Modern diesel vehicles inject a urea solution ('diesel exhaust fluid') into the exhaust ahead of a catalyst. This system is designed to reduce emissions of:","options":["Nitrogen oxides","Particulate matter (soot)","Carbon monoxide","Sulphur dioxide"],"answer":0,"explanation":"In selective catalytic reduction, ammonia from urea reduces NOx to nitrogen and water; soot is trapped by a separate particulate filter.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-230","question":"Consider the following statements about ozone near the ground: 1. It is a secondary pollutant. 2. Its concentration in cities usually peaks in the afternoon on sunny days. 3. It is emitted directly in large amounts from vehicle exhausts. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 only","1, 2 and 3"],"answer":0,"explanation":"Ground-level ozone is formed when nitrogen oxides and volatile organic compounds react in sunlight, so it is not emitted directly and builds up through the sunny part of the day.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-231","question":"Which of the following are secondary air pollutants, formed in the atmosphere rather than emitted directly? 1. Peroxyacetyl nitrate (PAN) 2. Ground-level ozone 3. Carbon monoxide 4. Sulphuric acid aerosol. Select the correct answer.","options":["1 and 2 only","1, 2 and 4 only","3 and 4 only","1, 2, 3 and 4"],"answer":1,"explanation":"PAN, ozone and sulphate aerosols form by reactions of emitted gases; carbon monoxide is emitted directly from incomplete combustion, so it is primary.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-232","question":"Which of the following correctly describes classical (London-type) smog?","options":["It is oxidising in nature and forms on warm, sunny afternoons","It is a mixture of smoke, fog and sulphur dioxide that forms in cool, humid conditions and is chemically reducing","Its main constituents are ozone and peroxyacetyl nitrate","It forms only in the upper troposphere, far above cities"],"answer":1,"explanation":"London smog (as in 1952) comes from coal smoke and SO2 in cold, damp, still air; ozone and PAN are the oxidising components of photochemical (Los Angeles-type) smog.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-233","question":"Consider the following statements about indoor air pollution: 1. Radon, a colourless, odourless radioactive gas, can seep into buildings from the ground. 2. Burning biomass in traditional cookstoves exposes women and children to high levels of particulates and carbon monoxide. 3. Formaldehyde can be given off by furniture made from pressed wood. Which of the statements given above are correct?","options":["1 only","1 and 2 only","1, 2 and 3","2 and 3 only"],"answer":2,"explanation":"All three are recognised indoor pollutants; radon from uranium-bearing soils and rocks is a leading cause of lung cancer among non-smokers.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-234","question":"Which of the following is NOT among the pollutants covered by India's National Ambient Air Quality Standards notified in 2009?","options":["Ammonia","Benzene","Carbon dioxide","Nickel"],"answer":2,"explanation":"The 2009 standards cover twelve pollutants, including PM10, PM2.5, SO2, NO2, CO, ozone, ammonia, lead, benzene, benzo(a)pyrene, arsenic and nickel; CO2 is a greenhouse gas, not a regulated ambient pollutant.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-235","question":"Consider the following statements about India's National Air Quality Index: 1. It has six categories ranging from 'Good' to 'Severe'. 2. The overall index for a location is set by the highest sub-index among the pollutants measured. 3. Carbon dioxide is one of the pollutants used to calculate it. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"The AQI uses pollutants such as PM10, PM2.5, NO2, SO2, CO, ozone, ammonia and lead; the worst sub-index decides the reported value. CO2 is not part of it.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-236","question":"Consider the following statements about alternatives to burning crop residue: 1. The Happy Seeder sows wheat directly into the stubble of the harvested rice crop without burning it. 2. The Pusa decomposer is a microbial preparation that speeds up the decomposition of stubble in the field. Which of the statements given above is/are correct?","options":["Both 1 and 2","1 only","2 only","Neither 1 nor 2"],"answer":0,"explanation":"Both are in-situ residue management options promoted to reduce paddy-stubble burning in north-west India; the decomposer is a fungal formulation from IARI.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-237","question":"Rain is usually called 'acid rain' only when its pH falls below about 5.6, not below 7. This is because:","options":["Pure water itself has a pH of 5.6","Rain always contains dissolved sulphuric acid from volcanoes","pH values between 5.6 and 7 cannot be measured accurately","Even unpolluted rain is slightly acidic, as it dissolves atmospheric carbon dioxide to form carbonic acid"],"answer":3,"explanation":"CO2 in equilibrium with rainwater gives a pH of about 5.6; only acidity beyond that, from sulphur and nitrogen oxides, is counted as acid rain.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-238","question":"Consider the following statements about acid deposition: 1. It can release toxic aluminium from soils into lakes, harming fish. 2. Adding lime to acidified lakes is one way of neutralising them. 3. Acid deposition can occur as dry particles and gases, not only as rain. Which of the statements given above are correct?","options":["1, 2 and 3","1 and 2 only","2 and 3 only","1 only"],"answer":0,"explanation":"Acidity mobilises aluminium that damages fish gills; liming raises pH; and dry deposition of SO2, NOx and sulphate particles is as important as wet deposition.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-239","question":"Consider the following statements about noise: 1. On the decibel scale, an increase of 10 dB means a tenfold increase in sound intensity. 2. India's Noise Pollution (Regulation and Control) Rules, 2000 were framed under the Environment (Protection) Act, 1986. 3. Under these rules, the area within 100 metres of hospitals, educational institutions and courts can be declared a silence zone. Which of the statements given above are correct?","options":["1 and 2 only","1, 2 and 3","2 only","1 and 3 only"],"answer":1,"explanation":"The decibel scale is logarithmic; the Noise Rules were made under the EPA, 1986 and define silence zones of at least 100 metres around such institutions.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-240","question":"The sound in a busy factory hall measures 90 dB, while a normal conversation measures about 60 dB. The sound intensity in the factory is greater than that of the conversation by a factor of:","options":["1.5","30","300","1,000"],"answer":3,"explanation":"Each 10 dB is a tenfold rise in intensity, so 30 dB is 10 × 10 × 10 = 1,000 times; 1.5 comes from dividing the decibel values, a common slip.","difficulty":"moderate","source":"UPSC Prelims · CDS"},
  {"id":"env-ecology-241","question":"The amount of dissolved oxygen in a river is likely to fall when: 1. The water temperature rises. 2. Untreated organic sewage is discharged into it. 3. Aquatic plants photosynthesise actively in daylight. Select the correct answer.","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Warm water holds less oxygen and microbes decomposing sewage use it up; photosynthesis adds oxygen during the day.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-242","question":"Consider the following statements about sewage treatment: 1. Primary treatment removes solids physically by screening and sedimentation. 2. Secondary treatment uses microbes to reduce the organic load (BOD) of the sewage. 3. Biogas from anaerobic sludge digesters is mainly methane, with carbon dioxide and hydrogen sulphide. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Primary treatment is physical; in secondary treatment aerobic microbes in flocs (activated sludge) consume organic matter; the settled sludge is digested anaerobically to give biogas.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-243","question":"In most freshwater lakes, controlling the input of which nutrient is usually the most effective way to prevent algal blooms?","options":["Nitrogen","Phosphorus","Potassium","Carbon"],"answer":1,"explanation":"Phosphorus is usually the limiting nutrient in fresh water, which is why phosphate detergents and sewage are key targets; in many coastal seas nitrogen is limiting instead.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-244","question":"The high levels of arsenic in groundwater in parts of the Ganga–Brahmaputra delta are mainly:","options":["The result of pesticide run-off from paddy fields","Leaked from tannery effluents","Of natural geological origin, released from sediments into groundwater and worsened by heavy pumping","Deposited from fly ash of thermal power plants"],"answer":2,"explanation":"The arsenic is geogenic: it comes from the delta's own sediments under oxygen-poor conditions, and is drawn up by tube wells, so it is not mainly industrial.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-245","question":"Warm cooling water discharged from a power plant can harm fish downstream chiefly because warmer water:","options":["Contains more dissolved salts","Is always more acidic","Blocks sunlight from reaching the river bed","Holds less dissolved oxygen while raising the oxygen needs of aquatic animals"],"answer":3,"explanation":"Oxygen is less soluble in warm water, and higher temperature speeds up the metabolism of cold-blooded fish, so oxygen stress comes from both sides.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-246","question":"Consider the following statements about microplastics: 1. They are usually defined as plastic particles smaller than 5 mm. 2. Primary microplastics, such as microbeads, are made small, while secondary microplastics come from the breakdown of larger plastic items. 3. Plastics labelled 'compostable' break down quickly and fully in the open ocean. Which of the statements given above are correct?","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"Compostable plastics generally need the heat and microbes of industrial composting; in cold seawater they persist for long periods.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-247","question":"Open burning of PVC-coated wires during informal e-waste recycling is especially dangerous because it releases:","options":["Ozone","Dioxins and furans","Methane","Radon"],"answer":1,"explanation":"Burning chlorine-containing plastics produces dioxins and furans, persistent and highly toxic compounds; methane comes from anaerobic decay, not burning.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-248","question":"Consider the following statements about the disposal of solid waste: 1. Leachate is the liquid that drains through waste and can contaminate groundwater. 2. A sanitary landfill uses an impermeable liner and a daily cover of soil. 3. Landfill gas is mainly nitrogen and oxygen. Which of the statements given above are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Landfill gas from anaerobic decay is mainly methane and carbon dioxide, which is why landfills are both a fire hazard and a greenhouse gas source.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-249","question":"In the widely used hierarchy of waste management, which option is the most preferred?","options":["Recycling","Incineration with energy recovery","Reducing waste at its source","Disposal in a sanitary landfill"],"answer":2,"explanation":"The hierarchy runs prevention or reduction, reuse, recycling, recovery and, last, disposal; waste that is never produced needs no handling at all.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-250","question":"Which radioactive isotope released in nuclear accidents poses a particular threat to the thyroid gland, especially in children?","options":["Iodine-131","Caesium-137","Strontium-90","Radon-222"],"answer":0,"explanation":"The thyroid concentrates iodine, so radioactive iodine-131 builds up there; strontium-90 behaves like calcium and lodges in bones.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-251","question":"Waterlogging and soil salinity in parts of canal-irrigated Punjab and Haryana result mainly from:","options":["Sea water entering through the river mouths","Excessive use of organic manure","Acid rain from nearby industries","Over-irrigation raising the water table, so that capillary rise and evaporation leave salts at the surface"],"answer":3,"explanation":"Seepage and excess irrigation raise the groundwater; as it rises and evaporates near the surface, dissolved salts are left behind in the root zone.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-252","question":"Consider the following statements about biofertilisers and biocontrol: 1. Azolla, with the cyanobacterium Anabaena in its leaves, is used as a biofertiliser in paddy fields. 2. Mycorrhizal fungi help plants take up phosphorus from the soil. 3. Trichoderma is a biofertiliser that fixes atmospheric nitrogen. Which of the statements given above are correct?","options":["1, 2 and 3","2 only","1 and 3 only","1 and 2 only"],"answer":3,"explanation":"Trichoderma is a free-living fungus used as a biocontrol agent against plant pathogens; it does not fix nitrogen.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-253","question":"Consider the following statements about atmospheric brown clouds over South Asia: 1. They reduce the sunlight reaching the ground (solar dimming). 2. The black carbon in them absorbs sunlight and warms the atmospheric layer in which it sits. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Brown clouds of soot, sulphates and other aerosols cool the surface by dimming sunlight while heating the air aloft, which can alter rainfall patterns.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-254","question":"The urban heat island effect, by which a city is warmer than its surrounding countryside, is usually most pronounced:","options":["Around noon on windy, cloudy days","At night in calm, clear weather","Only during the monsoon","Only in coastal cities"],"answer":1,"explanation":"Concrete and asphalt store heat by day and release it at night; calm, clear nights let the countryside cool fast while the city stays warm, so the contrast is greatest then.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-255","question":"Consider the following statements about vehicle emission norms in India: 1. India moved directly from Bharat Stage IV to Bharat Stage VI norms nationwide in April 2020, skipping Stage V. 2. Bharat Stage VI fuel has a much lower sulphur content than Bharat Stage IV fuel. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"BS-VI was introduced across the country from 1 April 2020, leapfrogging BS-V, and cut the sulphur limit in fuel from 50 ppm to 10 ppm.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-256","question":"Which of the following best describes how greenhouse gases warm the Earth's surface?","options":["They reflect incoming ultraviolet radiation back to space","They trap visible sunlight in the upper atmosphere","They let most incoming short-wave solar radiation pass but absorb and re-emit outgoing long-wave (infrared) radiation","They release heat through chemical reactions with oxygen"],"answer":2,"explanation":"The surface, warmed by sunlight, radiates infrared; greenhouse gases absorb it and re-radiate part back down, so the surface stays warmer than it would otherwise be.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-257","question":"Nitrogen and oxygen together make up about 99 per cent of dry air, yet they are not greenhouse gases. The reason is that:","options":["As symmetric two-atom molecules, their vibrations do not absorb infrared radiation","They are present only in the upper atmosphere","They absorb only ultraviolet radiation and convert it into heat","They are chemically inert and do not react with sunlight"],"answer":0,"explanation":"To absorb infrared, a molecule's vibration must change its dipole; N2 and O2 cannot, while CO2, H2O, CH4 and N2O can.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-258","question":"Without the natural greenhouse effect, the Earth's average surface temperature, now about 15 °C, would be roughly:","options":["0 °C","+5 °C","−60 °C","−18 °C"],"answer":3,"explanation":"Radiative balance alone gives about −18 °C; the natural greenhouse effect adds roughly 33 °C, making the planet habitable.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-259","question":"Arrange the following surfaces in decreasing order of their typical albedo (reflectivity): 1. Fresh snow 2. Open ocean 3. Desert sand 4. Coniferous forest","options":["1, 3, 4, 2","1, 4, 3, 2","3, 1, 4, 2","1, 3, 2, 4"],"answer":0,"explanation":"Fresh snow reflects most sunlight, bright sand about a third, dark conifer forest little, and open water at high sun least of all.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-260","question":"Which of the following are positive (amplifying) feedbacks in the climate system? 1. Melting sea ice exposing darker ocean water 2. A warmer atmosphere holding more water vapour 3. Thawing permafrost releasing carbon dioxide and methane 4. A warmer Earth radiating more long-wave energy to space. Select the correct answer.","options":["1 and 2 only","1, 2 and 3 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":1,"explanation":"The first three add to warming; the rise in outgoing radiation with temperature (the Planck response) is the basic negative feedback that stabilises climate.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-261","question":"Water vapour contributes more than any other gas to the natural greenhouse effect, yet it is treated as a feedback rather than a driver of climate change. This is because:","options":["Water vapour does not absorb infrared radiation","Human activities emit no water vapour","Water vapour is found only in the stratosphere","Its concentration is controlled by air temperature, and excess vapour rains out within days"],"answer":3,"explanation":"Water vapour stays in the air only for days and its amount depends on temperature, so it amplifies warming started by long-lived gases such as CO2.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-262","question":"In climate science, 'radiative forcing' refers to:","options":["The force exerted by sunlight on the Earth's orbit","The change in net energy flux at the top of the atmosphere caused by a factor such as a rise in greenhouse gases","The total heat stored in the oceans","The rate at which winds carry heat from the equator to the poles"],"answer":1,"explanation":"Forcing is measured in watts per square metre; a positive value means the factor pushes the climate towards warming.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-263","question":"Consider the following statements about aerosols: 1. Sulphate aerosols have a net cooling effect on climate. 2. Black carbon has a warming effect. 3. A large volcanic eruption that injects sulphur dioxide into the stratosphere can cool global climate for a year or two. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Sulphates reflect sunlight, soot absorbs it, and stratospheric sulphate from eruptions such as Pinatubo in 1991 cooled the planet measurably.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-264","question":"The global warming potential of methane is much higher over a 20-year horizon than over a 100-year horizon. Why?","options":["Methane is removed from the atmosphere in about a decade, so its warming is concentrated in the early years","Methane's ability to absorb infrared increases as it ages","Methane turns into carbon monoxide, which is a stronger greenhouse gas","Carbon dioxide's effect falls to zero after 20 years"],"answer":0,"explanation":"GWP compares warming with that of CO2 over a chosen period; a short-lived gas looks more powerful over a short window, because CO2 keeps acting for centuries.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-265","question":"The main process that removes methane from the atmosphere is:","options":["Dissolution in rainwater","Uptake by plants in photosynthesis","Reaction with hydroxyl (OH) radicals in the troposphere","Absorption by ocean surface waters"],"answer":2,"explanation":"The hydroxyl radical, the atmosphere's 'detergent', oxidises methane; soils remove a small additional amount.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-266","question":"Consider the following statements about nitrous oxide: 1. Agricultural soils treated with nitrogen fertilisers are the largest human source of it. 2. It is both a greenhouse gas and an ozone-depleting substance. 3. Its production is controlled under the Montreal Protocol. Which of the statements given above are correct?","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"N2O is now a leading ozone-depleting emission, but it is not a controlled substance under the Montreal Protocol; it is covered as a greenhouse gas under the UNFCCC.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-267","question":"Consider the following statements: 1. Hydrofluorocarbons (HFCs) do not deplete stratospheric ozone. 2. HFCs are powerful greenhouse gases. 3. Sulphur hexafluoride is used as an insulating gas in electrical switchgear. Which of the statements given above are correct?","options":["1 and 2 only","1, 2 and 3","2 and 3 only","1 only"],"answer":1,"explanation":"HFCs replaced CFCs because they contain no chlorine, but their high warming potential led to the Kigali Amendment; SF6, used in switchgear, has the highest GWP of the major gases.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-268","question":"The record of carbon dioxide at Mauna Loa, Hawaii, shows a regular rise and fall within each year on top of the long-term increase. The fall during each northern summer is mainly due to:","options":["Lower fossil fuel use in summer","Cooler oceans absorbing more CO2","Uptake of CO2 by growing vegetation in the Northern Hemisphere, which has most of the land","Volcanic activity being lower in summer"],"answer":2,"explanation":"The Northern Hemisphere holds most land plants, so its growing season draws CO2 down, and autumn decay and winter release raise it again.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-269","question":"Consider the following statements about ocean acidification: 1. The oceans absorb a substantial part of the carbon dioxide emitted by human activities. 2. Acidification lowers the concentration of the carbonate ions that corals and shellfish need to build shells and skeletons. 3. The average pH of seawater has already fallen below 7. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Seawater is still alkaline, with a pH of about 8.1; 'acidification' describes the downward shift, not a crossing of pH 7.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-270","question":"Which of the following contribute significantly to global sea-level rise? 1. Thermal expansion of seawater 2. Melting of glaciers and ice sheets on land 3. Melting of floating Arctic sea ice. Select the correct answer.","options":["1, 2 and 3","1 only","2 and 3 only","1 and 2 only"],"answer":3,"explanation":"Floating ice already displaces its own weight of water, so its melting adds almost nothing to sea level; land ice and warming water do.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-271","question":"Consider the following statements about ozone depletion: 1. CFCs are broken down by ultraviolet radiation in the stratosphere, releasing chlorine. 2. A single chlorine atom can destroy many thousands of ozone molecules because it acts as a catalyst. 3. Atom for atom, bromine is less effective than chlorine at destroying ozone. Which of the statements given above are correct?","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Bromine is far more destructive per atom than chlorine, which is why halons and methyl bromide are strictly controlled.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-272","question":"Consider the following statements: 1. The total amount of ozone in a column of the atmosphere is measured in Dobson units. 2. A region where total column ozone falls below 220 Dobson units is conventionally described as an 'ozone hole'. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Typical global ozone is about 300 DU; 220 DU is the threshold used to map the Antarctic ozone hole.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-273","question":"Which of the following are controlled as ozone-depleting substances under the Montreal Protocol? 1. Halons 2. Methyl bromide 3. Carbon tetrachloride 4. Methane. Select the correct answer.","options":["1 and 2 only","1, 2 and 3 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":1,"explanation":"Halons (fire extinguishers), methyl bromide (fumigant) and carbon tetrachloride (solvent) are controlled; methane is a greenhouse gas outside the Protocol.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-274","question":"Which one of the following is NOT an expected effect of increased UV-B radiation reaching the Earth's surface?","options":["A higher incidence of cataracts","Damage to DNA and more skin cancer","Lower productivity of phytoplankton","A rise in rickets due to vitamin D deficiency"],"answer":3,"explanation":"UV-B drives vitamin D synthesis in the skin, so more of it would not cause deficiency; cataract, skin cancer and harm to phytoplankton are all expected.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-275","question":"Ozone in the stratosphere is formed naturally when:","options":["Lightning combines nitrogen and oxygen","Water vapour breaks down in sunlight","Short-wavelength ultraviolet radiation splits oxygen molecules into atoms, which then join other oxygen molecules","CFCs react with oxygen at low temperatures"],"answer":2,"explanation":"O2 is split by high-energy UV, and O + O2 gives O3; ozone in turn absorbs UV-B, which is why the layer shields the surface.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-276","question":"Consider the following statements about the Intergovernmental Panel on Climate Change (IPCC): 1. It was set up in 1988 by the World Meteorological Organization and the UN Environment Programme. 2. It carries out its own climate measurements and research programmes. 3. Its assessments are prepared by working groups dealing with the physical science, with impacts and adaptation, and with mitigation. Which of the statements given above are correct?","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"The IPCC does not conduct original research; it assesses published literature through Working Groups I, II and III.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-277","question":"Consider the following statements about Milankovitch cycles: 1. They involve changes in the Earth's orbital eccentricity, axial tilt and precession. 2. They operate over tens of thousands of years. 3. They are the main cause of the global warming observed since the mid-twentieth century. Which of the statements given above are correct?","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"Orbital cycles pace the ice ages over roughly 20,000 to 100,000 years; they are far too slow to explain warming over a few decades.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-278","question":"Air bubbles trapped in Antarctic ice cores give scientists:","options":["The ages of nearby rocks","Records of past ocean salinity","Direct counts of past sunspots","Direct samples of the past atmosphere, including its carbon dioxide and methane levels"],"answer":3,"explanation":"As snow compacts into ice, it seals in air; cores going back hundreds of thousands of years show greenhouse gas levels rising and falling with temperature.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-279","question":"Observations show that while the lower atmosphere has warmed, the stratosphere has cooled. This pattern is strong evidence that recent warming is caused by:","options":["An increase in the Sun's output","More greenhouse gases, which trap heat lower down and let the upper layers radiate more to space","Volcanic eruptions","Changes in the Earth's orbit"],"answer":1,"explanation":"A brighter Sun would warm all layers; cooling aloft with warming below is the fingerprint of greenhouse gases (with ozone loss adding to stratospheric cooling).","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-280","question":"Which of the following currently act as net sinks of carbon? 1. Growing forests 2. The oceans 3. Drained peatlands that are being burned. Select the correct answer.","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Growing forests and the oceans take up a large share of human emissions; drained and burning peat releases long-stored carbon and is a source.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-281","question":"Which of the following can deliver net negative emissions, i.e., remove more carbon dioxide from the air than they release? 1. Bioenergy with carbon capture and storage (BECCS) 2. Afforestation 3. Replacing coal-fired power with natural gas. Select the correct answer.","options":["1, 2 and 3","2 and 3 only","1 and 2 only","1 only"],"answer":2,"explanation":"Switching coal to gas only reduces emissions; it still adds CO2. BECCS and new forests draw CO2 out of the air.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-282","question":"Which of the following is a form of solar radiation management rather than carbon dioxide removal?","options":["Ocean iron fertilisation","Stratospheric aerosol injection","Enhanced weathering of crushed basalt","Direct air capture"],"answer":1,"explanation":"Solar radiation management reflects sunlight to cool the planet without touching CO2 levels; the other three are attempts to pull CO2 out of the air.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-283","question":"Consider the following statements: 1. During El Niño, sea-surface temperatures in the central and eastern equatorial Pacific are above normal. 2. El Niño years are often, though not always, associated with below-normal Indian monsoon rainfall. 3. A positive Indian Ocean Dipole can partly offset the effect of El Niño on the Indian monsoon. Which of the statements given above are correct?","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three hold; in 1997, for example, a strong El Niño coincided with a near-normal monsoon, partly because of a positive Indian Ocean Dipole.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-284","question":"Methane hydrates (clathrates) on the sea floor and in permafrost are a concern in the context of climate change because:","options":["They absorb carbon dioxide when they warm","They block the ocean's heat transport","They make seawater more alkaline as they dissolve","Warming can destabilise them and release methane, a potent greenhouse gas"],"answer":3,"explanation":"Hydrates are ice-like solids holding methane, stable only when cold and under pressure; their breakdown could be a positive feedback.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-285","question":"Assertion (A): The Arctic is warming faster than the global average. Reason (R): The loss of snow and sea ice lowers the surface albedo, so more sunlight is absorbed. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"This 'Arctic amplification' is driven largely by the ice–albedo feedback, along with changes in atmospheric heat transport and the lapse rate.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-286","question":"Which of the following are among the three objectives of the Convention on Biological Diversity? 1. Conservation of biological diversity 2. Sustainable use of its components 3. Fair and equitable sharing of the benefits arising from the use of genetic resources 4. A ban on international trade in endangered species. Select the correct answer.","options":["1 and 2 only","1, 2 and 3 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":1,"explanation":"The CBD's three objectives are conservation, sustainable use and benefit-sharing; regulating trade in endangered species is the job of CITES.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-287","question":"Consider the following statements about the Convention on Biological Diversity: 1. It was opened for signature at the Rio Earth Summit in 1992. 2. The United States is not a party to it. 3. Its Cartagena Protocol deals with the safe handling and transboundary movement of living modified organisms. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three hold: the US signed the CBD but never ratified it, and the Cartagena Protocol on Biosafety governs living modified organisms.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-288","question":"Consider the following statements about CITES: 1. Species in Appendix I are threatened with extinction, and commercial international trade in them is generally not permitted. 2. Species are placed in Appendix III at the request of a party that already regulates trade in them and needs other countries' help. 3. CITES regulates trade in wildlife within a country's own borders. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 only","1, 2 and 3"],"answer":0,"explanation":"CITES covers only international trade; domestic trade is left to national laws such as India's Wildlife (Protection) Act.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-289","question":"Which international agreement is also known as the 'Washington Convention'?","options":["The Bonn Convention on Migratory Species","The Ramsar Convention","CITES","The Basel Convention"],"answer":2,"explanation":"CITES was signed in Washington, D.C. in 1973 and came into force in 1975; the CMS was signed in Bonn and the Ramsar Convention in Iran.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-290","question":"Consider the following statements about the Convention on the Conservation of Migratory Species of Wild Animals (CMS): 1. It was signed at Bonn in 1979. 2. India hosted its thirteenth Conference of the Parties at Gandhinagar in 2020. 3. India is not a party to the convention. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"India is a party to the CMS and hosted COP-13 at Gandhinagar, whose mascot was the Great Indian Bustard.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-291","question":"Consider the following statements: 1. The Vienna Convention (1985) was a framework convention, while the Montreal Protocol (1987) set binding phase-out schedules for ozone-depleting substances. 2. The Vienna Convention and the Montreal Protocol were the first treaties in UN history to achieve universal ratification. 3. A Multilateral Fund helps developing countries meet the costs of complying with the Montreal Protocol. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1, 2 and 3","1 only"],"answer":2,"explanation":"All three are correct; the ozone treaties are often cited as the most successful environmental agreements, with every UN member a party.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-292","question":"Consider the following statements about the UN Framework Convention on Climate Change (UNFCCC): 1. It entered into force in 1994. 2. It includes the principle of 'common but differentiated responsibilities and respective capabilities'. 3. It sets legally binding emission targets for each Annex I party. Which of the statements given above are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"The UNFCCC is a framework treaty without binding numerical targets; those came with the Kyoto Protocol for developed (Annex I) countries.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-293","question":"Under the Kyoto Protocol, which mechanism allowed developed (Annex I) countries to earn emission credits from emission-reduction projects in developing countries?","options":["Joint Implementation","Clean Development Mechanism","International Emissions Trading","REDD+"],"answer":1,"explanation":"The CDM generated Certified Emission Reductions from projects in non-Annex I countries such as India; Joint Implementation involved projects between Annex I countries.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-294","question":"Consider the following statements about the Kyoto Protocol: 1. It entered into force in 2005. 2. Its first commitment period ran from 2008 to 2012. 3. The United States ratified it but later withdrew. Which of the statements given above are correct?","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"The US signed but never ratified Kyoto; it was Canada that ratified and later withdrew.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-295","question":"Consider the following statements about the Paris Agreement: 1. Each party must prepare and communicate successive Nationally Determined Contributions. 2. It sets a legally binding emission target for each country, fixed by the Conference of the Parties. 3. It provides for a global stocktake every five years. Which of the statements given above are correct?","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Paris is 'bottom-up': submitting NDCs is binding, but each country sets its own targets; the global stocktake reviews collective progress every five years.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-296","question":"In REDD+, the '+' refers to:","options":["Additional finance from the private sector","Reducing emissions from agriculture as well as forests","Including wetlands and peatlands in the scheme","Conservation, sustainable management of forests and enhancement of forest carbon stocks"],"answer":3,"explanation":"REDD stands for Reducing Emissions from Deforestation and forest Degradation; the '+' adds conservation, sustainable forest management and enhancement of carbon stocks.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-297","question":"The headquarters of the Green Climate Fund, set up under the UNFCCC, is located in:","options":["Songdo, South Korea","Bonn, Germany","Geneva, Switzerland","Nairobi, Kenya"],"answer":0,"explanation":"The GCF was set up at COP-16 in Cancún (2010) and is based in Songdo, Incheon; Bonn hosts the UNFCCC secretariat and Nairobi hosts UNEP.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-298","question":"Consider the following statements about the UN Convention to Combat Desertification (UNCCD): 1. It deals with land degradation in arid, semi-arid and dry sub-humid areas. 2. Under it, 'desertification' means only the natural spreading of existing deserts. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"Desertification means land degradation in drylands from various factors, including climatic variations and human activities; it is not just the advance of sand dunes.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-299","question":"Which of the following are referred to as the 'Rio Conventions'? 1. UN Framework Convention on Climate Change 2. Convention on Biological Diversity 3. UN Convention to Combat Desertification 4. Ramsar Convention on Wetlands. Select the correct answer.","options":["1 and 2 only","1, 2 and 4 only","1, 2, 3 and 4","1, 2 and 3 only"],"answer":3,"explanation":"The three Rio Conventions arose from the 1992 Earth Summit; the UNCCD was negotiated soon after, as the Summit had called for. Ramsar dates from 1971.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-300","question":"'Agenda 21', adopted at the Rio Earth Summit in 1992, is:","options":["A non-binding action plan for sustainable development","A legally binding protocol on greenhouse gas emissions","A list of 21 endangered species to be protected worldwide","A treaty on trade in hazardous chemicals"],"answer":0,"explanation":"Agenda 21 is a voluntary, comprehensive plan for sustainable development at global, national and local levels; it has no binding obligations.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-301","question":"The widely cited definition of sustainable development as development that 'meets the needs of the present without compromising the ability of future generations to meet their own needs' comes from:","options":["The Limits to Growth (1972)","Silent Spring (1962)","Our Common Future, the Brundtland Report (1987)","The Stockholm Declaration (1972)"],"answer":2,"explanation":"The World Commission on Environment and Development, chaired by Gro Harlem Brundtland, gave this definition; Silent Spring was Rachel Carson's book on pesticides.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-302","question":"Consider the following statements: 1. The UN Environment Programme was set up following the Stockholm Conference of 1972. 2. UNEP is headquartered at Nairobi. 3. World Environment Day, 5 June, marks the opening day of the Stockholm Conference. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three are correct; the UN Conference on the Human Environment opened in Stockholm on 5 June 1972, and UNEP was created later that year with its base in Nairobi.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-303","question":"Which of the following were among the original twelve persistent organic pollutants (the 'dirty dozen') listed under the Stockholm Convention? 1. DDT 2. Aldrin 3. Polychlorinated biphenyls (PCBs) 4. Glyphosate. Select the correct answer.","options":["1, 2, 3 and 4","1 and 2 only","2, 3 and 4 only","1, 2 and 3 only"],"answer":3,"explanation":"The dirty dozen included DDT, aldrin, dieldrin, endrin, chlordane, heptachlor, PCBs, dioxins and furans among others; glyphosate is not a listed POP.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-304","question":"Consider the following statements: 1. The Stockholm Convention permits the restricted use of DDT for controlling disease vectors such as malaria mosquitoes. 2. India is a party to the Stockholm Convention. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"DDT is listed with an acceptable-purpose exemption for vector control, which India uses; India ratified the Convention in 2006.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-305","question":"Consider the following statements about the Minamata Convention: 1. It is named after a Japanese city where people were poisoned by mercury in industrial waste water. 2. It prohibits new primary mercury mining. 3. It covers mercury use in artisanal and small-scale gold mining. Which of the statements given above are correct?","options":["1 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Adopted in 2013, the Convention covers the whole life cycle of mercury: mining, products such as thermometers, emissions, and artisanal gold mining.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-306","question":"The Nagoya–Kuala Lumpur Supplementary Protocol relates to:","options":["Access to genetic resources and benefit-sharing","Liability and redress for damage caused by living modified organisms","Control of invasive alien species","Marine biodiversity in areas beyond national jurisdiction"],"answer":1,"explanation":"It supplements the Cartagena Protocol on Biosafety; access and benefit-sharing is the subject of the separate Nagoya Protocol.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-307","question":"The global moratorium on commercial whaling was introduced by which body, taking effect from 1986?","options":["CITES","The Convention on Migratory Species","UNCLOS","The International Whaling Commission"],"answer":3,"explanation":"The IWC, set up under the 1946 International Convention for the Regulation of Whaling, adopted the moratorium in 1982 to take effect from the 1986 season.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-308","question":"The MARPOL Convention deals with:","options":["Prevention of pollution of the marine environment by ships, from operational or accidental causes","Conservation of migratory marine mammals","Regulation of deep-sea mining","Protection of coral reefs from tourism"],"answer":0,"explanation":"MARPOL, adopted under the International Maritime Organization, covers pollution from ships by oil, chemicals, sewage, garbage and air emissions.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-309","question":"Consider the following statements: 1. The Antarctic Treaty, signed in 1959, reserves Antarctica for peaceful purposes and scientific research. 2. The Madrid Protocol (1991) prohibits any activity relating to mineral resources other than scientific research. 3. India's research stations in Antarctica include Maitri and Bharati. Which of the statements given above are correct?","options":["1 and 2 only","1, 2 and 3","2 and 3 only","1 only"],"answer":1,"explanation":"All three hold; the Madrid Protocol on Environmental Protection designates Antarctica a natural reserve, and Maitri and Bharati are India's working stations.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-310","question":"Consider the following statements about the World Heritage Convention: 1. It was adopted under UNESCO in 1972. 2. It covers both cultural and natural heritage. 3. It maintains a 'List of World Heritage in Danger'. Which of the statements given above are correct?","options":["1, 2 and 3","1 and 2 only","2 only","1 and 3 only"],"answer":0,"explanation":"The 1972 Convention protects cultural, natural and mixed sites, and the List in Danger flags sites facing serious threats.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-311","question":"Consider the following statements: 1. The Aichi Biodiversity Targets were adopted at the tenth Conference of the Parties to the CBD at Nagoya in 2010. 2. The Nagoya Protocol on access and benefit-sharing was adopted at the same meeting. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"COP-10 in Nagoya adopted both the Strategic Plan for Biodiversity 2011–2020 with its twenty Aichi Targets and the Nagoya Protocol.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-312","question":"The UN Decade on Ecosystem Restoration (2021–2030) is led by:","options":["UNDP and the World Meteorological Organization","UNEP and the Food and Agriculture Organization","IUCN and WWF","UNESCO and UNDP"],"answer":1,"explanation":"The UN General Assembly declared the Decade and asked UNEP and FAO to lead it; IUCN and WWF are not UN bodies.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-313","question":"Consider the following statements about the International Union for Conservation of Nature (IUCN): 1. Its members include both governments and civil-society organisations. 2. It is a specialised agency of the United Nations. 3. It is headquartered at Gland, Switzerland. Which of the statements given above are correct?","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"IUCN is a membership union of states, government agencies and NGOs with observer status at the UN General Assembly; it is not a UN agency.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-314","question":"TRAFFIC, often mentioned in news about the illegal wildlife trade, is:","options":["A UN convention on wildlife crime","An Interpol unit for environmental crime","A branch of the CITES secretariat","A non-governmental wildlife trade monitoring network"],"answer":3,"explanation":"TRAFFIC was set up by WWF and IUCN to monitor wildlife trade and support CITES; it is not itself a treaty body or police agency.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-315","question":"The Global Environment Facility serves as a financial mechanism for which of the following? 1. UNFCCC 2. Convention on Biological Diversity 3. Stockholm Convention on POPs 4. CITES. Select the correct answer.","options":["1, 2, 3 and 4","1 and 2 only","1, 2 and 3 only","2 and 4 only"],"answer":2,"explanation":"The GEF funds the climate, biodiversity, desertification, POPs and mercury conventions; CITES is not among the conventions it serves as financial mechanism for.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-316","question":"Consider the following statements about the Water (Prevention and Control of Pollution) Act, 1974: 1. The Central Pollution Control Board was first constituted under this Act. 2. Parliament enacted it under Article 252, after the legislatures of several states passed resolutions asking it to do so. 3. It did not provide for State Pollution Control Boards. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1, 2 and 3","1 only"],"answer":0,"explanation":"Water is a state subject, so Parliament legislated under Article 252 at the request of states; the Act created both the CPCB and the State Boards.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-317","question":"Consider the following statements: 1. Article 48A directs the State to protect and improve the environment and to safeguard forests and wildlife. 2. Article 51A(g) makes it a fundamental duty of every citizen to protect and improve the natural environment and to have compassion for living creatures. 3. Both provisions were inserted by the Constitution (Forty-second Amendment) Act, 1976. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"The 42nd Amendment added Article 48A to the Directive Principles and Article 51A(g) to the new chapter on Fundamental Duties.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-318","question":"After the Forty-second Amendment (1976), the subjects 'Forests' and 'Protection of wild animals and birds' are placed in the:","options":["State List","Union List","Concurrent List","Forests in the State List and wildlife in the Union List"],"answer":2,"explanation":"Both were moved from the State List to the Concurrent List, so Parliament and state legislatures can both legislate on them.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-319","question":"The Supreme Court of India has recognised the right to a clean and healthy environment as part of:","options":["Article 14, the right to equality","Article 21, the right to life and personal liberty","Article 19(1)(g), the freedom of trade and profession","Article 48A, the Directive Principle on the environment"],"answer":1,"explanation":"The Court read environmental protection into the right to life under Article 21; Article 48A is a Directive Principle and is not enforceable as a right.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-320","question":"In Vellore Citizens' Welfare Forum v. Union of India (1996), the Supreme Court held which of the following to be part of the environmental law of the country?","options":["The doctrine of eminent domain and the polluter pays principle","The public trust doctrine and absolute liability","Strict liability and the doctrine of laches","The precautionary principle and the polluter pays principle"],"answer":3,"explanation":"The case, about tannery pollution in Tamil Nadu, accepted both principles as part of sustainable development; the public trust doctrine came in the Kamal Nath case.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-321","question":"The principle of 'absolute liability' for enterprises engaged in hazardous or inherently dangerous activities was laid down by the Supreme Court in:","options":["The Vellore Citizens' Welfare Forum case","The oleum gas leak case (M.C. Mehta v. Union of India, 1986)","The T.N. Godavarman Thirumulpad case","The M.C. Mehta v. Kamal Nath case"],"answer":1,"explanation":"After the oleum leak at a Delhi plant, the Court held such enterprises absolutely liable, without the exceptions allowed under the older strict-liability rule.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-322","question":"In the T.N. Godavarman Thirumulpad case (1996), the Supreme Court held that the word 'forest' in the Forest (Conservation) Act, 1980 must be understood:","options":["According to its dictionary meaning, covering all forests whatever their ownership or classification","As only those areas notified as reserved forests","As only forests owned by the Central Government","As only areas with more than 40 per cent canopy cover"],"answer":0,"explanation":"The ruling greatly widened the Act's reach, bringing private and unclassified forests under its protection.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-323","question":"The 'public trust doctrine', under which the State holds natural resources such as rivers, forests and seashores as a trustee for the public, was applied by the Supreme Court in:","options":["The Bhopal gas leak case","The oleum gas leak case","The Vellore Citizens' Welfare Forum case","M.C. Mehta v. Kamal Nath (1997)"],"answer":3,"explanation":"In Kamal Nath, about a motel built by diverting the Beas river, the Court held that the State cannot hand over such resources for private use.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-324","question":"Consider the following statements: 1. Under the Forest (Conservation) Act, 1980, a state government needs the prior approval of the Central Government to use forest land for non-forest purposes. 2. Money collected for compensatory afforestation is governed by the Compensatory Afforestation Fund Act, 2016. Which of the statements given above is/are correct?","options":["1 only","2 only","Neither 1 nor 2","Both 1 and 2"],"answer":3,"explanation":"The 1980 Act requires central approval for diverting forest land, and the 2016 Act puts the money collected for such diversions into national and state funds.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-325","question":"Consider the following statements about the Indian Forest Act, 1927: 1. It classifies forests as reserved, protected and village forests. 2. It was amended in 2017 so that bamboo grown outside forest areas is no longer treated as a 'tree'. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Reserved forests have the strictest controls; the 2017 amendment freed bamboo grown on private and non-forest land from felling and transit permits.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-326","question":"Consider the following statements about the Wildlife (Protection) Act, 1972: 1. It provides for the protection of wild animals, birds and plants. 2. The 2022 amendment added a schedule for specimens listed in the Appendices of CITES. 3. Animals in Schedule I may not be hunted under any circumstances. Which of the statements given above are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"The Chief Wildlife Warden may permit the hunting of even a Schedule I animal if it has become dangerous to human life or is diseased beyond recovery.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-327","question":"Consider the following statements about declaring an animal 'vermin' under the Wildlife (Protection) Act, 1972: 1. The Central Government may declare a wild animal, other than one in Schedule I, to be vermin for a specified area and period. 2. Only State Governments have the power to declare an animal vermin. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"Section 62 gives this power to the Central Government, usually acting on a state's request; animals in Schedule I cannot be declared vermin.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-328","question":"Consider the following statements about the Environment (Protection) Act, 1986: 1. The Central Government can direct the closure of an industry or the stoppage of its electricity or water supply. 2. A citizen can file a complaint in court for an offence under the Act after giving 60 days' notice to the government. 3. The Act does not apply to hazardous substances. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"The Act expressly covers the handling of hazardous substances; Section 5 gives sweeping powers of direction and Section 19 allows citizen complaints after notice.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-329","question":"Consider the following statements about the Environmental Impact Assessment Notification, 2006: 1. It was issued under the Environment (Protection) Act, 1986. 2. Category A projects are appraised at the central level, and Category B projects by State-level Environment Impact Assessment Authorities. 3. Public consultation is required for all Category B2 projects. Which of the statements given above are correct?","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Category B2 projects need neither a full EIA report nor public consultation; that is what separates them from B1 projects.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-330","question":"Arrange the stages of environmental clearance under the EIA Notification, 2006 in the correct order: 1. Appraisal 2. Scoping 3. Public consultation 4. Screening","options":["2, 4, 3, 1","4, 3, 2, 1","4, 2, 3, 1","2, 3, 4, 1"],"answer":2,"explanation":"Screening decides whether a B project needs an EIA, scoping sets the terms of reference, public consultation follows the draft report, and appraisal comes last.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-331","question":"Consider the following statements about Coastal Regulation Zone notifications: 1. They are issued under the Environment (Protection) Act, 1986. 2. CRZ-I covers ecologically sensitive areas such as mangroves and coral reefs. 3. CRZ-IV covers the water area from the low tide line up to the limit of territorial waters (12 nautical miles). Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"CRZ-I is the most protected category; CRZ-II covers built-up areas, CRZ-III relatively undisturbed rural areas, and CRZ-IV the territorial waters and tidal water bodies.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-332","question":"Consider the following statements about the National Green Tribunal: 1. It is not bound by the procedure of the Code of Civil Procedure, 1908, but is guided by the principles of natural justice. 2. Appeals against its orders lie to the Supreme Court. 3. It hears cases arising under the Wildlife (Protection) Act, 1972. Which of the statements given above are correct?","options":["1, 2 and 3","1 and 2 only","2 only","1 and 3 only"],"answer":1,"explanation":"The Wildlife (Protection) Act is not among the seven laws listed in Schedule I of the NGT Act, which include the Water, Air, Environment (Protection), Forest (Conservation) and Biological Diversity Acts.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-333","question":"The Public Liability Insurance Act, 1991 provides for:","options":["Insurance of forest land diverted for industry","Compensation to farmers for crop loss from pollution, to be decided by courts","Insurance cover for wildlife killed in road accidents","Immediate relief, on a no-fault basis, to people affected by accidents while hazardous substances are handled"],"answer":3,"explanation":"Owners handling hazardous substances must take insurance so that victims get quick interim relief without proving negligence.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-334","question":"Consider the following statements about the Biological Diversity Act, 2002: 1. Foreign nationals and companies need the approval of the National Biodiversity Authority before obtaining biological resources occurring in India. 2. Local people and communities, including growers and practitioners of indigenous medicine such as vaids and hakims, are exempt from giving prior intimation to the State Biodiversity Board for access. Which of the statements given above is/are correct?","options":["1 only","2 only","Neither 1 nor 2","Both 1 and 2"],"answer":3,"explanation":"The Act regulates foreign access through the NBA and Indian commercial users through State Boards, while exempting local communities and traditional practitioners.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-335","question":"Consider the following statements about the Scheduled Tribes and Other Traditional Forest Dwellers (Recognition of Forest Rights) Act, 2006: 1. 'Other traditional forest dwellers' must have lived primarily in and depended on forests for at least three generations (75 years) before 13 December 2005. 2. Rights recognised under the Act are heritable but cannot be sold or transferred. 3. The Act recognises community rights over minor forest produce and community forest resources. Which of the statements given above are correct?","options":["1 and 2 only","1, 2 and 3","2 only","1 and 3 only"],"answer":1,"explanation":"All three are provisions of the Act; a generation is taken as 25 years, and rights pass to heirs but are not alienable.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-336","question":"Consider the following statements about tiger reserves: 1. A tiger reserve is notified by the State Government on the recommendation of the National Tiger Conservation Authority. 2. A tiger reserve consists of a core or critical tiger habitat and a buffer or peripheral area. 3. Tiger reserves are notified under the Environment (Protection) Act, 1986. Which of the statements given above are correct?","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"Tiger reserves are notified under Section 38V of the Wildlife (Protection) Act, inserted by the 2006 amendment, not under the EPA.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-337","question":"Consider the following statements about the Solid Waste Management Rules, 2016: 1. Waste generators must segregate waste into biodegradable (wet), non-biodegradable (dry) and domestic hazardous waste. 2. The rules apply only to municipal areas and not to special economic zones, railways or airports. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"The 2016 rules extended coverage beyond municipal areas to census towns, SEZs, railway and airport areas, industrial townships and more.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-338","question":"Under the Bio-Medical Waste Management Rules, 2016, used needles and other sharps are to be collected in:","options":["Yellow bags","Red bags","White (translucent) puncture-proof containers","Blue cardboard boxes"],"answer":2,"explanation":"Yellow is for anatomical and soiled waste, red for contaminated recyclables such as tubing and gloves, white for sharps, and blue for glassware and metallic implants.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-339","question":"Consider the following statements about the Wetlands (Conservation and Management) Rules, 2017: 1. They were framed under the Environment (Protection) Act, 1986. 2. They provide for a State Wetlands Authority in each state and union territory. 3. They exclude river channels and paddy fields from their definition of 'wetland'. Which of the statements given above are correct?","options":["1 only","1 and 2 only","1, 2 and 3","2 and 3 only"],"answer":2,"explanation":"Unlike the broad Ramsar definition, the Indian rules leave out river channels, paddy fields and certain human-made water bodies built for purposes such as drinking water or aquaculture.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-340","question":"The National Forest Policy, 1988 set the goal of having:","options":["Half of the country's area under dense forest","One-fourth of the country's area under protected areas","One-third of the plains and half of the hills under tree plantations","One-third of the country's geographical area under forest or tree cover, and two-thirds in the hills and mountains"],"answer":3,"explanation":"The policy's national goal is 33 per cent forest or tree cover, rising to two-thirds in hilly and mountainous regions to prevent erosion.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-341","question":"Consider the following statements about the Compensatory Afforestation Fund Act, 2016: 1. Money collected for compensatory afforestation is credited to funds in the public accounts of India and of the states. 2. Ninety per cent of the money goes to the state funds and ten per cent to the national fund. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"The Act created the National and State Compensatory Afforestation Funds under the public accounts, with a 90:10 split in favour of the states.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-342","question":"Which of the following pairs of body and the law under which it was set up are correctly matched? 1. Wildlife Crime Control Bureau — Wildlife (Protection) Act, 1972 2. Central Zoo Authority — Wildlife (Protection) Act, 1972 3. State Biodiversity Boards — Environment (Protection) Act, 1986. Select the correct answer.","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"The WCCB (2006 amendment) and the Central Zoo Authority (1991 amendment) are bodies under the Wildlife Act; State Biodiversity Boards are set up under the Biological Diversity Act, 2002.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-343","question":"By an amendment in 2023, the Forest (Conservation) Act, 1980 was renamed as the:","options":["Van (Sanrakshan Evam Samvardhan) Adhiniyam, 1980","Van Adhikar Adhiniyam, 1980","Rashtriya Van Niti Adhiniyam, 1980","Van Suraksha Adhiniyam, 1980"],"answer":0,"explanation":"The new name means Forest (Conservation and Augmentation) Act; 'Van Adhikar' (forest rights) belongs to the separate Forest Rights Act, 2006.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-344","question":"Consider the following statements about the Air (Prevention and Control of Pollution) Act, 1981: 1. State Governments may declare any area an air pollution control area. 2. Noise was brought within the meaning of 'air pollutant' by an amendment in 1987. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Both are correct; the 1987 amendment added noise to the definition of air pollutant, before the separate Noise Rules of 2000.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-345","question":"The Environment (Protection) Act, 1986 was enacted by Parliament under Article 253, to implement decisions taken at:","options":["The Rio Earth Summit, 1992","The UN Conference on the Human Environment, Stockholm, 1972","The Montreal Protocol negotiations, 1987","The Brundtland Commission"],"answer":1,"explanation":"Article 253 lets Parliament legislate to give effect to international decisions; the Act's preamble refers to the Stockholm Conference. Rio came six years after the Act.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-346","question":"Consider the following statements: 1. Keibul Lamjao National Park floats on phumdis in Loktak Lake, Manipur. 2. It is the natural home of the sangai, or brow-antlered deer. 3. Phumdis are floating mats of vegetation, soil and organic matter. Which of the statements given above are correct?","options":["1 and 2 only","1, 2 and 3","2 and 3 only","1 only"],"answer":1,"explanation":"Keibul Lamjao is the world's only floating national park; the sangai's survival depends on the thickness of the phumdis, which change with the lake's water level.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-347","question":"Consider the following statements about the leatherback turtle: 1. It is the largest living turtle and lacks a hard bony shell. 2. In India, it nests mainly on beaches of the Andaman and Nicobar Islands. 3. It feeds mainly on jellyfish. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Its carapace is leathery skin over small bones; Great and Little Nicobar and Little Andaman host its nesting beaches, and floating plastic bags are a hazard because they resemble jellyfish.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-348","question":"Consider the following statements about pangolins: 1. Two species of pangolin are found in India. 2. Pangolins feed mainly on ants and termites. 3. Pangolin scales are made of keratin. Which of the statements given above are correct?","options":["1, 2 and 3","1 and 2 only","2 only","1 and 3 only"],"answer":0,"explanation":"India has the Indian and the Chinese pangolin; their keratin scales, the same material as human nails, are smuggled for unproven medicinal uses.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-349","question":"The fishing cat, the state animal of West Bengal, is primarily a species of:","options":["High-altitude grasslands","Dry thorn scrub","Wetlands, marshes and mangroves","Dense coniferous forests"],"answer":2,"explanation":"It hunts fish in wetlands and mangroves such as the Sundarbans and Coringa; draining and converting wetlands is its main threat.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-350","question":"Consider the following statements about vultures in South Asia: 1. Their steep decline was traced to the veterinary drug diclofenac in the carcasses of treated cattle. 2. Diclofenac causes kidney failure in Gyps vultures. 3. Meloxicam is considered a vulture-safe alternative to diclofenac. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Vultures feeding on carcasses of cattle treated with diclofenac died of kidney failure; India banned its veterinary use in 2006 and meloxicam was found safe.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-351","question":"The pygmy hog, the world's smallest wild pig, survives mainly in:","options":["Mangrove forests of the Sundarbans","Tall, wet grasslands of the Himalayan foothills, notably Manas in Assam","Dry deciduous forests of central India","Shola grasslands of the Nilgiris"],"answer":1,"explanation":"It depends on undisturbed tall terai-duar grasslands; dry-season burning and grassland conversion pushed it to the edge of extinction.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-352","question":"Chilika Lake in Odisha is well known for its population of the:","options":["Ganges river dolphin","Indus river dolphin","Irrawaddy dolphin","Finless porpoise"],"answer":2,"explanation":"Chilika, a brackish lagoon, holds one of the largest lagoon populations of the Irrawaddy dolphin; the Ganges dolphin lives in fresh rivers.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-353","question":"Neelakurinji (Strobilanthes kunthiana), which carpets the shola grasslands of the Western Ghats with blue flowers, is notable because it:","options":["Flowers together over large areas only once in about twelve years","Flowers every monsoon for one week","Is an invasive weed introduced from Africa","Grows only in mangrove swamps"],"answer":0,"explanation":"This synchronised, long-interval flowering (as in the Munnar hills) is a famous example of gregarious plietesial flowering.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-354","question":"Nepenthes khasiana, a plant found in the north-east of India, is:","options":["A mangrove species of the Sundarbans","A parasitic plant that grows on the roots of trees","A floating aquatic weed","An insect-eating pitcher plant endemic to Meghalaya"],"answer":3,"explanation":"It traps insects in pitcher-shaped leaves to obtain nitrogen in poor soils and is India's only native pitcher plant species.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-355","question":"Which of the following are invasive alien species in India? 1. African catfish (Clarias gariepinus) 2. Giant African land snail 3. Golden mahseer. Select the correct answer.","options":["1 and 2 only","2 and 3 only","1 only","1, 2 and 3"],"answer":0,"explanation":"The African catfish, introduced for aquaculture, preys on native fish, and the giant African snail damages crops; the golden mahseer is a native Himalayan game fish.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-356","question":"Sal and teak are characteristic trees of which forest type in India?","options":["Tropical wet evergreen forests","Tropical deciduous forests","Montane temperate forests","Littoral and swamp forests"],"answer":1,"explanation":"Both shed their leaves in the dry season; sal dominates moister deciduous forests of the north and east, and teak the drier peninsular ones.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-357","question":"Arrange the following vegetation types of the Himalaya in order of increasing altitude: 1. Alpine meadows 2. Tropical deciduous forests 3. Temperate coniferous forests","options":["2, 3, 1","3, 2, 1","2, 1, 3","1, 3, 2"],"answer":0,"explanation":"Deciduous forests clothe the foothills, conifers such as deodar and fir grow higher up, and alpine meadows (bugyals) lie above the tree line.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-358","question":"Cacti and other CAM plants open their stomata at night rather than during the day. This helps them to:","options":["Absorb more sunlight at night","Avoid being eaten by daytime herbivores","Take in carbon dioxide while losing far less water, storing it as organic acids for use in daytime photosynthesis","Release oxygen faster in the dark"],"answer":2,"explanation":"Cool night air cuts evaporation; the CO2 fixed at night is released inside the leaf by day while the stomata stay shut.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-359","question":"Consider the following statements: 1. In hot, dry conditions, C4 plants use water more efficiently than C3 plants. 2. Wheat and rice are C4 plants. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"C4 plants such as maize, sugarcane and sorghum concentrate CO2 and avoid photorespiration; wheat and rice are C3 plants.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-360","question":"Alternate wetting and drying of paddy fields, instead of keeping them flooded throughout, reduces methane emissions because:","options":["Dry soil absorbs methane from the air","Periodic draining lets oxygen into the soil, suppressing the methane-producing microbes that need oxygen-free conditions","Rice plants stop growing when the field is dry","Water itself is the source of methane"],"answer":1,"explanation":"Methanogenic archaea work only in anaerobic, waterlogged soil; brief aerobic spells cut their activity, though they can raise nitrous oxide a little.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-361","question":"Coating urea with neem oil mainly helps by:","options":["Making urea dissolve faster in irrigation water","Adding phosphorus to the fertiliser","Killing earthworms that consume nitrogen","Slowing nitrification, so that nitrogen is released more gradually and less is lost"],"answer":3,"explanation":"Neem compounds inhibit nitrifying bacteria; this improves nitrogen-use efficiency, reduces leaching and nitrous oxide loss, and also discourages diversion of subsidised urea to industry.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-362","question":"Ocean thermal energy conversion (OTEC) is best suited to tropical seas because it requires:","options":["A temperature difference of about 20 °C between warm surface water and cold deep water","Very high tides twice a day","Strong steady winds over the ocean","Water with high salt content"],"answer":0,"explanation":"OTEC runs a heat engine between warm surface and cold deep water; only tropical waters give a large enough difference over a reasonable depth.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-363","question":"The Puga valley in Ladakh is known for its potential for:","options":["Tidal energy","Wind energy","Geothermal energy","Uranium mining"],"answer":2,"explanation":"Hot springs and high subsurface temperatures make Puga one of India's most promising geothermal fields.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-364","question":"Consider the following statements: 1. Green hydrogen is produced by electrolysis of water using renewable electricity. 2. Grey hydrogen is produced from natural gas without capturing the carbon dioxide released. 3. Blue hydrogen is made from fossil fuels with the carbon dioxide captured and stored. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"The colour labels describe how the hydrogen is made; only the green route avoids fossil fuels altogether.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-365","question":"Second-generation (2G) ethanol is produced mainly from:","options":["Sugarcane juice and grain","Lignocellulosic biomass such as crop residues and woody waste","Algae grown in ponds","Used cooking oil"],"answer":1,"explanation":"First-generation ethanol uses food crops; 2G ethanol breaks down the cellulose in residues such as rice straw, so it does not compete with food.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-366","question":"The Gaia hypothesis, which proposes that the Earth's living and non-living parts act together as a self-regulating system, was put forward by:","options":["Rachel Carson","James Lovelock","Aldo Leopold","Garrett Hardin"],"answer":1,"explanation":"Lovelock, later with Lynn Margulis, proposed it in the 1970s; Carson wrote Silent Spring and Hardin 'The Tragedy of the Commons'.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-367","question":"The Environmental Kuznets Curve hypothesis suggests that, as a country's income per head rises:","options":["Pollution falls steadily from the very start","Pollution rises without limit","Pollution has no relationship with income","Pollution first rises and then falls after a certain income level, giving an inverted U-shape"],"answer":3,"explanation":"The idea is that richer societies eventually demand and can afford cleaner technology; the curve holds for some local pollutants but is disputed for CO2.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-368","question":"Which one of the following is NOT one of the nine 'planetary boundaries' proposed by Johan Rockström and colleagues?","options":["Ocean acidification","Stratospheric ozone depletion","Size of the human population","Land-system change"],"answer":2,"explanation":"The boundaries cover climate change, biosphere integrity, land-system change, freshwater, biogeochemical flows, ocean acidification, aerosols, ozone and novel entities; population is a driver, not a boundary.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-369","question":"Populations of one plant species growing in different habitats show inherited differences in form that suit them to local conditions, which persist when they are grown together in the same garden. Such populations are called:","options":["Ecotypes","Ecads","Ecotones","Ecological equivalents"],"answer":0,"explanation":"Ecotypes differ genetically; ecads differ only because of the environment and lose those differences when grown under the same conditions.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-370","question":"The part of its potential range of conditions and resources that a species actually occupies in the presence of competitors is called its:","options":["Fundamental niche","Habitat","Ecotone","Realised niche"],"answer":3,"explanation":"The fundamental niche is what a species could use with no competitors; competition usually squeezes it into a smaller realised niche.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-371","question":"Where two similar species of finch live on the same island, their beak sizes differ more than where each lives alone. This pattern is called:","options":["Convergent evolution","Character displacement","Competitive release","Adaptive radiation"],"answer":1,"explanation":"Competition favours divergence in the traits used for feeding where the species overlap; competitive release is a species widening its niche when a competitor is absent.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-372","question":"A harmless hoverfly with black-and-yellow stripes that resembles a stinging wasp is an example of:","options":["Müllerian mimicry","Batesian mimicry","Camouflage","Aposematism"],"answer":1,"explanation":"In Batesian mimicry a harmless species copies a harmful one; in Müllerian mimicry two harmful species share the same warning pattern.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-373","question":"The breaking down of detritus into smaller particles by detritivores such as earthworms is called:","options":["Catabolism","Humification","Mineralisation","Fragmentation"],"answer":3,"explanation":"Fragmentation is physical breakdown by detritivores; catabolism is the chemical breakdown by bacterial and fungal enzymes that follows.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-374","question":"Consider the following statements: 1. Humus is highly resistant to microbial action and decomposes very slowly. 2. Mineralisation is the release of inorganic nutrients as humus is further broken down by microbes. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Humus is a dark, colloidal store of nutrients that breaks down slowly; its gradual mineralisation releases nutrients for plants.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-375","question":"Although the oceans cover about 70 per cent of the Earth's surface, their share of the biosphere's total annual net primary productivity is roughly:","options":["Two-thirds","Nine-tenths","One-third","Seven-tenths"],"answer":2,"explanation":"Of about 170 billion tonnes of dry matter produced each year, the oceans contribute only about 55 billion, limited by nutrients and light.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-376","question":"Assertion (A): The pyramid of energy in an aquatic ecosystem is inverted. Reason (R): In the open ocean, the standing biomass of phytoplankton can be smaller than that of the zooplankton feeding on it. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Only the biomass pyramid can be inverted in the sea; the energy pyramid is always upright because each level receives less energy per unit time than the one below.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-377","question":"Assertion (A): Dead leaves decompose much faster on the floor of a tropical rainforest than in a coniferous forest of high latitudes. Reason (R): Warm and moist conditions favour the activity of decomposer microbes. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Temperature and moisture are the main climatic controls on decomposition; cold boreal soils with resinous litter build up thick organic layers instead.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-378","question":"Assertion (A): Molecule for molecule, methane traps far more heat than carbon dioxide. Reason (R): Methane is produced by the anaerobic decomposition of organic matter in wetlands. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true, but methane's potency comes from how strongly it absorbs infrared in otherwise open parts of the spectrum, not from where it is produced.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-379","question":"Assertion (A): Chlorofluorocarbons were once widely used as refrigerants and aerosol propellants. Reason (R): CFCs are highly reactive and toxic in the lower atmosphere. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"CFCs were popular precisely because they are stable, non-flammable and non-toxic; that stability lets them survive long enough to reach the stratosphere.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-380","question":"Assertion (A): Mangrove forests are well developed in the Sundarbans delta. Reason (R): In many mangrove species, seeds germinate while still attached to the parent tree. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Vivipary is a real mangrove adaptation, but the Sundarbans' extensive mangroves are explained by its sheltered, silt-rich, tidal delta, not by vivipary.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-381","question":"Assertion (A): In winter, a deep lake in a cold region freezes only at the surface, and fish survive in the water below. Reason (R): Water is densest at about 4 °C, so colder water and ice stay at the top. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Water below 4 °C is lighter and rises, so ice forms on top and insulates the denser, 4 °C water at the bottom.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-382","question":"Assertion (A): Depletion of the ozone layer is the main cause of global warming. Reason (R): Ozone in the stratosphere absorbs ultraviolet radiation from the Sun. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Ozone depletion and global warming are different problems; warming is driven mainly by CO2 and other greenhouse gases, though some ozone-depleting gases also trap heat.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-383","question":"Assertion (A): DDT was used widely in India to control malaria mosquitoes. Reason (R): DDT breaks down rapidly in the environment and does not accumulate in food chains. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"DDT is persistent and fat-soluble, which is exactly why it biomagnifies; it is a persistent organic pollutant under the Stockholm Convention.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-384","question":"Assertion (A): Clear-felling the forest in a river's catchment often increases peak flood flows downstream. Reason (R): Forest soils, with their litter and root channels, let more rainwater soak in and so delay runoff. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Without forest cover, infiltration falls and rain runs off quickly, so floods peak higher and sooner and more silt reaches the river.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-385","question":"Assertion (A): Lichens are often the pioneer organisms on bare rock. Reason (R): Lichens are sensitive to sulphur dioxide pollution. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Lichens pioneer rock because they tolerate drought and secrete acids that weather it into soil; their SO2 sensitivity makes them pollution indicators but does not explain the pioneering.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-386","question":"Assertion (A): Mercury contamination of fish is a serious health concern for communities that eat a lot of fish. Reason (R): Inorganic mercury is absorbed and retained in body tissues far more readily than methylmercury. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"It is the other way round: bacteria convert inorganic mercury into methylmercury, which is readily absorbed, retained and biomagnified.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-387","question":"Assertion (A): Secondary succession is usually slower than primary succession. Reason (R): In secondary succession, soil is already present at the start. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Because soil and often seeds survive, secondary succession is faster; primary succession on bare rock must first build soil, which can take centuries.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-388","question":"Assertion (A): Coral reefs are often called the 'rainforests of the sea'. Reason (R): Coral reefs are built from the calcium carbonate skeletons of coral polyps. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"The nickname reflects their exceptional biodiversity and productivity, not the material they are built from.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-389","question":"Assertion (A): Nitrogen often limits plant growth even though it makes up about 78 per cent of the atmosphere. Reason (R): Most plants can absorb atmospheric nitrogen directly through their leaves. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Plants cannot use N2 gas; they depend on nitrogen fixed into ammonium or nitrate by microbes, lightning or industry, which is why nitrogen is so often limiting.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-390","question":"Assertion (A): Monoculture plantations of eucalyptus restore biodiversity as effectively as natural regeneration of a native forest. Reason (R): Tree plantations can take up and store carbon. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Plantations store carbon, but single-species stands support far fewer species than diverse native forest, so tree cover alone is a poor measure of restoration.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-391","question":"Assertion (A): Burning fossil fuels lowers the proportion of carbon-14 in the carbon dioxide of the atmosphere. Reason (R): Fossil fuels are millions of years old, so their carbon-14 has almost completely decayed. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"This dilution, the Suess effect, is one of the isotopic fingerprints showing that the rise in atmospheric CO2 comes from fossil carbon.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-392","question":"Consider the following statements about wetlands: 1. Many wetlands help recharge groundwater. 2. Wetlands filter sediments and pollutants and are sometimes called the 'kidneys of the landscape'. 3. Draining wetlands always reduces greenhouse gas emissions. Which of the statements given above are correct?","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"Draining peat-rich wetlands exposes stored carbon to oxygen, releasing large amounts of CO2, even if methane emissions fall.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-393","question":"The East Kolkata Wetlands, a Ramsar site, are internationally known for:","options":["Being the largest breeding ground of flamingos in India","Using the city's sewage for fish farming and agriculture, which also treats the waste water","Hosting the only population of the Irrawaddy dolphin in West Bengal","Being a high-altitude glacial lake"],"answer":1,"explanation":"Kolkata's sewage feeds fishponds (bheris) where sunlight and algae treat the water while producing fish and vegetables: a model of resource recovery.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-394","question":"Sambhar Lake, a Ramsar site that hosts large numbers of flamingos, is:","options":["A freshwater lake formed by a volcanic crater in Maharashtra","A brackish coastal lagoon in Odisha","A glacial lake in Ladakh","India's largest inland saline lake, in Rajasthan"],"answer":3,"explanation":"Sambhar is a shallow saline wetland and a major source of salt; Lonar is the crater lake, Chilika the coastal lagoon.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-395","question":"Two river water samples have a Biochemical Oxygen Demand of 2 mg/L (sample A) and 25 mg/L (sample B). Which of the following is the correct inference?","options":["Sample B probably carries more organic pollution and is likely to have less dissolved oxygen","Sample A is more polluted, because a low BOD means little oxygen is present","BOD measures dissolved salts, so sample B is saltier","BOD says nothing about pollution, so the samples cannot be compared"],"answer":0,"explanation":"BOD is the oxygen microbes need to break down organic matter; a high value signals heavy organic (often sewage) load that depletes dissolved oxygen.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-396","question":"According to the monoclimax theory of F. E. Clements, the climax community of a region is determined mainly by:","options":["The type of soil","Climate","Topography","Periodic fire"],"answer":1,"explanation":"Clements held that each climatic region has a single climax; the polyclimax view later argued that soil, topography and fire can produce several stable climaxes.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-397","question":"E. P. Odum's 'Y-shaped' model of energy flow shows:","options":["Energy returning from consumers to producers","Energy flowing equally to all trophic levels","Grazing and detritus food chains as two channels drawing on a common producer base","Producers and decomposers as a single trophic level"],"answer":2,"explanation":"The Y-shaped model splits the flow from producers into a grazing arm and a detritus arm, more realistic than a single-channel chain.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-398","question":"Consider the following statements about lead pollution: 1. Exposure to lead can harm the neurological development of children. 2. Lead is not a cumulative poison, because the body excretes it quickly. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"Lead accumulates in bones and tissues over time; there is no known safe level for children, which is why leaded petrol and lead paints were phased out.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-399","question":"Effluents from leather tanneries, such as those along the Ganga at Kanpur, are a major source of which pollutant?","options":["Arsenic","Fluoride","Radon","Chromium"],"answer":3,"explanation":"Chrome tanning uses chromium salts; the hexavalent form that can arise is toxic and carcinogenic, while arsenic and fluoride in groundwater are largely geogenic.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-400","question":"The Nalgonda technique, developed in India, is used for:","options":["Removing arsenic from groundwater","Treating tannery effluents","Removing excess fluoride from drinking water","Desalinating seawater"],"answer":2,"explanation":"It uses alum and lime to precipitate fluoride, a problem in groundwater in parts of Andhra Pradesh, Telangana, Rajasthan and other states.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-401","question":"Acid mine drainage arises mainly when:","options":["Sulphide minerals such as pyrite, exposed by mining, react with air and water to form sulphuric acid","Acid rain falls on open-cast mines","Miners use acids to dissolve coal","Limestone dust from mines dissolves in rivers"],"answer":0,"explanation":"Oxidation of exposed iron sulphides makes the water acidic and loaded with dissolved metals; limestone, by contrast, neutralises acidity.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-402","question":"Coastal 'dead zones', such as the one that forms each summer in the Gulf of Mexico, are caused mainly by:","options":["Oil spills from tankers","Nutrient run-off that fuels algal blooms, whose decomposition uses up the oxygen in the water","Rising sea temperatures alone, which kill fish directly","Overfishing of predatory fish"],"answer":1,"explanation":"Fertiliser-rich river water triggers blooms; as the algae die and decay, bottom water becomes hypoxic, so fish and shellfish flee or die.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-403","question":"Consider the following statements about 'red tides': 1. They are caused by blooms of certain dinoflagellates and other microalgae. 2. Toxins from such blooms can build up in shellfish and poison people who eat them. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Harmful algal blooms can discolour the sea and their toxins concentrate in filter-feeding shellfish, causing paralytic and other shellfish poisoning.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-404","question":"Endosulfan, whose aerial spraying on cashew plantations in Kasaragod, Kerala was linked to serious health problems, is:","options":["A herbicide that breaks down within days","A synthetic fertiliser containing phosphorus","A biological pesticide made from neem","An organochlorine pesticide listed as a persistent organic pollutant under the Stockholm Convention"],"answer":3,"explanation":"Endosulfan is persistent and toxic; it was added to the Stockholm Convention's list in 2011, the same year India's Supreme Court banned it.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-405","question":"Consider the following statements about biochar: 1. It is made by heating biomass with little or no oxygen (pyrolysis). 2. The carbon in biochar is far more stable in soil than the carbon in raw crop residues. Which of the statements given above is/are correct?","options":["Both 1 and 2","1 only","2 only","Neither 1 nor 2"],"answer":0,"explanation":"Pyrolysis converts biomass into a stable, porous charcoal that can store carbon in soil for centuries and improve water and nutrient retention.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-406","question":"Consider the following pairs of protected area and state: 1. Periyar — Kerala 2. Nagarhole — Karnataka 3. Sariska — Rajasthan 4. Nameri — Arunachal Pradesh. How many of the pairs given above are correctly matched?","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Nameri is in Assam, on the north bank of the Brahmaputra; its neighbour across the border in Arunachal Pradesh is Pakke.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-407","question":"Consider the following protected areas: 1. Eravikulam 2. Kudremukh 3. Dampa 4. Papikonda. How many of them lie in the Western Ghats?","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Eravikulam (Kerala) and Kudremukh (Karnataka) are in the Western Ghats; Dampa is in Mizoram and Papikonda in the Eastern Ghats of Andhra Pradesh.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-408","question":"Consider the following pairs of pollutant and control technology: 1. Sulphur dioxide — flue-gas desulphurisation 2. Particulate matter — electrostatic precipitator 3. Nitrogen oxides — selective catalytic reduction 4. Carbon monoxide — electrostatic precipitator. How many of the pairs given above are correctly matched?","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"An ESP captures charged particles and cannot remove a gas like CO, which is controlled by better combustion and oxidation catalysts.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-409","question":"Consider the following gases: 1. Methane 2. Sulphur hexafluoride 3. CFC-11 4. Water vapour. How many of them are in the basket of greenhouse gases covered by the Kyoto Protocol?","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"The Kyoto basket covers CO2, methane, nitrous oxide, HFCs, PFCs and SF6 (with NF3 added later); CFCs are left to the Montreal Protocol, and water vapour is not regulated.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-410","question":"Consider the following statements about Project Tiger: 1. It was launched in 1973. 2. It began with nine tiger reserves. 3. Corbett was among the first tiger reserves. How many of the statements given above are correct?","options":["Only one","Only two","All three","None"],"answer":2,"explanation":"Project Tiger started on 1 April 1973 with nine reserves, including Corbett, Kanha, Manas, Palamau, Ranthambore, Similipal, Bandipur, Melghat and Sundarbans.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-411","question":"Match the biosphere reserve with its state(s). A. Nokrek  B. Dibru-Saikhowa  C. Achanakmar-Amarkantak  D. Agasthyamala; 1. Assam  2. Kerala and Tamil Nadu  3. Meghalaya  4. Madhya Pradesh and Chhattisgarh","options":["A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4","A-1, B-3, C-2, D-4","A-3, B-1, C-4, D-2"],"answer":3,"explanation":"Nokrek is in the Garo Hills of Meghalaya, Dibru-Saikhowa in upper Assam, Achanakmar-Amarkantak spans MP and Chhattisgarh, and Agasthyamala lies at the southern tip of the Western Ghats.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-412","question":"Match the person with the field of work for which they are best known. A. Salim Ali  B. M. S. Swaminathan  C. Sunderlal Bahuguna  D. Madhav Gadgil; 1. Chipko movement  2. Ornithology  3. Western Ghats Ecology Expert Panel  4. Green Revolution in India","options":["A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3","A-2, B-1, C-4, D-3"],"answer":1,"explanation":"Salim Ali was the 'Birdman of India', Swaminathan led the Green Revolution in wheat and rice, Bahuguna was a Chipko leader, and Gadgil chaired the 2011 Western Ghats panel.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-413","question":"Consider the following refrigerants: 1. Ammonia 2. Carbon dioxide 3. Propane 4. HFC-134a. How many of them are 'natural' refrigerants with zero ozone-depleting potential and very low global warming potential?","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Ammonia, CO2 and hydrocarbons such as propane are natural refrigerants; HFC-134a does not harm ozone but has a GWP of over a thousand.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-414","question":"Consider the following gases: 1. Ozone 2. Nitrogen 3. Argon 4. Water vapour. How many of them are greenhouse gases?","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Ozone and water vapour absorb infrared; nitrogen (a symmetric two-atom molecule) and argon (a single atom) do not.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-415","question":"Which of the following pairs are correctly matched? 1. Bhitarkanika — estuarine (saltwater) crocodiles 2. Gahirmatha — mass nesting of olive ridley turtles 3. Rushikulya — Irrawaddy dolphins. Select the correct answer.","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Rushikulya, like Gahirmatha, is an olive ridley mass-nesting beach in Odisha; Irrawaddy dolphins are associated with Chilika Lake.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-416","question":"The greater one-horned rhinoceros is found in which of the following protected areas? 1. Pobitora 2. Jaldapara 3. Dudhwa 4. Bandipur. Select the correct answer.","options":["1 and 2 only","1, 2 and 3 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":1,"explanation":"Rhinos live in Kaziranga, Pobitora and Orang (Assam), Jaldapara and Gorumara (West Bengal), and Dudhwa (reintroduced); Bandipur in Karnataka has none.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-417","question":"Consider the following statements about hornbills: 1. They are important seed dispersers of large-fruited forest trees. 2. During nesting, the female great hornbill seals herself inside a tree cavity and is fed by the male through a narrow slit. Which of the statements given above is/are correct?","options":["Both 1 and 2","1 only","2 only","Neither 1 nor 2"],"answer":0,"explanation":"Hornbills swallow large fruits and spread the seeds widely; their dependence on big old trees for nest cavities makes them sensitive to logging.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-418","question":"The Doyang reservoir area in Nagaland is known for:","options":["India's largest colony of flamingos","The breeding grounds of the black-necked crane","The only population of the white-winged duck","Huge autumn gatherings of migrating Amur falcons, once heavily hunted and now protected by local communities"],"answer":3,"explanation":"Amur falcons stop in Nagaland on their migration from East Asia to southern Africa; communities such as Pangti turned from hunting them to protecting them.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-419","question":"Most of India lies within which of the world's major bird migration flyways?","options":["East Atlantic Flyway","Central Asian Flyway","Americas Flyway","Black Sea–Mediterranean Flyway"],"answer":1,"explanation":"The Central Asian Flyway links breeding grounds in Siberia and Central Asia to wintering areas in India; parts of the north-east also fall within the East Asian–Australasian Flyway.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-420","question":"Neonicotinoid pesticides have drawn concern from conservationists mainly because:","options":["They are fungicides that kill soil bacteria","They break down into ozone-depleting gases","They are systemic insecticides that spread through the plant into its pollen and nectar and can harm bees","They raise the acidity of soils"],"answer":2,"explanation":"Being systemic, they reach pollen and nectar, and even low doses can impair bees' foraging and navigation; several have been restricted in Europe.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-421","question":"Consider the following statements about glacial lake outburst floods (GLOFs): 1. They occur when a moraine or ice dam holding back a glacial lake fails. 2. Warming that shrinks glaciers can increase the number and size of glacial lakes. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Meltwater collects behind loose moraine; a landslide, avalanche or erosion can breach it, releasing a sudden flood downstream, as in Sikkim in 2023.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-422","question":"High humidity makes a heat wave more dangerous to human health mainly because:","options":["Sweat cannot evaporate effectively, so the body loses its main way of cooling itself","Humid air contains less oxygen","Humidity increases ultraviolet radiation","Moist air conducts heat away from the body too fast"],"answer":0,"explanation":"Evaporation of sweat removes body heat; as the wet-bulb temperature rises, this cooling fails, which is why heat-index and wet-bulb measures are used for warnings.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-423","question":"GRIHA, often mentioned in the context of sustainable buildings, is:","options":["A scheme for rural housing loans","A pollution-monitoring network for cities","An international treaty on building materials","India's national rating system for green buildings"],"answer":3,"explanation":"GRIHA (Green Rating for Integrated Habitat Assessment) was developed by TERI with the Ministry of New and Renewable Energy to rate buildings on energy, water and materials.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-424","question":"In a cap-and-trade system for controlling emissions:","options":["The government fixes a price per tonne of emissions, and firms emit as much as they wish at that price","Each firm must cut emissions by the same percentage, with no trading","Emissions are banned entirely in capped sectors","The government sets a total limit and issues allowances that firms can trade, so the market sets the price"],"answer":3,"explanation":"Cap-and-trade fixes the quantity and lets the price vary; a carbon tax does the reverse, fixing the price and letting the quantity vary.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-425","question":"Under India's Perform, Achieve and Trade (PAT) scheme for energy-intensive industries, units that beat their targets receive tradable:","options":["Renewable energy certificates","Certified emission reductions","Energy saving certificates","Green credits"],"answer":2,"explanation":"PAT, run by the Bureau of Energy Efficiency under the Energy Conservation Act, 2001, issues ESCerts to over-achievers, which under-achievers can buy.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-426","question":"Consider the following statements: 1. The Bureau of Energy Efficiency was set up under the Energy Conservation Act, 2001. 2. Star labelling is mandatory for every electrical appliance sold in India. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"The BEE runs the star-labelling programme, but labelling is mandatory only for notified appliances (such as air conditioners and refrigerators) and voluntary for others.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-427","question":"Consider the following statements: 1. Solar photovoltaic cells convert light directly into electricity. 2. Concentrated solar power plants use mirrors to focus sunlight and heat a fluid that drives a turbine. Which of the statements given above is/are correct?","options":["1 only","2 only","Neither 1 nor 2","Both 1 and 2"],"answer":3,"explanation":"PV relies on the photovoltaic effect in semiconductors, while CSP is a thermal route; CSP can store heat to generate power after sunset.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-428","question":"Consider the following statements about large dams: 1. Reservoirs in the tropics can emit significant amounts of methane as flooded vegetation decays. 2. Dams trap sediment, which can lead to erosion and shrinking of deltas downstream. Which of the statements given above is/are correct?","options":["1 only","Both 1 and 2","2 only","Neither 1 nor 2"],"answer":1,"explanation":"Hydropower is not always low-carbon: anaerobic decay in warm reservoirs releases methane, and sediment-starved deltas sink and erode.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-429","question":"The presence of faecal coliform bacteria such as E. coli in drinking water indicates that:","options":["The water has a high fluoride content","The water is hard because of calcium salts","The water has been treated with too much chlorine","The water has been contaminated with human or animal faeces"],"answer":3,"explanation":"Coliforms themselves are mostly harmless, but they signal faecal contamination and hence the possible presence of disease-causing organisms.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-430","question":"Which of the following is characteristic of an oligotrophic lake?","options":["Murky green water with frequent algal blooms","Shallow water with thick bottom sediments rich in organic matter","Very low oxygen in deep water throughout summer","Clear water, low nutrient levels and plenty of dissolved oxygen even at depth"],"answer":3,"explanation":"Oligotrophic lakes are nutrient-poor, so little algae grows and little organic matter decays at the bottom; the other options describe eutrophic lakes.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-431","question":"The relationship between fig trees and fig wasps is best described as:","options":["Obligate mutualism, in which each fig species is pollinated by its own wasp species, which lays eggs in some of the fig's flowers","Parasitism, in which the wasp gains and the fig is harmed","Commensalism, in which only the wasp benefits","Amensalism, in which the fig is harmed and the wasp unaffected"],"answer":0,"explanation":"The wasp pollinates the fig while laying eggs in some of its flowers, and its larvae feed on some developing seeds; neither partner can reproduce without the other.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-432","question":"Among animals, the group with the largest number of described species is:","options":["Insects","Fishes","Molluscs","Birds"],"answer":0,"explanation":"Insects account for well over half of all described animal species; fishes and birds are far fewer.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-433","question":"Robert May's widely quoted estimate of the total number of species on Earth, including those not yet described, is about:","options":["1.5 million","20 million","100 million","7 million"],"answer":3,"explanation":"About 1.5 million species have been described; May extrapolated from the ratio of tropical to temperate species to estimate roughly 7 million.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-434","question":"Biodiversity Heritage Sites in India are notified by:","options":["State Governments under the Biological Diversity Act, 2002, in consultation with local bodies","The Central Government under the Wildlife (Protection) Act, 1972","UNESCO on the recommendation of India","The National Green Tribunal"],"answer":0,"explanation":"Section 37 of the Biological Diversity Act lets state governments notify areas of biodiversity importance as heritage sites, in consultation with local bodies.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-435","question":"HCFCs were adopted as transitional substitutes for CFCs mainly because:","options":["They contain no chlorine at all","They are not greenhouse gases","The hydrogen in them makes them break down largely in the lower atmosphere, so less chlorine reaches the stratosphere","They react with ozone to create more ozone"],"answer":2,"explanation":"HCFCs still carry chlorine and have some ozone-depleting potential, which is why they too are being phased out under the Montreal Protocol.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-436","question":"A caterpillar eats leaves containing 1,000 J of energy. It passes 600 J out as faeces and uses 300 J in respiration; the rest goes into new tissue. What is its net production efficiency (new tissue as a share of the energy assimilated)?","options":["10%","25%","40%","33%"],"answer":1,"explanation":"Assimilated = 1,000 − 600 = 400 J; production = 400 − 300 = 100 J; 100/400 = 25%. 10% divides by the energy eaten, 40% is the assimilation efficiency, and 33% divides production by respiration.","difficulty":"very-hard","source":"UPSC Prelims · CDS"},
  {"id":"env-ecology-437","question":"To estimate the number of fish in a pond, 40 fish are caught, tagged and released. A week later, 50 fish are caught, of which 10 carry tags. Using the mark–recapture method, the estimated population is:","options":["100","400","200","2,000"],"answer":2,"explanation":"N = (marked first time × total caught second time) ÷ marked recaptured = 40 × 50 ÷ 10 = 200. Multiplying the two catches without dividing gives the 2,000 trap.","difficulty":"very-hard","source":"UPSC Prelims · CDS"},
  {"id":"env-ecology-438","question":"A population grows steadily at 2 per cent a year. Roughly how long will it take to double?","options":["20 years","50 years","70 years","35 years"],"answer":3,"explanation":"By the rule of 70, doubling time ≈ 70 ÷ 2 = 35 years (ln 2 ÷ ln 1.02 ≈ 35); 50 years is what simple, non-compounding growth would give.","difficulty":"moderate","source":"UPSC Prelims · CDS"},
  {"id":"env-ecology-439","question":"Consider the following statements: 1. In an ecosystem, both energy and nutrients flow in one direction only. 2. Gross primary productivity is the rate at which organic matter is produced in photosynthesis. 3. A considerable part of gross primary productivity is used by plants in their own respiration. Which of the statements given above are correct?","options":["2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Energy flows one way, but nutrients are recycled between living and non-living parts of the ecosystem; GPP minus plant respiration gives NPP.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-440","question":"Consider the following statements comparing the phosphorus and carbon cycles: 1. Atmospheric inputs of phosphorus through rain are much smaller than those of carbon. 2. Gaseous exchange of phosphorus between organisms and the environment is negligible. 3. The main reservoir of carbon is in the atmosphere and oceans, while that of phosphorus is in the Earth's crust. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three are standard differences: phosphorus is a sedimentary cycle with no meaningful gas phase, whereas carbon cycles largely through the air and water.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-441","question":"The ozone hole is far deeper over Antarctica than over the Arctic. The main reason is that:","options":["CFC emissions are higher in the Southern Hemisphere","There is more sunlight over Antarctica in winter","The Antarctic polar vortex is stronger and colder, so polar stratospheric clouds form more widely and last longer","Antarctic ice releases chlorine directly into the stratosphere"],"answer":2,"explanation":"Most CFCs were emitted in the north, but a stable, very cold vortex over Antarctica produces the clouds on which chlorine is activated, ready to destroy ozone when spring sunlight returns.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-442","question":"Consider the following statements about the Kigali Amendment: 1. It brought hydrofluorocarbons, which do not deplete ozone, under the Montreal Protocol. 2. Developed and developing countries follow the same timetable for phasing down HFCs. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"Kigali used the Montreal Protocol's machinery to tackle HFCs as greenhouse gases, with differentiated schedules: developing countries such as India start later.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-443","question":"Article 6 of the Paris Agreement deals with:","options":["Loss and damage","Adaptation to climate change","Voluntary cooperation between countries, including carbon markets and transfer of mitigation outcomes","The transparency framework for reporting"],"answer":2,"explanation":"Article 6 provides for cooperative approaches and a crediting mechanism; adaptation is Article 7, loss and damage Article 8, and transparency Article 13.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-444","question":"The Warsaw International Mechanism, set up at COP-19 of the UNFCCC in 2013, addresses:","options":["Reducing deforestation in developing countries","Loss and damage associated with the impacts of climate change","Technology transfer for renewable energy","Phasing down HFCs"],"answer":1,"explanation":"It deals with loss and damage, including extreme and slow-onset events in vulnerable countries; reducing deforestation is the subject of REDD+.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-445","question":"The principle of 'common but differentiated responsibilities' was formally set out as a principle in:","options":["The Rio Declaration on Environment and Development, 1992","The Stockholm Declaration, 1972","The Kyoto Protocol, 1997","The Paris Agreement, 2015"],"answer":0,"explanation":"Principle 7 of the Rio Declaration states it, and the UNFCCC adopted it the same year; Kyoto and Paris applied it in different ways.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-446","question":"The 'precautionary approach', set out in Principle 15 of the Rio Declaration, holds that:","options":["Only scientifically proven damage justifies regulation","The polluter must always pay the full cost of clean-up","Development must stop wherever any environmental risk exists","Where there are threats of serious or irreversible damage, lack of full scientific certainty should not be used as a reason to postpone cost-effective preventive measures"],"answer":3,"explanation":"It shifts the burden towards prevention under uncertainty; the polluter pays principle is a separate idea (Principle 16).","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-447","question":"The Genetic Engineering Appraisal Committee, which approves genetically modified organisms for environmental release in India, functions under:","options":["The Biological Diversity Act, 2002","The Seeds Act, 1966","Rules made under the Environment (Protection) Act, 1986","The Protection of Plant Varieties and Farmers' Rights Act, 2001"],"answer":2,"explanation":"GEAC works in the Environment Ministry under the 1989 Rules for hazardous micro-organisms and genetically engineered organisms, framed under the EPA.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-448","question":"Consider the following statements about Bt crops: 1. The Bt toxin is produced in the bacterium as an inactive protoxin and becomes active in the alkaline gut of the insect. 2. The bacterium Bacillus thuringiensis is killed by its own toxin. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"The bacterium is unharmed because the toxin stays inactive inside it; in the insect gut it is activated, binds to gut cells and kills the larva.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-449","question":"Farmers growing Bt crops are advised to plant 'refuge' rows of non-Bt plants of the same crop. The purpose is to:","options":["Provide food for pollinating bees","Increase the total yield of the field","Prevent the Bt gene from spreading to weeds","Keep a population of susceptible pests, so that rare resistant insects mate with them and resistance spreads more slowly"],"answer":3,"explanation":"Without refuges, only resistant pests survive and breed; failure to maintain them is one reason pink bollworm developed resistance to Bt cotton in India.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-450","question":"A gradual, continuous change in the species composition of communities along an environmental gradient, without any sharp boundary, is called:","options":["An ecotone","An ecocline","An ecad","An ecotype"],"answer":1,"explanation":"An ecotone is a relatively narrow transition zone between two communities; an ecocline is a smooth gradient, such as vegetation changing with altitude.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-451","question":"Fig trees are often regarded as keystone species in tropical forests mainly because:","options":["Different fig trees fruit at different times through the year, feeding many fruit-eating animals when other fruit is scarce","Their wood is the main timber of these forests","They fix large amounts of atmospheric nitrogen","Their roots prevent all soil erosion in the forest"],"answer":0,"explanation":"Asynchronous fruiting makes figs a lean-season lifeline for hornbills, primates, bats and other frugivores; losing figs would ripple through the whole community.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-452","question":"When a country exports large quantities of rice, it is said to be exporting 'virtual water'. This refers to:","options":["Water lost by evaporation during shipping","Groundwater that flows across national borders","The water used in growing and processing the exported crop","Desalinated water used in the exporting country"],"answer":2,"explanation":"Virtual water is the water embedded in the production of goods; water-intensive exports such as rice and cotton effectively ship water abroad.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-453","question":"In water footprint accounting, the 'grey water footprint' refers to:","options":["Rainwater stored in the soil and used by crops","Surface water and groundwater consumed in production","Lightly used household waste water from sinks and showers that can be reused","The volume of fresh water needed to dilute pollutants to meet water-quality standards"],"answer":3,"explanation":"Green is rainwater used by crops, blue is surface and groundwater consumed, and grey is dilution water; the trap is the everyday meaning of 'greywater' from households.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-454","question":"Consider the following statements: 1. Coastal upwelling brings cold, nutrient-rich deep water to the surface, making such waters highly productive. 2. During El Niño, upwelling off the coast of Peru weakens and fisheries such as the anchovy catch decline. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Upwelling zones cover a tiny share of the ocean but yield a large share of the fish catch; weaker trade winds in El Niño years shut down the Peruvian upwelling.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-455","question":"Consider the following statements about corals: 1. Bleached corals are not necessarily dead and can recover if the stress ends quickly enough. 2. Ocean acidification makes it harder for corals to build their calcium carbonate skeletons. Which of the statements given above is/are correct?","options":["1 only","Both 1 and 2","2 only","Neither 1 nor 2"],"answer":1,"explanation":"Bleached corals can regain zooxanthellae if temperatures fall soon, but prolonged bleaching starves them; lower carbonate ion levels slow calcification.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-456","question":"Arctic sea ice usually reaches its minimum extent each year in:","options":["March","June","September","December"],"answer":2,"explanation":"It melts through the northern summer and bottoms out in September, then reaches its maximum around March; Antarctic sea ice follows the opposite cycle.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-457","question":"Permafrost is defined as:","options":["Any ground covered by snow for more than six months a year","Glacier ice resting on bedrock","The top layer of soil that freezes every winter and thaws every summer","Ground that remains at or below 0 °C for at least two consecutive years"],"answer":3,"explanation":"The seasonally thawing surface layer above permafrost is the 'active layer'; as warming deepens it, carbon frozen for millennia begins to decompose.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-458","question":"Unlike methane, carbon dioxide has no single atmospheric 'lifetime'. This is because:","options":["CO2 is destroyed by ultraviolet light at a fixed rate","It is shared out among the atmosphere, oceans and land over many timescales, and a fraction of any emission stays in the air for thousands of years","CO2 is removed entirely by rain within a few weeks","CO2 turns into methane after a century"],"answer":1,"explanation":"Much of a CO2 pulse is absorbed by oceans and land within decades to centuries, but a significant share lingers for millennia until slow geological processes remove it.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-459","question":"Warmer air can hold about 7 per cent more water vapour for each 1 °C rise in temperature. This physical fact helps explain why a warming climate is expected to bring:","options":["More intense episodes of extreme rainfall","Fewer clouds everywhere","Less evaporation from the oceans","A steady fall in global humidity"],"answer":0,"explanation":"This relationship (Clausius–Clapeyron) means storms have more moisture to rain out, so heavy downpours intensify even where total rainfall changes little.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-460","question":"The idea of a remaining 'carbon budget' for a temperature limit rests on the finding that:","options":["Only methane emissions matter for long-term warming","Warming stops immediately once emissions begin to fall","Global warming is roughly proportional to cumulative total CO2 emissions","The oceans can absorb unlimited carbon dioxide"],"answer":2,"explanation":"Because warming tracks the total CO2 ever emitted, a temperature cap implies a finite amount that can still be emitted; slowing emissions alone does not stop warming.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-461","question":"'Equilibrium climate sensitivity' is defined as:","options":["The rise in sea level for each degree of warming","The warming that occurs in the first year after CO2 rises","The change in rainfall per degree of warming","The eventual global warming after atmospheric CO2 doubles from pre-industrial levels and the climate has fully adjusted"],"answer":3,"explanation":"It measures how strongly the climate responds to a doubling of CO2 once the oceans have caught up; the short-term response is a different, lower quantity.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-462","question":"Which of the following are counted as short-lived climate pollutants? 1. Black carbon 2. Methane 3. Tropospheric ozone 4. Nitrous oxide. Select the correct answer.","options":["1 and 2 only","1, 2 and 3 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":1,"explanation":"Black carbon lasts days, tropospheric ozone weeks and methane about a decade; nitrous oxide persists for over a century, so it is long-lived.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-463","question":"Which of the following are usually counted as coastal 'blue carbon' ecosystems? 1. Mangroves 2. Seagrass meadows 3. Tidal salt marshes 4. Coral reefs. Select the correct answer.","options":["1, 2 and 3 only","1 and 2 only","2 and 4 only","1, 2, 3 and 4"],"answer":0,"explanation":"Mangroves, seagrasses and salt marshes bury carbon in their sediments; coral reefs are not counted, as building calcium carbonate skeletons releases CO2.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-464","question":"Consider the following statements: 1. The world's soils hold more carbon than the atmosphere and all vegetation combined. 2. Repeated tillage generally increases the loss of organic carbon from soil. Which of the statements given above is/are correct?","options":["Both 1 and 2","1 only","2 only","Neither 1 nor 2"],"answer":0,"explanation":"Soil is the largest land carbon store; ploughing breaks up aggregates and aerates soil, speeding decomposition, which is why no-till and cover crops are promoted.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-465","question":"The average albedo of the Earth as a whole, i.e., the fraction of incoming sunlight reflected back to space, is about:","options":["0.03","0.7","0.9","0.3"],"answer":3,"explanation":"About 30 per cent of sunlight is reflected, mostly by clouds, with smaller shares from the surface and the air; 0.7 is the share absorbed, a common mix-up.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-466","question":"Under the Ramsar Convention's criteria for wetlands of international importance, a wetland qualifies on numbers alone if it regularly supports at least:","options":["2,000 waterbirds","10,000 waterbirds","20,000 waterbirds","1,00,000 waterbirds"],"answer":2,"explanation":"Criterion 5 sets the threshold at 20,000 or more waterbirds; Criterion 6 covers wetlands holding 1 per cent of a population of one waterbird species.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-467","question":"Consider the following statements about the Wildlife (Protection) Act, 1972: 1. Once a national park is finally notified, no right of any person can, as a rule, continue to exist within it. 2. In a wildlife sanctuary, the Collector may allow certain rights of people to continue, in consultation with the Chief Wildlife Warden. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"This is the key legal difference: rights must be settled and extinguished before a national park is finally declared, while a sanctuary can retain some rights such as limited grazing.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-468","question":"Under the guidelines for eco-sensitive zones around protected areas, which of the following activities is generally prohibited?","options":["Commercial mining","Rainwater harvesting","Organic farming","Construction of hotels and resorts"],"answer":0,"explanation":"Commercial mining, saw mills and polluting industries are prohibited; hotels and similar construction are regulated, while rainwater harvesting and organic farming are encouraged.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-469","question":"Camera-trap surveys used to estimate tiger numbers in India rely mainly on the fact that:","options":["Tigers are attracted to the flash of the camera","Each tiger has a unique stripe pattern, so individuals can be identified and capture–recapture methods applied","Tiger pugmarks differ by sex and can be photographed","Tigers always use the same trail each night"],"answer":1,"explanation":"Stripes are like fingerprints; photographing both flanks lets researchers identify individuals and estimate density statistically, replacing the old pugmark census.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-470","question":"Hot, dry summers and mild, wet winters, with evergreen scrub (maquis or chaparral) adapted to periodic fires, describe which biome?","options":["Tropical savanna","Mediterranean","Temperate deciduous forest","Temperate grassland (steppe)"],"answer":1,"explanation":"The Mediterranean biome occurs on west coasts at about 30–40° latitude, including California, central Chile, the Cape and south-west Australia, not just around the Mediterranean.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-471","question":"Consider the following statements about the tundra: 1. Permafrost prevents plants from developing deep roots. 2. Decomposition is rapid because of the long daylight of summer. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"Cold, waterlogged soils keep decomposition very slow despite the long summer days, so organic matter piles up as peat.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-472","question":"The soils beneath the coniferous taiga forests are typically:","options":["Deep, black and highly fertile","Red and rich in iron because of intense weathering","Saline because of high evaporation","Acidic, leached podzols, because needle litter decomposes slowly and releases acids"],"answer":3,"explanation":"Acidic needle litter and percolating snowmelt leach nutrients and iron from the upper layer, leaving a pale, infertile horizon typical of podzols.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-473","question":"Grasses withstand grazing and fire better than many other plants mainly because:","options":["They have deep tap roots that store water","Their leaves contain toxins that deter grazers","Their growing points (meristems) lie at or near the base of the plant","They reproduce only by seeds that survive fire"],"answer":2,"explanation":"Because growth comes from near the ground, grasses regrow after their tops are eaten or burnt, which is why fire and grazing maintain grasslands against trees.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-474","question":"Consider the following statements: 1. Deserts are defined mainly by very low precipitation, not by high temperature. 2. By that definition, much of Antarctica is a desert. Which of the statements given above is/are correct?","options":["1 only","2 only","Neither 1 nor 2","Both 1 and 2"],"answer":3,"explanation":"Cold deserts such as Ladakh, the Gobi and interior Antarctica receive very little precipitation even though they are cold.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-475","question":"A peat-forming wetland fed mainly by rain, with acidic, nutrient-poor water and dominated by Sphagnum moss, is called a:","options":["Fen","Marsh","Bog","Swamp"],"answer":2,"explanation":"Fens are fed by mineral-rich groundwater and are less acidic; marshes are dominated by grasses and reeds, swamps by trees.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-476","question":"The Navdanya movement, founded by Vandana Shiva, focuses mainly on:","options":["Conserving native seed diversity and promoting organic farming","Protesting against large dams on the Narmada","Protecting sacred groves in the Western Ghats","Saving the khejri trees of Rajasthan"],"answer":0,"explanation":"Navdanya ('nine seeds') runs community seed banks and promotes organic farming; the Narmada protests were the Narmada Bachao Andolan, and the khejri episode is the Bishnoi sacrifice of 1730.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-477","question":"The Plachimada struggle in Kerala was directed against:","options":["Sand mining on river beds","Groundwater depletion and pollution blamed on a soft-drink bottling plant","A nuclear power project on the coast","Clearing of mangroves for a port"],"answer":1,"explanation":"Villagers in Palakkad district protested that the plant had drawn down and polluted local groundwater; the case became a landmark in debates on water rights.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-478","question":"Consider the following pairs of Sustainable Development Goal and its theme: 1. SDG 13 — Climate action 2. SDG 14 — Life on land 3. SDG 15 — Life below water 4. SDG 6 — Clean water and sanitation. How many of the pairs given above are correctly matched?","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"SDG 14 is Life below water and SDG 15 is Life on land, so pairs 2 and 3 are swapped; SDG 13 and SDG 6 are correct.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-479","question":"Consider the following statements about ground-level ozone and crops: 1. It can reduce the yields of crops such as wheat. 2. It enters plant leaves mainly through the stomata. Which of the statements given above is/are correct?","options":["Both 1 and 2","1 only","2 only","Neither 1 nor 2"],"answer":0,"explanation":"Ozone taken in through the stomata oxidises leaf tissues and lowers photosynthesis; studies in South Asia link it to significant wheat and rice losses.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-480","question":"Ammonia released from fertilisers and livestock contributes to fine particulate (PM2.5) pollution in cities mainly because it:","options":["Is itself a solid particle when emitted","Reacts with ozone to form soot","Absorbs water vapour and becomes acid rain","Combines with acids formed from sulphur dioxide and nitrogen oxides to make ammonium sulphate and ammonium nitrate particles"],"answer":3,"explanation":"These secondary inorganic aerosols form a large share of winter PM2.5 in north India, which is why cutting ammonia can lower particulate levels even though ammonia is a gas.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-481","question":"Mesothelioma, a cancer of the lining of the lungs or abdomen, is most closely linked with exposure to:","options":["Silica dust","Coal dust","Asbestos fibres","Cotton dust"],"answer":2,"explanation":"Inhaled asbestos fibres cause asbestosis and mesothelioma; silica causes silicosis, coal dust black lung, and cotton dust byssinosis.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-482","question":"Which of the following pairs of occupational lung disease and its cause are correctly matched? 1. Byssinosis — cotton dust 2. Silicosis — silica dust from stone quarrying and cutting 3. Coal workers' pneumoconiosis — asbestos. Select the correct answer.","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Coal workers' pneumoconiosis ('black lung') is caused by coal dust, not asbestos.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-483","question":"The sievert is a unit used to measure:","options":["The number of radioactive decays per second","The energy absorbed per kilogram of tissue, without regard to the type of radiation","The effective dose of radiation, which allows for its biological effect on the body","The half-life of a radioactive isotope"],"answer":2,"explanation":"Becquerel measures activity and gray the absorbed dose; the sievert weights the dose by radiation type and tissue sensitivity to express health risk.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-484","question":"'Vitrification' of high-level radioactive waste refers to:","options":["Burning the waste at very high temperatures","Locking it into a stable glass form for long-term storage","Diluting it in seawater","Converting it into non-radioactive elements"],"answer":1,"explanation":"Mixing the waste with glass-forming materials and melting it immobilises the radionuclides; radioactivity itself cannot be destroyed by burning or chemistry.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-485","question":"The main environmental concern with seawater desalination by reverse osmosis is:","options":["The release of chlorofluorocarbons","Radioactive contamination of the product water","The large volumes of CO2 it pulls from the air","The discharge of concentrated brine into the sea and its high energy use"],"answer":3,"explanation":"Dense, highly saline brine (often with treatment chemicals) can harm seabed life near outfalls, and the energy demand adds emissions if supplied by fossil fuels.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-486","question":"Gypsum is applied to reclaim which kind of problem soil?","options":["Acidic soils","Sodic (alkali) soils, by replacing sodium with calcium","Waterlogged peat soils","Lateritic soils rich in iron"],"answer":1,"explanation":"Calcium from gypsum displaces exchangeable sodium, which is then leached away; acidic soils are corrected with lime instead.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-487","question":"LaCONES, a facility in Hyderabad, is associated with:","options":["Conserving endangered wild animals through biotechnology such as gene banking and assisted reproduction","Monitoring cyclones over the Bay of Bengal","Testing pesticides for residue levels","Breeding high-yielding rice varieties"],"answer":0,"explanation":"The Laboratory for the Conservation of Endangered Species, part of CCMB, stores genetic material and supports captive breeding, an ex situ conservation tool.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-488","question":"India's National Gene Bank for the long-term storage of plant germplasm is maintained by the:","options":["Botanical Survey of India, Kolkata","ICRISAT, Hyderabad","National Bureau of Plant Genetic Resources, New Delhi","Forest Research Institute, Dehradun"],"answer":2,"explanation":"The NBPGR stores seeds at sub-zero temperatures and other material by cryopreservation; the BSI surveys and documents wild flora.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-489","question":"Consider the following statements: 1. The Botanical Survey of India was established in 1890. 2. The Zoological Survey of India was established in 1916. 3. Both are headquartered in Kolkata. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three are correct; both bodies, under the Environment Ministry, survey, document and describe India's flora and fauna.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-490","question":"Consider the following statements about clouds and climate: 1. Low, thick clouds tend to cool the surface, mainly by reflecting sunlight. 2. High, thin cirrus clouds tend to warm the surface, because they trap outgoing infrared more than they reflect sunlight. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Cloud type and height decide the net effect, which is why clouds remain a major source of uncertainty in climate projections.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-491","question":"Consider the following statements about the Atlantic Meridional Overturning Circulation: 1. It is driven partly by cold, salty, dense water sinking in the North Atlantic. 2. Large inflows of fresh meltwater could weaken it. Which of the statements given above is/are correct?","options":["1 only","Both 1 and 2","2 only","Neither 1 nor 2"],"answer":1,"explanation":"Fresh water lowers salinity and density, reducing sinking; a weaker AMOC would alter heat transport to Europe and could shift tropical rain belts.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-492","question":"Assertion (A): The Montreal Protocol has also helped to slow global warming. Reason (R): Many of the ozone-depleting substances it controls are also potent greenhouse gases. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"CFCs have warming potentials thousands of times that of CO2, so phasing them out avoided a large amount of warming as well as ozone loss.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-493","question":"The Aarhus Convention (1998) concerns:","options":["Transboundary movement of hazardous waste","Conservation of European wildlife and habitats","Long-range air pollution","Public access to environmental information, public participation in decision-making and access to justice in environmental matters"],"answer":3,"explanation":"Aarhus is a UNECE treaty on environmental rights of citizens; hazardous waste is the Basel Convention and European wildlife the Bern Convention.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-494","question":"The Convention on Long-Range Transboundary Air Pollution (1979) was prompted chiefly by:","options":["The ozone hole over Antarctica","Acid rain damaging Scandinavian lakes, traced to emissions from other European countries","Smog over Los Angeles","Radioactive fallout from the Chernobyl accident"],"answer":1,"explanation":"Scandinavian scientists showed that sulphur emitted elsewhere in Europe was acidifying their lakes, leading to the first legally binding treaty on air pollution.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-495","question":"The idea of 'strong sustainability' holds that:","options":["Any loss of natural resources is acceptable if total wealth rises","Economic growth alone guarantees environmental protection","Natural capital cannot be fully replaced by human-made capital, so critical natural assets must be maintained","Only renewable resources need to be conserved"],"answer":2,"explanation":"Weak sustainability lets man-made capital substitute for nature as long as total capital does not fall; strong sustainability denies that full substitution is possible.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"env-ecology-496","question":"'Green GDP' refers to:","options":["GDP adjusted for the depletion of natural resources and the cost of environmental damage","The share of GDP spent on renewable energy","GDP from agriculture and forestry only","The GDP of countries with high forest cover"],"answer":0,"explanation":"Green accounting subtracts resource depletion and degradation, so growth that eats into natural capital no longer looks as large.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-497","question":"Which of the following best describes a 'circular economy'?","options":["An economy that relies mainly on exports and imports","An economy in which goods are made, used once and then landfilled","An economy driven only by recycling of plastics","An economy that keeps materials in use through reuse, repair, remanufacturing and recycling, designing waste out of the system"],"answer":3,"explanation":"The circular model replaces the linear take–make–dispose pattern; recycling is only one of several loops, and the higher loops such as reuse and repair save more.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"env-ecology-498","question":"In a food chain, producers fix 10,000 J. If the ecological efficiency between each level is 20 per cent instead of the usual 10 per cent, how much energy reaches the tertiary consumers?","options":["10 J","80 J","200 J","400 J"],"answer":1,"explanation":"10,000 × 0.2 × 0.2 × 0.2 = 80 J; 400 J is the secondary-consumer level and 10 J is what the 10 per cent rule would give.","difficulty":"hard","source":"UPSC Prelims · CDS"},
  {"id":"env-ecology-499","question":"Lake water contains 0.02 ppm of a persistent pesticide. If its concentration rises tenfold at each step from water to plankton, plankton to small fish, small fish to large fish, and large fish to fish-eating birds, its concentration in the birds will be:","options":["0.2 ppm","2 ppm","20 ppm","200 ppm"],"answer":3,"explanation":"Four tenfold steps multiply by 10,000: 0.02 × 10,000 = 200 ppm. Stopping one step short gives the 20 ppm trap.","difficulty":"hard","source":"UPSC Prelims · CDS"},
  {"id":"env-ecology-500","question":"In long-term records of predator and prey numbers, such as the lynx and snowshoe hare in Canada, the peaks in predator numbers typically:","options":["Follow the peaks in prey numbers after a time lag","Come before the peaks in prey numbers","Occur at exactly the same time as the prey peaks","Show no relation to prey numbers"],"answer":0,"explanation":"Abundant prey lets predators breed and increase, which then drives prey down and is followed by a predator decline: a lagged cycle.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"env-ecology-501","question":"In a grassland, plants fix 50,000 kJ per m² per year as gross primary production and use 30,000 kJ per m² per year in their own respiration. Grazing animals eat 2,000 kJ per m² per year of plant material. What percentage of the net primary production do the grazers consume?","options":["4 per cent","10 per cent","6.7 per cent","40 per cent"],"answer":1,"explanation":"NPP = GPP − respiration = 50,000 − 30,000 = 20,000; grazers take 2,000/20,000 = 10%. Dividing by GPP gives the 4% trap, and 40% is just NPP as a share of GPP.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-502","question":"In ecology, 'secondary productivity' is best defined as the:","options":["Rate at which green plants fix energy, minus what they lose in respiration","Total mass of living consumers present in a given area at one particular moment","Rate at which consumers form new organic matter from the food they assimilate","Rate at which decomposers release mineral nutrients from dead organic matter in soil"],"answer":2,"explanation":"Secondary productivity is the rate of formation of new organic matter by consumers (heterotrophs). The first option is net primary productivity and the second is a standing crop, which is a stock, not a rate.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-503","question":"A lake's phytoplankton has a standing biomass of 10 g per m², while its net primary productivity is 500 g per m² per year. On average, about how long does it take for this standing biomass to be replaced?","options":["About 50 days","About 7 days","About 20 days","About 0.02 days"],"answer":1,"explanation":"Turnover time = biomass ÷ productivity = 10/500 = 0.02 year ≈ 7.3 days. This rapid turnover is why a small phytoplankton stock can support a much larger biomass of consumers.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-504","question":"Consider the following statements: 1. In a mature terrestrial forest, the larger part of net primary production passes through the detritus food chain rather than the grazing food chain. 2. In the open ocean, the grazing food chain carries a larger share of the energy flow than it does in a forest. 3. The detritus food chain does not depend on solar energy, since it begins with dead organic matter. Which of the statements given above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Most forest NPP is never eaten alive and enters the detritus pathway, while ocean phytoplankton are grazed heavily. Statement 3 is wrong: dead organic matter itself came from photosynthesis, so the detritus chain also rests on solar energy.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-505","question":"In a light-and-dark bottle experiment, pond water starts with 8 mg/L of dissolved oxygen. After some hours, the light bottle holds 11 mg/L and the dark bottle 5 mg/L. What are the net and gross primary production, expressed as oxygen?","options":["Net 6 mg/L; gross 3 mg/L","Net 3 mg/L; gross 3 mg/L","Net 6 mg/L; gross 11 mg/L","Net 3 mg/L; gross 6 mg/L"],"answer":3,"explanation":"Net = light − initial = 11 − 8 = 3; respiration = initial − dark = 8 − 5 = 3; gross = net + respiration = light − dark = 6 mg/L.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-506","question":"A house sparrow eats grain and also eats caterpillars that feed on the same grain crop. In this system the sparrow occupies:","options":["The second trophic level only","The second and third trophic levels","The third trophic level only","The first and second trophic levels"],"answer":1,"explanation":"Eating grain makes it a primary consumer (level 2); eating herbivorous caterpillars makes it a secondary consumer (level 3). Omnivores routinely occupy more than one trophic level, which is why real systems form webs, not chains.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-507","question":"How many of the following statements about the capture of solar energy are correct? I. Photosynthetically active radiation (PAR) makes up less than half of the solar radiation falling on the Earth. II. PAR lies roughly in the 400–700 nm range of wavelengths. III. Plants capture only about 2–10 per cent of the PAR they receive. IV. Leaves absorb green light most strongly, which is why they look green.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are standard figures. IV reverses the truth: chlorophyll absorbs blue and red light strongly and reflects much of the green, which is why leaves look green.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-508","question":"During decomposition, water-soluble inorganic nutrients move down into the soil horizon and get precipitated as unavailable salts. This step is called:","options":["Leaching","Catabolism","Humification","Mineralisation"],"answer":0,"explanation":"Leaching is the downward movement of soluble nutrients. Catabolism is the enzymatic breakdown of detritus, humification forms humus, and mineralisation releases inorganic nutrients from humus.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-509","question":"Which of the following would speed up the decomposition of leaf litter? 1. A higher content of lignin and chitin 2. A higher content of nitrogen and water-soluble sugars 3. Warm, moist and well-aerated conditions 4. A higher carbon-to-nitrogen ratio in the litter. Select the correct answer:","options":["1 and 3 only","2 and 4 only","1, 3 and 4 only","2 and 3 only"],"answer":3,"explanation":"Nitrogen-rich, sugar-rich litter in warm, moist, aerated soil breaks down fastest. Lignin and chitin resist microbial attack, and a high C:N ratio starves decomposers of nitrogen, both slowing decay.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-510","question":"In 1997, Robert Costanza and colleagues tried to put a price on the world's ecosystem services. Their estimate of the average annual value of these services was roughly:","options":["US$ 3.3 trillion, about a fifth of global GNP then","US$ 18 trillion, about equal to global GNP then","US$ 33 trillion, nearly double global GNP then","US$ 330 trillion, about twenty times global GNP then"],"answer":2,"explanation":"Costanza et al. estimated about US$33 trillion a year, close to twice the global GNP of about US$18 trillion at the time, showing that nature's services are enormous though unpriced.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-511","question":"When Paramecium aurelia and Paramecium caudatum were grown together in the same culture with limited food, P. caudatum died out, though each species thrived when grown alone. This result led to the formulation of:","options":["The principle of resource partitioning","The principle of character displacement","The Allee principle of undercrowding","The competitive exclusion principle"],"answer":3,"explanation":"G. F. Gause's experiments showed that two species competing for the same limiting resource cannot coexist indefinitely; the inferior competitor is eliminated. Partitioning and displacement are ways species escape this outcome.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-512","question":"Robert MacArthur found that five closely related species of warbler lived on the same spruce trees without one excluding the others, because each fed mostly in a different part of the canopy. This is an example of:","options":["Interspecific facilitation","Competitive release","Interference competition","Resource partitioning"],"answer":3,"explanation":"By foraging in different zones and in different ways, the warblers divided the shared resource, which reduces competition and lets similar species coexist. Competitive release is the expansion of a niche after a competitor disappears.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-513","question":"'Each organism has a minimum and a maximum limit for every environmental factor, and excess of a factor can limit it just as much as deficiency.' This idea is associated with:","options":["Shelford's law of tolerance","Liebig's law of the minimum","Blackman's law of limiting factors","Gause's principle of exclusion"],"answer":0,"explanation":"Victor Shelford extended Liebig's idea: both too little and too much of a factor can limit an organism, so each species has a range of tolerance. Liebig considered only the scarcest nutrient.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-514","question":"How many of the following pairs of response and example are correctly matched? 1. Hibernation — bears during winter 2. Aestivation — some snails and fish during summer 3. Diapause — zooplankton in lakes under unfavourable conditions 4. Diapause — bacteria forming thick-walled spores","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Bears hibernate, some snails and fish aestivate, and many zooplankton enter diapause, a suspended development. Spore formation by bacteria is a different survival strategy, not diapause.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-515","question":"Robert Whittaker's classic diagram showing where the world's major biomes occur plots them against which two variables?","options":["Mean annual temperature and mean annual precipitation","Latitude and altitude above sea level","Soil fertility and the length of the frost-free growing season","Mean annual temperature and soil pH"],"answer":0,"explanation":"Whittaker showed that biomes are arranged mainly by annual temperature and rainfall. Latitude and altitude matter only through their effect on those two climate variables.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-516","question":"Assertion (A): Food chains in nature rarely have more than four or five trophic levels. Reason (R): Only a small fraction of the energy at one trophic level is passed on to the next, so too little remains to support a viable population at very high levels. Choose the correct option:","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because roughly 90% of energy is lost at each transfer, energy available after four or five steps is too small to sustain another level of consumers. R directly explains A.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-517","question":"Which one of the following is a structural rather than a functional aspect of an ecosystem?","options":["Decomposition of detritus","Nutrient cycling","Energy flow","Vertical stratification"],"answer":3,"explanation":"Stratification, the vertical layering of species, describes how an ecosystem is built. Productivity, decomposition, energy flow and nutrient cycling are its functional aspects.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-518","question":"In large parts of the Southern Ocean, surface water has plenty of nitrate and phosphate, yet phytoplankton remain sparse. The nutrient generally found to limit their growth in these waters is:","options":["Iron","Silicon","Nitrogen","Phosphorus"],"answer":0,"explanation":"These are 'high-nutrient, low-chlorophyll' waters, far from dust sources, where iron is the limiting micronutrient; iron-fertilisation experiments trigger blooms there. Nitrogen and phosphorus are already abundant.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-519","question":"In a food web, grass is eaten by grasshoppers, mice and rabbits; frogs eat grasshoppers; snakes eat frogs and mice; hawks eat rabbits and snakes. At which trophic levels does the hawk feed?","options":["Third and fourth only","Fourth, fifth and sixth","Third, fourth and fifth","Third and fifth only"],"answer":2,"explanation":"Grass→rabbit→hawk puts it at level 3; grass→mouse→snake→hawk at level 4; grass→grasshopper→frog→snake→hawk at level 5. The snake itself sits at levels 3 and 4.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-520","question":"Insects typically turn a larger fraction of the energy they assimilate into new body tissue than cattle or deer do. The main reason is that:","options":["Insects assimilate a much smaller share of their food than mammals manage to do","Cattle and deer eat food that is poorer in nitrogen than insects eat","Insects need fewer trophic steps to obtain their energy from plants","Mammals spend much of their assimilated energy keeping body temperature constant"],"answer":3,"explanation":"Endotherms burn a large share of assimilated energy in respiration to stay warm, so their production efficiency is only a few per cent, against roughly ten times that in many ectotherms such as insects.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-521","question":"How many of the following pairs are correctly matched? 1. Lentic — ponds and lakes 2. Lotic — rivers and streams 3. Nekton — tiny organisms drifting with water currents 4. Benthos — organisms living on or in the bottom sediments","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Lentic means still water and lotic flowing water; benthos live on the bottom. Nekton are active swimmers such as fish; drifting organisms are plankton.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-522","question":"Birds and mammals living in warm, humid regions tend to be more darkly pigmented than related forms in cool, dry regions. This generalisation is known as:","options":["Bergmann's rule","Gloger's rule","Allen's rule","Jordan's rule"],"answer":1,"explanation":"Gloger's rule links darker pigmentation with warm, humid climates. Bergmann's rule concerns larger body size in colder climates, and Allen's rule shorter extremities in colder climates.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-523","question":"The idea of the ecological niche as an 'n-dimensional hypervolume', in which each axis is an environmental condition or resource, was proposed by:","options":["Charles S. Elton","Joseph Grinnell","Eugene P. Odum","G. E. Hutchinson"],"answer":3,"explanation":"Hutchinson (1957) defined the niche as an n-dimensional hypervolume and distinguished fundamental from realised niches. Grinnell stressed the habitat niche and Elton the functional role of a species in its community.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-524","question":"The term 'ecosystem' was coined in 1935 by:","options":["Ernst Haeckel","Arthur Tansley","Raymond Lindeman","Eugene Odum"],"answer":1,"explanation":"Arthur Tansley introduced 'ecosystem' in 1935. Haeckel coined 'ecology' (1866), Lindeman worked on trophic energy transfer and Odum popularised ecosystem ecology later.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-525","question":"Biomass in ecological pyramids is usually expressed as dry weight rather than fresh weight mainly because:","options":["Water content varies greatly between organisms and seasons and supplies no energy","Dry weight is always larger than fresh weight and so is easier to read accurately on a balance","Fresh weight cannot be measured at all for microscopic organisms such as phytoplankton","Dry weight includes the energy lost in respiration while fresh weight does not"],"answer":0,"explanation":"Removing water gives a comparable measure of organic matter, since the proportion of water differs widely and has no calorific value. Dry weight is of course smaller than fresh weight.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-526","question":"India's National Air Quality Index, launched in 2014, computes sub-indices for eight pollutants. Consider the following: 1. Ammonia 2. Benzene 3. Lead 4. Carbon dioxide 5. Ozone. How many of these are among those eight pollutants?","options":["Only two","Only three","Only four","All five"],"answer":1,"explanation":"The eight AQI pollutants are PM10, PM2.5, NO2, SO2, CO, O3, NH3 and Pb, so ammonia, lead and ozone count. Benzene is in the 2009 ambient standards but not in the AQI, and CO2 is not a criteria pollutant at all.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-527","question":"Consider the following statements: 1. The Commission for Air Quality Management in the National Capital Region and Adjoining Areas is a statutory body set up under an Act of Parliament of 2021. 2. The Environment Pollution (Prevention and Control) Authority that it replaced had been constituted under the Air (Prevention and Control of Pollution) Act, 1981. 3. The Graded Response Action Plan for Delhi-NCR is now implemented by this Commission. Which of the statements given above are correct?","options":["1 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"CAQM was created by the CAQM in NCR and Adjoining Areas Act, 2021 and now runs GRAP. The EPCA it replaced (1998) was set up under Section 3 of the Environment (Protection) Act, 1986 on Supreme Court directions, not under the Air Act.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-528","question":"A factory must cut its emissions of fine particles (PM2.5) from flue gas. Which of the following control devices would be the LEAST effective for this purpose?","options":["Fabric (bag-house) filter","Electrostatic precipitator","Cyclone separator","Venturi wet scrubber"],"answer":2,"explanation":"A cyclone uses centrifugal force, which works well only for coarse particles (above roughly 10 µm); fine particles follow the gas stream out. Bag filters and ESPs capture fine dust at efficiencies of 99 per cent or more, and venturi scrubbers also handle fine particles.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-529","question":"Which of the following correctly describes the relationship between PM10 and PM2.5?","options":["PM2.5 is a subset of PM10, as any particle under 2.5 µm is also under 10 µm","PM10 and PM2.5 are two separate size classes, so a particle can belong to only one of them","PM2.5 refers to all particles of 2.5 µm or larger, so it includes the whole of PM10","PM10 particles are about ten times heavier than PM2.5 particles of the same diameter"],"answer":0,"explanation":"PM10 covers all inhalable particles of aerodynamic diameter up to 10 µm, which includes the fine fraction under 2.5 µm. That is why PM10 readings are always at least as high as PM2.5 readings at the same place and time.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-530","question":"The 'Pusa Decomposer', promoted as an alternative to burning paddy stubble in north-west India, is:","options":["A tractor-mounted machine that chops paddy straw and spreads it evenly over the field","A low-cost kiln that converts loose paddy straw into biochar briquettes for sale","A chemical spray that dries out green stubble so that it can be ploughed in quickly","A microbial formulation of fungi that speeds up the decay of straw in the field"],"answer":3,"explanation":"Developed by the Indian Agricultural Research Institute (Pusa), it is a consortium of fungal strains, applied as a solution, that breaks down stubble in situ so it enriches the soil. Straw choppers and the Happy Seeder are mechanical options.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-531","question":"Ground-level ozone readings are often higher in suburbs and rural areas downwind of a city than at busy traffic junctions in the city centre. The best explanation is that:","options":["Ozone is emitted directly by vehicle exhausts, but mainly from fast-moving traffic on highways outside the city","Rural vegetation emits ozone directly from its leaves, which adds to the ozone carried out from the city","Fresh nitric oxide from traffic destroys ozone near the source, while ozone keeps forming as the air moves downwind","Ozone is heavier than air, so at night it drains out of the elevated city centre towards low-lying rural areas"],"answer":2,"explanation":"Ozone is a secondary pollutant; near heavy traffic, freshly emitted NO 'titrates' it (NO + O3 gives NO2 + O2). Downwind, sunlight keeps driving reactions of NOx and VOCs, so ozone builds up away from the sources.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-532","question":"Apart from the direct health hazard of lead, why was unleaded petrol essential for vehicles fitted with catalytic converters?","options":["Lead raises the octane rating so much that engines with converters overheat","Lead compounds coat and deactivate the precious-metal catalyst, 'poisoning' it","Lead reacts with the catalyst to produce large amounts of sulphur dioxide","Lead makes the exhaust too cool for the catalyst to reach its working temperature"],"answer":1,"explanation":"Tetraethyl lead was added as an anti-knock agent, but lead deposits on platinum, palladium and rhodium surfaces and permanently deactivates them. So converters and unleaded fuel had to come together.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-533","question":"The yellowing and pitting of the Taj Mahal's marble, linked to emissions from industries and a refinery in the Agra–Mathura region, is mainly due to sulphur dioxide converting the marble surface into:","options":["Calcium sulphate (gypsum)","Calcium hydroxide (slaked lime)","Calcium oxide (quicklime)","Calcium chloride"],"answer":0,"explanation":"SO2 forms sulphurous and sulphuric acid with moisture, which reacts with calcium carbonate to form gypsum; the gypsum crust traps soot and flakes off. This 'marble cancer' led the Supreme Court to regulate industries in the Taj Trapezium Zone.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-534","question":"Assertion (A): Building very tall chimneys at coal-fired power plants can worsen acid rain in regions far away from the plants. Reason (R): Emissions released high in the atmosphere stay aloft longer and are carried farther before they are deposited. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Tall stacks dilute pollution near the plant but do not remove the SO2 and NOx; they export it, which is how acid deposition in Scandinavia was traced to emissions from Britain and central Europe.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-535","question":"Consider the following statements about fluidised bed combustion of coal: 1. Limestone added to the bed captures much of the sulphur dioxide inside the furnace itself. 2. Its relatively low combustion temperature reduces the formation of thermal nitrogen oxides. 3. It removes most of the carbon dioxide produced by burning the coal. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"In FBC, limestone in the bed reacts with SO2 to form calcium sulphate, and the bed runs at around 800–900 °C, too cool for much thermal NOx. CO2 is still released in full; it is not a carbon-capture technology.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-536","question":"Exhaust gas recirculation (EGR), used in many engines, reduces the emission of nitrogen oxides mainly because it:","options":["Converts the nitrogen oxides into ammonia inside the exhaust pipe","Adds extra oxygen to the cylinder so that the fuel burns more completely","Burns the nitrogen oxides a second time at a much higher temperature","Dilutes the intake charge and so lowers peak combustion temperature"],"answer":3,"explanation":"Most engine NOx is 'thermal NOx', formed when N2 and O2 combine at very high flame temperatures. Feeding some inert exhaust back into the intake lowers the peak temperature and so cuts NOx formation.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-537","question":"Consider the following statements about compressed natural gas (CNG) as a vehicle fuel: 1. It consists mainly of methane. 2. Shifting buses from diesel to CNG sharply reduces their particulate emissions. 3. CNG vehicles emit no nitrogen oxides. Which of the statements given above are correct?","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"CNG is mostly methane and burns with very little soot, which is why Delhi's bus fleet was converted on Supreme Court orders. But any high-temperature combustion in air still forms NOx, so statement 3 is wrong.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-538","question":"The 'ventilation coefficient', used to judge how well the air over a city can disperse pollutants, is the product of:","options":["Air temperature and relative humidity measured near the ground","Rainfall intensity and the number of hours of rain in a day","Mixing height and the average wind speed within that layer","Surface atmospheric pressure and the lapse rate of temperature"],"answer":2,"explanation":"A deep mixing layer and strong winds dilute pollutants. In north Indian winters both the mixing height and wind speed drop, so the ventilation coefficient falls and pollution accumulates.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-539","question":"Which of the following is an important natural (biogenic) precursor of ground-level ozone, emitted in large amounts by many trees on hot, sunny days?","options":["Carbon dioxide","Nitrous oxide","Sulphur dioxide","Isoprene"],"answer":3,"explanation":"Isoprene is a reactive volatile organic compound released by trees such as oaks and eucalyptus; with NOx and sunlight it helps form ozone. CO2 and N2O are too unreactive in the lower atmosphere to drive ozone formation.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-540","question":"Consider the following statements about the Noise Pollution (Regulation and Control) Rules, 2000: 1. They were framed under the Environment (Protection) Act, 1986. 2. An area of not less than 100 metres around hospitals, educational institutions and courts may be declared a silence zone. 3. 'Night time' under the rules runs from 10 p.m. to 6 a.m. 4. The daytime ambient noise limit for residential areas is higher than that for commercial areas. How many of the statements given above are correct?","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Statements 1–3 are correct. The daytime limits are 75 dB(A) industrial, 65 commercial, 55 residential and 50 in silence zones, so residential limits are lower than commercial ones.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-541","question":"Which of the following statements about fluoride in drinking water is correct?","options":["Fluoride gives no benefit to teeth, so BIS sets its permissible limit in drinking water at 0.05 mg/L","Small amounts protect teeth, but above about 1.5 mg/L fluoride causes dental and skeletal fluorosis","Fluorosis is a fluoride-deficiency disease, which is why some countries add fluoride to public water","High fluoride in Indian groundwater comes mainly from phosphate fertilisers and industrial effluents"],"answer":1,"explanation":"The Indian standard sets 1.0 mg/L as acceptable and 1.5 mg/L as the permissible limit; low levels help prevent caries while excess causes fluorosis. Fertilisers and effluents are a tempting source, but high fluoride in states such as Rajasthan and Telangana is mainly geogenic, leached from fluoride-bearing rocks.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-542","question":"In the activated sludge process of sewage treatment, part of the sludge that settles in the secondary clarifier is pumped back into the aeration tank. The purpose is to:","options":["Add chemical coagulants so that fine suspended particles settle faster","Raise the temperature of the sewage so that the bacteria grow more quickly","Dilute toxic heavy metals before the treated water is discharged into a river","Keep a large, active population of microbes to digest the organic matter"],"answer":3,"explanation":"The returned sludge carries the flocs of aerobic bacteria and protozoa that consume the organic load, so recycling it keeps the BOD-removing biomass high. The excess sludge goes to anaerobic digesters, which produce biogas.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-543","question":"Consider the following statements: 1. The Ganga was declared India's 'National River' in 2008. 2. The National Ganga River Basin Authority was constituted under the Environment (Protection) Act, 1986. 3. The National Mission for Clean Ganga is a constitutional body. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"The Ganga became the National River in November 2008, and the NGRBA was set up in 2009 under Section 3 of the EP Act. NMCG was registered as a society and later made an authority under the same Act; no constitutional provision created it.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-544","question":"An industrial unit described as achieving 'zero liquid discharge' (ZLD):","options":["Uses no water at any stage of its production process","Treats its effluent only up to the standard for discharge into rivers","Treats and recycles its wastewater so that no liquid effluent leaves the plant","Sends all of its wastewater to a common effluent treatment plant nearby"],"answer":2,"explanation":"ZLD plants recover water through treatment, reverse osmosis and evaporators, reuse it, and leave only solid residues. Meeting discharge standards or sending effluent to a CETP still releases liquid effluent.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-545","question":"Ballast water carried by ships is a major environmental concern mainly because it:","options":["Contains crude oil residues that leak into harbours when it is pumped out","Transfers aquatic organisms, including invasive species, between distant seas","Is heavily chlorinated before discharge and so kills corals near shipping lanes","Raises the salinity of rivers sharply when it is discharged at inland river ports"],"answer":1,"explanation":"Ships take in seawater with plankton, larvae and pathogens at one port and release it at another, spreading species such as the zebra mussel. The IMO's Ballast Water Management Convention (2004) addresses this.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-546","question":"Below a sewage outfall, a river's dissolved oxygen falls and then recovers, tracing an 'oxygen sag curve'. Where is the lowest point of this curve usually found, and why?","options":["Exactly at the outfall, because the oxygen demand is greatest where the sewage enters","Upstream of the outfall, because polluted water mixes back against the river's current","Far downstream at the river mouth, because oxygen keeps falling until the river meets the sea","Some distance downstream, where oxygen used in decay still exceeds re-aeration"],"answer":3,"explanation":"Microbial decomposition takes time, so oxygen keeps falling as the water flows on. The minimum (critical point) lies where the rate of deoxygenation equals the rate of re-aeration from the air; beyond it, oxygen recovers.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-547","question":"A survey of a stream bed finds large numbers of Tubifex (sludge) worms and red chironomid larvae, but no stonefly or mayfly nymphs. This most likely indicates that the stream:","options":["Is heavily polluted with organic matter and low in dissolved oxygen","Is clean, cold and well oxygenated, typical of a fast mountain stream","Is acidified by mine drainage but otherwise has normal oxygen levels","Has been polluted mainly by excess heat from a power plant upstream"],"answer":0,"explanation":"Tubifex and red 'bloodworm' larvae tolerate very low oxygen, while stonefly and mayfly nymphs need clean, oxygen-rich water. Such biotic indices are used to grade organic pollution.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-548","question":"Tannery effluent treatment aims to keep chromium in its trivalent form, Cr(III), rather than the hexavalent form, Cr(VI). This is because:","options":["Cr(III) evaporates easily and leaves the water as a harmless gas","Cr(VI) is insoluble and clogs treatment plants, while Cr(III) dissolves","Cr(VI) is far more toxic, soluble and carcinogenic than Cr(III)","Cr(III) is a plant nutrient that raises crop yields on irrigated fields"],"answer":2,"explanation":"Hexavalent chromium is highly soluble, mobile and carcinogenic; treatment reduces it to Cr(III), which precipitates as hydroxide and is far less toxic. Tanneries at Kanpur and Vellore are known sources.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-549","question":"In discussions of marine pollution, 'ghost gear' refers to:","options":["Plastic pellets that leak from factories into rivers and the sea","Oil residues released when ships wash out their cargo tanks","Sunken shipwrecks that slowly leak fuel and heavy metals","Abandoned, lost or discarded fishing nets, lines and traps"],"answer":3,"explanation":"Lost fishing gear keeps trapping and killing fish, turtles, dolphins and seabirds for years ('ghost fishing') and is a large share of large plastic debris in the oceans.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-550","question":"Wells in some coastal areas of Gujarat and Tamil Nadu have turned saline over the years even though no polluted effluent was discharged nearby. The most likely cause is:","options":["Acid rain dissolving salts out of the coastal rocks and carrying them into the groundwater","Over-pumping of fresh groundwater, letting seawater move inland into the aquifer","Evaporation of irrigation water from fields, leaving salt that seeps down to the water table","Seepage of untreated sewage from towns, which carries dissolved salts into the wells"],"answer":1,"explanation":"Fresh groundwater normally holds back seawater; when pumping lowers the water table, the freshwater–saltwater interface advances inland (saltwater intrusion). Recharge structures and pumping limits are the usual remedies.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-551","question":"Consider a food chain in which one large banyan tree supports a few hundred fruit-eating birds, and each bird carries many lice and other ectoparasites. The pyramid of numbers for this chain is:","options":["Fully inverted, widening at every level from producer to parasite","Upright, narrowing at every level from producer to parasite","Spindle-shaped, widest at the bird level and narrow at both ends","Upright at the base but inverted between the birds and parasites only"],"answer":0,"explanation":"One tree < hundreds of birds < many thousands of parasites, so every level is larger than the one below and the pyramid is fully inverted. A tree–insect–bird chain, by contrast, gives a spindle shape.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-552","question":"How many of the following are recognised limitations of ecological pyramids? I. They do not account for one species occupying two or more trophic levels. II. They assume a simple food chain, which seldom exists in nature, rather than a food web. III. They give no place to saprophytes, though these play a vital role in the ecosystem. IV. A pyramid of energy can turn inverted when the producers are very small and short-lived.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I–III are the standard limitations. IV is false: a pyramid of energy is always upright, because energy is lost at each transfer, even when a biomass pyramid is inverted.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-553","question":"Arrange the following steps in the order in which nitrogen in the proteins of a dead animal becomes available to plants as nitrate: 1. Conversion of nitrite into nitrate by Nitrobacter 2. Release of ammonia by decomposers (ammonification) 3. Oxidation of ammonia into nitrite by Nitrosomonas","options":["3-2-1","2-1-3","2-3-1","1-3-2"],"answer":2,"explanation":"Decomposers first release ammonia from organic nitrogen; Nitrosomonas oxidises it to nitrite, and Nitrobacter then oxidises nitrite to nitrate. Mixing up the two nitrifiers gives the 2-1-3 trap.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-554","question":"The actinomycete Frankia fixes atmospheric nitrogen in nodules formed on:","options":["Roots of leguminous crops such as pea, gram, lentil and soybean","Leaf cavities of the small aquatic fern Azolla","Coralloid roots of the gymnosperm Cycas","Roots of non-leguminous trees such as alder and Casuarina"],"answer":3,"explanation":"Frankia forms actinorhizal nodules on non-legumes like Alnus and Casuarina. Legume nodules hold Rhizobium, while Azolla and Cycas harbour cyanobacteria (Anabaena, Nostoc).","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-555","question":"Consider the following statements: 1. Lightning converts some atmospheric nitrogen into oxides of nitrogen that reach the soil in rain. 2. The Haber–Bosch process fixes atmospheric nitrogen industrially as ammonia. 3. The enzyme nitrogenase works best in oxygen-rich conditions. Which of the statements given above is/are correct?","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"Lightning and industrial fixation both add reactive nitrogen. Nitrogenase is inactivated by oxygen, which is why nodules use leghaemoglobin and cyanobacteria fix nitrogen in thick-walled heterocysts.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-556","question":"Fungi of the genus Glomus form mycorrhizal associations with the roots of many crop plants. The main benefit the plant gets from this association is:","options":["Better uptake of phosphorus from the soil","Fixation of nitrogen gas directly from the air","Protection of leaves from insect grazers","Release of potassium from organic matter"],"answer":0,"explanation":"The fungal hyphae extend far beyond the roots and absorb phosphorus, which moves slowly in soil, and pass it to the plant in exchange for sugars. Mycorrhizal fungi do not fix nitrogen.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-557","question":"The 'rotten egg' smell of the black, oxygen-poor mud of mangroves and marshes comes from hydrogen sulphide produced mainly by:","options":["Sulphur-oxidising bacteria such as Thiobacillus","Sulphate-reducing bacteria such as Desulfovibrio","Methane-producing archaea living in the deeper mud layers","Nitrifying bacteria such as Nitrosomonas"],"answer":1,"explanation":"Without oxygen, Desulfovibrio uses sulphate as an electron acceptor and reduces it to H₂S. Thiobacillus does the opposite, oxidising reduced sulphur back to sulphate.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-558","question":"The average time that a water molecule stays in the atmosphere before falling back as precipitation is about:","options":["Nine months","Nine years","Ninety days","Nine days"],"answer":3,"explanation":"Atmospheric water is replaced roughly every 9–10 days, far faster than water in oceans (thousands of years) or deep groundwater. This short residence time is why weather responds so quickly to evaporation.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-559","question":"Which of the following holds the largest amount of carbon on Earth?","options":["Sedimentary rocks such as limestone and shale","The dissolved inorganic carbon of the deep ocean","Organic matter held in the world's soils","The proven reserves of coal, oil and natural gas"],"answer":0,"explanation":"Carbonate rocks and organic carbon in sediments hold tens of millions of gigatonnes, far more than the deep ocean (tens of thousands of gigatonnes). Among the active, fast-exchanging pools, the ocean is the largest.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-560","question":"Sedimentary nutrient cycles, such as that of phosphorus, are often described as less 'perfect' than gaseous cycles. This is because:","options":["Their elements are needed by organisms only in very small trace amounts","Their elements cannot be absorbed by plants without fungi","Much of the element gets locked in deep sediments for very long periods","Their elements are rapidly lost to space from the upper atmosphere"],"answer":2,"explanation":"Elements with a sedimentary reservoir can be carried to the deep sea or buried, and return only through slow geological uplift. Gaseous cycles self-adjust quickly through the large, well-mixed atmospheric pool.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-561","question":"Legume crops on some acid soils nodulate poorly and fix little nitrogen until a small dose of a micronutrient that forms part of the enzyme nitrogenase is applied. This micronutrient is:","options":["Zinc","Molybdenum","Boron","Manganese"],"answer":1,"explanation":"Nitrogenase contains a molybdenum–iron cofactor, so molybdenum deficiency, common on acid soils, directly cuts nitrogen fixation. Zinc, boron and manganese have other roles in plants.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-562","question":"A classic study of energy flow through every trophic level of a whole ecosystem, carried out at Silver Springs in Florida in the 1950s, is associated with:","options":["Raymond Lindeman","Arthur Tansley","Charles Elton","Howard T. Odum"],"answer":3,"explanation":"H. T. Odum's Silver Springs study (1957) produced a full energy budget and pyramid. Lindeman's earlier trophic-dynamic work was on Cedar Bog Lake in Minnesota.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-563","question":"In the phosphorus cycle, which of the following correctly pairs the reservoir pool with the exchange (cycling) pool?","options":["Reservoir: the atmosphere; exchange pool: rocks, sediments and ocean-floor deposits","Reservoir: rocks and sediments; exchange pool: soil solution and living organisms","Reservoir: living organisms; exchange pool: atmosphere and ocean water","Reservoir: ocean water; exchange pool: the atmosphere, soil air and living organisms"],"answer":1,"explanation":"Phosphorus is stored mainly in phosphate rocks and sediments and moves quickly only between soil or water and organisms. It has no significant atmospheric pool.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-564","question":"How many of the following statements about the slow, geological carbon cycle are correct? I. Chemical weathering of silicate rocks removes carbon dioxide from the atmosphere over long periods. II. Volcanic outgassing returns carbon dioxide to the atmosphere. III. This cycle operates over hundreds of thousands to millions of years. IV. Volcanoes today release more carbon dioxide each year than human activities do.","options":["Only one","Only two","All four","Only three"],"answer":3,"explanation":"I–III describe the rock–climate thermostat. IV is false: human emissions are roughly a hundred times larger than average volcanic emissions of CO₂.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-565","question":"Consider the following statements about the global water cycle: 1. Over the oceans, evaporation exceeds precipitation. 2. Over the land, precipitation exceeds evaporation, and the difference returns to the sea as runoff. 3. Most of the water vapour in the atmosphere comes from transpiration by land plants. Which of the statements given above is/are correct?","options":["1 and 2 only","2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"The oceans are a net source of vapour carried over land, and rivers return the surplus. Statement 3 is wrong: most atmospheric moisture evaporates from the oceans.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-566","question":"The ocean's 'solubility pump' moves carbon dioxide from the surface to the deep sea mainly because:","options":["Phytoplankton fix carbon dioxide at the surface and their remains sink to great depths","Coral reefs lock carbon dioxide into limestone at the sea floor","Carbon dioxide is more soluble in cold water, and cold, dense polar water sinks","Warm tropical water sinks and carries dissolved carbon dioxide down with it"],"answer":2,"explanation":"Cold high-latitude water absorbs more CO₂ and, being dense, sinks into the deep ocean. Sinking organic matter is the separate biological pump; warm water does not sink.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-567","question":"Ecological pyramids, also called Eltonian pyramids, were first described by:","options":["Charles Elton","Raymond Lindeman","Eugene Odum","Ernst Haeckel"],"answer":0,"explanation":"Charles Elton introduced the pyramid of numbers in his book Animal Ecology (1927). Lindeman later developed the trophic-dynamic concept of energy transfer.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-568","question":"Which of the following elements follow a sedimentary rather than a gaseous biogeochemical cycle? 1. Calcium 2. Potassium 3. Oxygen 4. Phosphorus. Select the correct answer:","options":["1, 2 and 4 only","1 and 4 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":0,"explanation":"Calcium, potassium and phosphorus are stored mainly in rocks and soils. Oxygen, like carbon and nitrogen, has its main reservoir in the atmosphere and follows a gaseous cycle.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-569","question":"Plants absorb nitrogen from the soil mainly in the form of:","options":["Free nitrogen gas taken in through the stomata","Nitrite and nitrous oxide dissolved in soil water","Nitrate and ammonium ions dissolved in soil water","Amino acids released from decomposing humus"],"answer":2,"explanation":"Roots take up nitrogen mainly as NO₃⁻ and NH₄⁺. Plants cannot use N₂ directly, and nitrite is toxic and short-lived in well-aerated soil.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-570","question":"The sharp rise in the oxygen content of the Earth's atmosphere about 2.4 billion years ago, the 'Great Oxidation Event', resulted mainly from:","options":["Splitting of water vapour by ultraviolet light in the upper atmosphere","Photosynthesis by cyanobacteria in the oceans","Release of oxygen gas from volcanic eruptions","Weathering of iron-rich rocks exposed on land"],"answer":1,"explanation":"Oxygenic photosynthesis by cyanobacteria built up free oxygen once natural sinks were saturated. Weathering of iron-rich rocks actually consumed oxygen, and volcanoes emit almost none.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-571","question":"When urea is spread on the surface of an alkaline soil and not worked in, a large part of its nitrogen is lost to the air as ammonia gas. This loss is called:","options":["Denitrification","Volatilisation","Leaching","Immobilisation"],"answer":1,"explanation":"Urea hydrolyses to ammonium, which at high pH turns into ammonia gas and escapes: volatilisation. Denitrification loses nitrogen as N₂ or N₂O from nitrate under anaerobic conditions.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-572","question":"Which of the following are free-living (non-symbiotic) nitrogen-fixing micro-organisms? 1. Azotobacter 2. Clostridium 3. Rhizobium 4. Nostoc. Select the correct answer:","options":["1 and 3 only","1, 2 and 4 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":1,"explanation":"Azotobacter (aerobic), Clostridium (anaerobic) and the cyanobacterium Nostoc fix nitrogen while living freely. Rhizobium fixes significant nitrogen only inside legume root nodules.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-573","question":"The pyramid of energy narrows at each higher trophic level because, in every transfer, some energy is degraded to heat. This is a consequence of:","options":["The first law of thermodynamics","The law of conservation of mass and energy","The second law of thermodynamics","The law of the minimum"],"answer":2,"explanation":"The second law says every energy conversion produces some unusable heat, so less energy is available at each step. The first law only says energy is conserved in total.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-574","question":"Plants normally take up sulphur from the soil in the form of:","options":["Hydrogen sulphide gas","Elemental sulphur","Sulphite ions","Sulphate ions"],"answer":3,"explanation":"Sulphate (SO₄²⁻) is the form absorbed by roots; elemental sulphur and sulphides must first be oxidised, for example by Thiobacillus. H₂S is toxic to most plants.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-575","question":"Methane released from wetlands and flooded rice fields is produced mainly by:","options":["Methanotrophic bacteria working in oxygen-rich surface water","Nitrifying bacteria working in well-drained soils","Cyanobacteria growing on the surface of the water","Methanogenic archaea working in oxygen-free mud"],"answer":3,"explanation":"Methanogenic archaea produce methane as they break down organic matter without oxygen. Methanotrophs do the opposite: they consume methane in oxygenated layers, reducing what escapes.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-576","question":"Under the Plastic Waste Management Rules, 2016 as amended in 2021, the minimum thickness of plastic carry bags was raised in two steps. From 31 December 2022 the minimum thickness became:","options":["50 microns","75 microns","120 microns","150 microns"],"answer":2,"explanation":"The 2021 amendment raised the limit from 50 to 75 microns from 30 September 2021, and to 120 microns from 31 December 2022, so that thicker bags would be reused and be worth collecting.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-577","question":"Consider the following statements about the E-Waste (Management) Rules, 2016: 1. They brought compact fluorescent lamps and other mercury-containing lamps within their scope. 2. They provided for Producer Responsibility Organisations to help producers meet their collection duties. 3. They were framed under the Air (Prevention and Control of Pollution) Act, 1981. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"The 2016 rules widened the scope to CFLs and mercury lamps, set EPR collection targets and introduced PROs. Like all waste rules, they were framed under the Environment (Protection) Act, 1986.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-578","question":"Match the e-waste component with the hazardous substance it is best known for. A. Cathode-ray tube glass  B. Fluorescent lamps and older LCD backlights  C. Nickel-based rechargeable batteries  D. Plastic casings and circuit boards; 1. Brominated flame retardants  2. Cadmium  3. Lead  4. Mercury","options":["A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2","A-2, B-4, C-3, D-1","A-3, B-4, C-2, D-1"],"answer":3,"explanation":"CRT glass contains several kilograms of lead, lamps and CCFL backlights contain mercury, Ni-Cd cells contain cadmium, and plastics are treated with brominated flame retardants that form dioxins when burnt.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-579","question":"Which one of the following statements about bioplastics is correct?","options":["Every plastic made from plant material breaks down quickly in both soil and water","A bio-based plastic need not be biodegradable; bio-polyethylene from cane is not","Polylactic acid (PLA) breaks down within a few weeks in ordinary seawater or soil","A plastic can be labelled biodegradable only if it is made from plant raw material"],"answer":1,"explanation":"'Bio-based' describes the raw material and 'biodegradable' describes the end of life. Bio-PE is chemically identical to fossil polyethylene, PLA needs industrial composting conditions, and some fossil-based plastics such as PBAT are biodegradable.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-580","question":"Environmental agencies have criticised 'oxo-degradable' plastics, which contain additives that make them break down on exposure to heat and light. The main criticism is that they:","options":["They need high-temperature industrial composting and do not break down in home compost","They are made from food crops such as maize, competing with food production for land","They fragment into microplastics instead of being fully broken down by microbes","They give off methane as they break down in landfills, adding to greenhouse emissions"],"answer":2,"explanation":"Pro-oxidant additives make conventional plastic brittle so it crumbles, but the fragments are not mineralised by microbes on a useful time scale and persist as microplastics. The composting and food-crop criticisms are tempting but apply to bio-based compostable plastics such as PLA, not to oxo-degradable polyethylene.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-581","question":"Shredded waste plastic is mixed into the hot stone aggregate when laying bituminous roads, a technique popularised in India. The method works mainly because the molten plastic:","options":["Coats the aggregate and improves its bond with bitumen and its water resistance","Burns off completely at the mixing temperature, leaving no plastic in the road","Replaces all of the bitumen, so that no petroleum product is needed for the road","Reacts chemically with the stone to form cement, so no other binder is required"],"answer":0,"explanation":"Plastic-coated aggregate bonds better with bitumen and absorbs less water, reducing potholes, while using up low-value plastic waste. The plastic is only a partial additive; bitumen is still the binder.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-582","question":"Which of the following is the most suitable measure to reduce wind erosion of soil in the arid parts of western Rajasthan?","options":["Building contour bunds and bench terraces across the steeper slopes","Flooding the fields through the winter to keep the topsoil wet and heavy","Deep ploughing of all fields at the start of the dry, windy summer season","Planting rows of trees and shrubs as shelterbelts across the prevailing wind"],"answer":3,"explanation":"Shelterbelts and windbreaks reduce wind speed near the ground and trap blowing sand. Contour bunds and terracing target water erosion on slopes, and ploughing before the windy season loosens the soil and worsens erosion.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-583","question":"For most Indian soils and crops, the nitrogen–phosphorus–potassium (N:P:K) fertiliser use ratio generally recommended as balanced is about:","options":["1:2:4","4:2:1","2:1:4","8:4:1"],"answer":1,"explanation":"The commonly cited balanced ratio is 4:2:1. Heavily subsidised urea has pushed actual use far towards nitrogen, degrading soil health and contributing to nitrate pollution and nitrous oxide emissions.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-584","question":"Parts of the Kerala coast around Karunagappally and Chavara have some of the highest natural background radiation in the world. This is because of:","options":["Fallout carried by monsoon winds from nuclear weapons tests","Leakage from the nuclear power station located on that coast","Thorium-bearing monazite in the beach sands of the area","Radon released from the oil and gas wells offshore"],"answer":2,"explanation":"The black sands of this coast are rich in monazite, which contains thorium. Kerala has no nuclear power station; the radiation is entirely natural.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-585","question":"Under the Bio-Medical Waste Management Rules, 2016, match the waste with the colour of its container. A. Human anatomical waste and soiled dressings  B. Contaminated recyclable items such as tubing, catheters and gloves  C. Broken or discarded glassware such as vials; 1. Blue  2. Yellow  3. Red","options":["A-3, B-2, C-1","A-2, B-1, C-3","A-1, B-3, C-2","A-2, B-3, C-1"],"answer":3,"explanation":"Yellow bags take incinerable waste such as anatomical and soiled waste; red takes contaminated plastics that are to be recycled after disinfection; blue cardboard boxes take glassware and metal implants, and white puncture-proof containers take sharps.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-586","question":"The gas collected from a mature municipal solid waste landfill consists mainly of:","options":["Methane and carbon dioxide in roughly equal proportions","Hydrogen sulphide with small amounts of ammonia","Carbon monoxide and nitrogen in roughly equal proportions","Nearly pure methane with traces of oxygen"],"answer":0,"explanation":"Anaerobic decomposition of organic waste gives landfill gas of roughly 45–60 per cent methane, the rest mainly CO2, with traces of H2S and other gases. It can be captured for energy; if vented it is a major methane source.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-587","question":"Several waste-to-energy incineration plants in Indian cities have run below capacity or needed extra fuel. The main technical reason is that unsegregated Indian municipal waste:","options":["Contains too much plastic, which melts in the furnace and blocks the grates","Is high in moisture, organics and inerts, so its calorific value is low","Has so much paper and cardboard that it burns too hot and damages the boilers","Contains almost no carbon at all, so it cannot release heat when it is burnt"],"answer":1,"explanation":"Wet kitchen waste, silt and debris make up a large share of Indian MSW, so it burns poorly without support fuel. Segregation, removing wet waste for composting or biogas, is the key to viable incineration.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-588","question":"Refuse-derived fuel (RDF), increasingly used in cement kilns in India, is:","options":["Biogas produced by anaerobic digestion of the wet fraction of kitchen waste","Liquid fuel re-refined from used engine oil collected at garages and workshops","The dry, combustible fraction of waste, such as plastics and paper, shredded","Charcoal briquettes made by heating garden waste in the absence of air"],"answer":2,"explanation":"RDF is prepared by removing wet organics and inert material and shredding the high-calorific remainder. Cement kilns can 'co-process' it because their very high temperatures destroy pollutants and the ash is absorbed into clinker.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-589","question":"'Biomining' of a legacy dumpsite, such as old garbage mountains in Indian cities, refers to:","options":["Extracting gold and copper from e-waste using bacteria inside sealed steel reactors","Capping the dumpsite with clay and planting grass on it so that it stops emitting gas","Injecting micro-organisms into the dump so that all of the waste is turned into methane","Digging out aged waste and sieving it into soil-like fines, recyclables and combustibles"],"answer":3,"explanation":"After bio-stabilisation, the old waste is dug out and sieved: the fine fraction is used as fill or soil, combustibles go as RDF, and inerts go to construction, freeing the land. Capping leaves the waste in place.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-590","question":"Two identical machines each produce a noise level of 70 dB at a point when running alone. If both run together, the noise level at that point will be:","options":["140 dB","70 dB","about 73 dB","about 76 dB"],"answer":2,"explanation":"Decibels are logarithmic: doubling the sound intensity adds 10 log10(2), about 3 dB. So two equal 70 dB sources give about 73 dB, not 140 dB.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-591","question":"For a small, steady noise source in open air, the sound level falls by about how much each time the distance from the source is doubled?","options":["About 6 dB","About 3 dB","About 10 dB","About 20 dB"],"answer":0,"explanation":"Intensity from a point source falls with the square of distance, so doubling the distance cuts intensity to a quarter: 10 log10(4), about 6 dB. A 3 dB drop corresponds to halving the intensity.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-592","question":"Organophosphate insecticides such as malathion largely replaced organochlorines such as DDT. Which of the following correctly compares the two groups?","options":["Organophosphates are more persistent and biomagnify more than organochlorines","Organophosphates break down faster, but many are more acutely toxic to people","Organochlorines are water-soluble and so are flushed quickly out of animal bodies","Both groups act only on insects and are harmless to birds and mammals"],"answer":1,"explanation":"Organochlorines are fat-soluble and persistent, hence biomagnification. Organophosphates degrade in days or weeks but inhibit the enzyme acetylcholinesterase and cause many acute poisonings among farm workers.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-593","question":"India's Recycling of Ships Act, 2019, which governs ship-breaking yards such as Alang in Gujarat, was enacted in line with which international convention?","options":["The Basel Convention on hazardous wastes","The MARPOL Convention on pollution from ships","The Rotterdam Convention on prior informed consent","The Hong Kong Convention on ship recycling"],"answer":3,"explanation":"India acceded to the Hong Kong International Convention for the Safe and Environmentally Sound Recycling of Ships (2009) in 2019 and passed the Act alongside. Basel deals with hazardous waste trade in general, and MARPOL with pollution from operating ships.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-594","question":"Some plants take up selenium or mercury from contaminated soil, convert it into volatile compounds and release them into the air through their leaves. This form of phytoremediation is called:","options":["Phytovolatilisation","Phytostabilisation","Rhizofiltration","Phytoextraction"],"answer":0,"explanation":"In phytovolatilisation the contaminant leaves through the plant as a gas. Phytoextraction stores metals in harvestable shoots, phytostabilisation locks them in the root zone, and rhizofiltration uses roots to absorb pollutants from water.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-595","question":"In the resin identification codes printed inside the recycling triangle on plastic items, code 3 denotes:","options":["Polyethylene terephthalate (PET)","Polyvinyl chloride (PVC)","High-density polyethylene (HDPE)","Polystyrene (PS)"],"answer":1,"explanation":"The codes are 1 PET, 2 HDPE, 3 PVC, 4 LDPE, 5 PP, 6 PS and 7 others. PVC is the hardest common plastic to recycle and releases hydrogen chloride and dioxins when burnt.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-596","question":"Integrated Pest Management (IPM), promoted in India as a way to cut pesticide use, is best described as:","options":["Spraying a fixed calendar of pesticides every season so that pests never get a chance to appear","Banning all chemical pesticides and relying entirely on genetically modified, pest-resistant crops","Combining cultural, biological and mechanical controls, using chemicals only above a pest threshold","Rotating different chemical pesticides each season so that pests cannot build up resistance to any"],"answer":2,"explanation":"IPM uses crop rotation, resistant varieties, natural enemies such as Trichoderma or Trichogramma, traps and monitoring, and allows chemicals only when pests exceed an economic threshold level.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-597","question":"Which feature distinguishes a properly engineered sanitary landfill from an open dump?","options":["Waste is burnt in the open every few days to reduce its volume and smell","Waste is spread thinly over a large area so that it dries quickly in the sun","Only wet kitchen waste is accepted, while all dry waste is sent elsewhere","An impermeable liner, leachate collection and daily soil cover over the waste"],"answer":3,"explanation":"Liners and leachate collection protect groundwater, daily cover controls odour, flies and fires, and gas can be vented or captured. Open dumps have none of these and often catch fire.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-598","question":"Consider the following statements about the Hazardous and Other Wastes (Management and Transboundary Movement) Rules, 2016: 1. They were framed under the Environment (Protection) Act, 1986. 2. Import of hazardous and other wastes into India for disposal is not permitted. 3. They regulate transboundary movement of hazardous waste in line with the Basel Convention. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1, 2 and 3","1 and 3 only"],"answer":2,"explanation":"All three are correct. The rules allow import only for recycling, recovery or reuse with permission, never for disposal, and they give effect to India's obligations under the Basel Convention.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-599","question":"Strontium-90, released by nuclear weapon tests and reactor accidents, is especially dangerous because it:","options":["Collects in the thyroid gland in place of iodine","Is taken up like calcium and stored in bones and teeth","Is a gas that is breathed in and lodges in the lungs","Concentrates in body fat in the same way as DDT"],"answer":1,"explanation":"Strontium is chemically similar to calcium, so Sr-90 enters milk and is deposited in bone, where it irradiates the marrow for years (half-life about 29 years). The thyroid hazard comes from iodine-131.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-600","question":"Tributyltin (TBT), once used in anti-fouling paints on ship hulls, was banned under an IMO convention mainly because it:","options":["Disrupts hormones in marine snails, causing females to develop male organs","Corrodes the steel of ship hulls from outside and causes fuel oil to leak into the sea","Depletes the ozone layer when it slowly evaporates from freshly painted surfaces","Raises the acidity of harbour water enough to dissolve nearby coral reefs and shells"],"answer":0,"explanation":"Even at a few nanograms per litre, TBT causes 'imposex' in dog whelks and other gastropods, collapsing their populations. The IMO's AFS Convention (2001) banned organotin anti-fouling paints.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-601","question":"In a xerosere developing on bare rock, the very first (pioneer) stage is usually formed by:","options":["Foliose lichens","Crustose lichens","Mosses","Annual herbs"],"answer":1,"explanation":"Crustose lichens, pressed flat against the rock, secrete acids that start weathering it; foliose lichens follow, then mosses, herbs, shrubs and finally trees.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-602","question":"Arrange the following stages of a hydrosere in the order in which they replace one another in a filling pond: 1. Reed-swamp stage (Typha, Phragmites) 2. Rooted floating stage (Nymphaea, Trapa) 3. Rooted submerged stage (Hydrilla, Vallisneria) 4. Sedge-meadow stage","options":["2-3-1-4","3-2-4-1","3-2-1-4","2-3-4-1"],"answer":2,"explanation":"After phytoplankton, rooted submerged plants raise the bottom, then rooted floating plants, then amphibious reed-swamp species, then sedges on the near-dry margin, before woodland takes over.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-603","question":"The entire sequence of communities that replace one another in a given area during ecological succession is called a:","options":["Sere","Biome","Ecotone","Ecocline"],"answer":0,"explanation":"A sere is the whole sequence; each transitional community is a seral stage. An ecotone is a boundary zone between two communities, and an ecocline a gradual change along a gradient.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-604","question":"The view that a region can have several stable climax communities, controlled by local soil, drainage and topography as well as by climate, is called the:","options":["Monoclimax theory of Clements","Climax-pattern hypothesis of Whittaker","Individualistic concept of Gleason","Polyclimax theory of Tansley"],"answer":3,"explanation":"Tansley's polyclimax theory allowed many climaxes in one climatic region. Clements held that climate alone sets a single climax, and Whittaker saw climax as a continuous pattern along gradients.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-605","question":"Consider the following statements about the models of succession proposed by Connell and Slatyer: 1. In the facilitation model, early species modify the site and make it more suitable for later species. 2. In the inhibition model, early species hold the site and hinder later ones until they die or are damaged. 3. In the tolerance model, later species can establish only after early species have modified the site for them. Which of the statements given above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Statement 3 describes facilitation, not tolerance. In the tolerance model, later species are neither helped nor hindered much by earlier ones; they simply tolerate lower resource levels and come to dominate.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-606","question":"A small lake gradually turns into marsh because a deforested catchment upstream washes large amounts of silt into it every monsoon. This change is an example of:","options":["Allogenic succession","Autogenic succession","Primary succession on rock","Retrogressive succession"],"answer":0,"explanation":"Allogenic succession is driven by forces from outside the community, here silt from the catchment. Autogenic succession is driven by the organisms themselves, for example by the build-up of their own dead remains.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-607","question":"Succession on a fallen, decaying log, or in a stream receiving organic sewage, where heterotrophs dominate and community respiration exceeds production, is known as:","options":["Autotrophic succession","Heterotrophic succession","Secondary succession","Cyclic succession"],"answer":1,"explanation":"In heterotrophic succession the P/R ratio is below 1 and the community runs down a stock of organic matter. Autotrophic succession, as on new land, begins with green plants and P/R above 1.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-608","question":"Which of the following are generally observed as ecological succession proceeds towards a climax? 1. Total biomass increases. 2. Net community productivity reaches its highest value at the climax. 3. The ratio of gross production to community respiration approaches 1. 4. Nutrient cycles become more closed, with fewer losses. Select the correct answer:","options":["1 and 2 only","2, 3 and 4 only","1, 3 and 4 only","1, 2, 3 and 4"],"answer":2,"explanation":"Mature communities store more biomass, recycle nutrients tightly and spend almost all their production on respiration, so P/R nears 1. Net community production is therefore highest in developing stages, not at the climax.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-609","question":"Which one of the following is an attribute of a population but NOT of an individual organism?","options":["Body size","Metabolic rate","Life span","Sex ratio"],"answer":3,"explanation":"Sex ratio, like birth rate, death rate and age distribution, exists only for a group. An individual has a size, a metabolic rate and a life span, but no ratio of sexes.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-610","question":"A deer population of 500 records, over one year, 60 births, 40 deaths, 20 animals arriving from outside and 30 animals leaving. What is the population at the end of the year?","options":["520","530","510","490"],"answer":2,"explanation":"Nₜ₊₁ = Nₜ + (B + I) − (D + E) = 500 + (60 + 20) − (40 + 30) = 510. Ignoring migration gives 520, and swapping immigration with emigration gives 530.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-611","question":"Under logistic (S-shaped) growth, the number of individuals added to a population per unit time is greatest when the population size N is:","options":["Very small, just after colonisation","About one-quarter of carrying capacity","About half of carrying capacity","Equal to carrying capacity"],"answer":2,"explanation":"dN/dt = rN(K − N)/K is a parabola in N with its peak at N = K/2. Near zero there are too few breeders; near K the brake (K − N)/K approaches zero.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-612","question":"A population follows logistic growth with r = 0.2 per year and carrying capacity K = 1,000. When N = 250, how many individuals are added per year?","options":["50","12.5","150","37.5"],"answer":3,"explanation":"dN/dt = rN(K − N)/K = 0.2 × 250 × 750/1,000 = 37.5. The trap 50 ignores the logistic brake, 12.5 uses N/K instead of (K − N)/K, and 150 multiplies r by (K − N).","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-613","question":"In very small populations of some species, survival and breeding success fall because individuals cannot find mates or defend themselves in groups. This phenomenon is called the:","options":["Allee effect","Founder effect","Edge effect","Bottleneck effect"],"answer":0,"explanation":"The Allee effect is a fall in per-capita growth at low density, which can push small populations to extinction. The founder and bottleneck effects describe loss of genetic variation, not of growth rate.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-614","question":"Which of the following act on a population as density-dependent factors? 1. Spread of an infectious disease 2. A severe, unseasonal frost 3. Competition for limited food 4. A forest fire started by lightning. Select the correct answer:","options":["1 and 3 only","2 and 4 only","1, 3 and 4 only","1, 2, 3 and 4"],"answer":0,"explanation":"Disease spreads and competition intensifies as crowding rises, so their effect depends on density. Frost and a lightning fire kill a similar proportion whatever the density, so they are density-independent.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-615","question":"On a survivorship graph drawn with a logarithmic scale, a population shows a straight diagonal line, meaning that a constant proportion of individuals dies at every age. This is a:","options":["Type I curve","Type II curve","Type III curve","Logistic curve"],"answer":1,"explanation":"A constant mortality rate gives a straight line on a log scale: Type II. Type I populations die mostly in old age; Type III populations suffer heavy losses among the very young.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-616","question":"An age pyramid in which the pre-reproductive and reproductive age groups are of nearly equal size, giving a bell shape, indicates a population that is:","options":["Growing rapidly","Declining steadily","Stable","Collapsing suddenly"],"answer":2,"explanation":"A bell shape means births roughly replace the breeding cohort, so the population is stable. A broad-based triangle indicates growth and an urn shape a decline.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-617","question":"Consider the following statements: 1. A metapopulation is a set of local populations in separate habitat patches linked by dispersal. 2. In a metapopulation, local populations may die out and their patches be recolonised later. 3. In source–sink dynamics, a sink population has more deaths than births and persists only through immigration. How many of the statements given above are correct?","options":["Only one","Only two","All three","None"],"answer":2,"explanation":"All three describe the metapopulation idea developed by Richard Levins and its source–sink extension. This is why protecting corridors and unoccupied patches matters for fragmented species.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-618","question":"The Lotka–Volterra equations, first developed in the 1920s, are mathematical models of:","options":["Energy transfer efficiency between trophic levels","Predator–prey interaction and interspecific competition","Logistic growth of a single population towards carrying capacity","The relation between island area and species number"],"answer":1,"explanation":"Lotka and Volterra independently modelled coupled predator–prey cycles and competition between two species. Logistic growth is Verhulst's equation, and the species–area relation comes from island biogeography.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-619","question":"Pacific salmon and many bamboos reproduce only once in their lifetime, putting all their resources into a single burst of breeding, and then die. This life-history strategy is called:","options":["Iteroparity","Parthenogenesis","Polyembryony","Semelparity"],"answer":3,"explanation":"Semelparous organisms breed once and die; iteroparous ones, such as most mammals and trees, breed repeatedly. Parthenogenesis is reproduction without fertilisation.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-620","question":"A population of 100 grows continuously and exponentially at an intrinsic rate r = 0.1 per year. Approximately what will its size be after 10 years?","options":["200","259","272","110"],"answer":2,"explanation":"Nₜ = N₀e^(rt) = 100 × e¹ ≈ 272. Compounding once a year (1.1¹⁰) gives the 259 trap, and assuming linear addition of 10% of the original each year gives 200.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-621","question":"The gap between a population's biotic potential and the growth it actually achieves in nature is attributed to:","options":["Environmental resistance","Intrinsic rate of increase","Reproductive isolation","Genetic drift"],"answer":0,"explanation":"Biotic potential is maximum growth under ideal conditions; environmental resistance (limits of food, space, predators, disease) holds actual growth below it, giving the S-shaped curve.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-622","question":"Match the type of sere with the habitat in which it begins. A. Psammosere  B. Halosere  C. Lithosere  D. Hydrosere; 1. Saline soil or water  2. Bare rock  3. Sand  4. Fresh water","options":["A-1, B-3, C-2, D-4","A-3, B-1, C-4, D-2","A-2, B-1, C-3, D-4","A-3, B-1, C-2, D-4"],"answer":3,"explanation":"Psammo- refers to sand, halo- to salt, litho- to rock and hydro- to water. Xerosere is the broad term for successions starting in dry habitats such as rock and sand.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-623","question":"Grasslands kept open for centuries by repeated burning and heavy grazing, in a climate where forest would otherwise develop, are best described as a:","options":["Climatic climax","Disclimax (biotic climax)","Pioneer community","Edaphic climax"],"answer":1,"explanation":"A disclimax is a stable community held short of the climatic climax by continued disturbance such as fire, grazing or cutting. An edaphic climax is set by soil conditions rather than by disturbance.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-624","question":"The cheetah shows remarkably low genetic variation, so that skin grafts between unrelated individuals are often not rejected. This is generally attributed to:","options":["A population bottleneck in its past","Its strictly solitary hunting habit","Hybridisation with the leopard","Its very short generation time"],"answer":0,"explanation":"A drastic fall in numbers long ago left survivors with only a fraction of the original genetic diversity. Low variation reduces a species' ability to adapt to disease or environmental change.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-625","question":"In a mark–recapture study, animals that were caught and marked once become 'trap-shy' and avoid traps afterwards. The Lincoln–Petersen estimate of population size will then be:","options":["Unaffected, since marks are not lost","Too low, an underestimate","Exactly halved","Too high, an overestimate"],"answer":3,"explanation":"N = (marked × second catch) ÷ recaptured marked. Trap-shy marked animals make the recaptured count too small, so N comes out too large. 'Trap-happy' animals cause the opposite error.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-626","question":"As atmospheric CO2 has risen, the ratio of carbon-13 to carbon-12 in that CO2 has steadily fallen. Why is this taken as a fingerprint of fossil-fuel burning?","options":["Volcanic CO2 is rich in carbon-12, and volcanic activity has increased sharply since 1850","Carbon-13 is radioactive and decays away faster in a warmer atmosphere","Fossil fuels come from ancient plants, which took up carbon-12 in preference to carbon-13","The oceans release mostly carbon-13 when they warm, so seawater becomes depleted in it"],"answer":2,"explanation":"Photosynthesis discriminates against the heavier 13C, so plant-derived fossil carbon is 13C-poor; adding it dilutes atmospheric 13C. Carbon-13 is a stable isotope, and volcanic emissions are small and have not risen.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-627","question":"Precise measurements show that the oxygen content of the atmosphere has been falling very slightly while CO2 rises. This observation mainly supports the conclusion that:","options":["The extra CO2 comes from combustion of carbon-containing fuels, which consumes oxygen","Volcanic eruptions are the main source of the extra CO2, since they absorb oxygen","The oceans are releasing CO2 because they are warming, and this uses up oxygen","Photosynthesis on land has increased sharply, which removes oxygen from the air"],"answer":0,"explanation":"Burning carbon consumes O2 in proportion to the fuel burnt, and the measured O2 decline matches fossil-fuel use. CO2 released from warming oceans or volcanoes would not consume atmospheric oxygen, and more photosynthesis would add O2.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-628","question":"Of the CO2 emitted each year by human activities, roughly what share stays in the atmosphere (the 'airborne fraction'), the rest being taken up by land and ocean sinks?","options":["About 10 per cent","About 45 per cent","About 80 per cent","Nearly all of it"],"answer":1,"explanation":"Over recent decades a little under half of emitted CO2 has remained airborne; the oceans and land ecosystems have each absorbed roughly a quarter. That is why concentrations rise more slowly than cumulative emissions alone would suggest.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-629","question":"The pre-industrial concentration of carbon dioxide in the atmosphere, as recorded in ice cores, was about:","options":["180 parts per million","350 parts per million","420 parts per million","280 parts per million"],"answer":3,"explanation":"Ice cores show CO2 near 280 ppm before about 1750. Around 180 ppm is typical of glacial maxima, 350 ppm was passed in the late 1980s, and levels crossed 400 ppm in the 2010s.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-630","question":"Consider the following statements: 1. The atmospheric concentration of methane has more than doubled since pre-industrial times. 2. The atmospheric concentration of carbon dioxide has more than doubled since pre-industrial times. 3. In proportional terms, methane has risen more than carbon dioxide since pre-industrial times. Which of the statements given above are correct?","options":["1 and 3 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Methane has risen from about 0.7 to well over 1.8 parts per million, more than two and a half times. CO2 has risen from about 280 ppm to the low 400s, roughly 50 per cent, far short of doubling.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-631","question":"Why can a very small amount of CFCs reaching the stratosphere destroy a very large amount of ozone?","options":["Each CFC molecule splits into thousands of separate chlorine atoms once it reaches the stratosphere","CFCs absorb all of the ultraviolet light that would otherwise be used to make new ozone molecules","Chlorine acts as a catalyst: it is regenerated after each reaction and destroys more ozone","CFCs combine permanently with ozone, so each CFC molecule keeps removing ozone for centuries"],"answer":2,"explanation":"In the cycle Cl + O3 gives ClO + O2, then ClO + O gives Cl + O2, the chlorine atom is freed again, so a single atom can destroy tens of thousands of ozone molecules before it is locked up in a reservoir species.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-632","question":"Halons, used in fire extinguishers, have far higher ozone-depleting potentials than CFC-11. The main reason is that halons:","options":["Are released into the air in much larger quantities than CFCs ever were","Contain bromine, which destroys ozone far more efficiently than chlorine","Reach the stratosphere within days because they are much lighter than air","Absorb ultraviolet light so strongly that no new ozone can form near them"],"answer":1,"explanation":"Bromine is roughly 60 times more effective than chlorine per atom, as less of it is held in inactive reservoir forms. Halon-1301 has an ODP of about 10, against 1 for CFC-11, though far less halon was produced.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-633","question":"Which of the following substances is now considered the largest ozone-depleting emission from human activity, yet is not controlled under the Montreal Protocol?","options":["Methyl bromide","Carbon tetrachloride","HCFC-22","Nitrous oxide"],"answer":3,"explanation":"N2O, mainly from fertilised soils, breaks down in the stratosphere to nitric oxide, which destroys ozone catalytically. It is covered as a greenhouse gas under the UNFCCC but not by the Montreal Protocol, unlike the other three.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-634","question":"Which of the following correctly describes how the atmosphere filters the Sun's ultraviolet radiation?","options":["UV-C is absorbed completely, UV-B mostly, and most UV-A reaches the ground","UV-A is absorbed completely, UV-B mostly, and most UV-C reaches the ground","All three types are absorbed equally, so ozone loss raises each of them alike","UV-B is absorbed completely, while UV-A and UV-C both reach the ground"],"answer":0,"explanation":"The shortest, most energetic UV-C is fully absorbed by oxygen and ozone; ozone absorbs most UV-B, so ozone thinning mainly increases UV-B at the surface; UV-A passes largely unaffected.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-635","question":"Most stratospheric ozone is produced over the tropics, where sunlight is strongest, yet the total ozone column (outside the ozone-hole season) is usually lowest over the tropics. The main reason is that:","options":["Tropical thunderstorms carry CFCs upward and destroy most of the ozone made there","Ozone made over the tropics is carried poleward and downward by stratospheric circulation","The tropical stratosphere is too warm for ozone to form at all, so it all comes from the poles","Tropical forests release gases that destroy ozone as soon as it forms overhead"],"answer":1,"explanation":"The slow Brewer–Dobson circulation lifts air in the tropics and moves it towards the poles, where it descends and ozone piles up, especially in late winter and spring. So production and column amount peak in different places.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-636","question":"Molecule for molecule, CFCs are thousands of times more powerful greenhouse gases than CO2. An important reason is that they:","options":["Absorb incoming visible sunlight strongly before it reaches the ground","Remain in the atmosphere for only a few days, so their effect is concentrated","Make clouds brighter, so they reflect more of the heat back to the surface","Absorb infrared in the 'atmospheric window' where other gases absorb little"],"answer":3,"explanation":"Between roughly 8 and 13 µm, water vapour and CO2 absorb weakly, so the Earth's heat escapes to space there. Gases absorbing in this window, such as CFCs, close a gap and so have a large effect per molecule.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-637","question":"Each additional part per million of CO2 adds a little less warming effect than the one before. This is mainly because:","options":["CO2 molecules bind to one another at high concentrations and form inactive clusters","The core of CO2's absorption band is already saturated, so forcing rises logarithmically","The oceans absorb a larger share of each extra part per million than of the previous one","Rising CO2 cools the stratosphere, which cancels most of the extra warming near the ground"],"answer":1,"explanation":"Where CO2 already absorbs almost all outgoing radiation, more gas adds little; extra absorption happens mainly in the band's wings. So each doubling of CO2 adds roughly the same forcing, about 3.7 W/m².","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-638","question":"Where has most of the extra heat trapped by the enhanced greenhouse effect since the 1970s gone?","options":["Into the oceans, which have taken up more than 90 per cent of it","Into the atmosphere, which has taken up about two-thirds of it","Into melting ice, which has taken up about half of it","Into the land surface, which has taken up most of it"],"answer":0,"explanation":"Water's high heat capacity means the oceans have absorbed over 90 per cent of the accumulated energy; the atmosphere, land and melting ice share the small remainder. Ocean warming drives thermal expansion and coral bleaching.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-639","question":"Newly hatched olive ridley turtles on a brightly lit beach often crawl inland, towards roads and buildings, instead of towards the sea. This happens mainly because:","options":["Artificial lights outshine the brighter seaward horizon that hatchlings move towards","Warm sand near lit buildings feels like the shallow sea water they are seeking","Hatchlings move downhill, and the lit ground behind most beaches lies lower","Lights drown out the stars that hatchlings use as a compass to find the sea"],"answer":0,"explanation":"Hatchlings find the sea by heading for the lowest, brightest horizon, which on a natural beach is over the water; artificial light inland overrides this cue. They do not navigate by star patterns, and beaches slope down towards the sea, not inland.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-640","question":"Over millions of years, the chemical weathering of silicate rocks is thought to act as a 'thermostat' for the Earth's climate. This is because:","options":["Weathering releases CO2 from the rocks, so a colder climate quickly leads to faster warming","Weathered rock fragments reflect more sunlight, so faster weathering cools the whole planet","Silicate rocks absorb infrared radiation, so exposing more of them steadily warms the planet","Weathering draws down CO2 and speeds up in warmer, wetter climates, pulling CO2 back"],"answer":3,"explanation":"Rain carrying dissolved CO2 weathers silicates, and the carbon ends up in ocean carbonate sediments. Warmer, wetter conditions speed this up and remove more CO2, a negative feedback that is far too slow to offset present-day emissions.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-641","question":"Consider the following statements about volcanoes and climate: 1. A large explosive eruption can cool the global climate for a year or two by putting sulphur dioxide into the stratosphere. 2. Volcanoes emit more CO2 each year than human activities do. 3. The eruption of Mount Pinatubo in 1991 was followed by a temporary global cooling of about half a degree Celsius. Which of the statements given above are correct?","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Stratospheric sulphate aerosols reflect sunlight for a year or two, as after Pinatubo. But volcanic CO2 output is around one per cent of human emissions, so statement 2 is wrong.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-642","question":"Land areas have warmed faster than the oceans in recent decades. The main reasons are that land:","options":["Has lower heat capacity and less water available for evaporative cooling","Receives more sunlight per square metre than the ocean does at the same latitude","Contains more greenhouse gases in the air directly above it than the ocean does","Reflects much less sunlight than the open ocean, so it absorbs more energy"],"answer":0,"explanation":"Water stores heat and mixes it downward, and evaporation from the sea removes heat; land heats up quickly at the surface. The open ocean is in fact darker (lower albedo) than most land.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-643","question":"Rising CO2 can raise plant photosynthesis (the 'CO2 fertilisation effect'). This effect is expected to be stronger in wheat and rice than in maize and sugarcane because:","options":["Wheat and rice are grown in winter, when the CO2 level in the air is noticeably higher","Wheat and rice carry many more leaves per plant than maize and sugarcane usually do","Wheat and rice are C3 plants; C4 crops already concentrate CO2 inside their leaves","Maize and sugarcane are unable to open their stomata at all when CO2 levels are high"],"answer":2,"explanation":"C4 plants pump CO2 into bundle-sheath cells, so their photosynthesis is nearly saturated at present CO2. C3 plants lose carbon to photorespiration, which higher CO2 suppresses, so they respond more.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-644","question":"Which of the following is the largest NATURAL source of methane emissions to the atmosphere?","options":["Termites in tropical grasslands","Geological seeps on the sea floor","Wild ruminants such as deer and antelope","Natural wetlands"],"answer":3,"explanation":"Waterlogged, oxygen-poor wetland soils host methanogenic archaea and supply the largest natural share of methane. Termites, geological seeps and wild animals are much smaller natural sources.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-645","question":"Which greenhouse gas was added to the Kyoto Protocol's basket of gases for its second commitment period by the Doha Amendment?","options":["Sulphur hexafluoride","Nitrogen trifluoride","Hydrofluorocarbons","Tropospheric ozone"],"answer":1,"explanation":"The original Kyoto basket had six gases: CO2, CH4, N2O, HFCs, PFCs and SF6. The Doha Amendment (2012) added nitrogen trifluoride, used in making flat-panel displays and solar cells.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-646","question":"The largest reservoir of carbon on Earth is held in:","options":["Sedimentary rocks such as limestone and shale","The deep ocean, as dissolved inorganic carbon","The atmosphere, as carbon dioxide","Soils and permafrost, as organic matter"],"answer":0,"explanation":"Carbonate rocks and organic kerogen in shales hold tens of millions of gigatonnes of carbon, far more than the ocean (about 38,000 Gt). This 'slow' carbon cycle exchanges with the surface over millions of years.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-647","question":"Oxygen levels in large parts of the ocean have declined in recent decades. Which of the following best explains this?","options":["Seawater is becoming saltier, and the extra salt reacts chemically with dissolved oxygen","Phytoplankton have begun using dissolved oxygen in place of carbon dioxide for growth","Warmer water holds less oxygen, and stronger layering cuts mixing with deep water","Ocean acidification converts the dissolved oxygen into carbonic acid near the surface"],"answer":2,"explanation":"Gas solubility falls as water warms, and a warmer, lighter surface layer mixes less with deeper water, so less oxygen reaches depth. Nutrient run-off adds coastal dead zones on top of this.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-648","question":"Consider the following statements: 1. A mature old-growth forest usually stores more carbon per hectare than a young plantation. 2. A young, fast-growing plantation usually absorbs carbon faster each year than an old-growth forest. Which of the statements given above is/are correct?","options":["1 only","2 only","Neither 1 nor 2","Both 1 and 2"],"answer":3,"explanation":"Stock and flow differ: old forests hold large stocks in big trees and soil, while young stands take up carbon faster as they grow. Clearing old forest to plant new trees releases far more carbon than the plantation soon recovers.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-649","question":"The Hindu Kush–Himalaya and Tibetan Plateau region is often called the 'Third Pole' because:","options":["It has the third-highest rainfall of any region in the world","It holds the largest store of ice outside the polar regions","It lies at the third-highest average elevation among regions","Its magnetic field is nearly as strong as at the two poles"],"answer":1,"explanation":"Its glaciers and snowfields form the largest ice mass after Antarctica and Greenland and feed rivers such as the Indus, Ganga, Brahmaputra and Yangtze, which is why their retreat is a major concern.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-650","question":"Greenhouse gases let most incoming sunlight through but absorb the heat radiated by the Earth. This difference arises mainly because:","options":["Sunlight arrives only by day, while the Earth radiates heat only at night","Incoming sunlight is mostly ultraviolet, which no gas in the atmosphere can absorb","The Earth's surface is far cooler than the Sun, so it radiates at much longer, infrared wavelengths","Greenhouse gases are found only near the ground, below the level that sunlight passes through"],"answer":2,"explanation":"By Wien's law, the Sun at about 5,800 K emits mostly visible and near-infrared light, while the Earth at about 288 K emits thermal infrared around 10 µm, where CO2, water vapour and methane absorb strongly.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-651","question":"Several unrelated species of butterfly that are all distasteful to birds share very similar bright warning patterns, so that a bird which learns to avoid one avoids them all. This is an example of:","options":["Batesian mimicry","Müllerian mimicry","Aggressive mimicry","Cryptic colouration"],"answer":1,"explanation":"In Müllerian mimicry all the look-alikes are unpalatable and share the cost of 'educating' predators. In Batesian mimicry a harmless species copies a harmful one.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-652","question":"The monarch butterfly is highly distasteful to birds. It acquires this protection by:","options":["Synthesising alkaloids in its wing scales during the pupal stage","Absorbing toxic heavy metals from the nectar of flowers it visits","Mimicking the appearance of a stinging wasp in flight","Storing toxins from the milkweed plants its caterpillars eat"],"answer":3,"explanation":"Caterpillars feeding on milkweeds sequester cardiac glycosides, which make the adult butterfly toxic to predators, and its bright colours advertise this. Defence acquired from the host plant is a classic predator–prey–plant link.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-653","question":"Cattle and goats usually avoid grazing the common wasteland shrub Calotropis (aak). This is mainly because the plant:","options":["Produces highly poisonous cardiac glycosides","Is covered in long, sharp thorns on its stems","Grows only on salt-encrusted alkaline soils","Has leaves too high for the animals to reach"],"answer":0,"explanation":"Calotropis defends itself chemically with cardiac glycosides in its milky latex. Chemical defences against herbivores are widespread in plants; Calotropis has no thorns.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-654","question":"The Abingdon Island tortoise of the Galápagos declined to extinction within about a decade after goats were introduced to its island. The interaction mainly responsible is best described as:","options":["Predation of tortoise eggs and hatchlings by the feral goats","Parasitism of tortoises by mites and ticks carried by goats","Amensalism through trampling of nests","Competition for plants, which goats browse more efficiently"],"answer":3,"explanation":"Goats and tortoises used the same food, and the goats' greater browsing efficiency left the tortoises without enough to eat: interspecific competition between unrelated species.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-655","question":"On the rocky Scottish coast, Joseph Connell found that the barnacle Chthamalus occupied only the upper intertidal zone, though it could survive lower down when the larger barnacle Balanus was removed. This showed that:","options":["Competition from Balanus narrowed the realised niche of Chthamalus","Chthamalus is a parasite that depends on Balanus for its food supply","Balanus is a keystone predator that feeds on Chthamalus larvae","The two barnacles share a mutualistic relationship on the rocks"],"answer":0,"explanation":"Competition from Balanus excluded Chthamalus from the lower zone it could physically tolerate, shrinking its realised niche. Connell's field experiment is a classic demonstration of competitive exclusion in nature.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-656","question":"The human liver fluke completes its life cycle using:","options":["Only one host, the human, throughout its life cycle","Two intermediate hosts, a snail and a fish","Pigs as the only intermediate host before humans","A mosquito as the intermediate host"],"answer":1,"explanation":"Fluke larvae develop first in a snail and then in a fish, and people are infected by eating raw or undercooked fish. Complex life cycles with several hosts are a common parasitic adaptation.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-657","question":"Two forest plots each contain the same four tree species and 100 trees in all. Plot P has 25 trees of each species; plot Q has 97 trees of one species and one tree of each of the others. Which statement is correct?","options":["Both have equal diversity, since species richness is the same","Q is more diverse, since it has a clearly dominant species","P is more diverse, because its species are more evenly represented","Neither can be compared without first knowing the areas of the plots"],"answer":2,"explanation":"Diversity indices such as Shannon's combine richness with evenness. With equal richness, the evenly spread plot P scores much higher than the strongly dominated plot Q.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-658","question":"According to the intermediate disturbance hypothesis, the species diversity of a community tends to be highest when disturbance is:","options":["Absent, so the community reaches a stable climax","Of intermediate frequency and intensity","Very frequent and severe, so pioneers keep arriving","Restricted to the edges of the community"],"answer":1,"explanation":"With little disturbance strong competitors exclude others; with too much only a few tolerant pioneers survive. Moderate disturbance lets both pioneer and late-successional species coexist.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-659","question":"When Robert Paine removed the starfish Pisaster from patches of rocky shore, mussels spread over the rocks and the number of invertebrate species fell sharply. The starfish was acting as a:","options":["Foundation species that physically builds the habitat","Keystone predator preventing competitive exclusion","Flagship species that draws public support for the shore","Pioneer species starting succession"],"answer":1,"explanation":"By eating the dominant competitor (mussels), Pisaster kept space open for many other species. Its loss allowed competitive exclusion; the term 'keystone species' came from this work.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-660","question":"Kangaroos in Australian grasslands and antelopes in African savannas are unrelated but play similar roles as large grazers in similar habitats. Such species are called:","options":["Ecological equivalents","Allopatric sibling species","Ecotypes","Keystone species"],"answer":0,"explanation":"Ecological equivalents occupy similar niches in different geographical regions. Sibling species are closely related look-alikes, and ecotypes are locally adapted forms of one species.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-661","question":"Match the temperate grassland with its region. A. Pampas  B. Veld  C. Downs  D. Steppe; 1. South Africa  2. Eurasia  3. Argentina  4. Australia","options":["A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-2, D-4"],"answer":0,"explanation":"Pampas are in Argentina, the veld in South Africa, the downs in Australia and the steppes across Eurasia; the North American equivalent is the prairie.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-662","question":"Consider the following statements about tropical rainforests: 1. Lianas are woody climbers rooted in the ground that use trees for support to reach light. 2. Epiphytes such as many orchids grow on trees and draw their food from the host's tissues. 3. Emergent trees rise above the general canopy. Which of the statements given above is/are correct?","options":["1 and 3 only","2 only","1, 2 and 3","2 and 3 only"],"answer":0,"explanation":"Epiphytes use trees only for support and make their own food; they are not parasites. Lianas and emergents are standard features of the multi-layered rainforest.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-663","question":"Assertion (A): Climbing from the foothills to the snowline of the Himalaya, one passes through vegetation belts resembling those met when travelling from the tropics towards the poles. Reason (R): Temperature falls with altitude, much as it falls with increasing latitude. Choose the correct option:","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Air cools by about 6.5 °C per kilometre of ascent, so altitude zones repeat the latitudinal sequence: tropical forest, temperate forest, conifers, alpine meadows and then snow.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-664","question":"Which of the following pairs of interaction are correctly matched? 1. Cattle egret feeding on insects disturbed by grazing cattle — commensalism 2. Barnacles growing on the skin of a whale — commensalism 3. Honeybees and the flowering plants they visit — mutualism 4. Tapeworm in the human intestine — amensalism. Select the correct answer:","options":["1 and 3 only","2, 3 and 4 only","1, 2 and 3 only","1, 2, 3 and 4"],"answer":2,"explanation":"The egret and the barnacles gain while their hosts are largely unaffected, and bees and flowers both benefit. A tapeworm harms its host while benefiting itself, which is parasitism, not amensalism.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-665","question":"In community ecology, a group of species that exploit the same kind of resource in a similar way, such as all the birds that glean insects from foliage in a forest, is called a:","options":["Trophic level","Population","Guild","Biome"],"answer":2,"explanation":"A guild groups species by how they use a resource, regardless of relatedness. A trophic level is broader, including all organisms at the same feeding step.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-666","question":"In Opuntia and many other cacti, leaves are reduced to spines. Photosynthesis in these plants is carried out mainly by:","options":["Underground storage roots","The spines themselves","Specialised root hairs","Flattened green stems"],"answer":3,"explanation":"The flattened, green stems (phylloclades) take over photosynthesis, while spines cut water loss and deter herbivores. Many cacti also use CAM to keep stomata closed by day.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-667","question":"The kangaroo rat of North American deserts can live without ever drinking water. It manages this mainly by:","options":["Storing large volumes of water in its swollen tail to use during dry spells","Absorbing atmospheric moisture through its skin and fur during cool nights","Making water by oxidising fat and excreting very concentrated urine","Feeding only on juicy cactus stems that are rich in stored water and salts"],"answer":2,"explanation":"Metabolic water from fat oxidation, very concentrated urine and nocturnal habits let it balance its water budget on dry seeds alone.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-668","question":"The roots and fallen leaves of the black walnut tree release juglone, a chemical that stops many other plants from growing near it. This phenomenon is called:","options":["Mutualism","Allelopathy","Commensalism","Competitive release"],"answer":1,"explanation":"Allelopathy is chemical inhibition of one plant by another, a form of amensalism. Competitive release is the expansion of a species' niche after a competitor is removed.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-669","question":"In many forests, eagles and hawks hunt small mammals by day, while owls hunt similar prey at night. Their coexistence is an example of:","options":["Temporal resource partitioning","Commensalism between predators","Batesian mimicry","Competitive exclusion"],"answer":0,"explanation":"Dividing the use of a shared resource by time of day reduces direct competition. Partitioning can also be spatial or by type of food.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-670","question":"After examining a Madagascar orchid whose nectar lay at the bottom of a spur about 30 cm long, Charles Darwin predicted the existence of a moth with an equally long proboscis, which was later discovered. This illustrates:","options":["Convergent evolution","Coevolution","Adaptive radiation","Industrial melanism"],"answer":1,"explanation":"Plant and pollinator evolved reciprocally, the flower's spur lengthening with the moth's tongue. Convergent evolution concerns unrelated species becoming alike, not paired adaptation.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-671","question":"In Central America, certain ants live in the hollow thorns of bullhorn acacias, feed on nectar and protein-rich bodies produced by the tree, and aggressively attack herbivores and clear competing plants around it. This relationship is:","options":["Parasitism of the tree by the ants","Commensalism, the tree being unaffected","Amensalism, the ants harming the tree","Mutualism benefiting both partners"],"answer":3,"explanation":"The tree provides food and shelter while the ants defend it; experiments show acacias without ants grow poorly. Both partners benefit, so it is mutualism.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-672","question":"'Reindeer moss', a major winter food of reindeer and caribou in the tundra, is actually a:","options":["Moss","Fern","Liverwort","Lichen"],"answer":3,"explanation":"Reindeer moss (Cladonia) is a lichen, a fungus–alga partnership, despite its name. Its slow growth makes tundra pastures vulnerable to overgrazing.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-673","question":"In which of the following biomes is the share of ecosystem organic carbon held in the soil, rather than in living vegetation, the greatest?","options":["Tropical rainforest","Tropical savanna","Hot desert","Arctic tundra"],"answer":3,"explanation":"Cold, waterlogged tundra soils decompose organic matter very slowly, so most carbon lies in soil and permafrost. In tropical rainforests much of the carbon is in the trees themselves.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-674","question":"Which one of the following is NOT a typical adaptation of endoparasites such as tapeworms?","options":["Hooks or suckers for attachment to the host","Very high reproductive capacity","Well-developed sense organs","Loss or reduction of the digestive system"],"answer":2,"explanation":"Living inside a host with food all around, endoparasites lose unnecessary organs, including sense organs and often the gut, while developing attachment organs and huge reproductive output.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-675","question":"Trees of the temperate deciduous forest shed their broad leaves in autumn. The main advantage of this is that it helps them:","options":["Get rid of salts that have built up in the leaves before spring growth","Let more sunlight reach the herbs of the forest floor in winter","Avoid water loss and frost damage while soil water is frozen in winter","Return nitrogen to the soil quickly in time for the next season"],"answer":2,"explanation":"In winter, frozen soil makes water unavailable while broad leaves would keep losing it and suffer frost damage, so shedding them is a drought-and-cold adaptation. Most leaf nitrogen is actually withdrawn into the tree before leaf fall.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-676","question":"Consider the following measures: 1. Breeding drought-tolerant crop varieties 2. Restoring mangrove belts to buffer storm surges 3. Replacing a coal power plant with a solar park 4. Running a city heat action plan with early warnings and cool shelters. How many of these are primarily adaptation (rather than mitigation) measures?","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Adaptation reduces harm from climate change that is already happening or expected; measures 1, 2 and 4 do that. Replacing coal with solar cuts emissions, which is mitigation (mangroves also store carbon, but buffering surges is an adaptation aim).","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-677","question":"The first city in South Asia to adopt a formal Heat Action Plan, in 2013, after a deadly heat wave in 2010 was:","options":["Ahmedabad","Nagpur","Jaipur","Hyderabad"],"answer":0,"explanation":"Ahmedabad's plan, prepared with public health experts, set up early warnings, cool shelters, hospital readiness and public outreach; it later became a model for heat action plans across Indian cities and states.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-678","question":"Under India's National Adaptation Fund for Climate Change (NAFCC), the National Implementing Entity that appraises and channels funds to state adaptation projects is:","options":["The Indian Renewable Energy Development Agency","The Bureau of Energy Efficiency","The Small Industries Development Bank of India","The National Bank for Agriculture and Rural Development"],"answer":3,"explanation":"NABARD is the National Implementing Entity for the NAFCC, launched in 2015, and also for the UNFCCC's Adaptation Fund in India. BEE deals with energy efficiency, a mitigation area.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-679","question":"State Action Plans on Climate Change (SAPCCs) in India are:","options":["Prepared by the Central Pollution Control Board for each state","Prepared by state governments in line with the NAPCC and its national missions","Binding emission-reduction targets set for each state under the Paris Agreement","Plans that each state must submit directly to the UNFCCC secretariat every five years"],"answer":1,"explanation":"States were asked from about 2009 onward to prepare SAPCCs that apply the NAPCC's missions to local conditions. Only the national government reports to the UNFCCC, and the Paris Agreement sets no state-level targets.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-680","question":"In its Nationally Determined Contribution, India committed to create an additional carbon sink through additional forest and tree cover by 2030 of:","options":["0.5 to 1 billion tonnes of CO2 equivalent","1 to 1.5 billion tonnes of CO2 equivalent","2.5 to 3 billion tonnes of CO2 equivalent","5 to 6 billion tonnes of CO2 equivalent"],"answer":2,"explanation":"The forestry target of 2.5–3 billion tonnes CO2e, set in 2015, was retained in the 2022 update, which also raised the emissions-intensity target to 45 per cent below 2005 and the non-fossil power capacity target to about 50 per cent by 2030.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-681","question":"Which one of the following was NOT among the five commitments ('Panchamrit') announced by India at COP-26 in Glasgow in 2021?","options":["Reaching 500 GW of non-fossil energy capacity by 2030","Reducing projected carbon emissions by one billion tonnes by 2030","Reaching net-zero emissions by 2070","Phasing out all coal-based power generation by 2040"],"answer":3,"explanation":"The Panchamrit were 500 GW non-fossil capacity, 50 per cent of energy needs from renewables, a one-billion-tonne cut in projected emissions and under 45 per cent carbon intensity, all by 2030, and net zero by 2070. India made no coal phase-out date.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-682","question":"Mission LiFE, promoted by India from 2021–22, stands for:","options":["Lifestyle for Environment, a movement for mindful, sustainable consumption","Low-Impact Forest Ecosystems, a national programme to restore degraded forests","Livelihoods in Fragile Ecosystems, a scheme for Himalayan and coastal communities","Legal Initiative for the Environment, a plan to revise and update India's green laws"],"answer":0,"explanation":"LiFE was announced by India at COP-26 in 2021 and launched as Mission LiFE in 2022; it urges individuals and communities to adopt habits such as saving energy and water and reducing waste.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-683","question":"Consider the following statements about the Green Credit Programme notified by India in 2023: 1. It was notified under the Environment (Protection) Act, 1986. 2. It rewards voluntary environmental actions such as tree plantation and water conservation with tradable green credits. 3. It replaces India's commitments under the Paris Agreement. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"The Green Credit Rules, 2023 were framed under the EP Act, with the Indian Council of Forestry Research and Education as administrator, to reward voluntary actions. It is a domestic market-based scheme and does not replace India's NDC.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-684","question":"India's Carbon Credit Trading Scheme, notified in 2023, draws its legal authority from:","options":["The Environment (Protection) Act, 1986","The Air (Prevention and Control of Pollution) Act, 1981","The Energy Conservation Act, 2001, as amended in 2022","The Electricity Act, 2003, as amended in 2021"],"answer":2,"explanation":"The 2022 amendment to the Energy Conservation Act empowered the Centre to specify a carbon credit trading scheme, and the Bureau of Energy Efficiency acts as its administrator; the PAT scheme also stems from this Act.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-685","question":"Consider the following statements about the International Solar Alliance: 1. It was launched by India and France at COP-21 in Paris in 2015. 2. Its headquarters is at Gurugram in India. 3. Membership is restricted to countries lying between the Tropics of Cancer and Capricorn. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"The ISA began as an alliance of sunshine-rich tropical countries, but its framework agreement was later amended to open membership to all UN member states. It is headquartered in Gurugram.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-686","question":"The Coalition for Disaster Resilient Infrastructure (CDRI), whose secretariat is in New Delhi, was launched in 2019 at:","options":["The G20 summit at Osaka","COP-25 of the UNFCCC at Madrid","The Sendai conference on disaster risk reduction","The UN Climate Action Summit in New York"],"answer":3,"explanation":"India launched CDRI at the UN Secretary-General's Climate Action Summit in September 2019 as a partnership of countries and agencies to make infrastructure resilient to climate and disaster risks.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-687","question":"The Leadership Group for Industry Transition (LeadIT), which works on decarbonising heavy industries such as steel and cement, was launched in 2019 by India together with:","options":["France","Sweden","Germany","Japan"],"answer":1,"explanation":"India and Sweden launched LeadIT at the UN Climate Action Summit in 2019. France partnered India in founding the International Solar Alliance, a frequent source of confusion.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-688","question":"Which of the following is the best example of 'maladaptation' to climate change?","options":["Restoring floodplain wetlands so that they store floodwater during heavy rain","Planting heat-tolerant wheat varieties in the plains ahead of hotter summers","A sea wall that saves one beach but speeds up erosion further along the coast","Shifting school hours to the cooler early morning during heat-wave weeks"],"answer":2,"explanation":"Maladaptation is an action meant to reduce climate risk that ends up raising vulnerability elsewhere, for others or in the future. A sea wall that diverts erosion to neighbouring coasts is a classic case; the other options reduce risk without such side effects.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-689","question":"The decision to establish a dedicated fund for responding to loss and damage from climate change, for vulnerable developing countries, was taken at:","options":["COP-27 at Sharm el-Sheikh","COP-21 at Paris, France","COP-19 at Warsaw, Poland","COP-26 at Glasgow, UK"],"answer":0,"explanation":"COP-27 (2022) agreed to set up the fund, and COP-28 (2023) made it operational. COP-19 at Warsaw created the Warsaw International Mechanism, which deals with loss and damage but is not a fund.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-690","question":"Consider the following statements about the 'Global Stocktake' under the Paris Agreement: 1. It assesses the collective progress of all parties towards the agreement's long-term goals. 2. It is held every five years. 3. The first one was concluded at COP-28 in 2023. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Under Article 14, the stocktake reviews collective, not individual, progress every five years and informs the next round of NDCs. The first was completed at COP-28 in Dubai.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-691","question":"The pledge by developed countries to mobilise 100 billion US dollars a year in climate finance for developing countries by 2020 was first made at:","options":["COP-3 at Kyoto in 1997","COP-15 at Copenhagen in 2009","COP-21 at Paris in 2015","COP-16 at Cancún in 2010"],"answer":1,"explanation":"The goal appeared in the Copenhagen Accord (2009), was formalised at Cancún in 2010 and extended to 2025 at Paris. Kyoto set emission targets; Cancún only formalised a goal already pledged.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-692","question":"Under the Kyoto Protocol, 'Joint Implementation' allowed:","options":["A developed country to earn credits from emission-reduction projects in a developing country","Developing countries to trade surplus emission allowances among themselves","One developed country to earn credits from emission-cutting projects in another","Two or more developing countries to pool their targets into a single shared target"],"answer":2,"explanation":"Joint Implementation operated between Annex I parties and generated Emission Reduction Units. Projects in developing countries came under the Clean Development Mechanism, and developing countries had no Kyoto targets to trade or pool.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-693","question":"Which of the following correctly contrasts a carbon tax with a cap-and-trade system?","options":["A carbon tax fixes the price of emissions but not the quantity, while cap-and-trade fixes the quantity but lets the price vary","A carbon tax fixes the quantity of emissions but not the price, while cap-and-trade fixes the price but lets the quantity vary","Both fix the quantity of emissions in advance, but only a carbon tax lets firms trade permits among themselves","Both fix the price of emissions in advance, but only cap-and-trade raises revenue for the government"],"answer":0,"explanation":"A tax sets a known price per tonne and leaves total emissions to firms' responses; a cap limits total permits and lets the market set the price. Auctioned permits can also raise revenue, so revenue does not separate them.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-694","question":"The European Union's Carbon Border Adjustment Mechanism (CBAM), which affects exports of steel and aluminium from India, is designed mainly to:","options":["Ban all imports from countries that have not yet ratified the Paris Agreement","Fund adaptation projects in developing countries through a levy on all flights","Exempt developing countries from any emission targets under the UNFCCC","Prevent 'carbon leakage' by pricing the embedded emissions of some imports"],"answer":3,"explanation":"CBAM requires importers of goods such as steel, aluminium, cement and fertilisers to pay a price for their embedded carbon, so that EU industry does not simply move to places with weaker carbon pricing. India has criticised it as a unilateral trade barrier.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-695","question":"A 'green bond', such as the sovereign green bonds first issued by India in 2023, differs from an ordinary bond mainly in that:","options":["It pays no interest at all, since investors are rewarded with carbon credits","Its proceeds are earmarked for projects with environmental or climate benefits","It can be bought only by government-owned banks, insurers and pension funds","It must be repaid within one year so that the funded projects finish quickly"],"answer":1,"explanation":"A green bond is an ordinary debt instrument with interest and maturity, except that the money raised is ring-fenced for eligible green projects such as renewable energy or clean transport.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-696","question":"UJALA, launched by the Government of India in 2015 and run by Energy Efficiency Services Limited, mainly aimed at:","options":["Installing rooftop solar panels on rural homes free of cost to the families","Replacing kerosene lamps with solar lanterns in tribal and forest villages","Distributing LED bulbs to households at low cost in place of old bulbs","Providing free LPG cooking gas connections to women from poor households"],"answer":2,"explanation":"UJALA used bulk procurement to cut LED prices sharply and distributed over 36 crore bulbs, saving electricity and peak demand. Free LPG connections came under the separate Ujjwala scheme, a common confusion.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-697","question":"National Innovations in Climate Resilient Agriculture (NICRA), which studies crops, livestock and fisheries under climate stress, is a network project of:","options":["The Indian Council of Agricultural Research","The India Meteorological Department","The National Bank for Agriculture and Rural Development","The Ministry of Earth Sciences"],"answer":0,"explanation":"ICAR launched NICRA in 2011 to develop and demonstrate climate-resilient technologies, including in climate-vulnerable villages. IMD provides weather data but does not run this research programme.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-698","question":"In transport policy, the 'Avoid–Shift–Improve' framework for cutting emissions refers to:","options":["Avoiding new road building, shifting freight to coastal ships and improving tyre quality","Avoiding fuel taxes, shifting subsidies to private car owners and improving road surfaces","Avoiding electric vehicles, shifting all fleets to biofuels and improving engine design","Avoiding needless trips, shifting to public and non-motorised transport, improving vehicles"],"answer":3,"explanation":"The framework ranks options: first reduce travel demand (through land use, telework), then move trips to buses, rail, walking and cycling, and finally make vehicles and fuels cleaner.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-699","question":"The Global Methane Pledge, launched at COP-26 in 2021, aims to cut global methane emissions by at least 30 per cent from 2020 levels by 2030. Which of the following is correct about India's position?","options":["India co-founded the pledge in 2021 along with the USA and the European Union","India has not joined the pledge, citing methane's link to farm livelihoods","India joined the pledge, but only for methane emitted from its coal mines","India joined the pledge with a deeper national target of 50 per cent by 2030"],"answer":1,"explanation":"Most of India's methane comes from livestock and paddy fields, tied to small farmers' livelihoods, and India has declined to sign. The pledge was led by the USA and the European Union.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-700","question":"The Glasgow Climate Pact (COP-26, 2021), after a late intervention led by India, called on countries to accelerate efforts towards the:","options":["Phase-out of all coal power by 2040 in developed countries and 2050 elsewhere","Phase-out of all fossil fuels, including oil and gas, by the middle of the century","Phase-down of unabated coal power and phase-out of inefficient fossil fuel subsidies","Phase-down of all coal use, including coal used for steel making, by 2030"],"answer":2,"explanation":"The draft spoke of 'phase-out' of unabated coal; India's amendment changed it to 'phase-down', and the pact also targeted inefficient fossil fuel subsidies. It was the first COP text to mention coal explicitly.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-701","question":"Following the addition of the Forests of East Australia in 2016, how many global biodiversity hotspots are recognised by Conservation International?","options":["25","34","36","40"],"answer":2,"explanation":"Myers' original 2000 list had 25 hotspots; it grew to 34 and then 35, and with the Forests of East Australia the count became 36, four of which extend into India.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-702","question":"How many of the following statements about megadiverse countries are correct? I. Conservation International identified 17 countries that together hold a majority of the world's species. II. India is one of these megadiverse countries. III. The group of Like-Minded Megadiverse Countries was formed through the Cancún Declaration of 2002. IV. All the megadiverse countries lie wholly within the tropics.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I–III are correct. IV is wrong: the list includes the USA, China, Australia and South Africa, which extend far outside the tropics.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-703","question":"India, with deserts, rainforests, mangroves, coral reefs, wetlands, estuaries and alpine meadows, is said to be far richer than a Scandinavian country such as Norway in which level of biodiversity?","options":["Genetic diversity","Ecosystem diversity","Alpha diversity","Taxonomic diversity"],"answer":1,"explanation":"The variety of habitats and ecosystems within a country is ecosystem (ecological) diversity. Genetic diversity is variation within a species, and alpha diversity is the count within one habitat.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-704","question":"In the Western Ghats, which of the following animal groups shows the highest proportion of endemic species?","options":["Birds","Mammals","Butterflies","Amphibians"],"answer":3,"explanation":"Most Western Ghats frogs and caecilians occur nowhere else, because amphibians disperse poorly and are tied to moist local habitats. Birds, being mobile, have a low share of endemics.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-705","question":"The closest living relatives of the purple frog (Nasikabatrachus) of the Western Ghats are found in the Seychelles. This distribution is best explained by:","options":["Recent introduction of frogs by traders sailing across the Indian Ocean","The break-up of the Gondwana supercontinent","Rafting of frogs on floating vegetation during monsoon storms","A land bridge through Arabia during the last ice age"],"answer":1,"explanation":"India and the Seychelles separated as Gondwana broke up, so their frog lineages diverged from a common ancestor. The purple frog is thus an ancient relict, not a recent arrival.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-706","question":"The Nicobar Islands lie in the Sundaland hotspot. In which biodiversity hotspot do the Andaman Islands lie?","options":["Sundaland","Western Ghats and Sri Lanka","Indo-Burma","Himalaya"],"answer":2,"explanation":"The Andamans' flora and fauna are allied to Myanmar and are included in Indo-Burma, while the Nicobars, nearer Sumatra, belong to Sundaland. The Ten Degree Channel lies roughly between them.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-707","question":"The Wallace Line, a boundary between Asian and Australasian faunas, runs between:","options":["Sri Lanka and the Maldives","Sumatra and the Malay Peninsula","New Guinea and Australia","Bali and Lombok"],"answer":3,"explanation":"Deep water between Bali and Lombok, and between Borneo and Sulawesi, kept these islands apart even at low ice-age sea levels, so placental mammals stay west and marsupials east of the line.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-708","question":"In the classification prepared for the Wildlife Institute of India by Rodgers and Panwar, India is divided into how many biogeographic zones?","options":["Eight","Ten","Twelve","Fifteen"],"answer":1,"explanation":"There are ten zones, from the Trans-Himalaya to the Islands, further split into biotic provinces; the Deccan Peninsula is the largest zone by area.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-709","question":"Consider the following statements about the species–area relationship, log S = log C + Z log A: 1. For areas within a region, Z usually lies in the range of about 0.1 to 0.2, whatever the taxonomic group. 2. When very large areas such as whole continents are compared, the slope becomes much steeper. 3. A larger Z means that species number changes less with area. Which of the statements given above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Z is typically 0.1–0.2 but rises to about 0.6–1.2 between continents. A larger Z means a steeper line, so species number changes more, not less, with area.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-710","question":"If the species–area relationship S = cA^z holds with z = 0.3, then destroying 90 per cent of a habitat would be expected eventually to eliminate roughly what share of the species it held?","options":["About 50 per cent","About 90 per cent","About 27 per cent","About 70 per cent"],"answer":0,"explanation":"The remaining 10% of area keeps 0.1^0.3 ≈ 0.50 of the species, so about half are lost. Species loss is less than proportional to habitat loss, but still severe.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-711","question":"When a fish species becomes extinct, the parasites that could live only in that fish also disappear. This process is called:","options":["Co-extinction","Background extinction","Mass extinction","Pseudo-extinction"],"answer":0,"explanation":"Co-extinction is the loss of species that depend obligately on another, such as specialist parasites or pollinators; it is one of the 'Evil Quartet' of causes of biodiversity loss.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-712","question":"Compared with the 'background' rate in the fossil record before humans, present-day rates of species extinction are estimated to be roughly:","options":["About the same as the background rate","Two to five times the background rate","100 to 1,000 times the background rate","A million times the background rate"],"answer":2,"explanation":"Estimates of 100–1,000 times the background rate are why many scientists speak of a sixth mass extinction, this time driven by human activity.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-713","question":"Exploring molecular, genetic and species-level diversity for products of economic value, such as new medicines, is known as:","options":["Biopiracy","Bioremediation","Biomagnification","Bioprospecting"],"answer":3,"explanation":"Bioprospecting is the search for useful products in nature; when it uses resources or traditional knowledge without consent or benefit-sharing, it becomes biopiracy.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-714","question":"The argument that biodiversity should be conserved because it provides services such as pollination, oxygen production and climate regulation, on which human well-being depends, is called the:","options":["Narrowly utilitarian argument","Ethical argument","Aesthetic argument","Broadly utilitarian argument"],"answer":3,"explanation":"Broadly utilitarian arguments rest on ecosystem services. Narrowly utilitarian ones point to direct products such as food, timber and drugs, while the ethical argument holds that every species has intrinsic value.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-715","question":"Two sites together contain 40 species. Site A has 20 species and site B has 30. Using Whittaker's measure, beta diversity = gamma diversity ÷ mean alpha diversity, what is the beta diversity?","options":["0.625","1.6","2.0","15"],"answer":1,"explanation":"Mean alpha = (20 + 30)/2 = 25, so beta = 40/25 = 1.6. A value of 1 would mean both sites hold identical species; 2 would mean they share none.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-716","question":"The Narcondam hornbill is found naturally only on:","options":["A small volcanic island in the Andaman Sea","The wet evergreen forests of Silent Valley in Kerala","The Garo Hills of western Meghalaya","The Car Nicobar island in the Nicobar group"],"answer":0,"explanation":"Narcondam is a tiny volcanic island east of the Andamans and is the only home of this hornbill, a striking case of island endemism.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-717","question":"According to N. I. Vavilov's centres of origin of cultivated plants, which one of the following crops did NOT originate in the Indian (Hindustan) centre?","options":["Mango","Brinjal","Black pepper","Maize"],"answer":3,"explanation":"Maize was domesticated in Mexico, in the Central American centre. Mango, brinjal and black pepper all trace to the Indian region, which also contributed sugarcane and several pulses.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-718","question":"In India, the Important Bird and Biodiversity Areas (IBAs) programme of BirdLife International has been coordinated by:","options":["The Zoological Survey of India","The Wildlife Institute of India","The Botanical Survey of India","The Bombay Natural History Society"],"answer":3,"explanation":"BNHS, BirdLife's partner in India, identified the country's IBAs using standard criteria for threatened, range-restricted and congregatory birds.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-719","question":"Assertion (A): Species endemic to small islands are especially prone to extinction. Reason (R): They often have small populations and ranges and have evolved without mainland predators and competitors. Choose the correct option:","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Small, isolated populations have nowhere to retreat and little defence against introduced rats, cats or diseases, which is why most recorded bird extinctions have been on islands.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-720","question":"The 'Satpura hypothesis' proposed by S. L. Hora sought to explain:","options":["Why the Deccan plateau has very few endemic plant species","How the Narmada valley acts as a barrier to tigers moving south","How Malayan species reached the Western Ghats through the central Indian hills","Why the Satpura forests receive more rainfall than the Western Ghats"],"answer":2,"explanation":"Hora suggested the Satpura and associated ranges once formed a moist forest corridor from north-east India to the Western Ghats, explaining the Malayan affinities of some Ghats fauna.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-721","question":"Myristica swamps, an ancient type of freshwater swamp forest dominated by trees of the nutmeg family, are found in India mainly in:","options":["The Western Ghats","The Sundarbans delta","The Terai of Uttar Pradesh","The Andaman Islands"],"answer":0,"explanation":"These relict swamps survive in small patches in Kerala, Karnataka and Goa, with trees bearing stilt and knee roots. The Sundarbans are tidal mangroves, a different ecosystem.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-722","question":"The '30 by 30' target in the Kunming–Montreal Global Biodiversity Framework (2022) calls for:","options":["Cutting the extinction rate of known species by 30 per cent by 2030","Effectively conserving at least 30 per cent of land and of oceans by 2030","Raising global finance for biodiversity by 30 per cent before 2030","Restoring 30 per cent of degraded wetlands in each country by 2030"],"answer":1,"explanation":"Target 3 of the framework, adopted at CBD COP-15, seeks effective conservation of at least 30% of terrestrial, inland water, coastal and marine areas by 2030.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-723","question":"The replacement of thousands of traditional rice landraces in Indian fields by a few high-yielding varieties after the Green Revolution is an example of:","options":["Genetic erosion","Ecological succession","Adaptive radiation","Co-extinction"],"answer":0,"explanation":"Genetic erosion is the loss of genetic diversity within crops or species. Landraces carry genes for drought, pest and flood tolerance, which is why gene banks try to save them.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-724","question":"Consider the following statements: 1. Every exotic species introduced into a new region becomes invasive. 2. An invasive species is one that spreads in its new range and harms native species or ecosystems. 3. Oceanic islands are particularly vulnerable to invasive species. Which of the statements given above is/are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Most introduced species never spread widely; only a minority become invasive. Islands, whose species evolved in isolation, suffer the heaviest damage from invaders.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-725","question":"The Nicobar megapode, a bird endemic to the Nicobar Islands, is notable because it:","options":["Is flightless and nests in burrows dug on sandy beaches","Lays its eggs in the nests of crows, which then raise its chicks","Incubates its eggs in mounds of decaying vegetation and sand","Lives only in mangroves and feeds entirely on crabs at night"],"answer":2,"explanation":"Megapodes bury their eggs in large mounds where the heat of decomposition (or of the sun) incubates them, and the chicks dig themselves out able to fend for themselves.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-726","question":"Which of the following Indian wetlands are on the Montreux Record of the Ramsar Convention? 1. Keoladeo National Park 2. Loktak Lake 3. Chilika Lake 4. Wular Lake. Select the correct answer using the code given below.","options":["1 and 2 only","1, 2 and 3 only","2 and 4 only","1, 3 and 4 only"],"answer":0,"explanation":"Keoladeo (since 1990) and Loktak (since 1993) remain on the Montreux Record of sites with adverse ecological change. Chilika was added in 1993 but removed in 2002 after the reopening of its sea mouth restored it, a common trap.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-727","question":"By area, the largest Ramsar site in India is:","options":["Chilika Lake in Odisha","Vembanad–Kol wetland in Kerala","The Sundarbans in West Bengal","Wular Lake in Jammu and Kashmir"],"answer":2,"explanation":"The Indian Sundarbans, designated in 2019, cover over 4,000 sq km, ahead of Vembanad–Kol (about 1,500 sq km) and Chilika (about 1,165 sq km).","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-728","question":"Consider the following statements about CITES: 1. It is legally binding on the countries that are parties to it. 2. It replaces the national wildlife laws of its parties. 3. Its secretariat, in Geneva, is administered by UNEP. Which of the statements given above are correct?","options":["1 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"CITES binds its parties but does not take the place of national laws; each party must enforce it through its own legislation, which India does through the Wildlife (Protection) Act. The secretariat is in Geneva under UNEP.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-729","question":"In 2020, India hosted the 13th Conference of the Parties to the Convention on Migratory Species (CMS), at which the Great Indian Bustard was added to Appendix I. The venue was:","options":["Hyderabad","Greater Noida","New Delhi","Gandhinagar"],"answer":3,"explanation":"CMS COP-13 met at Gandhinagar in February 2020 and also listed the Asian elephant and Bengal florican in Appendix I. Hyderabad hosted CBD COP-11 (2012) and Greater Noida hosted UNCCD COP-14 (2019).","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-730","question":"The 'Advance Informed Agreement' procedure, under which an importing country must consent before the first transboundary movement of certain living modified organisms meant for release into the environment, is a feature of the:","options":["Cartagena Protocol on Biosafety","Nagoya Protocol on Access and Benefit-sharing","Rotterdam Convention","Basel Convention"],"answer":0,"explanation":"The Cartagena Protocol (2000) to the CBD applies the AIA procedure to LMOs such as GM seeds for planting. Rotterdam uses a similar-sounding 'prior informed consent' procedure, but for hazardous chemicals and pesticides.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-731","question":"Hot water discharged from a thermal power plant's condenser into a river harms fish mainly because the warmer water:","options":["Contains more dissolved oxygen, which damages the delicate tissue of fish gills","Dissolves more carbon dioxide, which sharply raises the alkalinity of the river","Holds less dissolved oxygen even as it raises the fish's own demand for oxygen","Becomes denser, so fish must spend more energy to stay at their usual depth"],"answer":2,"explanation":"Gas solubility falls as temperature rises, while a cold-blooded fish's metabolism, and so its oxygen need, rises; the two effects together cause stress and kills. Warm water also holds less CO2, not more, and is less dense than cold water.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-732","question":"Which was the first treaty in the history of the United Nations to achieve universal ratification by all member states?","options":["The Ramsar Convention","The Montreal Protocol","The UN Framework Convention on Climate Change","The Convention on Biological Diversity"],"answer":1,"explanation":"In 2009, the Vienna Convention and its Montreal Protocol became the first UN treaties ratified by every country. The CBD is not universal because the United States has not ratified it.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-733","question":"The Multilateral Fund, which pays the extra costs incurred by developing countries in phasing out ozone-depleting substances, was set up by:","options":["The Vienna Convention itself when it was adopted in 1985","The Kigali Amendment to the Montreal Protocol in 2016","The London Amendment to the Montreal Protocol in 1990","The Global Environment Facility at its launch in 1991"],"answer":2,"explanation":"The London Amendment created the Multilateral Fund for the Implementation of the Montreal Protocol, run by an executive committee with secretariat in Montreal. The GEF is a separate mechanism, and the Vienna Convention set no binding controls.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-734","question":"Under the UN Framework Convention on Climate Change, the parties listed in Annex II are:","options":["All developing countries, which are entitled to receive finance and technology","The economies in transition of eastern Europe, such as Russia and Ukraine","The small island developing states that are most at risk from rising seas","Developed (OECD) countries obliged to provide finance to developing ones"],"answer":3,"explanation":"Annex I includes the developed countries and economies in transition; Annex II is the subset of OECD members of 1992 that must help developing countries with finance and technology. Economies in transition are in Annex I but not Annex II.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-735","question":"Match the convention with the city where its secretariat is located. A. UNFCCC  B. Convention on Biological Diversity  C. Ramsar Convention  D. CITES; 1. Montreal  2. Gland  3. Geneva  4. Bonn","options":["A-4, B-1, C-2, D-3","A-4, B-2, C-1, D-3","A-1, B-4, C-2, D-3","A-4, B-1, C-3, D-2"],"answer":0,"explanation":"The UNFCCC (with UNCCD and CMS) is in Bonn, the CBD in Montreal, the Ramsar secretariat at Gland, Switzerland, alongside IUCN, and CITES in Geneva. Montreal is also home to the Montreal Protocol's Multilateral Fund, not its ozone secretariat (Nairobi).","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-736","question":"Consider the following statements about the Kyoto Protocol: 1. The United States signed it but never ratified it. 2. Canada withdrew from it during the first commitment period. 3. India accepted binding emission-reduction targets under it. Which of the statements given above are correct?","options":["1 only","2 and 3 only","1 and 3 only","1 and 2 only"],"answer":3,"explanation":"The USA signed in 1998 but never ratified, and Canada announced its withdrawal in 2011. Developing countries such as India had no binding targets; they could host CDM projects instead.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-737","question":"The Paris Agreement could enter into force only after it had been ratified by at least:","options":["55 parties accounting for at least 55 per cent of global emissions","All of the developed-country parties listed in Annex I of the UNFCCC","Two-thirds of all UN member states, regardless of their share of emissions","100 parties together accounting for at least 75 per cent of global emissions"],"answer":0,"explanation":"The 'double threshold' of 55 parties and 55 per cent of emissions was crossed in October 2016, and the agreement entered into force on 4 November 2016, much faster than Kyoto, which took until 2005.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-738","question":"The 'Ban Amendment' to the Basel Convention, which entered into force in 2019, prohibits:","options":["All international trade in hazardous wastes between any two countries","Exports of hazardous wastes from OECD and EU countries to other countries","Imports of plastic waste of any kind into any developing country","Dumping of hazardous wastes at sea by ships of any party"],"answer":1,"explanation":"The Ban Amendment bars Annex VII parties (OECD members, the EU and Liechtenstein) from exporting hazardous wastes for any purpose to non-Annex VII countries. Trade among other countries remains under the prior informed consent rules, and dumping at sea is covered by the London Convention.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-739","question":"The 2019 amendments to the Basel Convention on plastic waste mean that:","options":["All production of single-use plastic items is banned in every party to the convention","Plastic waste can no longer be recycled in any country other than the one producing it","Exports of most mixed or contaminated plastic waste need importers' prior consent","Developed countries must pay a fixed levy for every tonne of plastic waste they export"],"answer":2,"explanation":"From 2021, hard-to-recycle or contaminated plastic waste was brought under the Basel prior informed consent procedure, giving importing countries the right to refuse it. Clean, sorted plastic for recycling largely remains outside it.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-740","question":"Consider the following statements: 1. The Basel, Rotterdam and Stockholm Conventions share a joint secretariat. 2. The secretariat of the Rotterdam Convention is provided jointly by UNEP and the FAO. 3. The Minamata Convention on mercury is serviced by the same joint secretariat. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Since 2012 the BRS conventions have shared one secretariat under UNEP, with FAO co-hosting the Rotterdam part because it covers pesticides. The Minamata Convention has its own separate secretariat, though it is also in Geneva.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-741","question":"Under the Stockholm Convention, dioxins and furans are listed in Annex C. This means that parties must:","options":["Eliminate their deliberate production and use within five years of listing","Restrict their use to disease-vector control only, as is done for DDT","Report all exports to the secretariat under the prior informed consent procedure","Cut their unintentional release, as from open burning and industrial processes"],"answer":3,"explanation":"Annex A covers chemicals to be eliminated, Annex B those to be restricted (such as DDT), and Annex C by-products formed unintentionally, such as dioxins and furans from open burning and incineration, whose releases must be minimised.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-742","question":"At COP-14 of the UN Convention to Combat Desertification in 2019, India announced a target to restore degraded land by 2030 of:","options":["5 million hectares","13 million hectares","21 million hectares","26 million hectares"],"answer":3,"explanation":"India raised its target from 21 to 26 million hectares of degraded land to be restored by 2030, as part of its goal of land degradation neutrality, which it also links to the Bonn Challenge.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-743","question":"The Intergovernmental Science-Policy Platform on Biodiversity and Ecosystem Services (IPBES), set up in 2012, is best described as:","options":["A binding protocol under the CBD that sets each country's national biodiversity targets","The body that compiles and maintains the IUCN Red List of threatened species worldwide","A fund that pays developing countries for protecting and restoring their tropical forests","A body that assesses biodiversity science for policymakers, much as the IPCC does for climate"],"answer":3,"explanation":"IPBES produces assessments such as its 2019 Global Assessment, which warned that about a million species face extinction. It sets no targets and holds no funds; the Red List is compiled by IUCN.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-744","question":"The UN Conference on Sustainable Development (Rio+20) held in 2012 is best known for its outcome document 'The Future We Want', which:","options":["Launched the process to develop the Sustainable Development Goals","Adopted the Kyoto Protocol's second commitment period","Created the UN Environment Programme in Nairobi","Opened the Convention on Biological Diversity for signature"],"answer":0,"explanation":"Rio+20 agreed to set up a process for SDGs, adopted in 2015, and to strengthen UNEP. UNEP itself dates from 1972, the CBD from Rio 1992, and the second Kyoto period from Doha in 2012.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-745","question":"The 2030 Agenda for Sustainable Development, adopted by the UN General Assembly in 2015, contains:","options":["8 goals and 21 targets","17 goals and 169 targets","17 goals and 232 targets","15 goals and 169 targets"],"answer":1,"explanation":"The SDGs comprise 17 goals with 169 targets, tracked by a set of indicators numbering over 230. The Millennium Development Goals they replaced had 8 goals and 21 targets.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-746","question":"The international treaty that regulates the dumping of wastes and other matter at sea from ships and aircraft is the:","options":["MARPOL Convention of 1973","Basel Convention of 1989","London Convention of 1972","Ramsar Convention of 1971"],"answer":2,"explanation":"The London Convention (and its 1996 Protocol), under the IMO, controls deliberate dumping at sea. MARPOL deals with pollution arising from the normal operation of ships, such as oil and sewage discharges.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-747","question":"The 'High Seas Treaty' (BBNJ Agreement), adopted in 2023 under the UN Convention on the Law of the Sea, deals with:","options":["Marine biodiversity in areas beyond national jurisdiction","Fishing quotas inside the exclusive economic zones of coastal states","Disputes over seabed mining in territorial waters","Shipping lanes and freedom of navigation through straits"],"answer":0,"explanation":"The agreement covers the high seas and international seabed, about two-thirds of the ocean, providing for marine protected areas there, environmental impact assessments and sharing of benefits from marine genetic resources.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-748","question":"In 2022, the UN Environment Assembly resolved to negotiate a legally binding international instrument on plastic pollution. Which statement about it is correct?","options":["It applies only to plastic floating in the open ocean beyond national waters","It was adopted as an amendment to the Stockholm Convention on persistent pollutants","It addresses the full life cycle of plastic, from production and design to disposal","It sets a target to end all plastic production worldwide by the year 2030"],"answer":2,"explanation":"Resolution 5/14 at UNEA-5.2 in Nairobi mandated an intergovernmental negotiating committee for a treaty covering the full life cycle of plastics, including in the marine environment. It is a new instrument, not an amendment to an existing convention.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-749","question":"Which one of the following countries is NOT a party to the Convention on Biological Diversity?","options":["Australia","United States","Indonesia","Argentina"],"answer":1,"explanation":"The USA signed the CBD in 1993 but the Senate has not ratified it, so it is one of the very few non-parties. Australia, Indonesia and Argentina, like almost every other country, are parties.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-750","question":"World Wetlands Day is observed on 2 February each year because that date marks:","options":["The entry into force of the Ramsar Convention in 1975","The adoption of the Ramsar Convention in 1971","The designation of the first Ramsar site in India","The founding of the IUCN in Switzerland in 1948"],"answer":1,"explanation":"The Convention on Wetlands was signed at Ramsar, Iran, on 2 February 1971; it entered into force in 1975. India's first Ramsar sites, Chilika and Keoladeo, were designated in 1981.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-751","question":"The current IUCN Red List system (version 3.1) places every species into one of how many categories, from 'Extinct' to 'Not Evaluated'?","options":["Seven","Eight","Nine","Eleven"],"answer":2,"explanation":"The nine categories are Extinct, Extinct in the Wild, Critically Endangered, Endangered, Vulnerable, Near Threatened, Least Concern, Data Deficient and Not Evaluated.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-752","question":"Match the IUCN Red List criterion with what it is based on. A. Criterion A  B. Criterion B  C. Criterion D  D. Criterion E; 1. Quantitative analysis of the probability of extinction  2. Reduction in population size  3. Very small or restricted population  4. Geographic range, with fragmentation, decline or fluctuation","options":["A-2, B-4, C-1, D-3","A-4, B-2, C-3, D-1","A-2, B-3, C-4, D-1","A-2, B-4, C-3, D-1"],"answer":3,"explanation":"A is population reduction, B geographic range, C small population with decline, D very small or restricted population, and E a quantitative extinction-probability analysis. A species needs to meet only one criterion to be listed.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-753","question":"Under criterion E of the IUCN Red List, a species qualifies as Critically Endangered if quantitative analysis shows a probability of extinction in the wild of at least:","options":["20 per cent within 20 years or five generations","50 per cent within 10 years or three generations","10 per cent within 100 years","90 per cent within 50 years or ten generations"],"answer":1,"explanation":"The CR threshold is ≥50% in 10 years or 3 generations. A 20% chance in 20 years or 5 generations corresponds to Endangered, and 10% in 100 years to Vulnerable.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-754","question":"Under criterion D of the IUCN Red List, a species whose entire wild population numbers more than 50 but fewer than 250 mature individuals qualifies as:","options":["Critically Endangered","Endangered","Vulnerable","Near Threatened"],"answer":1,"explanation":"For criterion D the thresholds are fewer than 50 mature individuals for CR, fewer than 250 for EN and fewer than 1,000 for VU. Counting juveniles as well is a common error.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-755","question":"A bird has not been reliably recorded for several decades, but surveys of its remote range have not been thorough enough to rule out its survival. On the IUCN Red List it would normally appear as:","options":["Extinct, since decades have passed without a record","Data Deficient, until further surveys are done","Critically Endangered (Possibly Extinct)","Near Threatened, pending new survey results"],"answer":2,"explanation":"IUCN lists a species as Extinct only when there is no reasonable doubt the last individual has died. Until then such a species stays CR with a 'Possibly Extinct' tag; Data Deficient is for species too poorly known to assess.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-756","question":"In national or regional Red Lists prepared using IUCN guidelines, an additional category is used for a species that has disappeared from that region but survives elsewhere. This category is:","options":["Regionally Extinct","Extinct in the Wild","Locally Endangered","Not Applicable"],"answer":0,"explanation":"Regionally Extinct (RE) covers species lost from the assessed region only, such as the cheetah in India before its reintroduction. Extinct in the Wild applies globally, when a species survives only in captivity.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-757","question":"Which of the following are listed as Critically Endangered on the IUCN Red List? 1. Gharial 2. Hawksbill turtle 3. Greater one-horned rhinoceros 4. Bengal florican. Select the correct answer:","options":["1 and 2 only","1, 2 and 4 only","2, 3 and 4 only","1, 3 and 4 only"],"answer":1,"explanation":"The gharial, hawksbill turtle and Bengal florican are all Critically Endangered. The greater one-horned rhinoceros recovered enough to be listed as Vulnerable.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-758","question":"Which one of the following pairs of animal and IUCN Red List status is NOT correctly matched?","options":["Gharial — Critically Endangered","Asian elephant — Endangered","Red panda — Endangered","Snow leopard — Endangered"],"answer":3,"explanation":"The snow leopard was moved from Endangered to Vulnerable in 2017. The gharial is Critically Endangered, and the Asian elephant and red panda are Endangered.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-759","question":"Banana, potato, sugarcane and cassava are usually conserved ex situ as living plants or in tissue culture rather than as seeds in a seed bank. The main reason is that:","options":["Their seeds lose viability within a few days of harvest","They are protected under law and cannot be stored as seeds","They are vegetatively propagated and often seed poorly or not true to type","Their seeds are too large to fit into standard storage packets"],"answer":2,"explanation":"These crops are multiplied by suckers, tubers or cuttings and many varieties set little viable seed, which in any case would not reproduce the variety. They are kept in field gene banks or in vitro.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-760","question":"For long-term storage in base collections, dried orthodox seeds in gene banks such as the National Gene Bank in New Delhi are typically kept at about:","options":["−196 °C","+4 °C","0 °C","−18 °C"],"answer":3,"explanation":"Seeds dried to low moisture are sealed and stored at about −18 °C, where many species stay viable for decades. −196 °C (liquid nitrogen) is used for cryopreservation, and +4 °C only for short-term working collections.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-761","question":"A high-altitude seed vault set up in 2010 by the DRDO with the National Bureau of Plant Genetic Resources, using the natural cold to store seeds without electricity, is located at:","options":["Chang La in Ladakh","Rohtang Pass in Himachal Pradesh","Nathu La in Sikkim","Badrinath in Uttarakhand"],"answer":0,"explanation":"The Chang La facility, at over 5,000 m, stays below freezing year-round, providing low-cost backup storage for India's crop germplasm.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-762","question":"In 1975, India launched the Crocodile Conservation Project with UNDP and FAO support, whose main approach for the gharial was:","options":["Moving all wild gharials permanently into closed zoos and breeding centres","Rearing wild-collected eggs in captivity and releasing the young into rivers","Culling mugger crocodiles that compete with gharials for fish in the rivers","Introducing gharials into large reservoirs behind dams in southern India"],"answer":1,"explanation":"Under 'rear and release', wild eggs were hatched and the young raised past their most vulnerable stage before release, for example into the Chambal. Natural hatchling survival in the wild is very low.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-763","question":"India's first conservation breeding centre for Gyps vultures, set up after the collapse of their populations, is located at:","options":["Rajabhatkhawa, West Bengal","Rani, Assam","Bhopal, Madhya Pradesh","Pinjore, Haryana"],"answer":3,"explanation":"The Jatayu Conservation Breeding Centre at Pinjore, begun in 2001, was the first; centres in West Bengal, Assam and Madhya Pradesh followed. Captive breeding paired with the veterinary diclofenac ban is meant to restore wild flocks.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-764","question":"The Great Banyan, a single tree whose aerial roots make it look like a small forest, stands in the:","options":["Lloyd Botanical Garden, Darjeeling","Lalbagh Botanical Garden, Bengaluru","Acharya Jagadish Chandra Bose Indian Botanic Garden, Howrah","National Botanical Research Institute garden, Lucknow"],"answer":2,"explanation":"The Great Banyan at Shibpur, Howrah, is the garden's best-known feature. Botanical gardens are a key ex situ method, holding living plant collections.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-765","question":"The Central Zoo Authority, which recognises and regulates zoos in India, was set up in 1992 under:","options":["The Environment (Protection) Act, 1986","The Biological Diversity Act, 2002","The Wildlife (Protection) Act, 1972","The Prevention of Cruelty to Animals Act, 1960"],"answer":2,"explanation":"A 1991 amendment to the Wildlife (Protection) Act provided for the Central Zoo Authority, constituted in 1992. No zoo may operate without its recognition.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-766","question":"India's first gene sanctuary, created to conserve wild citrus species in their natural habitat, is in the:","options":["Nilgiri Hills of Tamil Nadu","Kumaon Hills of Uttarakhand","Garo Hills of Meghalaya","Aravalli Hills of Rajasthan"],"answer":2,"explanation":"The citrus gene sanctuary in the Garo Hills (Nokrek area) protects wild relatives such as Citrus indica, an in situ way of preserving crop genetic diversity.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-767","question":"Under IUCN guidelines, releasing individuals of a species into an area where a population of that species already exists, to increase its numbers or genetic diversity, is called:","options":["Reintroduction","Assisted colonisation","Ecological replacement","Reinforcement"],"answer":3,"explanation":"Reinforcement (supplementation) adds to an existing population. Reintroduction returns a species to part of its former range where it has died out, and assisted colonisation moves it outside its native range.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-768","question":"The IUCN Red List of Threatened Species was first established in:","options":["1948","1964","1972","1992"],"answer":1,"explanation":"The Red List began in 1964. IUCN itself was founded in 1948, the Stockholm Conference was held in 1972 and the CBD opened for signature in 1992.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-769","question":"Assertion (A): Ex situ conservation in zoos and gene banks cannot by itself secure the long-term future of most species. Reason (R): Captive populations are usually small and isolated from natural selection in the wild, so they lose genetic diversity and adaptive behaviour. Choose the correct option:","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Ex situ methods are a back-up; species keep evolving with their habitats only in situ. Small captive populations suffer inbreeding and drift and can lose skills such as foraging and predator avoidance.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-770","question":"Which of the following are methods of in situ conservation? 1. On-farm conservation of traditional landraces by farmers 2. A gene sanctuary for wild relatives of crops 3. A field gene bank of mango varieties at a research station 4. A sacred grove protected by a village community. Select the correct answer:","options":["1, 2 and 4 only","2 and 4 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":0,"explanation":"On-farm conservation keeps landraces evolving in the farming systems where they arose, so it counts as in situ. A field gene bank grows plants away from their native setting and is ex situ.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-771","question":"Under the IUCN Red List, a species is classified as 'Extinct' when:","options":["No individual has been seen in the wild for at least ten years","Its population has fallen by more than 90 per cent in three generations","Its last wild population is confined to a single protected area","There is no reasonable doubt that the last individual has died"],"answer":3,"explanation":"Extinct requires exhaustive surveys over the species' range and time that fail to find any individual. A fixed number of years without sightings is not enough, and a 90% fall can at most qualify a species as Critically Endangered.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-772","question":"The IUCN Green Status of Species, launched in 2021, complements the Red List by measuring:","options":["The trade volume of a species under CITES permits","How far a species' populations have recovered across its historical range","The carbon stored in the habitats of a threatened species","The share of a species' range that lies inside protected areas"],"answer":1,"explanation":"While the Red List measures extinction risk, the Green Status scores how close a species is to full ecological recovery and what conservation has achieved or could achieve.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-773","question":"The Millennium Seed Bank, one of the largest ex situ collections of wild plant seeds in the world, is run by:","options":["The Royal Botanic Gardens, Kew, at Wakehurst in England","The Norwegian government on the island of Spitsbergen","The Food and Agriculture Organization at its headquarters in Rome","The International Rice Research Institute in the Philippines"],"answer":0,"explanation":"Kew's Millennium Seed Bank focuses on wild species. The Svalbard vault on Spitsbergen is a back-up store for duplicate crop seed from gene banks, and IRRI holds rice germplasm.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-774","question":"Semen, embryos and other genetic material of indigenous livestock breeds are conserved ex situ in India by the:","options":["National Bureau of Plant Genetic Resources, New Delhi","National Dairy Development Board, Anand","National Bureau of Animal Genetic Resources, Karnal","Indian Veterinary Research Institute, Izatnagar"],"answer":2,"explanation":"NBAGR at Karnal characterises, documents and cryopreserves livestock germplasm. NBPGR does the equivalent for crop plants.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-775","question":"In the Red Data Book, the pink pages and the green pages traditionally list, respectively:","options":["Critically endangered species; once-endangered species now recovered","Endemic species of islands; widespread species of the continents","Species threatened by trade; species threatened by loss of habitat","Threatened plant species; threatened animal species of the same region"],"answer":0,"explanation":"Pink pages highlight critically endangered species at high risk, while green pages record species that were once endangered but have recovered to the point of no longer being threatened.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-776","question":"A person aggrieved by an award or order of the National Green Tribunal can appeal against it:","options":["To the High Court of the state concerned, within 30 days","To the Supreme Court, within 90 days of the order being communicated","To the Union Ministry of Environment, within 60 days","To a larger bench of the NGT only, as no further appeal lies"],"answer":1,"explanation":"Section 22 of the NGT Act, 2010 provides an appeal to the Supreme Court within 90 days. High Courts have no appellate role over the NGT, which is why the Act is said to reduce delays in environmental cases.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-777","question":"The National Green Tribunal hears civil cases arising under the Acts listed in Schedule I of the NGT Act, 2010. Which one of the following Acts is NOT in that Schedule?","options":["The Biological Diversity Act, 2002","The Wild Life (Protection) Act, 1972","The Public Liability Insurance Act, 1991","The Forest (Conservation) Act, 1980"],"answer":1,"explanation":"Schedule I lists seven Acts: the Water Act, Water Cess Act, Forest (Conservation) Act, Air Act, Environment (Protection) Act, Public Liability Insurance Act and Biological Diversity Act. The Wild Life (Protection) Act and the Indian Forest Act are not included.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-778","question":"The National Green Tribunal has its principal bench at New Delhi. Which one of the following cities is NOT a seat of one of its zonal benches?","options":["Pune","Bhopal","Hyderabad","Kolkata"],"answer":2,"explanation":"The four zonal benches are at Bhopal (central), Pune (western), Kolkata (eastern) and Chennai (southern). Hyderabad has no NGT bench; southern cases go to Chennai.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-779","question":"Consider the following statements: 1. The definition of 'environment' in the Environment (Protection) Act, 1986 includes property. 2. The Air (Prevention and Control of Pollution) Act was amended in 1987 to include noise within the meaning of 'air pollutant'. 3. Under the Environment (Protection) Act, only state governments can set standards for emission of pollutants. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Section 2(a) of the EP Act covers water, air and land and their interrelationship with human beings, other living creatures, plants, micro-organisms and property; the 1987 Air Act amendment added noise. Standard-setting under Section 3 rests with the Central Government.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-780","question":"Consider the following statements: 1. The Water (Prevention and Control of Pollution) Act, 1974 was enacted by Parliament under Article 252, after the legislatures of several states passed resolutions. 2. The Air (Prevention and Control of Pollution) Act, 1981 was enacted under Article 253 to implement decisions of the Stockholm Conference. Which of the statements given above is/are correct?","options":["1 only","2 only","Neither 1 nor 2","Both 1 and 2"],"answer":3,"explanation":"Water is a state subject, so Parliament legislated under Article 252 on the request of state legislatures, and other states adopted the Act later. The Air Act, like the EP Act, rests on Article 253, which lets Parliament implement international agreements.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-781","question":"Consider the following statements about the Water (Prevention and Control of Pollution) Cess Act, 1977: 1. It levied a cess on water consumed by specified industries and local authorities. 2. Its proceeds were meant to augment the resources of the pollution control boards. 3. It was repealed in 2017 when the Goods and Services Tax was introduced. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"The cess, with rebates for installing treatment plants, funded the central and state boards. It was among the levies subsumed with the introduction of GST and was repealed by the Taxation Laws (Amendment) Act, 2017.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-782","question":"Consider the following statements about the Wild Life (Protection) Amendment Act, 2022: 1. It reduced the number of schedules in the Act from six to four. 2. It removed the separate schedule listing vermin species. 3. It took away the power of the Central Government to declare any wild animal as vermin. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"After 2022 the schedules are: I and II for animals with different levels of protection, III for plants and IV for CITES-listed specimens; the vermin schedule went. But Section 62 still lets the Centre notify an animal as vermin for an area and period.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-783","question":"Under the Forest (Conservation) Act, 1980, which of the following uses of forest land counts as a 'non-forest purpose', requiring prior approval of the Central Government?","options":["Laying fire lines to protect the forest from fires","Building check-posts and wireless stations for forest staff","Planting rubber, oil palm or tea on cleared forest land","Fencing a plantation of native trees inside the forest"],"answer":2,"explanation":"The Act's explanation expressly treats cultivation of tea, coffee, spices, rubber, palms, oil-bearing plants, horticultural crops and medicinal plants as non-forest purposes. Works for conservation and management of forests, such as fire lines, check-posts and fencing, are excluded.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-784","question":"The 2023 amendment to the Forest (Conservation) Act, 1980 exempts from its approval requirement, among other things, forest land needed for strategic linear projects of national importance located within:","options":["100 km of India's international borders, the LoC or the Line of Actual Control","10 km on either side of any national highway or railway line through the forest","50 km of the coastline, for new ports, jetties and coastal security roads","25 km of the boundary of any protected area, for its patrolling roads"],"answer":0,"explanation":"The amendment exempts land within 100 km of the borders, LoC or LAC for strategic linear projects, and up to 10 hectares for security-related infrastructure, among other exemptions; critics argued these could fragment border forests in the north-east and Himalaya.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-785","question":"When forest land is diverted for a project, compensatory afforestation is normally to be carried out on:","options":["An equal area of degraded forest land, anywhere in the country","Equal non-forest land or, failing that, twice the area of degraded forest land","Non-forest land five times the area diverted, within the same district","Any land at all, of an area decided freely by the user agency itself"],"answer":1,"explanation":"The rules require equivalent non-forest land, or double the area on degraded forest land where non-forest land is not available. The user agency also pays the net present value of the forest lost into the CAMPA fund.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-786","question":"Under the Coastal Regulation Zone Notification, 2019, in densely populated rural coastal areas classified as CRZ-III A, the 'No Development Zone' extends from the high tide line up to:","options":["500 metres","200 metres","100 metres","50 metres"],"answer":3,"explanation":"The 2019 notification cut the NDZ to 50 m in CRZ-III A areas, those with a population density above 2,161 per sq km in the 2011 census. In less densely populated CRZ-III B areas the NDZ remains 200 m; 500 m is the outer limit of the CRZ on the sea front.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-787","question":"Under the Forest Rights Act, 2006, recognition of an individual's right to forest land under occupation for habitation or self-cultivation is subject to which of the following limits?","options":["Only land under actual occupation, and not more than 4 hectares","Any area the claimant names, subject only to approval by the Gram Sabha","Not more than 1 hectare, irrespective of the area actually occupied","Not more than 10 hectares, provided the land was cultivated after 2010"],"answer":0,"explanation":"Rights are limited to the area actually occupied, with a ceiling of 4 hectares, and the land must have been occupied before the cut-off date of 13 December 2005. The Gram Sabha starts the process, but committees at sub-division and district level decide.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-788","question":"The Panchayats (Extension to the Scheduled Areas) Act, 1996 (PESA) gives Gram Sabhas and panchayats in Scheduled Areas:","options":["Ownership of minor forest produce","Power to grant environmental clearance to mining projects","Power to notify national parks and sanctuaries","Ownership of all reserved forests in the area"],"answer":0,"explanation":"PESA vests ownership of minor forest produce in panchayats at the appropriate level and requires consultation with Gram Sabhas before land acquisition. Clearances and notification of protected areas remain with governments; reserved forests stay state property.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-789","question":"Arrange the following in chronological order: 1. Creation of the Department of Environment in the Government of India 2. Creation of the Ministry of Environment and Forests 3. Enactment of the Environment (Protection) Act 4. Setting up of the National Green Tribunal","options":["2-1-3-4","1-3-2-4","1-2-3-4","2-3-1-4"],"answer":2,"explanation":"The Department of Environment came in 1980, the Ministry of Environment and Forests in 1985, the EP Act in 1986 and the NGT in 2010. 'Climate Change' was added to the Ministry's name in 2014.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-790","question":"Consider the following statements about the National Board for Wildlife: 1. It is a statutory body constituted under the Wild Life (Protection) Act, 1972. 2. It is chaired by the Prime Minister. 3. Its Standing Committee, which examines projects in and around protected areas, is chaired by the Union Minister for Environment. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Section 5A, added in 2002, creates the NBWL under the Prime Minister. In practice most project clearances in protected areas and eco-sensitive zones are given by its Standing Committee, headed by the Environment Minister as vice-chairperson.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-791","question":"The Animal Welfare Board of India is a statutory advisory body established under:","options":["The Wild Life (Protection) Act, 1972","The Environment (Protection) Act, 1986","The Societies Registration Act, 1860","The Prevention of Cruelty to Animals Act, 1960"],"answer":3,"explanation":"AWBI was set up in 1962 under Section 4 of the PCA Act, 1960, and advises on animal welfare laws, a role prominent in matters such as jallikattu. The WPA deals with wild animals and their habitats.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-792","question":"In 2010, the Government of India declared which animal as the 'National Heritage Animal'?","options":["Asian elephant","Bengal tiger","Ganges river dolphin","Great one-horned rhinoceros"],"answer":0,"explanation":"The elephant was declared National Heritage Animal in 2010 on the recommendation of an elephant task force. The tiger is the National Animal, and the Ganges river dolphin the National Aquatic Animal.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-793","question":"The 'polluter pays' principle was applied by the Supreme Court to make chemical units pay for remedying soil and groundwater contamination by sludge at Bichhri village, Rajasthan, in:","options":["M.C. Mehta v. Union of India (oleum gas leak case)","Vellore Citizens' Welfare Forum v. Union of India","Indian Council for Enviro-Legal Action v. Union of India","Rural Litigation and Entitlement Kendra v. State of U.P."],"answer":2,"explanation":"In Indian Council for Enviro-Legal Action (1996), units making H-acid were held absolutely liable to pay for remediation of Bichhri. Vellore Citizens' (1996) later declared polluter pays and precaution part of Indian law, and the oleum case set absolute liability.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-794","question":"The case of Rural Litigation and Entitlement Kendra v. State of Uttar Pradesh, decided in the mid-1980s, is known for the Supreme Court's order to:","options":["Shift tanneries away from the Ganga at Kanpur","Close limestone quarries in the Doon Valley because of ecological damage","Convert Delhi's public transport fleet to compressed natural gas","Relocate industries away from the Taj Mahal"],"answer":1,"explanation":"Acting on a letter treated as a writ petition, the Court ordered the closure of most limestone quarries in the Dehradun valley, one of the earliest cases balancing development and ecology. The other orders came in M.C. Mehta's separate cases.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-795","question":"In the Niyamgiri case (2013) concerning bauxite mining in Odisha, the Supreme Court directed that:","options":["Mining should go ahead, with compensation paid to affected tribal families","The Central Government alone should decide, as the hills were reserved forest","The National Green Tribunal should hear the matter afresh within six months","The Gram Sabhas of the area should decide whether the project affected their rights"],"answer":3,"explanation":"Relying on the Forest Rights Act, the Court held that the Dongria Kondh Gram Sabhas must decide whether mining would affect their religious and cultural rights; all the Gram Sabhas consulted rejected the project.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-796","question":"The National Green Tribunal, set up in 2010, replaced which earlier body that heard appeals against environmental clearances?","options":["The National Environment Appellate Authority","The Central Empowered Committee","The Environment Pollution (Prevention and Control) Authority","The Central Pollution Control Board's appellate wing"],"answer":0,"explanation":"The NGT Act repealed the National Environment Appellate Authority Act, 1997. The Central Empowered Committee is a Supreme Court-appointed body on forest matters, and EPCA was a Delhi-NCR pollution authority later replaced by CAQM.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-797","question":"The 'Ecomark' scheme, launched in India in 1991 to label environment-friendly consumer products, is administered by:","options":["The Central Pollution Control Board","The Bureau of Energy Efficiency","The Bureau of Indian Standards","The Indian Council of Agricultural Research"],"answer":2,"explanation":"Ecomark products must meet BIS quality standards plus environmental criteria; the label is an earthen pot. BEE runs the separate star-labelling programme for energy efficiency.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-798","question":"'Urban forestry, protection of the environment and promotion of ecological aspects' is listed as a function of municipalities in the:","options":["Seventh Schedule","Eleventh Schedule","Tenth Schedule","Twelfth Schedule"],"answer":3,"explanation":"The Twelfth Schedule (Article 243W), added by the 74th Amendment, lists it for municipalities. The Eleventh Schedule for panchayats lists social forestry, farm forestry and minor forest produce instead.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-799","question":"Where an eco-sensitive zone has not yet been notified around a national park or sanctuary, the Supreme Court and Central guidelines have applied a default buffer of:","options":["1 km from the boundary","5 km from the boundary","10 km from the boundary","25 km from the boundary"],"answer":2,"explanation":"Following a National Board for Wildlife decision of 2002 and the Goa Foundation case, a 10 km belt was treated as the ESZ until site-specific zones were notified under the EP Act. Notified zones can be narrower or wider depending on the site.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-800","question":"India's Ozone Depleting Substances (Regulation and Control) Rules, 2000, which give effect to the Montreal Protocol, were framed under:","options":["The Air (Prevention and Control of Pollution) Act, 1981","The Environment (Protection) Act, 1986","The Factories Act, 1948","The Insecticides Act, 1968"],"answer":1,"explanation":"Most environmental rules in India, including those on ODS, hazardous waste, plastic and e-waste, are framed under the umbrella EP Act, 1986. They regulate production, trade and use of CFCs, halons and HCFCs.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-801","question":"Consider the following statements about conservation reserves and community reserves: 1. Both categories were added to the Wildlife (Protection) Act, 1972 by an amendment in 2002. 2. A community reserve may be declared on community or private land where the community or individual has volunteered to conserve wildlife. 3. A conservation reserve is declared on land owned by the State Government, especially land adjacent to national parks and sanctuaries or linking them. How many of the statements given above are correct?","options":["Only one","Only two","All three","None"],"answer":2,"explanation":"All three are correct. These categories, from the 2002 amendment, give communities and governments flexible ways to protect corridors and landscapes outside national parks and sanctuaries.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-802","question":"India's first marine national park, declared in the early 1980s to protect coral reefs and mangroves off Jamnagar, is in the:","options":["Gulf of Mannar, Tamil Nadu","Wandoor area, South Andaman","Malvan coast, Maharashtra","Gulf of Kutch, Gujarat"],"answer":3,"explanation":"The Marine National Park in the Gulf of Kutch was the first. The Mahatma Gandhi Marine National Park at Wandoor came in 1983 and the Gulf of Mannar Marine National Park in 1986.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-803","question":"The first marine biosphere reserve in South and South-East Asia, set up in 1989, is the:","options":["Great Nicobar Biosphere Reserve","Sundarbans Biosphere Reserve","Gulf of Mannar Biosphere Reserve","Agasthyamala Biosphere Reserve"],"answer":2,"explanation":"The Gulf of Mannar reserve, between India and Sri Lanka, protects coral islands, seagrass beds and the dugong. The Sundarbans reserve centres on mangroves rather than open sea.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-804","question":"Which one of the following Indian biosphere reserves has been included in UNESCO's World Network of Biosphere Reserves?","options":["Manas","Panna","Kachchh","Cold Desert"],"answer":1,"explanation":"Panna was added to the world network in 2020, joining eleven other Indian reserves such as Nilgiri and Sundarbans. Manas, Kachchh and Cold Desert are national biosphere reserves not on the UNESCO list.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-805","question":"The largest biosphere reserve in India by area is:","options":["Great Nicobar","Gulf of Mannar","Nilgiri","Kachchh"],"answer":3,"explanation":"The Kachchh Biosphere Reserve, covering much of the Great Rann, exceeds 12,000 km². Nilgiri was the first, not the largest.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-806","question":"Consider the following statements about tiger reserves under the Wildlife (Protection) Act, 1972: 1. A tiger reserve consists of a core or critical tiger habitat and a buffer or peripheral area. 2. The buffer area is meant to promote coexistence between wildlife and human activity, with due recognition of local livelihood rights. 3. A State Government can alter the boundaries of a tiger reserve on its own, without any recommendation from the National Tiger Conservation Authority. Which of the statements given above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Boundaries of a tiger reserve can be altered only in the public interest, on the NTCA's recommendation and with the approval of the National Board for Wildlife, so statement 3 is wrong.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-807","question":"Consider the following statements: 1. Elephant reserves are a legal category of protected area defined in the Wildlife (Protection) Act, 1972. 2. Elephant reserves often include national parks and sanctuaries along with reserved forests and other land. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":1,"explanation":"Elephant reserves are administrative units under Project Elephant, notified by states, not a statutory protected-area category. They span existing protected areas and other forests used by elephants.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-808","question":"The largest surviving population of the Nilgiri tahr is protected in:","options":["Eravikulam National Park, Kerala","Bandipur National Park, Karnataka","Mukurthi National Park, Tamil Nadu","Silent Valley National Park, Kerala"],"answer":0,"explanation":"Eravikulam, on the high grassland plateau near Munnar, holds the largest tahr population. Mukurthi also protects tahr but in smaller numbers; Bandipur lies in lower dry forests.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-809","question":"Hemis National Park, India's largest national park, is best known for protecting the:","options":["Hangul","Red panda","Snow leopard","Asiatic black bear"],"answer":2,"explanation":"Hemis in Ladakh is famous for its snow leopard population, along with bharal and Tibetan wolves. The hangul lives in Dachigam in Kashmir and the red panda in the eastern Himalaya.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-810","question":"Which national park in India is noted as a home to all four large cats of the region: tiger, common leopard, clouded leopard and snow leopard?","options":["Manas","Kaziranga","Namdapha","Dibru-Saikhowa"],"answer":2,"explanation":"Namdapha in Arunachal Pradesh spans altitudes from low tropical forest to high snow-clad peaks, so all four cats occur within it.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-811","question":"The Hornbill Nest Adoption Programme, in which members of the Nyishi community are paid to protect nesting trees, is associated with:","options":["Pakke Tiger Reserve, Arunachal Pradesh","Dampa Tiger Reserve, Mizoram","Nagarhole National Park, Karnataka","Nameri National Park, Assam"],"answer":0,"explanation":"Former hunters now monitor and guard hornbill nests in and around Pakke; the scheme is a well-known model of community-based conservation.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-812","question":"Because of its grasslands, wetlands and dense population of one-horned rhinoceros, which protected area on the north bank of the Brahmaputra is often called a 'mini Kaziranga'?","options":["Dibru-Saikhowa National Park","Rajiv Gandhi Orang National Park","Nameri National Park","Pobitora Wildlife Sanctuary"],"answer":1,"explanation":"Orang has a landscape and fauna much like Kaziranga's on a smaller scale. Pobitora, with the highest rhino density, lies south of the Brahmaputra.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-813","question":"A national park lying largely within the limits of a metropolitan city, known for its leopards and the ancient Kanheri caves, is:","options":["Guindy National Park","Bannerghatta National Park","Sanjay Gandhi National Park","Van Vihar National Park"],"answer":2,"explanation":"Sanjay Gandhi National Park at Borivali, Mumbai, holds a resident leopard population and the Buddhist Kanheri caves. Guindy in Chennai is far smaller and has no caves.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-814","question":"Which of the following protected areas form part of the Nilgiri Biosphere Reserve? 1. Mudumalai 2. Silent Valley 3. Bandipur 4. Periyar. Select the correct answer:","options":["1 and 3 only","1, 2 and 3 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":1,"explanation":"Mudumalai, Bandipur, Nagarhole, Wayanad, Mukurthi and Silent Valley lie in the Nilgiri Biosphere Reserve. Periyar is much further south, in the Cardamom Hills.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-815","question":"The Harike wetland, a Ramsar site that hosts large numbers of wintering waterbirds, was formed by a barrage at the confluence of the:","options":["Ravi and Beas in Punjab","Sutlej and Ghaggar in Haryana","Yamuna and Hindon in Uttar Pradesh","Beas and Sutlej in Punjab"],"answer":3,"explanation":"The Harike headworks stand just below the meeting point of the Beas and Sutlej; the resulting reservoir is one of north India's largest wetlands.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-816","question":"Nalabana Bird Sanctuary, an island that is submerged during the monsoon and hosts huge numbers of wintering birds, lies within:","options":["Kolleru Lake","Pulicat Lake","Chilika Lake","Loktak Lake"],"answer":2,"explanation":"Nalabana lies in the middle of Chilika lagoon in Odisha. Kolleru (Andhra Pradesh), Pulicat (on the Andhra–Tamil Nadu border) and Loktak (Manipur) are other important wetlands.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-817","question":"Point Calimere (Kodiakkarai) Wildlife Sanctuary, a Ramsar site known for flamingos and blackbuck on a coastal plain, is in:","options":["Gujarat","Odisha","Andhra Pradesh","Tamil Nadu"],"answer":3,"explanation":"Point Calimere lies on the Coromandel coast in Nagapattinam district of Tamil Nadu, combining tropical dry evergreen forest, mudflats and salt swamps.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-818","question":"Ranganathittu Bird Sanctuary, a group of islets that hosts colonies of nesting waterbirds, lies on the:","options":["Kaveri river in Karnataka","Godavari river in Andhra Pradesh","Krishna river in Telangana","Mahanadi river in Odisha"],"answer":0,"explanation":"Ranganathittu is on the Kaveri near Srirangapatna, Mysuru district. Its islets host painted storks, open-billed storks, spoonbills and mugger crocodiles.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-819","question":"In 1984, greater one-horned rhinoceroses were reintroduced from Assam and Nepal into which protected area, part of their former range?","options":["Corbett National Park","Valmiki Tiger Reserve","Dudhwa National Park","Jaldapara National Park"],"answer":2,"explanation":"Dudhwa in the Terai of Uttar Pradesh received rhinos in 1984, re-establishing the species where it had been extinct. Jaldapara has a surviving natural rhino population.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-820","question":"Match the tiger reserve with its state. A. Satpura  B. Melghat  C. Buxa  D. Kawal; 1. West Bengal  2. Telangana  3. Madhya Pradesh  4. Maharashtra","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"answer":3,"explanation":"Satpura is in Madhya Pradesh, Melghat in Maharashtra's Amravati district, Buxa in north Bengal and Kawal in Telangana.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-821","question":"Guindy National Park, one of the few national parks located inside a city, is in:","options":["Chennai","Bengaluru","Hyderabad","Kolkata"],"answer":0,"explanation":"Guindy, in Chennai, protects tropical dry evergreen scrub and a population of blackbuck and spotted deer. Bengaluru's Bannerghatta lies on the city's outskirts.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-822","question":"Sathyamangalam Tiger Reserve in Tamil Nadu is ecologically important mainly because it:","options":["Forms a link between the Western Ghats and the Eastern Ghats","Holds the only population of tigers living in mangroves in south India","Protects the largest surviving shola grassland of the Nilgiris","Is the southernmost point of the range of the Asiatic lion"],"answer":0,"explanation":"Sathyamangalam lies where the two ranges meet and connects the Nilgiri landscape with the Eastern Ghats, making it a key corridor for tigers and elephants.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-823","question":"Coringa Wildlife Sanctuary, an important mangrove area in India, lies in the delta of the:","options":["Mahanadi in Odisha","Godavari in Andhra Pradesh","Kaveri in Tamil Nadu","Krishna in Telangana"],"answer":1,"explanation":"Coringa protects the mangroves of the Godavari delta near Kakinada; Bhitarkanika is the corresponding mangrove area in the Brahmani–Baitarani–Mahanadi delta of Odisha.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-824","question":"Campbell Bay National Park and Galathea National Park form core areas of which biosphere reserve?","options":["Great Nicobar","Gulf of Mannar","Sundarbans","Andaman Islands"],"answer":0,"explanation":"Both national parks lie on Great Nicobar island, the southernmost part of India, and form the core of the Great Nicobar Biosphere Reserve, which falls in the Sundaland hotspot.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-825","question":"The golden langur, brought to scientific attention by the naturalist E. P. Gee, has a small natural range in western Assam and Bhutan that is bounded mainly by:","options":["The Teesta, the Mahananda and the Ganga","The Subansiri, the Kameng and the Lohit","The Barak, the Surma and the Kopili","The Sankosh, the Manas and the Brahmaputra"],"answer":3,"explanation":"The langur lives between the Sankosh river in the west, the Manas in the east and the Brahmaputra in the south, with the Bhutan hills to the north; rivers act as barriers that it does not cross.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-826","question":"The wild water buffalo, whose few surviving central Indian herds live in Indravati and Udanti-Sitanadi, is the state animal of:","options":["Odisha","Madhya Pradesh","Chhattisgarh","Jharkhand"],"answer":2,"explanation":"Chhattisgarh adopted the wild buffalo as its state animal. Apart from these small central Indian herds, the main wild populations are in Assam, notably Kaziranga and Manas.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-827","question":"The largest antelope found in Asia is the:","options":["Blackbuck","Chinkara","Four-horned antelope","Nilgai"],"answer":3,"explanation":"The nilgai or blue bull is Asia's largest antelope; its sacred status in many areas lets it thrive near farms, where it is often a crop pest.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-828","question":"The chousingha, found in dry deciduous forests of India and Nepal, is unique among the world's wild bovids because:","options":["Females have larger horns than males","It sheds its horns every year like a deer","Males carry two pairs of horns","It has no horns in either sex"],"answer":2,"explanation":"The chousingha, or four-horned antelope, is the only wild bovid in which males bear two pairs of horns, a short front pair and a longer rear pair. Bovid horns, unlike deer antlers, are not shed.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-829","question":"Consider the following statements about the Himalayan musk deer: 1. Males grow branched antlers that are shed every year. 2. Males have long, tusk-like upper canine teeth. 3. It is poached for a gland whose secretion is used in perfumes and traditional medicines. Which of the statements given above is/are correct?","options":["2 and 3 only","1 and 3 only","3 only","1, 2 and 3"],"answer":0,"explanation":"Musk deer have no antlers at all; males instead carry long upper canines. The musk pod of males is the reason for heavy poaching.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-830","question":"The mithun, regarded as a domesticated form of the gaur and central to the culture of many hill communities, is the state animal of:","options":["Arunachal Pradesh and Nagaland","Meghalaya and Mizoram","Manipur and Tripura","Sikkim and Assam"],"answer":0,"explanation":"The mithun is the state animal of both Arunachal Pradesh and Nagaland, where it is a symbol of wealth and is used in ceremonies.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-831","question":"The clouded leopard, an arboreal cat with the longest canines relative to body size of any living cat, is the state animal of:","options":["Sikkim","Meghalaya","Mizoram","Arunachal Pradesh"],"answer":1,"explanation":"Meghalaya chose the clouded leopard, which lives in its forests. Sikkim's state animal is the red panda, and Arunachal's the mithun.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-832","question":"The Indian giant squirrel (Malabar giant squirrel), known locally as 'shekru' and protected in Bhimashankar Wildlife Sanctuary, is the state animal of:","options":["Kerala","Karnataka","Goa","Maharashtra"],"answer":3,"explanation":"Maharashtra adopted the shekru as its state animal; Bhimashankar was created largely to protect it. It is an important seed predator and disperser in the canopy.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-833","question":"The only species of marten endemic to southern India, found in the evergreen forests of the Western Ghats, is the:","options":["Yellow-throated marten","Beech marten","Nilgiri marten","Pine marten"],"answer":2,"explanation":"The Nilgiri marten is a Western Ghats endemic. The yellow-throated marten, its closest relative, lives in the Himalaya and north-east, far to the north.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-834","question":"An Endangered pack-hunting canid of Indian forests, known for its whistling calls and for cooperatively hunting prey as large as sambar, is the:","options":["Indian wolf","Golden jackal","Dhole","Indian fox"],"answer":2,"explanation":"The dhole or Asiatic wild dog hunts in packs and communicates with whistles. The Indian wolf lives mainly in open grasslands and scrub, and the golden jackal is a smaller, more solitary opportunist.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-835","question":"The sloth bear can suck termites out of their mounds with great force. An anatomical feature that helps it do this is:","options":["A long, sticky tongue like that of an anteater","Very large, flat molars for grinding","Loss of the inner pair of upper incisors","Webbed claws for digging"],"answer":2,"explanation":"The gap left by the missing upper incisors, together with mobile lips and closable nostrils, lets the bear blow away dust and suck up termites like a vacuum.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-836","question":"India's only population of the Indus river dolphin survives in the:","options":["Beas river in Punjab","Chenab river in Jammu","Sutlej river in Himachal Pradesh","Ghaggar river in Haryana"],"answer":0,"explanation":"A small population lives in the Beas between Talwara and Harike. Most Indus dolphins live in Pakistan; the Ganges dolphin is a separate species found in the Ganga–Brahmaputra system.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-837","question":"The slender loris, a small nocturnal primate with large eyes, is found naturally in:","options":["The Himalayan foothills of Uttarakhand","The hill forests of north-east India","The Andaman and Nicobar Islands","Southern India and Sri Lanka"],"answer":3,"explanation":"The slender loris lives in the forests of peninsular India and Sri Lanka. North-east India has a different species, the Bengal slow loris.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-838","question":"The hispid hare, an Endangered mammal that shares its habitat with the pygmy hog, depends on:","options":["Alpine meadows above the treeline in the western Himalaya","Tall, wet grasslands of the Terai and Duars","Sand dunes of the Thar desert in western Rajasthan","Mangrove forests of the Sundarbans delta"],"answer":1,"explanation":"Both animals live in tall grasslands at the foot of the Himalaya, notably in Manas, and suffer when these grasslands are burnt, cleared or converted to farms.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-839","question":"The pygmy hog-sucking louse is listed as Critically Endangered, though it has never been directly hunted or traded. The reason is that:","options":["It is killed by the same pesticides used on tea plantations in Assam","Its larvae can develop only in clear, fast-flowing mountain streams","It lives only on the pygmy hog, so it shares that host's fate","It is exported in large numbers for laboratory research"],"answer":2,"explanation":"A host-specific parasite cannot outlive its host, so the louse is threatened with co-extinction. Conservation of the pygmy hog is therefore conservation of its parasite too.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-840","question":"Shahtoosh shawls, whose trade is banned in India, are woven from the fine underfur of the:","options":["Pashmina goat","Himalayan ibex","Kashmir stag (hangul)","Tibetan antelope (chiru)"],"answer":3,"explanation":"Shahtoosh comes from the chiru, which must be killed for its wool; in India it occurs in the Changthang of Ladakh. Pashmina, by contrast, is combed from domestic Changthangi goats.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-841","question":"The markhor, a wild goat with spectacular corkscrew horns, is found in India only in:","options":["The Pir Panjal ranges of Jammu and Kashmir","The Changthang plateau of Ladakh","The Kumaon Himalaya of Uttarakhand","The Kinnaur district of Himachal Pradesh"],"answer":0,"explanation":"In India the markhor survives in a small area of the Pir Panjal range around Kazinag and Hirpora; it is more widespread in Pakistan, where it is the national animal.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-842","question":"The bharal, the main prey of the snow leopard in much of the Himalaya, is popularly known as the:","options":["Blue sheep","Barking deer","Mountain goat","Red goral"],"answer":0,"explanation":"Bharal (Pseudois nayaur) are called blue sheep for their slate-grey coat, though in many features they are intermediate between sheep and goats.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-843","question":"The gaur, often wrongly called the 'Indian bison', is noteworthy as:","options":["The ancestor of all humped zebu cattle of India","The largest living species of wild cattle","A native of Africa introduced into India","The only wild ox found in the Thar desert"],"answer":1,"explanation":"The gaur is the largest wild bovine in the world. Zebu cattle descend from the aurochs, not the gaur, though the mithun is considered a domesticated gaur.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-844","question":"In Asian elephants, an adult male that has no tusks is commonly called a:","options":["Musth bull","Tusker","Gunda","Makhna"],"answer":3,"explanation":"Tuskless males are called makhnas; female Asian elephants normally lack tusks or have only small 'tushes'. Musth is a periodic hormonal state of bulls, with or without tusks.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-845","question":"A shaggy, black, tree-dwelling mammal of north-east India with a prehensile tail, sometimes called the 'bearcat' and said to smell like buttered popcorn, is the:","options":["Binturong","Red panda","Slow loris","Hoolock gibbon"],"answer":0,"explanation":"The binturong is a large civet, related neither to bears nor to cats, and one of the few Old World mammals with a prehensile tail. Its musky scent contains the same compound as popcorn.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-846","question":"The red panda, a bamboo-eating mammal of the eastern Himalaya, is the state animal of:","options":["Arunachal Pradesh","Sikkim","Meghalaya","Nagaland"],"answer":1,"explanation":"Sikkim adopted the red panda as its state animal. It is Endangered, threatened by loss of temperate forest with a bamboo understorey.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-847","question":"The blackbuck is the state animal of which group of states?","options":["Rajasthan, Gujarat and Madhya Pradesh","Haryana, Punjab and Andhra Pradesh","Uttar Pradesh, Bihar and Odisha","Karnataka, Tamil Nadu and Kerala"],"answer":1,"explanation":"Punjab, Haryana and Andhra Pradesh all chose the blackbuck. Rajasthan's state animals are the chinkara and the camel, and Gujarat's is the Asiatic lion.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-848","question":"The Indian chevrotain or 'mouse deer', the smallest hoofed mammal of Indian forests, is not a true deer because it:","options":["Is a rodent that only resembles a deer","Belongs to a separate, more primitive family and lacks antlers","Feeds mainly on insects and small vertebrates","Is a marsupial that carries its young in a pouch"],"answer":1,"explanation":"Chevrotains form the family Tragulidae, an ancient lineage of ruminants. They have no antlers, and males have small tusk-like canines.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-849","question":"Pollination of flowers by bats, as in the baobab and several night-blooming trees, is known as:","options":["Ornithophily","Entomophily","Chiropterophily","Anemophily"],"answer":2,"explanation":"Chiropterophily is bat pollination; such flowers are large, pale, strong-smelling and open at night. Ornithophily is pollination by birds and anemophily by wind.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-850","question":"Strategic Environmental Assessment (SEA) differs from project-level Environmental Impact Assessment (EIA) mainly in that SEA:","options":["Is carried out only after a project has been built, to audit its actual impacts","Is applied to policies, plans and programmes, before individual projects are chosen","Covers only social and economic impacts, leaving ecological ones to the EIA","Is a voluntary exercise done by companies for investors, not by governments"],"answer":1,"explanation":"SEA brings environmental concerns into decisions at the level of a sector plan or regional programme, such as a river-basin hydropower plan, where cumulative impacts and alternatives can still be weighed. EIA looks at one project at a time.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-851","question":"Under the EIA Notification, 2006, the public hearing for a project requiring public consultation is conducted by:","options":["The Expert Appraisal Committee of the Union Ministry of Environment","The project proponent, through a consultant accredited by the Ministry","The State Pollution Control Board or the UT Pollution Control Committee","The Gram Sabha of the village in which the project is to be located"],"answer":2,"explanation":"The SPCB or UTPCC organises the hearing, chaired by the District Magistrate or an officer not below Additional District Magistrate, and forwards the proceedings to the regulatory authority. The EAC appraises the project afterwards.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-852","question":"Under India's Coastal Regulation Zone notifications, the zone classified as CRZ-IV covers:","options":["Ecologically sensitive areas such as mangroves, coral reefs and turtle nesting beaches","Developed urban areas that are already substantially built up up to the shoreline","Rural and relatively undisturbed coastal land, including fishing villages","The water area from the low tide line up to 12 nautical miles, and tidal water bodies"],"answer":3,"explanation":"CRZ-I is ecologically sensitive areas, CRZ-II developed urban areas and CRZ-III relatively undisturbed rural areas. CRZ-IV regulates activities in the sea up to the territorial limit of 12 nautical miles and in tidal creeks, rivers and backwaters.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-853","question":"Consider the following statements about the National Clean Air Programme (NCAP): 1. It was launched in 2019. 2. Its targets for reducing particulate matter concentrations were set against 2017 as the base year. 3. It is a statutory programme under the Air Act, so its city targets are legally binding. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"NCAP, launched by the Environment Ministry in January 2019 for non-attainment cities, set an initial target of a 20–30 per cent cut in PM concentrations by 2024 from 2017 levels. It is a national programme without statutory backing, a point often criticised.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-854","question":"The Central Ground Water Authority, which regulates groundwater extraction by industries and infrastructure projects, was constituted under:","options":["The Water (Prevention and Control of Pollution) Act, 1974","The River Boards Act, 1956","The Environment (Protection) Act, 1986","The Inter-State River Water Disputes Act, 1956"],"answer":2,"explanation":"CGWA was set up in 1997 under Section 3(3) of the EP Act on the directions of the Supreme Court, which allows the Centre to constitute authorities. India has no single central law on groundwater, so the EP Act was used.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-855","question":"In 2013, in Centre for Environmental Law, WWF-India v. Union of India, the Supreme Court directed that:","options":["Cheetahs from Africa be introduced into Kuno National Park within a year","Some Asiatic lions be moved from Gir to Kuno to form a second population","All tigers living outside reserves be shifted into the core areas of reserves","Gir National Park be declared a tiger reserve under the Wild Life Act, 1972"],"answer":1,"explanation":"The Court held that the lion, confined to one region of Gujarat, needed a second home to guard against epidemics or disasters, and ordered translocation to Kuno in Madhya Pradesh. In the same judgment it rejected the then cheetah plan; cheetahs were brought to Kuno only in 2022.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-856","question":"Under the Montreal Protocol, developing countries that qualify under 'Article 5' are:","options":["Given a grace period to meet phase-out schedules and access to the Multilateral Fund","Exempted permanently from phasing out CFCs, halons and other controlled substances","Required to phase out ozone-depleting substances before the developed countries do","Barred from producing any ozone-depleting substance, even for essential uses"],"answer":0,"explanation":"Article 5 parties, developing countries with low per capita consumption, got roughly a ten-year delay in compliance and financial and technical help, an early application of common but differentiated responsibilities. India is an Article 5 party.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-857","question":"The Montreal Protocol is often praised for its flexibility because 'adjustments' to the phase-out schedules of substances already controlled:","options":["Must be ratified by every party before they apply to anyone","Apply only to developed countries, never to developing ones","Can be made by a single party for its own territory","Become binding on all parties without separate ratification"],"answer":3,"explanation":"Under Article 2(9), the parties can tighten phase-out schedules by adjustment, binding on all of them, whereas adding new substances (as with HFCs at Kigali) needs an amendment that each party ratifies. This let the phase-out be accelerated quickly as the science advanced.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-858","question":"The first Conference of the Parties (COP-1) to the UNFCCC, held in 1995, is known for the 'Berlin Mandate'. It took place at:","options":["Geneva","Kyoto","Berlin","Rio de Janeiro"],"answer":2,"explanation":"COP-1 in Berlin agreed that the commitments of developed countries were inadequate and launched talks that led to the Kyoto Protocol at COP-3 in 1997. Rio de Janeiro hosted the 1992 Earth Summit, not a COP.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-859","question":"The Green Climate Fund, now headquartered at Songdo in South Korea, was established by a decision of the UNFCCC at:","options":["COP-16 at Cancún in 2010","COP-15 at Copenhagen in 2009","COP-21 at Paris in 2015","COP-13 at Bali in 2007"],"answer":0,"explanation":"The Copenhagen Accord proposed a fund, but the GCF was formally set up by the Cancún Agreements (COP-16). It later became an operating entity of the financial mechanism for the Paris Agreement as well.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-860","question":"The 'Durban Platform for Enhanced Action', agreed at COP-17 in 2011, is important because it:","options":["Set up the Clean Development Mechanism under the Kyoto Protocol for the first time","Launched talks on a new agreement for all parties, to be adopted by 2015","Created the Intergovernmental Panel on Climate Change under WMO and UNEP","Adopted the Kyoto Protocol's first commitment period, running from 2008 to 2012"],"answer":1,"explanation":"Durban started negotiations for an agreement covering developed and developing countries alike, which produced the Paris Agreement in 2015. The CDM was created by Kyoto itself (1997) and the IPCC dates from 1988.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-861","question":"The 'Paris Rulebook', which set out detailed rules for implementing most of the Paris Agreement, was largely adopted at:","options":["COP-22 at Marrakech in 2016","COP-23 at Bonn in 2017","COP-25 at Madrid in 2019","COP-24 at Katowice in 2018"],"answer":3,"explanation":"COP-24 in Katowice, Poland, agreed most of the rules, including those for transparency and NDCs. The rules on carbon markets under Article 6 were left unresolved until COP-26 at Glasgow in 2021.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-862","question":"Under the Paris Agreement, the 'Enhanced Transparency Framework' (Article 13) requires parties to:","options":["Have their NDC targets approved by the UNFCCC secretariat before submission","Pay a penalty into the Green Climate Fund if they miss their NDC targets","Report regularly on their emissions and progress, subject to technical expert review","Allow independent inspectors to measure emissions directly at their factories"],"answer":2,"explanation":"The ETF obliges all parties, with flexibility for developing countries that need it, to submit biennial transparency reports that undergo expert review and a facilitative multilateral consideration. The agreement has no penalties and targets are nationally determined.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-863","question":"India hosted COP-8 of the UNFCCC in 2002, which adopted a declaration stressing that climate action must fit with sustainable development and poverty eradication. It was held at:","options":["New Delhi","Mumbai","Hyderabad","Goa"],"answer":0,"explanation":"COP-8 in New Delhi adopted the Delhi Ministerial Declaration on Climate Change and Sustainable Development, reflecting developing countries' emphasis on adaptation and development needs.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-864","question":"Which one of the following was NOT an outcome of the UN Conference on Environment and Development (Earth Summit) held at Rio de Janeiro in 1992?","options":["The Rio Declaration on Environment and Development","Agenda 21","The Forest Principles","The Kyoto Protocol"],"answer":3,"explanation":"Rio produced the Rio Declaration, Agenda 21 and the non-binding Forest Principles, and opened the UNFCCC and CBD for signature. The Kyoto Protocol was adopted five years later at COP-3 in Japan.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-865","question":"A species can be placed in a CITES Appendix by a single party acting on its own, without a vote of the Conference of the Parties. That Appendix is:","options":["Appendix I","Appendix III","Appendix II","None, since every listing needs a two-thirds vote"],"answer":1,"explanation":"Appendix III lists species protected in at least one country that asks others for help in controlling trade; the party can add them unilaterally. Changes to Appendices I and II need a two-thirds majority at a CoP.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-866","question":"The Global Tiger Forum, the only intergovernmental body set up solely to conserve tigers, has its secretariat at:","options":["New Delhi","Kathmandu","Bangkok","Dhaka"],"answer":0,"explanation":"The GTF was formed in the 1990s with its secretariat in New Delhi; it works with tiger range countries, for example on the St Petersburg goal of doubling wild tigers.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-867","question":"The Basel Convention (1989) was negotiated largely in response to:","options":["The Bhopal gas leak of 1984 and the thousands of resulting deaths in India","The discovery of the Antarctic ozone hole by British scientists in the mid-1980s","Cases of hazardous waste from rich countries being dumped in Africa and elsewhere","The Chernobyl nuclear disaster of 1986 and the spread of radioactive fallout"],"answer":2,"explanation":"Episodes such as the 1988 dumping of toxic waste at Koko in Nigeria exposed a trade in which rich countries shipped wastes to poorer ones, leading to the convention on transboundary movement of hazardous wastes.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-868","question":"On joining the Ramsar Convention, a country is required to:","options":["Ban all fishing and farming activity in every wetland within its territory","Pay a fixed annual fee per hectare of its wetlands to the Ramsar secretariat","Hand over the management of its listed wetlands to an international body","Designate at least one suitable wetland for the Ramsar List"],"answer":3,"explanation":"Article 2 requires each party to designate at least one site; parties also commit to the 'wise use' of all their wetlands and to international cooperation. Wise use permits sustainable human use such as fishing.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-869","question":"The World Day to Combat Desertification and Drought, linked to the UNCCD, is observed every year on:","options":["5 June","17 June","22 April","16 September"],"answer":1,"explanation":"17 June marks the adoption of the UNCCD text in 1994. 5 June is World Environment Day, 22 April Earth Day and 16 September the International Day for the Preservation of the Ozone Layer.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-870","question":"Match the IPCC Working Group with its area. A. Working Group I  B. Working Group II  C. Working Group III; 1. Mitigation of climate change  2. Impacts, adaptation and vulnerability  3. The physical science basis","options":["A-1, B-2, C-3","A-2, B-3, C-1","A-3, B-2, C-1","A-3, B-1, C-2"],"answer":2,"explanation":"Working Group I covers the physical science of climate change, Working Group II impacts, adaptation and vulnerability, and Working Group III mitigation; a separate task force handles national greenhouse gas inventories.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-871","question":"The UN-REDD Programme, launched in 2008 to help developing countries prepare for REDD+, is a collaboration of:","options":["FAO, UNDP and UNEP","The World Bank, IMF and WTO","UNESCO, IUCN and WWF","WMO, UNEP and the IPCC"],"answer":0,"explanation":"UN-REDD brings together the Food and Agriculture Organization, UNDP and UNEP. The World Bank runs a separate Forest Carbon Partnership Facility, and WMO with UNEP set up the IPCC.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-872","question":"The International Day for the Preservation of the Ozone Layer is observed on 16 September because that date marks:","options":["The discovery of the Antarctic ozone hole in 1985","The adoption of the Vienna Convention in 1985","The entry into force of the Kigali Amendment in 2019","The signing of the Montreal Protocol in 1987"],"answer":3,"explanation":"The Montreal Protocol was signed on 16 September 1987. The Vienna Convention was adopted in March 1985, and the ozone hole was reported by British Antarctic Survey scientists in 1985.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-873","question":"Which statement about the UN Environment Assembly (UNEA) is correct?","options":["It is the governing body of the UNFCCC and meets during each COP","It was created after Rio+20 and has universal membership of UN states","It is a tribunal that settles disputes between countries over shared rivers","It is made up of 58 member countries elected by the UN General Assembly"],"answer":1,"explanation":"UNEA replaced UNEP's 58-member Governing Council in 2012–13 and is open to all UN member states, making it the world's highest decision-making body on the environment. It meets at Nairobi; its 2022 session launched the plastics treaty talks.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-874","question":"The India Cooling Action Plan, released in 2019, is notable because it:","options":["Bans the sale of all air conditioners that use any fluorinated refrigerant gas","Applies only to cold storage for farm produce and not to homes or offices","Sets out a 20-year plan to cut cooling demand and refrigerant use across sectors","Requires every new commercial building to install centralised air-conditioning"],"answer":2,"explanation":"India was among the first countries to prepare such a plan; it looks ahead to 2037–38 to reduce cooling demand, refrigerant demand and cooling energy use, supporting the HFC phase-down under the Kigali Amendment and thermal comfort for all.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-875","question":"Jerdon's courser, a nocturnal bird thought to be extinct until it was rediscovered in 1986, is known only from the scrub jungle of:","options":["The Desert National Park near Jaisalmer in Rajasthan","The Banni grasslands of the Kutch region in Gujarat","Sri Lankamalleswara Wildlife Sanctuary in Andhra Pradesh","The Great Indian Bustard Sanctuary near Solapur, Maharashtra"],"answer":2,"explanation":"After decades without records, Jerdon's courser was found again near Lankamalla in Andhra Pradesh's Kadapa district, its only known stronghold.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-876","question":"The forest owlet, rediscovered in 1997 after more than a century without any confirmed record, lives in:","options":["The dry deciduous forests of central and western India","The evergreen rainforests of the Andaman and Nicobar Islands","The oak forests of the western Himalaya","The mangroves of the Sundarbans"],"answer":0,"explanation":"Rediscovered in Maharashtra, the forest owlet survives in teak-dominated dry deciduous forests such as Melghat and Toranmal. Many old 'specimens' had been fraudulent, which delayed the search.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-877","question":"The sarus crane, the state bird of Uttar Pradesh, is notable as:","options":["The only crane that migrates to India from Siberia","The tallest flying bird in the world","India's largest bird of prey","A bird that breeds only in the high Himalaya"],"answer":1,"explanation":"Standing up to about 1.8 m, the resident sarus is the world's tallest flying bird and nests in wetlands and paddy fields of the Gangetic plain.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-878","question":"In India, the black-necked crane breeds in summer in the high-altitude wetlands of Ladakh and spends the winter mainly in:","options":["The salt flats of the Little Rann of Kutch in Gujarat","The Keoladeo National Park wetlands at Bharatpur","The brackish lagoon of Chilika Lake in coastal Odisha","The Sangti and Zemithang valleys of Arunachal Pradesh"],"answer":3,"explanation":"Black-necked cranes winter in valleys of western Arunachal Pradesh and in Bhutan, after breeding on the Tibetan plateau and in Ladakh's Changthang.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-879","question":"The western population of the Siberian crane, which used to spend the winter in Keoladeo National Park, has not been seen there since about:","options":["1972","1985","2002","2015"],"answer":2,"explanation":"The last Siberian cranes were recorded at Bharatpur around the winter of 2001–02; hunting along the long migratory route through Afghanistan and Pakistan is blamed for the population's collapse.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-880","question":"The white-bellied heron, one of the world's rarest herons and Critically Endangered, is found in India mainly along rivers in:","options":["Namdapha in Arunachal Pradesh","The Western Ghats of Kerala","The Chambal ravines of Madhya Pradesh","The Gulf of Kutch in Gujarat"],"answer":0,"explanation":"The heron survives in tiny numbers along undisturbed rivers of Namdapha and adjacent areas, in Bhutan and in Myanmar; dams and disturbance threaten its habitat.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-881","question":"The great hornbill is the state bird of:","options":["Kerala and Arunachal Pradesh","Karnataka and Assam","Tamil Nadu and Arunachal Pradesh","Goa and Nagaland"],"answer":0,"explanation":"Both Kerala and Arunachal Pradesh chose the great hornbill. Its wide distribution across the Western Ghats and north-east mirrors the shared Indo-Malayan character of these forests.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-882","question":"The Himalayan monal, a brilliantly iridescent pheasant, is the state bird of:","options":["Himachal Pradesh","Sikkim","Uttarakhand","Jammu and Kashmir"],"answer":2,"explanation":"The Himalayan monal is Uttarakhand's state bird (and Nepal's national bird). Himachal Pradesh's state bird is the western tragopan.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-883","question":"Mrs Hume's pheasant, a bar-tailed pheasant of the north-eastern hills, is the state bird of:","options":["Assam and Tripura","Arunachal Pradesh and Sikkim","Meghalaya and Nagaland","Mizoram and Manipur"],"answer":3,"explanation":"Mizoram and Manipur both chose Mrs Hume's pheasant, named after the wife of the ornithologist A. O. Hume.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-884","question":"The Indian skimmer, which nests on river sandbars such as those of the Chambal, is unusual among birds because:","options":["It dives from great heights to catch fish underwater","Its lower mandible is longer than the upper one","It feeds only at night on insects attracted to water","It carries water to its chicks in its breast feathers"],"answer":1,"explanation":"The skimmer flies low with its long lower mandible slicing the surface and snaps shut on fish it touches. Sand mining and disturbance of sandbars threaten its nesting.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-885","question":"'Flamingo City', one of the largest breeding colonies of flamingos in Asia, is located in the:","options":["Great Rann of Kachchh, Gujarat","Nal Sarovar Bird Sanctuary, Gujarat","Point Calimere, Tamil Nadu","Chilika Lake, Odisha"],"answer":0,"explanation":"Flamingos nest on mudflats of the Great Rann when monsoon rains flood it. Sambhar and Chilika host many wintering flamingos, but the breeding colonies are in the Rann.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-886","question":"The bar-headed goose is famous for migrating between Central Asia and India by flying over the Himalaya at great heights. Which of the following helps it do this?","options":["It flies only by gliding on rising warm air currents","It stops to breathe at oxygen-rich glacial lakes","It flies only at night, when the air contains more oxygen","Its haemoglobin binds oxygen very readily at low pressure"],"answer":3,"explanation":"A high-affinity haemoglobin, large lungs and dense muscle capillaries let it fly where oxygen is scarce. The proportion of oxygen in air does not change by night; it is total pressure that falls with altitude.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-887","question":"Which of the following pairs of Indian birds are both listed by the IUCN as 'Critically Endangered (Possibly Extinct)'?","options":["Great Indian bustard and Bengal florican","Pink-headed duck and Himalayan quail","Siberian crane and white-bellied heron","Sarus crane and Indian skimmer"],"answer":1,"explanation":"Neither the pink-headed duck nor the Himalayan quail has been reliably recorded for many decades. The bustard, florican, Siberian crane and heron are Critically Endangered but known to survive.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-888","question":"The edible-nest swiftlet of the Andaman and Nicobar Islands is threatened by the harvesting of its nests, which are made almost entirely of:","options":["Mud mixed with chopped seaweed fibres","Woven grass and feathers","Twigs bound with spider silk","Hardened strands of its own saliva"],"answer":3,"explanation":"Swiftlets build cup-shaped nests from saliva in dark caves, and these are prized for bird's-nest soup. Over-harvesting before the chicks fledge caused steep declines.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-889","question":"The lesser florican, a small bustard of western and central Indian grasslands, is best known for:","options":["Nesting in tree holes in dry deciduous forests of central India","Spending the winter only on high meadows of the western Himalaya","Males leaping repeatedly into the air in display during the monsoon","Feeding in large mixed flocks on coastal mudflats of the east coast"],"answer":2,"explanation":"Breeding males make dramatic vertical leaps above the tall monsoon grass to attract females; loss of these seasonal grasslands has made it one of India's most threatened birds.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-890","question":"Consider the following statements about the king cobra: 1. It feeds mainly on other snakes. 2. The female builds a nest of leaf litter and guards her eggs. 3. It is the longest venomous snake in the world. Which of the statements given above is/are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Its scientific name Ophiophagus means 'snake-eater'; it is the only snake known to build a nest, and it can exceed five metres, the longest of all venomous snakes.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-891","question":"The broad-snouted freshwater crocodile found in rivers, lakes and reservoirs across most of India is the:","options":["Gharial","Saltwater crocodile","Mugger","Caiman"],"answer":2,"explanation":"The mugger or marsh crocodile is widespread in fresh water. The gharial has a thin snout and lives in a few rivers, the saltwater crocodile is restricted to coastal mangroves, and caimans are American.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-892","question":"The northern river terrapin (Batagur baska), a Critically Endangered turtle, survives in India mainly in:","options":["The Sundarbans","The Chambal river","The backwaters of Kerala","The Gulf of Kutch"],"answer":0,"explanation":"This large estuarine turtle lives in the tidal creeks of the Sundarbans, where a captive breeding programme supports it. The Chambal holds other species such as the red-crowned roofed turtle.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-893","question":"In 2019, the Conference of the Parties to CITES moved which Indian reptile, heavily smuggled for the pet trade, to Appendix I?","options":["Indian rock python","Bengal monitor lizard","Indian flapshell turtle","Indian star tortoise"],"answer":3,"explanation":"At CoP-18 the star tortoise was uplisted to Appendix I on India's proposal, banning commercial international trade. Its attractive shell pattern drives illegal collection.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-894","question":"The golden mahseer (Tor putitora), a large game fish sometimes called the 'tiger of the water', lives mainly in:","options":["Brackish lagoons and backwaters of the east coast","Coral reefs of Lakshadweep","Fast-flowing rivers of the Himalayan region","Saline lakes of Rajasthan"],"answer":2,"explanation":"The golden mahseer inhabits clear, fast Himalayan and sub-Himalayan rivers and migrates upstream to breed, so dams that block its movement are a major threat.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-895","question":"The humpback mahseer, a giant fish endemic to the Kaveri basin and now Critically Endangered, has declined partly because of:","options":["Competition from the introduced blue-finned mahseer","Overfishing of its eggs for the international caviar trade","Warming of the sea where it spawns","Pollution from oil drilling in the river delta"],"answer":0,"explanation":"Stocking of the non-native blue-finned mahseer for angling, along with dams and sand mining, pushed the humpback mahseer close to extinction.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-896","question":"The hilsa swims from the Bay of Bengal up rivers such as the Hooghly and Padma to spawn in fresh water. Such a fish is described as:","options":["Catadromous","Potamodromous","Oceanodromous","Anadromous"],"answer":3,"explanation":"Anadromous fish live in the sea and breed in rivers; catadromous fish, such as freshwater eels, do the opposite. Barrages such as Farakka have reduced the hilsa's upstream run.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-897","question":"The Malabar gliding frog of the Western Ghats can glide from tree to tree because:","options":["It inflates air sacs on both sides of its body like a balloon","It has broad, fully webbed feet that act like parachutes","Its skin folds stretch between its fore and hind limbs","It leaps using its strong tail as a spring"],"answer":1,"explanation":"Large webbing between its long toes lets it descend at a controlled angle. Frogs have no tail as adults, and skin folds between the limbs are the gliding method of flying squirrels.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-898","question":"In 2001, the whale shark became the first fish species to be placed in Schedule I of the Wildlife (Protection) Act. Which of the following statements about it is correct?","options":["It is a mammal that must surface to breathe air like a whale","It is the largest living fish and feeds mainly on plankton","It is a fierce predator of dolphins and seals","It lives only in fresh water near river mouths"],"answer":1,"explanation":"Despite its name, the whale shark is a fish, the world's largest, and a gentle filter-feeder. A community campaign in Gujarat turned fishermen from hunting it to rescuing it from nets.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-899","question":"The Ganges shark (Glyphis gangeticus), listed as Critically Endangered, is unusual because it:","options":["Lives only in the deep sea far beyond the continental shelf","Is a river shark of the Hooghly and other tidal rivers","Is found only in cold, high-altitude lakes of the Himalaya","Feeds by filtering plankton like the whale shark"],"answer":1,"explanation":"It is one of the few sharks adapted to rivers and estuaries, recorded mainly from the Hooghly–Ganga system; it is often confused with the bull shark.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-900","question":"Caecilians, several species of which are found in the Western Ghats and north-east India, are best described as:","options":["Legless lizards related to snakes","Larval stages of salamanders","Limbless, mostly burrowing amphibians","Primitive earthworms that have developed a backbone"],"answer":2,"explanation":"Caecilians are amphibians that have lost their limbs and live mostly in moist soil; they look like large earthworms or snakes but have a skull and backbone and breathe partly through their skin.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-901","question":"Solar photovoltaic panels in Rajasthan often produce less power at noon in May than on a clear, cooler day in February with similar sunlight. The main reason is that:","options":["Silicon cells stop absorbing visible light once they become warm","Summer sunlight contains less ultraviolet light, which PV cells mainly use","The conversion efficiency of PV cells falls as their temperature rises","The inverters switch off automatically whenever the air is above 40 °C"],"answer":2,"explanation":"Higher cell temperature lowers the voltage of a silicon cell, cutting output by roughly 0.4–0.5 per cent per °C above 25 °C. Dust also matters, but the temperature effect explains the summer drop under similar irradiance.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-902","question":"'Bifacial' solar modules, increasingly used in Indian solar parks, can give higher output than ordinary modules because they:","options":["Also capture sunlight reflected from the ground onto their rear side","Track the Sun automatically from east to west through the day","Use two layers of silicon, so they convert infrared light as well","Store part of the electricity in a battery built into the panel"],"answer":0,"explanation":"Bifacial panels have a transparent back, so light reflected by bright ground (sand, white gravel) adds to generation, with gains depending on ground albedo and mounting height. Tracking and storage are separate technologies.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-903","question":"If the wind speed at a turbine site rises from 5 m/s to 10 m/s, the power available in the wind increases by a factor of about:","options":["2","4","6","8"],"answer":3,"explanation":"Power in the wind is proportional to the cube of wind speed (P = ½ρAv³), so doubling speed gives 2³ = 8 times the power. This is why small differences in average wind speed matter greatly in choosing sites.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-904","question":"According to Betz's law, the maximum fraction of the kinetic energy in the wind that any turbine can capture is about:","options":["100 per cent, if the blades are perfectly designed","59 per cent","33 per cent","90 per cent, minus friction losses"],"answer":1,"explanation":"A turbine cannot stop the air completely, or no more air would flow through it; the theoretical limit is 16/27, about 59.3 per cent. Real turbines reach roughly 40–50 per cent.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-905","question":"The main advantage of offshore wind farms over onshore ones is that at sea:","options":["Winds are generally stronger and steadier, so turbines yield more energy","Turbines need no foundations at all, so they cost far less to build","Salty sea air cools the generators, so they never need any maintenance","There is no need for any transmission lines to bring the power to land"],"answer":0,"explanation":"The smooth sea surface causes less friction, so winds are faster and less turbulent, raising the capacity factor. Offshore projects cost more because of foundations, undersea cables and corrosion.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-906","question":"In India, hydropower projects classified as 'small hydro' under the Ministry of New and Renewable Energy are those with a capacity of up to:","options":["5 MW","10 MW","25 MW","100 MW"],"answer":2,"explanation":"Plants up to 25 MW are classed as small hydro and handled by MNRE. Large hydro was declared a renewable source in 2019 but remains under the Ministry of Power.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-907","question":"A pumped storage hydropower plant helps a grid with a large share of solar and wind power mainly because it:","options":["Generates more electricity over each day than it consumes in pumping","Produces power with no reservoir at all, using only the river's flow","Burns biomass in its turbines whenever reservoir water levels are low","Pumps water uphill with surplus power and releases it at peak demand"],"answer":3,"explanation":"Pumped storage is a large battery: it consumes more energy than it returns (losses of about 20–30 per cent), but shifts energy from hours of surplus, such as sunny afternoons, to evening peaks.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-908","question":"Which of the following regions of India are considered to have the highest potential for tidal energy?","options":["The Konkan coast and the Gulf of Mannar","The Gulfs of Khambhat and Kutch, and the Sundarbans","The Malabar coast and the Lakshadweep islands","The coasts of Andhra Pradesh and Odisha"],"answer":1,"explanation":"Tidal power needs a large tidal range; the funnel-shaped Gulf of Khambhat has a range of up to about 11 m, the Gulf of Kutch about 8 m, and the Sundarbans delta is also suitable. The west-coast and Gulf of Mannar ranges are small.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-909","question":"Biodiesel made from the seeds of Jatropha curcas is produced mainly by:","options":["Transesterification of the oil with methanol, giving glycerol as a by-product","Fermenting the seed cake with yeast to produce ethanol and carbon dioxide","Gasifying the dried seeds at high temperature to give hydrogen and carbon monoxide","Distilling the crushed seeds directly to separate diesel-like hydrocarbons"],"answer":0,"explanation":"The vegetable oil reacts with an alcohol (usually methanol) and a catalyst to form fatty acid methyl esters (biodiesel) and glycerol. Jatropha was favoured because its oil is non-edible and the plant grows on poor land.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-910","question":"India's three-stage nuclear power programme is designed ultimately to make use of the country's large reserves of:","options":["Uranium, through light water reactors in all three stages","Plutonium, mined from deposits in Jharkhand","Thorium, found in the monazite sands of the coast","Deuterium, extracted from seawater for fusion"],"answer":2,"explanation":"Stage one uses natural uranium in pressurised heavy water reactors, stage two uses plutonium in fast breeder reactors that also breed uranium-233 from thorium, and stage three runs on thorium–U-233. India has modest uranium but large thorium reserves.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-911","question":"A 100 MW solar plant operates at an annual capacity utilisation factor of 20 per cent. About how much electricity does it generate in a year?","options":["876 GWh","175 GWh","438 GWh","17.5 GWh"],"answer":1,"explanation":"Energy = 100 MW × 8,760 hours × 0.20 = 175,200 MWh, about 175 GWh. 876 GWh would need the plant to run at full output all year, which is why rated capacity overstates solar output compared with coal plants.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-912","question":"The 'duck curve', discussed in power systems with much solar generation, describes:","options":["The steady fall in the price of solar panels over the past two decades","The sharp drop in solar output during the monsoon months every year","The rise in deaths of water birds near solar parks built on wetlands","Net demand dipping at midday and then ramping up steeply at sunset"],"answer":3,"explanation":"When demand minus solar output is plotted over a day, the midday trough and steep evening rise as the sun sets look like a duck's outline. It creates a need for flexible plants, storage and demand shifting.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-913","question":"The National Green Hydrogen Mission, approved by India in January 2023, aims at a green hydrogen production capacity by 2030 of at least:","options":["5 million tonnes per year","50 million tonnes per year","0.5 million tonnes per year","500 million tonnes per year"],"answer":0,"explanation":"The mission targets about 5 MMT a year by 2030, with associated renewable capacity of about 125 GW, to cut fossil-fuel imports and decarbonise refineries, fertilisers and steel.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-914","question":"The PM-KUSUM scheme, launched in 2019, mainly aims to:","options":["Provide free electric two-wheelers to rural women entrepreneurs","Fund wind turbines on the coast of Gujarat and Tamil Nadu","Promote solar pumps and solar power plants for farmers","Replace diesel generators in telecom towers with fuel cells"],"answer":2,"explanation":"KUSUM supports standalone solar pumps, solarisation of grid-connected pumps and small solar plants on farmers' land, reducing diesel use and giving farmers an income from selling surplus power.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-915","question":"Bhadla Solar Park, one of the largest solar parks in the world, is located in:","options":["Kutch district, Gujarat","Jodhpur district, Rajasthan","Anantapur district, Andhra Pradesh","Tumakuru district, Karnataka"],"answer":1,"explanation":"Bhadla in Jodhpur district has high irradiance and cheap desert land. Pavagada in Tumakuru and the Kurnool and Anantapur parks are other large Indian solar parks, which makes this a common trap.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-916","question":"A 'Renewable Purchase Obligation' (RPO) in India requires:","options":["Renewable energy developers to buy back their own power whenever grid demand falls","Households above a set income to buy a minimum number of solar appliances every year","Coal power plants to sell a fixed share of their output to renewable energy firms","Discoms and some large consumers to buy a minimum share of renewable power"],"answer":3,"explanation":"RPOs are set under the Electricity Act for obligated entities such as discoms, open-access consumers and captive users; they can meet them by buying renewable power or Renewable Energy Certificates.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-917","question":"Under 'net metering' for a house with rooftop solar panels:","options":["The household is billed only for the difference between power drawn and fed in","The household must consume all of its own solar power and cannot export any of it","The household is paid for all of its solar generation at a fixed rate, separately","The household's meter is removed, and it pays a flat monthly fee for all power used"],"answer":0,"explanation":"A bidirectional meter records imports and exports, so surplus daytime solar offsets night-time consumption. In gross metering, by contrast, all generation is sold to the grid at a fixed tariff.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-918","question":"Garrett Hardin's 1968 essay 'The Tragedy of the Commons' argued that:","options":["Common lands are always better managed by local communities than private lands are","Industrial pollution in the world is caused mainly by poverty in developing countries","People acting in self-interest can overuse and ruin a shared, open-access resource","Population growth in any country will stop by itself once that country becomes rich"],"answer":2,"explanation":"Hardin's example was herders each adding cattle to a shared pasture until it is ruined. Elinor Ostrom later showed that communities often manage commons well through local rules, an important rejoinder.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-919","question":"'The Limits to Growth' (1972), which modelled the consequences of exponential growth in population and resource use, was commissioned by:","options":["The World Bank","The Club of Rome","The UN Environment Programme","The Brundtland Commission"],"answer":1,"explanation":"A team at MIT led by Donella and Dennis Meadows produced the report for the Club of Rome, warning of overshoot and collapse within a century without change. The Brundtland Commission's 'Our Common Future' came in 1987.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-920","question":"The 'doughnut' model of economics, proposed by Kate Raworth, describes a safe and just space for humanity that lies between:","options":["A minimum annual growth rate and a maximum inflation rate set for every economy","The remaining carbon budget for 1.5 °C and the larger one for 2 °C of warming","The average incomes of the poorest tenth and the richest tenth of humanity","A social foundation of basic needs and an ecological ceiling of planetary limits"],"answer":3,"explanation":"The inner ring represents shortfalls in essentials such as food, water and health; the outer ring represents overshoot of planetary boundaries such as climate change and biodiversity loss.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-921","question":"A country's GDP grows by 6 per cent a year while its total carbon emissions fall by 1 per cent a year. This is an example of:","options":["Absolute decoupling of emissions from economic growth","Relative decoupling of emissions from economic growth","The rebound effect of improved energy efficiency","Carbon leakage to the country from its trading partners"],"answer":0,"explanation":"Absolute decoupling means emissions fall while output grows. If emissions rose but more slowly than GDP, it would be relative decoupling, meaning only the emissions intensity of the economy is falling.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-922","question":"W. S. Jevons observed in 1865 that more efficient steam engines led to greater, not lower, total coal use in Britain. This 'Jevons paradox' is an extreme case of:","options":["Carbon leakage","The precautionary principle","The rebound effect","Diminishing marginal utility"],"answer":2,"explanation":"Efficiency lowers the effective cost of an energy service, so people use more of it; when the extra use outweighs the savings, total consumption rises. Policies on efficiency therefore often pair it with pricing or caps.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-923","question":"In the 'I = P × A × T' identity proposed by Ehrlich and Holdren, environmental impact is expressed as the product of:","options":["Investment, Pollution and Taxation","Population, Affluence and Technology","Industry, Agriculture and Transport","Income, Area and Time"],"answer":1,"explanation":"Impact depends on the number of people, consumption per person and the impact per unit of consumption set by technology. It shows that cleaner technology can offset growth in population and affluence only if it improves faster than they grow.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-924","question":"A 'run-of-the-river' hydroelectric project differs from a conventional storage project mainly in that it:","options":["Burns biomass to pump river water up to a turbine on a hill","Can generate power only during the dry season, when flows are steady","Requires a reservoir large enough to store a full year's river flow","Uses the river's natural flow with little or no storage reservoir"],"answer":3,"explanation":"Run-of-river schemes divert flow through turbines with at most a small pondage, so they submerge less land but their output follows seasonal river flow, peaking in the monsoon and snow-melt months.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-925","question":"Muppandal, one of the largest onshore wind power clusters in India, is located in:","options":["Jaisalmer district, Rajasthan","Kutch district, Gujarat","Kanyakumari district, Tamil Nadu","Satara district, Maharashtra"],"answer":2,"explanation":"Muppandal lies near the Aralvaimozhi gap in the Western Ghats, which funnels strong monsoon winds. Jaisalmer, Kutch and Satara also host wind farms, which is why this is a common trap.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-926","question":"Young sandalwood (Santalum album) plants grow poorly in plantations unless other plants are grown alongside them. The reason is that sandalwood:","options":["Needs shade from taller trees throughout its life","Is a root hemiparasite that draws water and nutrients from host plants","Depends on nitrogen-fixing neighbours because it cannot absorb nitrate","Requires insect pollinators that nest only in neighbouring shrubs"],"answer":1,"explanation":"Sandalwood photosynthesises but attaches to roots of neighbouring plants through haustoria to obtain water and minerals, so suitable hosts are planted with it.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-927","question":"Red sanders (Pterocarpus santalinus), whose heartwood is heavily smuggled abroad, grows naturally only in:","options":["The Seshachalam hills and nearby ranges of Andhra Pradesh","The Nilgiri and Anamalai hills of the southern Western Ghats","The Aravalli ranges of Rajasthan and Haryana","The Chota Nagpur plateau of Jharkhand and northern Odisha"],"answer":0,"explanation":"Red sanders is endemic to a small belt of the southern Eastern Ghats in Andhra Pradesh; its narrow range makes illegal felling especially damaging.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-928","question":"The Himalayan yew has been heavily stripped of its bark and leaves in many areas because it is a source of:","options":["Quinine, used to treat malaria","Reserpine, used for lowering high blood pressure","Paclitaxel (taxol), used in cancer treatment","Artemisinin, used against malaria parasites"],"answer":2,"explanation":"Taxol, an anticancer drug, was first isolated from yews; demand for Himalayan yew bark led to severe over-harvesting. Reserpine comes from Rauwolfia and quinine from Cinchona.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-929","question":"The Brahma kamal (Saussurea obvallata), a flower of high Himalayan meadows used in religious offerings, is the state flower of:","options":["Himachal Pradesh","Sikkim","Arunachal Pradesh","Uttarakhand"],"answer":3,"explanation":"Uttarakhand chose the Brahma kamal; it blooms in alpine areas such as the Valley of Flowers and is threatened by excessive picking by pilgrims.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-930","question":"Rohida (Tecomella undulata), sometimes called 'Marwar teak' for its fine timber, is the state flower of:","options":["Gujarat","Haryana","Madhya Pradesh","Rajasthan"],"answer":3,"explanation":"Rohida is a tree of the Thar that helps stabilise sand dunes and bears showy orange-yellow flowers; Rajasthan adopted it as its state flower.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-931","question":"The hollong (Dipterocarpus macrocarpus), a tall tree of the wet evergreen forests of the north-east, is the state tree of:","options":["Meghalaya","Arunachal Pradesh","Assam","Nagaland"],"answer":2,"explanation":"Assam's state tree is the hollong, which gives its name to the Hollongapar Gibbon Sanctuary near Jorhat. Dipterocarps dominate many tropical rainforests of Asia.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-932","question":"The mahua tree (Madhuca longifolia) is important in the economy of many tribal communities of central India mainly because:","options":["Its flowers are eaten and distilled into liquor, and its seeds yield oil","Its leaves are rolled into bidis and sold as a nationalised minor forest produce","Its bark yields tannin that is used for curing leather in rural tanneries","Its milky latex is tapped and sold as natural rubber to factories"],"answer":0,"explanation":"Mahua flowers are collected for food and liquor and the seeds for edible oil. Bidi wrappers come from tendu (kendu) leaves, a different tree.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-933","question":"Leaves of which tree are collected on a large scale in central and eastern India for rolling bidis and are traded as a nationalised minor forest produce in several states?","options":["Sal","Palash","Mahua","Tendu"],"answer":3,"explanation":"Tendu or kendu leaf collection is a major seasonal income for forest dwellers; states such as Odisha and Madhya Pradesh control its trade. Sal leaves are used to make plates.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-934","question":"In Mizoram, the 'mautam' event that occurs about every 48–50 years is feared because:","options":["Monsoon floods sweep away the terraced hill fields in the same season","A bamboo flowers en masse and rats feeding on its seed destroy crops","Locust swarms arriving from the west devastate crops across the hills","Cyclones from the Bay of Bengal flatten the bamboo forests and villages"],"answer":1,"explanation":"Melocanna baccifera flowers gregariously and dies; rats feasting on its abundant seed multiply explosively and then devour crops, as in the famine of 1959.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-935","question":"The famous living root bridges of Meghalaya are made by Khasi and Jaintia villagers by training the aerial roots of:","options":["The banyan, Ficus benghalensis","The peepal, Ficus religiosa","The rubber fig, Ficus elastica","The cluster fig, Ficus racemosa"],"answer":2,"explanation":"Roots of the Indian rubber fig are guided across streams until they grow and fuse into strong bridges, some of which last for centuries.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-936","question":"Sapria himalayana, a rare flowering plant of north-east India such as Namdapha, is a close relative of Rafflesia. Which feature does it share with Rafflesia?","options":["It is a root parasite with no leaves, stem or chlorophyll","It is an epiphytic orchid that grows on tree trunks","It is an insectivorous plant with large pitcher-shaped leaves","It is a tree fern that grows above the treeline"],"answer":0,"explanation":"Like Rafflesia, Sapria lives entirely inside the roots of host vines and shows itself only as a large, foul-smelling flower that attracts carrion flies.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-937","question":"Guggul (Commiphora wightii), a shrub of the arid zones of Rajasthan and Gujarat, has become threatened mainly because of:","options":["Felling for its valuable timber used in carved furniture","Grazing of its leaves by camels and goats","Destructive tapping of its stems for medicinal gum resin","Clearing of the coastal mangroves where it grows"],"answer":2,"explanation":"Guggul gum resin is prized in Ayurveda, and crude, excessive tapping kills the plants; it grows in dry, rocky areas, not mangroves.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-938","question":"Kuth (Saussurea costus), a Himalayan medicinal herb whose roots were exported in large quantities, is notable for being:","options":["Declared India's national medicinal plant by the AYUSH ministry","The original natural source of the anti-malarial drug quinine","A plant that flowers only once in twelve years","Listed in CITES Appendix I, which bans its commercial trade"],"answer":3,"explanation":"Over-collection for its aromatic roots led to kuth's listing in CITES Appendix I. Quinine comes from Cinchona, and twelve-yearly flowering is a feature of neelakurinji.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-939","question":"Yarsagumba (keeda jadi), collected in large quantities from the high meadows of Uttarakhand and Nepal, is:","options":["A fungus growing out of the bodies of infected caterpillars","The dried underground root of a rare high-altitude orchid","A slow-growing lichen found on rocks just above the snowline","The aromatic resin collected from an alpine juniper shrub"],"answer":0,"explanation":"Ophiocordyceps sinensis infects ghost-moth larvae underground and sends up a fruiting body; its high price has led to over-harvesting and conflicts over collection.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-940","question":"All species of lady's slipper orchids (Paphiopedilum), several of which occur in north-east India, are listed in which appendix of CITES?","options":["Appendix III","Appendix II","Appendix I","They are not listed in CITES"],"answer":2,"explanation":"Because collectors prize them, all Paphiopedilum species are in Appendix I. Most other orchids are in Appendix II, which permits regulated trade.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-941","question":"In their classic 1968 classification of the forest types of India, Champion and Seth grouped the forests into five major groups. How many type groups did they recognise at the next level?","options":["Ten","Sixteen","Twenty-five","Two hundred"],"answer":1,"explanation":"Champion and Seth recognised 5 major groups, divided into 16 type groups (such as tropical wet evergreen and alpine scrub), which are further split into about 200 forest types.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-942","question":"According to the forest type mapping based on Champion and Seth's classification, which forest type group covers the largest area in India?","options":["Tropical wet evergreen forests","Tropical moist deciduous forests","Montane wet temperate forests","Tropical dry deciduous forests"],"answer":3,"explanation":"Tropical dry deciduous forests, typical of areas with about 70–100 cm of rain, cover the largest share of India's forest area, followed by tropical moist deciduous forests.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-943","question":"The Sundarbans are popularly said to take their name from the sundari tree, which is a:","options":["Mangrove tree of the genus Heritiera","Stemless mangrove palm of the genus Nypa","Seagrass of the genus Halophila","Strangler fig of the genus Ficus"],"answer":0,"explanation":"Sundari (Heritiera fomes) is a characteristic mangrove of the less saline parts of the Sundarbans and is threatened by rising salinity as fresh water from upstream declines.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-944","question":"Consider the following statements about tropical wet evergreen forests in India: 1. They occur where annual rainfall exceeds about 200 cm. 2. All the trees shed their leaves together in the dry season. 3. Mahogany, ebony and rosewood are among the typical trees. Which of the statements given above is/are correct?","options":["1 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"These forests, found in the Western Ghats, the north-east and the Andamans, have no common leaf-fall season and so stay green all year; statement 2 describes deciduous forests.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-945","question":"The Himalayan birch (Betula utilis), whose papery bark was used for writing manuscripts ('bhojpatra'), typically grows:","options":["In the lowland sal forests of the Terai","On sand dunes of the Thar desert","Near the treeline in the high Himalaya","In the mangrove swamps of the delta coast"],"answer":2,"explanation":"Birch forms forests at the upper treeline, often with rhododendron and juniper, just below the alpine meadows; these treeline forests are sensitive indicators of climate change.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-946","question":"Neem-based biopesticides act against many insect pests mainly through azadirachtin, which:","options":["Kills insects instantly on contact like an organochlorine","Repels insects and disrupts their feeding and moulting","Fixes nitrogen in the soil for the crop","Makes the plant poisonous to people who eat it"],"answer":1,"explanation":"Azadirachtin is an antifeedant and insect growth regulator; it acts slowly and selectively, so it fits integrated pest management better than broad-spectrum poisons.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-947","question":"Mikania micrantha, which smothers plantations and forest edges in Kerala and north-east India, is a:","options":["Native shade tree planted in tea gardens of Assam and Kerala","Fast-growing invasive climber nicknamed 'mile-a-minute'","Parasitic fungus that kills bamboo clumps","Floating aquatic plant that blocks backwaters"],"answer":1,"explanation":"Mikania, a South American vine, grows extremely fast and covers other vegetation, cutting off its light. The floating weed of backwaters is water hyacinth.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-948","question":"The red seaweed Kappaphycus alvarezii has caused concern in the Gulf of Mannar because it:","options":["Releases toxins that cause red tides along the Tamil Nadu coast","Grazes on living coral polyps at night and bleaches the reefs","Was farmed there and escaped onto reefs, smothering the corals","Is a native weed that blocks the seagrass feeding beds of dugongs"],"answer":2,"explanation":"Kappaphycus was brought in for commercial carrageenan farming and escaped onto reefs near Kurusadai island, where it overgrows and kills corals.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-949","question":"Utricularia (bladderwort), found in wetlands and paddy fields across India, obtains extra nitrogen by:","options":["Trapping tiny aquatic animals in small bladders that suck them in","Catching insects on sticky glandular hairs on its leaves","Housing nitrogen-fixing cyanobacteria in its leaf cavities","Closing hinged leaf traps when sensitive trigger hairs are touched"],"answer":0,"explanation":"Bladderwort's bladders create a vacuum and snap open to suck in prey such as water fleas. Sticky hairs are the method of sundews (Drosera); hinged traps belong to the Venus flytrap.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-950","question":"The noble dendrobium (Dendrobium nobile), an epiphytic orchid, is the state flower of:","options":["Meghalaya","Assam","Mizoram","Sikkim"],"answer":3,"explanation":"Sikkim, rich in orchids, chose the noble dendrobium as its state flower. Epiphytic orchids use trees only for support and absorb moisture through spongy aerial roots.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-951","question":"Assertion (A): Hydrofluorocarbons (HFCs), which replaced CFCs in refrigerators, do not damage the ozone layer. Reason (R): HFC molecules contain no chlorine or bromine. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Ozone destruction by CFCs and halons comes from the chlorine and bromine they release; HFCs contain only hydrogen, fluorine and carbon, so their ODP is zero. Their high GWP is why the Kigali Amendment now phases them down.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-952","question":"Assertion (A): Sharply cutting sulphur dioxide emissions from power plants can temporarily speed up global warming. Reason (R): Sulphur dioxide is a powerful greenhouse gas that traps outgoing infrared radiation. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"SO2 forms sulphate aerosols that reflect sunlight and brighten clouds, masking part of greenhouse warming; removing them unmasks it. SO2 is not a significant greenhouse gas, so R is false.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-953","question":"Assertion (A): Fish kills in lakes with dense algal blooms often happen in the early hours of the morning. Reason (R): At night, photosynthesis stops while respiration by algae, bacteria and fish continues to consume dissolved oxygen. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Dissolved oxygen in a eutrophic lake swings daily: it is supersaturated in the afternoon and falls to its lowest just before dawn, after a night of respiration without photosynthesis. That is when fish suffocate.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-954","question":"Assertion (A): A wind turbine emits no carbon dioxide while it is generating electricity. Reason (R): Wind turbines are built without using any steel, cement or other energy-intensive materials. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Operation involves no combustion, but towers use steel and foundations use concrete, so turbines have life-cycle emissions from manufacture and construction, though these are far lower per unit of electricity than for coal.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-955","question":"The Jharia coalfield, known for underground coal-seam fires that have burned for about a century and for land subsidence, is in:","options":["Chhattisgarh","Jharkhand","Odisha","West Bengal"],"answer":1,"explanation":"Jharia, in Dhanbad district of Jharkhand, holds India's main coking coal reserves; its mine fires release smoke, CO2 and toxic gases and have forced the relocation of many residents. Raniganj in West Bengal is the nearby, separate coalfield.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-956","question":"Chemical dispersants are sometimes sprayed on an oil slick at sea. Which of the following best describes what they do?","options":["They dissolve the oil completely into harmless carbon dioxide and water within hours","They make the oil sink to the sea floor, where it stays buried permanently","They set the oil alight so that it burns off the surface of the sea quickly","They break the slick into tiny droplets that mix into the water and degrade faster"],"answer":3,"explanation":"Dispersants reduce surface tension so oil disperses into the water column, protecting coasts and seabirds and speeding biodegradation; the trade-off is greater exposure of fish and plankton below the surface. Burning in situ is a separate method.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-957","question":"Conservationists ask coastal towns near turtle nesting beaches to switch off or shield bright lights during the hatching season. The reason is that:","options":["Bright light warms the nest sand, so that all of the hatchlings turn out to be males","Hatchlings head for the brightest horizon, so artificial light draws them inland","Artificial light attracts crabs and stray dogs, which then dig up the turtle nests","Strong light stops the eggs from hatching until the night of the next new moon"],"answer":1,"explanation":"Hatchlings emerge at night and head for the brighter seaward horizon; street and building lights draw them inland, where they die of exhaustion or predation. Sand temperature, not light, determines sex, and warmer sand produces more females.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-958","question":"In cloud seeding operations to induce rain, the substance most commonly dispersed into suitable clouds is:","options":["Calcium carbonate","Sulphur dioxide","Ammonium nitrate","Silver iodide"],"answer":3,"explanation":"Silver iodide has a crystal structure similar to ice and acts as an ice nucleus in cold clouds; salts such as sodium chloride are used for warm clouds, and dry ice is also used. Seeding works only if suitable moist clouds are already present.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-959","question":"In large river deltas such as the Sundarbans, the rise in sea level relative to the land is often faster than the global average rise. A major reason is:","options":["Land subsidence as delta sediments compact and get less new silt from dammed rivers","Deltas lie closer to the poles, where the melting of ice raises the sea fastest","Mangrove roots absorb seawater and so lift the level of the surrounding sea","Tidal ranges in deltas are nil, so the whole global rise is concentrated there"],"answer":0,"explanation":"Relative sea-level rise combines global ocean rise with local land movement. Deltas sink as sediments compact and as dams and embankments starve them of new silt; groundwater extraction can add to subsidence.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-960","question":"LOHAFEX, an Indo-German experiment carried out in the Southern Ocean in 2009, tested the idea of:","options":["Pumping liquefied CO2 into deep-sea sediments below the ocean floor","Measuring how krill populations respond to warming ocean water","Fertilising the ocean with iron to boost plankton that absorb CO2","Spraying fine seawater into clouds so that they reflect more sunlight"],"answer":2,"explanation":"In iron-limited waters, adding iron sulphate triggers plankton blooms. LOHAFEX found that much of the fixed carbon was eaten by zooplankton and recycled near the surface rather than sinking, casting doubt on iron fertilisation as a carbon sink.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-961","question":"According to the IPCC's Special Report on Global Warming of 1.5 °C (2018), pathways that limit warming to 1.5 °C with no or limited overshoot require global net CO2 emissions to reach zero around:","options":["2030","2050","2070","2100"],"answer":1,"explanation":"Such pathways cut net CO2 emissions by about 45 per cent from 2010 levels by 2030 and reach net zero around 2050; for likely below 2 °C, net zero comes around 2070. This report drove the many 'net zero by 2050' pledges.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-962","question":"Which one of the following statements about India's greenhouse gas emissions is correct?","options":["India's per capita emissions are higher than those of the European Union","India's emissions are mostly from agriculture rather than from energy","India accepted absolute emission caps under the Kyoto Protocol","India's per capita emissions are well below the world average"],"answer":3,"explanation":"Although India is a large emitter in total, its per capita CO2 emissions are under half the world average, a central point in its argument for equity and CBDR. Energy, not agriculture, is the largest source, and India had no Kyoto caps.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-963","question":"HFC-23, a greenhouse gas with a global warming potential of over 10,000, became controversial under the Clean Development Mechanism because it is:","options":["An unwanted by-product of manufacturing the refrigerant HCFC-22","Released naturally in large amounts by termites and tropical wetlands","Emitted mainly when tropical forests are burnt to clear land for farms","A by-product of producing green hydrogen through water electrolysis"],"answer":0,"explanation":"Plants making HCFC-22 earned huge numbers of CDM credits by destroying HFC-23, creating incentives to produce more HCFC-22. The Kigali Amendment now requires parties to destroy HFC-23 by-product emissions as far as practicable.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-964","question":"The Love Canal disaster in the United States, where homes and a school were built over buried chemical waste, led directly to the US law popularly known as:","options":["The Clean Air Act","The Endangered Species Act","The Superfund law (CERCLA)","The Oil Pollution Act"],"answer":2,"explanation":"Leaking chemicals at Love Canal near Niagara Falls caused an emergency evacuation in 1978, and Congress passed the Comprehensive Environmental Response, Compensation, and Liability Act in 1980 to clean up hazardous waste sites and make polluters pay.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-965","question":"The 1976 industrial accident at Seveso in Italy, which led to European laws on the control of major-accident hazards, released large amounts of:","options":["Methyl isocyanate","Dioxin (TCDD)","Radioactive caesium","Liquid ammonia"],"answer":1,"explanation":"A reactor at Seveso released a cloud containing TCDD, the most toxic dioxin, contaminating a large area and causing chloracne. The EU's Seveso Directives on industrial accident prevention followed. Methyl isocyanate was the Bhopal gas.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-966","question":"The Exxon Valdez disaster of 1989, which led to the US Oil Pollution Act of 1990, occurred in:","options":["The Gulf of Mexico","The North Sea off Scotland","The Persian Gulf","Prince William Sound, Alaska"],"answer":3,"explanation":"The tanker ran aground in Prince William Sound, spilling crude oil that killed huge numbers of seabirds and sea otters. The Deepwater Horizon blowout of 2010 was in the Gulf of Mexico, and Gulf War spills in 1991 were in the Persian Gulf.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-967","question":"The Great Smog of London in December 1952, which caused thousands of deaths, was mainly due to:","options":["Smoke and sulphur dioxide from coal burning, trapped under an inversion","Ozone and nitrogen oxides from car exhausts in strong summer sunshine","Dust storms carrying fine sand all the way from the Sahara Desert","Radioactive fallout drifting in from British nuclear weapon tests"],"answer":0,"explanation":"Cold, still weather and an inversion trapped soot and SO2 from household coal fires and power stations for days; the episode prompted the UK Clean Air Act of 1956. Photochemical smog of the Los Angeles type is the summer, traffic-related kind.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-968","question":"The gas leak at the LG Polymers plant in Visakhapatnam in May 2020 involved vapour of:","options":["Methyl isocyanate","Chlorine","Styrene","Hydrogen sulphide"],"answer":2,"explanation":"Styrene monomer stored in a tank heated up and polymerised, releasing vapour that killed several people and affected thousands. The NGT held the company liable and directed it to deposit an interim amount towards damages.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-969","question":"The Sukinda valley in Odisha, often listed among the most polluted places in India, is affected mainly by:","options":["Arsenic leached from deep aquifers into tube wells","Fluoride released by phosphate fertiliser factories","Mercury from chlor-alkali plants upstream","Hexavalent chromium from open-cast chromite mining"],"answer":3,"explanation":"Sukinda holds most of India's chromite reserves; overburden and mine water carry Cr(VI) into the Brahmani river and groundwater. Arsenic contamination is typical of the Ganga–Brahmaputra plains.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-970","question":"The Comprehensive Environmental Pollution Index (CEPI), used to identify critically polluted industrial clusters such as Vapi and Ankleshwar, was developed by:","options":["The Bureau of Indian Standards","The Central Pollution Control Board","The National Green Tribunal","NITI Aayog"],"answer":1,"explanation":"CPCB developed CEPI around 2009 with IIT Delhi, scoring clusters on air, water and land pollution and health effects; clusters scoring 70 or more were termed critically polluted and faced a moratorium on new units.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-971","question":"Under the Bhopal Gas Leak Disaster (Processing of Claims) Act, 1985:","options":["Each victim had to sue Union Carbide separately in courts in the United States","All claims were to be decided by a special bench of the National Green Tribunal","The Centre got the exclusive right to represent the victims and press their claims","The State of Madhya Pradesh became liable to pay all of the compensation itself"],"answer":2,"explanation":"Acting as parens patriae, the Union Government took over the claims, and in 1989 settled with Union Carbide for 470 million US dollars, a settlement widely criticised as inadequate. The NGT did not exist until 2010.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-972","question":"The rapid depletion of groundwater in north-west India, including Punjab, Haryana and Rajasthan, was confirmed from space by the GRACE satellites. They detected it by measuring:","options":["Changes in the colour of crops as seen in infrared satellite images","Tiny changes in the Earth's gravity caused by the loss of water mass","The temperature of the soil surface measured from orbit every day","The depth of water in wells measured by radar beams from space"],"answer":1,"explanation":"GRACE's twin satellites tracked tiny changes in the distance between them caused by variations in gravity; loss of water stored underground over years showed up as a falling mass, attributed mainly to pumping for irrigation.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-973","question":"'Oilzapper', used in India to clean up oily sludge and oil-contaminated soil, is:","options":["A chemical dispersant sprayed from aircraft over oil slicks at sea","An incinerator that burns oily sludge at a very high temperature","A floating boom that collects oil from the surface of harbours","A consortium of oil-degrading bacteria developed by TERI"],"answer":3,"explanation":"Oilzapper is a bioremediation product, a mix of bacteria that break down hydrocarbons, developed by The Energy and Resources Institute with the oil industry. It has been used at refineries and oil spill sites.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-974","question":"The 'green muffler' approach to controlling noise pollution involves:","options":["Planting rows of dense trees and shrubs along roads and near noise sources","Fitting all city buses and auto-rickshaws with quieter electric engines","Covering factory roofs and walls with grass mats to absorb vibration","Banning the use of horns on roads marked with green signboards"],"answer":0,"explanation":"Belts of dense vegetation, often four to six rows deep, absorb and scatter sound and screen residential areas from traffic noise, while also trapping dust. Horn bans and silence zones are separate measures.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-975","question":"'Cool roofs', promoted in several Indian heat action plans, keep buildings cooler mainly because they:","options":["Contain refrigerant pipes that pump heat out of the building","Have a high albedo, reflecting much of the incoming sunlight","Are made of thick concrete that stores the heat for winter","Absorb sunlight and convert it into electricity for fans"],"answer":1,"explanation":"White or reflective coatings reflect sunlight and emit heat well, lowering roof temperatures and indoor heat in homes without air-conditioning; on a city scale they also reduce the urban heat island. Solar panels are a different technology.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-976","question":"The National Plan for Conservation of Aquatic Ecosystems (NPCA), a centrally sponsored scheme, was formed by merging:","options":["The National Lake Conservation Plan and the National Wetlands Conservation Programme","The National River Conservation Plan and the Namami Gange programme for the Ganga","Project Tiger and Project Elephant, along with the scheme for other wild species","The National Afforestation Programme and the National Mission for a Green India"],"answer":0,"explanation":"NPCA combined the lake and wetland programmes so that lakes and wetlands are managed under one integrated scheme. River pollution abatement remains under the National River Conservation Plan and the Ganga programme.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-977","question":"'Amrit Dharohar', announced in the Union Budget 2023–24, is a scheme for:","options":["Restoring stepwells, tanks and other traditional water bodies in historic towns","Promoting wise use of Ramsar sites, their biodiversity and eco-tourism","Digitising the records of India's protected monuments and sacred groves","Reviving indigenous seed varieties through village community seed banks"],"answer":1,"explanation":"Amrit Dharohar aims to encourage wise use of Ramsar sites, enhancing their biodiversity, carbon stock and eco-tourism, and income for local communities. Coastal mangroves were addressed by the separate MISHTI scheme announced in the same budget.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-978","question":"MISHTI, announced by the Government of India in 2023, is an initiative for:","options":["Promoting millet cultivation in drought-prone rainfed districts","Cleaning up plastic waste from beaches, estuaries and harbours","Planting mangroves along the coastline and on salt-pan lands","Installing solar-powered desalination plants on small islands"],"answer":2,"explanation":"The Mangrove Initiative for Shoreline Habitats and Tangible Incomes plans mangrove plantation along the coast and on salt pans through convergence of MGNREGS, CAMPA funds and other sources, for coastal protection and livelihoods.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-979","question":"The Nagar Van Yojana, launched on World Environment Day 2020, aims to:","options":["Relocate villages from the core areas of national parks","Pay forest-dwelling communities for not cutting trees","Convert degraded forests into commercial plantations","Develop urban forests in cities and towns"],"answer":3,"explanation":"The scheme supports creating 'Nagar Vans' (city forests) on forest or other land in urban areas, with local bodies, schools and citizens, to improve urban greenery and biodiversity and reduce pollution and heat.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-980","question":"PARIVESH, launched by the Union Environment Ministry in 2018, is:","options":["A satellite-based system that monitors and reports forest fires in real time","An annual index ranking all the states on the quality of their environment","A national register of every wetland in India larger than one hectare","A single-window online system for green clearances of all kinds"],"answer":3,"explanation":"PARIVESH lets project proponents apply for and track all central green clearances online, with documents and decisions placed in the public domain. Forest fire alerts come from the Forest Survey of India.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-981","question":"Under the CPCB's categorisation of industries (2016) by pollution index into Red, Orange, Green and White, units in the 'White' category:","options":["Are practically non-polluting and do not need consent to establish or operate","Are the most polluting and may not be set up near protected areas","Must install continuous online emission monitoring with real-time reporting","Are allowed only inside notified industrial estates with common effluent plants"],"answer":0,"explanation":"White-category units, with a pollution index up to 20, need only intimate the board, not obtain consent. Red-category units, the most polluting, are generally not permitted in ecologically fragile and protected areas.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-982","question":"Under the Water Act, 1974 and the Air Act, 1981, a new industrial unit must obtain 'Consent to Establish' and later 'Consent to Operate' from:","options":["The State Pollution Control Board","The Union Ministry of Environment","The National Green Tribunal","The District Collector of the area"],"answer":0,"explanation":"Consents are granted, with conditions, by the SPCB (or Pollution Control Committee in a UT). These are separate from environmental clearance under the EIA Notification, which large projects need from the Centre or SEIAA.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-983","question":"The Adaptation Fund, set up under the Kyoto Protocol to finance adaptation in developing countries, was distinctive because it was financed mainly by:","options":["A levy on international air tickets, paid by passengers at the time of booking","A 2 per cent share of the credits issued under the Clean Development Mechanism","Compulsory contributions fixed in proportion to each Annex I country's emissions","Concessional loans from the World Bank and the IMF to the developing countries"],"answer":1,"explanation":"The 'share of proceeds' from CERs was an innovative, automatic source of funding beyond voluntary donations; it also supports direct access by national implementing entities, such as NABARD in India.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-984","question":"The 'Santiago Network', established under the UNFCCC, is meant to:","options":["Trade carbon credits among Latin American countries under Article 6","Monitor deforestation across the Amazon basin using satellite data","Coordinate the phase-out of coal from South American power grids","Link vulnerable countries with technical help on loss and damage"],"answer":3,"explanation":"The network was set up at COP-25 in 2019, chaired by Chile though held in Madrid, as part of the Warsaw International Mechanism to connect vulnerable countries with technical expertise on loss and damage.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-985","question":"The SDG India Index, which ranks states and union territories on their progress towards the Sustainable Development Goals, is prepared by:","options":["The Ministry of Environment, Forest and Climate Change","The Reserve Bank of India","NITI Aayog","The Comptroller and Auditor General"],"answer":2,"explanation":"NITI Aayog, which coordinates SDG implementation in India, has published the index since 2018 in partnership with the UN in India and the statistics ministry.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-986","question":"The Energy Conservation Building Code (ECBC), first launched in 2007, is administered by:","options":["The Bureau of Energy Efficiency","The Bureau of Indian Standards","The Central Public Works Department","The Ministry of New and Renewable Energy"],"answer":0,"explanation":"BEE, set up under the Energy Conservation Act, 2001, framed the ECBC to set minimum energy performance standards for new commercial buildings; states notify it to make it mandatory.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-987","question":"The FAME scheme, launched in India in 2015, is aimed at:","options":["Mapping India's forest areas and their carbon stock through satellite imagery","Funding afforestation and soil restoration on old mined-out lands","Reforming fertiliser subsidies so that small farmers use less urea","Faster adoption and manufacturing of electric and hybrid vehicles"],"answer":3,"explanation":"FAME (Faster Adoption and Manufacturing of Hybrid and Electric Vehicles) gave demand incentives and supported charging infrastructure under the National Electric Mobility Mission Plan, to cut oil imports and vehicle pollution.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-988","question":"In 2023, the Geological Survey of India reported inferred resources of lithium, important for batteries in electric vehicles and grid storage, in:","options":["Mandya district, Karnataka","Reasi district, Jammu and Kashmir","Singhbhum district, Jharkhand","Korba district, Chhattisgarh"],"answer":1,"explanation":"GSI reported about 5.9 million tonnes of inferred lithium resources in Reasi in February 2023. A small lithium find had earlier been reported at Mandya, which makes it a common trap.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-989","question":"Consider the following statements about the Construction and Demolition Waste Management Rules, 2016: 1. They were framed under the Environment (Protection) Act, 1986. 2. Waste generators are responsible for collecting and segregating their construction and demolition waste. 3. They apply only to the eight largest metropolitan cities. Which of the statements given above are correct?","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"These were India's first separate rules for C&D waste; they place duties on generators and local bodies, and encourage use of recycled C&D products in construction. They apply across the country, not only to metros.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-990","question":"The Battery Waste Management Rules, 2022 differ from the earlier Batteries (Management and Handling) Rules, 2001 mainly in that the 2022 rules:","options":["Apply only to the lead-acid batteries used in cars, trucks and inverters","Ban the sale of all lithium-ion batteries in India from a notified date","Allow used batteries to be disposed of in municipal sanitary landfills","Cover all battery types, including EV batteries, under producer responsibility"],"answer":3,"explanation":"The 2001 rules dealt essentially with lead-acid batteries. The 2022 rules cover portable, automotive, industrial and EV batteries, set EPR collection and recycling targets and require minimum recycled content in new batteries.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-991","question":"SAFAR, a system that provides location-specific air quality forecasts for several Indian cities, was developed by:","options":["The Indian Institute of Tropical Meteorology, Pune","The Central Pollution Control Board, Delhi","The Indian Space Research Organisation, Bengaluru","The National Environmental Engineering Research Institute, Nagpur"],"answer":0,"explanation":"SAFAR (System of Air Quality and Weather Forecasting and Research) was developed by IITM Pune under the Ministry of Earth Sciences; it was first deployed during the 2010 Commonwealth Games in Delhi.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-992","question":"HCFC-141b, an ozone-depleting chemical widely used as a blowing agent for making polyurethane foam, was completely phased out in India by:","options":["1 January 2010","1 January 2015","1 January 2030","1 January 2020"],"answer":3,"explanation":"India phased out HCFC-141b from 1 January 2020 under its HCFC Phase-out Management Plan, converting foam manufacturers to alternatives with zero ODP and low GWP. CFCs had been phased out in 2010.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-993","question":"The Biological Diversity (Amendment) Act, 2023 changed the 2002 Act by, among other things:","options":["Exempting registered AYUSH practitioners from giving prior intimation for access to bioresources","Abolishing the National Biodiversity Authority and transferring all its functions to the Ministry","Requiring foreign companies to obtain separate approval from each Gram Sabha whose land they use","Bringing the 2002 Act under the authority of the Chief Wildlife Wardens appointed under the WPA"],"answer":0,"explanation":"The amendment eased compliance for codified traditional knowledge and AYUSH practitioners, decriminalised offences into monetary penalties and promoted cultivation of medicinal plants. The NBA continues to exist.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-994","question":"The Environment Relief Fund, used to pay immediate relief to victims of accidents involving hazardous substances, was set up under:","options":["The Environment (Protection) Act, 1986, through its Section 3","The Public Liability Insurance Act, 1991, as amended in 1992","The National Green Tribunal Act, 2010, under its Section 24","The Disaster Management Act, 2005, as a part of the NDRF"],"answer":1,"explanation":"Owners handling hazardous substances must take insurance and also contribute to the Environment Relief Fund, so that victims get relief on a no-fault basis without proving negligence.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-995","question":"Match the study with its subject. A. Stern Review (2006)  B. Dasgupta Review (2021)  C. TEEB initiative (from 2007); 1. The economics of biodiversity, for the UK Treasury  2. The economics of climate change  3. Making visible the economic value of ecosystems and biodiversity, hosted by UNEP","options":["A-1, B-2, C-3","A-2, B-3, C-1","A-2, B-1, C-3","A-3, B-1, C-2"],"answer":2,"explanation":"Nicholas Stern's review argued that early climate action costs far less than inaction; Partha Dasgupta's review treated nature as an asset; TEEB, led by Pavan Sukhdev, grew out of a G8+5 initiative at Potsdam.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-996","question":"Which of the following is the best example of 'payment for ecosystem services'?","options":["A government fines a factory heavily for discharging effluent into a river","A city water utility pays upstream farmers to keep its catchment forested","A tourist pays an entry fee at a national park that funds its staff salaries","A farmer buys organic manure instead of urea for use on his own fields"],"answer":1,"explanation":"PES rewards land managers for maintaining services, here clean and steady water supply, that benefit others downstream. A fine is a penalty under polluter pays, and an entry fee is simply a user charge.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-997","question":"Common Effluent Treatment Plants (CETPs) are set up in Indian industrial clusters mainly because:","options":["Large industries are prohibited by law from treating their own effluent on site","They allow treated water to be sold back to member industries at a large profit","Rivers next to industrial estates need extra water released in the dry season","Small units cannot afford their own treatment plants, so they share one"],"answer":3,"explanation":"CETPs pool effluent from many small units, making treatment affordable and easier to monitor; member units usually pre-treat their wastewater first. Poorly run CETPs remain a problem in clusters such as Vapi and Ankleshwar.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-998","question":"The SATAT initiative, launched in India in 2018, promotes:","options":["Solar-powered trains on suburban railway routes in large cities","Sale of electric three-wheelers through post offices in villages","Compressed biogas plants that turn biomass into transport fuel","Ethanol made from sugarcane juice for blending with petrol"],"answer":2,"explanation":"Sustainable Alternative Towards Affordable Transportation invites entrepreneurs to set up compressed biogas (CBG) plants, with oil marketing companies buying the gas, helping reduce stubble burning and gas imports.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-999","question":"Under the Green Highways (Plantation, Transplantation, Beautification and Maintenance) Policy, 2015, funds for planting along national highways come mainly from:","options":["Penalties collected from vehicles that violate emission norms on highways","Earmarking about 1 per cent of the civil works cost of highway projects","A special cess levied on diesel sold at fuel stations along the highways","Voluntary donations collected from road users at the toll plazas"],"answer":1,"explanation":"The policy sets aside about 1 per cent of the total project cost of highway construction for plantation and maintenance, involving local communities, NGOs and the private sector.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"env-ecology-1000","question":"While the cold North Atlantic absorbs CO2 from the air, the equatorial Pacific is a net source of CO2 to the atmosphere. The main reason is that in the equatorial Pacific:","options":["Intense phytoplankton photosynthesis in warm water gives off CO2 as a by-product","Frequent tropical cyclones churn up sediments that are rich in organic carbon","Upwelled deep water rich in dissolved carbon warms at the surface and releases CO2","Volcanoes on the sea floor emit large amounts of CO2 directly into the water"],"answer":2,"explanation":"Deep water carries carbon accumulated from sinking organic matter; when it upwells and warms, CO2 becomes less soluble and outgasses. In the North Atlantic, cold surface water takes up CO2 and sinks, the solubility pump in reverse.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
];

export default questions;
